// Moquete - Capitulo 6: La hora oscura de Chrono
// Chrono cruza la grieta que abrio la Maquina Rara y llega al mundo oscuro.

const chronoChapterProgressKey = 'moqueteChronoChapterProgress';
const chronoChapterLevelCount = 9;
const chronoChapterPlayableLevels = 9;
// the secret level: unlocked by seeing Abnormal drop in on the roof (level 7, 15%)
const chronoSecretLevel = 10;
const chronoSecretUnlockKey = 'moqueteChronoSecretUnlocked';
const chronoSecretBeatenKey = 'moqueteChronoSecretBeaten';
const chronoSecretLevelReady = true;

function isChronoSecretUnlocked() {
  try {
    return localStorage.getItem(chronoSecretUnlockKey) === '1';
  } catch (error) {
    return false;
  }
}

function isChronoSecretBeaten() {
  try {
    return localStorage.getItem(chronoSecretBeatenKey) === '1';
  } catch (error) {
    return false;
  }
}

function unlockChronoSecretLevel() {
  if (isChronoSecretUnlocked()) return false;
  try {
    localStorage.setItem(chronoSecretUnlockKey, '1');
  } catch (error) {
    // the secret stays open for this session only
  }
  return true;
}

function isChronoChapterUnlocked() {
  return Boolean(scammerShop.owned && scammerShop.owned.rareMachine || isRareMachineUsed()) &&
    typeof isKnightSecretLevelBeaten === 'function' && isKnightSecretLevelBeaten() &&
    typeof isFlametombUnlocked === 'function' && isFlametombUnlocked() &&
    isRareMachineUsed();
}

// ---------- the chapter card ----------
function syncChronoChapterUnlock() {
  const card = document.getElementById('chronoArcadeChapterButton');
  if (!card) return;
  const open = isChronoChapterUnlocked();
  card.classList.toggle('chrono-open', open);
  const tape = card.querySelector('.knightArcade-tape');
  if (tape) tape.classList.toggle('hidden', open);
  const badge = card.querySelector('.chronoArcade-badge');
  if (badge) badge.textContent = open ? 'NUEVO' : 'PROXIMAMENTE';
  const copy = card.querySelector('.arcade-chapter-copy > span');
  if (copy) copy.textContent = open
    ? 'Capitulo 6. Chrono cruzo la grieta que abrio la Maquina Rara. Del otro lado, el mundo oscuro... y algo que se repite.'
    : 'Capitulo 6. Chrono cruza al mundo oscuro siguiendo una grieta en el tiempo. Algo alla adentro se esta repitiendo...';
}

// the card opens the chapter once the requirements are done (it was "under construction" before)
if (chronoArcadeChapterButton) {
  chronoArcadeChapterButton.addEventListener('click', (event) => {
    if (!isChronoChapterUnlocked()) return;
    event.stopImmediatePropagation();
    openArcadeChapter('chrono', false);
  }, true);
}
syncChronoChapterUnlock();
setInterval(syncChronoChapterUnlock, 2000);

function syncChronoChapterUI() {
  const titles = ['Del otro lado', 'Hojas rojas', 'Otro color', 'La Orden Oscura', 'El Caballero Negro', 'El juicio del bufon', 'El palco', 'El titan', 'La persecucion', '???'];
  const descriptions = [
    'Un cielo negro, un suelo que no es de ningun lugar. Chrono avanza... y alguien baja del cielo a recibirlo.',
    'Un bosque de hojas rojas que caen sin parar. Entre los arboles, ojos... y una sonrisa conocida.',
    'El mismo bosque, pero las hojas ya no son rojas. Algo de tres cabezas se arrastra entre los troncos.',
    'Las puertas del castillo, sus salas curiosas... y una sala sellada donde lo esperan tres figuras.',
    'Buscando la salida del castillo... hasta que un caballero de armadura negra le cierra el paso.',
    'Arrastrado hacia el trono... un bufon que no se cansa, y un general desterrado frente al guardian de la puerta.',
    'El techo del castillo. El bufon quiere su segundo acto... y Chrono, algo mas fuerte que la luz.',
    'Algo subio desde el suelo. Es mas alto que el castillo. Y Chrono ya no tiene a donde correr.',
    'El castillo se derrumba, el titan lo persigue... y Chrono ya no tiene aire. Pero no esta solo.',
    'Algo que Abnormal dejo escapar aquella noche, en el techo... Distinguidamente secreto.',
  ];
  normalArcadeLevelButtons.forEach((levelButton, index) => {
    const title = levelButton.querySelector('.arcade-level-copy strong');
    const description = levelButton.querySelector('.arcade-level-copy span');
    if (index >= titles.length) return;
    if (title) title.innerText = titles[index];
    if (description) description.innerText = descriptions[index];
  });
  arcadeLevelsTitle.innerText = 'Capitulo 6: La hora oscura de Chrono';
  arcadeStoryKicker.innerText = 'El mundo oscuro';
  arcadeStoryParagraphOne.innerText =
    'La Maquina Rara abrio una grieta en el tiempo. Chrono la cruzo, y detras de el... alguien mas.';
  arcadeStoryParagraphTwo.innerText =
    'Del otro lado el cielo es negro y algo se repite, una y otra vez, como un reloj atascado. Tempus Corp. nunca llego tan lejos.';
}

// ---------- level setup ----------
const chronoCh = { abilityTimer: 0, nextAbility: 0, cards: [], pillars: [], blink: null, diamonds: [], banner: null, phase2: false, thoughtTimer: 0 };

function isChronoChapterFight() {
  return normalArcadeActive && arcadeChapter === 'chrono';
}

function makeChapterChrono(fighter) {
  fighter.setCharacterType('chrono');
  fighter.giantScale = 1;
  fighter.brokenLook = false;
  fighter.machineLook = true;
  fighter.setMaxHealth(160);
  fighter.health = fighter.maxHealth;
}

function configureChronoChapterLevel() {
  makeChapterChrono(player1);
  selectedMap = selectedNormalArcadeLevel === 2 ? 'redForest' : selectedNormalArcadeLevel === 3 ? 'violetForest' : selectedNormalArcadeLevel === 4 ? 'orderChamber' : selectedNormalArcadeLevel === 5 ? 'castleHall' : selectedNormalArcadeLevel === 6 ? 'castleThroneHall' : selectedNormalArcadeLevel === 7 || selectedNormalArcadeLevel === 8 ? 'castleRoof' : selectedNormalArcadeLevel === 9 ? 'castleRuins' : selectedNormalArcadeLevel === 10 ? 'abnormalArena' : 'darkWorld';
  if (selectedNormalArcadeLevel === 8 || selectedNormalArcadeLevel === 9) resetChronoTitan();
  if (selectedNormalArcadeLevel === 9) {
    // the titan already lost 2000 on the roof
    chronoTitan.bar = { max: 10000, value: 8000, shown: 8000, t: 30, hitT: 0, lastHit: 0 };
    chronoTitan.dodgeLeft = chronoTitan9ChaseFrames;
    chronoTitan.power = 1.15;
    chronoTitan.ally = null;
    chronoTitan.popups = [];
  }
  // (level 4: the Rare Machine powers him up)
  if (selectedNormalArcadeLevel === 4 || selectedNormalArcadeLevel === 5) player1.damageMultiplier = 1.5;
  player1.machineLight = false;
  chronoCh.lightMode = { state: null, t: 0 };
  botEnabled = true;
  normalArcadeEnemiesRemaining = chronoChLevels[selectedNormalArcadeLevel] ? chronoChLevels[selectedNormalArcadeLevel].enemies.length - 1 : 0;
  normalArcadeEnemyIndex = 1;
  Object.assign(chronoCh, { titanPhase: selectedNormalArcadeLevel === 9 ? 'chase' : 'dodge', titanBabyCount: 2, ceilingBroken: false, duelPhase: false, ceilingDone: false, darkShotStarted: false, overcharged: false, overchargeStarted: false, knightShield: 0, knightSlam: null, shieldFlash: 0, reflectDone: false, knightRage: false, rescued: false, outroPlayed: false, abilityTimer: 200, nextAbility: 0, cards: [], pillars: [], blink: null, diamonds: [], banner: null, phase2: false, thoughtTimer: 500 });
  configureChronoChapterEnemy();
}

function configureChronoChapterEnemy() {
  resetForestFx();
  if (selectedNormalArcadeLevel === 8) {
    configureChronoTitanEnemy();
    return;
  }
  if (selectedNormalArcadeLevel === 9) {
    configureChronoTitan9Enemy();
    return;
  }
  if (selectedNormalArcadeLevel === chronoSecretLevel) {
    configureChronoSecretEnemy();
    return;
  }
  if (selectedNormalArcadeLevel === 6 || selectedNormalArcadeLevel === 7) {
    if (selectedNormalArcadeLevel === 6 && chronoCh.duelPhase) configureChronoHallKnight();
    else configureChronoJester();
    return;
  }
  const levelData = chronoChLevels[selectedNormalArcadeLevel];
  if (levelData) {
    const index = Math.min(levelData.enemies.length - 1, normalArcadeEnemyIndex - 1);
    const variant = levelData.enemies[index];
    player2.setCharacterType('normal', variant);
    botDifficulty = levelData.difficulties[index] || 'medium';
    applyBotDifficulty();
    player2.setMaxHealth(levelData.health ? levelData.health[index] : variant === 'friendThing' ? 130 : originsHealth[variant]);
    // (the captain's deal from chapter 5 doesn't apply here)
    player2.darkDealDone = true;
    // (each knight down: the machine gives back a little more life)
    if (selectedNormalArcadeLevel === 4 && normalArcadeEnemyIndex > 1) {
      player1.health = Math.min(player1.maxHealth, player1.health + 40);
      showScamLabel(player1, '+40');
    }
    player2.health = player2.maxHealth;
    if (variant === 'friendThing') {
      resetFriendThing(player2);
      if (typeof playFriendLaugh === 'function') playFriendLaugh('normal');
    }
    updateHealthBars();
    updateCombatHudIdentity();
    return;
  }
  player2.setCharacterType('normal', 'abnormal');
  botDifficulty = 'medium';
  applyBotDifficulty();
  player2.setMaxHealth(originsHealth.abnormal);
  player2.health = player2.maxHealth;
  updateHealthBars();
  updateCombatHudIdentity();
}

// ABNORMAL: the "normal" of the dark world (it uses the variant tables of the special chapter)
['abnormal'].forEach((variant) => {
  if (!originsVariants.includes(variant)) originsVariants.push(variant);
  if (!arcadeBossVariants.includes(variant)) arcadeBossVariants.push(variant);
});
originsSizes.abnormal = [62, 124];
originsSpeeds.abnormal = 1.08;
originsDamage.abnormal = 0.9;
originsHealth.abnormal = 340;
originsNames.abnormal = 'Abnormal';
reflecterBattleTrackSources.rouxls = reflecterBattleTrackSources.rouxls || encodeURI('assetsaudio/Rouxls Kaard.mp3');

function isAbnormal(fighter) {
  return Boolean(fighter && fighter.secretVariant === 'abnormal');
}

// dark blue, with dark blue and white armor, a plume and a card on his chest
function drawAbnormalDetails(fighter) {
  const x = fighter.position.x;
  const y = fighter.position.y;
  const w = fighter.width;
  const h = fighter.height;
  const dir = fighter.attacksToTheRight ? 1 : -1;
  const time = performance.now() / 1000;
  ctx.save();
  // the armor: shoulder pads, breastplate, belt and greaves
  ctx.fillStyle = '#0d1b4a';
  ctx.fillRect(x - 6, y + 30, 18, 14);
  ctx.fillRect(x + w - 12, y + 30, 18, 14);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(x - 6, y + 30, 18, 3);
  ctx.fillRect(x + w - 12, y + 30, 18, 3);
  ctx.fillStyle = '#0d1b4a';
  ctx.fillRect(x + 6, y + 36, w - 12, 40);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 6, y + 36, w - 12, 40);
  ctx.fillStyle = '#e8eaf6';
  ctx.fillRect(x + 4, y + 78, w - 8, 6);
  ctx.fillStyle = '#0d1b4a';
  ctx.fillRect(x + 6, y + h - 26, 18, 26);
  ctx.fillRect(x + w - 24, y + h - 26, 18, 26);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(x + 6, y + h - 26, 18, 3);
  ctx.fillRect(x + w - 24, y + h - 26, 18, 3);
  // a white spade on the breastplate
  const cx = x + w / 2;
  const cy = y + 54;
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.moveTo(cx, cy - 10);
  ctx.bezierCurveTo(cx + 12, cy - 2, cx + 10, cy + 8, cx, cy + 4);
  ctx.bezierCurveTo(cx - 10, cy + 8, cx - 12, cy - 2, cx, cy - 10);
  ctx.fill();
  ctx.fillRect(cx - 2, cy + 3, 4, 8);
  // the helmet: a white visor and a tall plume
  ctx.fillStyle = '#0d1b4a';
  ctx.fillRect(x + 2, y - 4, w - 4, 16);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(x + 8, y + 14, w - 16, 5);
  ctx.fillStyle = '#90caf9';
  ctx.fillRect(x + (dir > 0 ? w - 22 : 10), y + 15, 12, 3);
  ctx.fillStyle = '#e8eaf6';
  ctx.beginPath();
  ctx.moveTo(cx - 4, y - 4);
  ctx.quadraticCurveTo(cx - dir * 30, y - 34 + Math.sin(time * 3) * 3, cx - dir * 46, y - 10);
  ctx.quadraticCurveTo(cx - dir * 20, y - 18, cx + 4, y - 4);
  ctx.fill();
  // a little elegant cape
  ctx.fillStyle = 'rgba(13, 27, 74, 0.9)';
  ctx.beginPath();
  ctx.moveTo(x + (dir > 0 ? 4 : w - 4), y + 32);
  ctx.lineTo(x + (dir > 0 ? -18 : w + 18) + Math.sin(time * 2) * 3, y + 96);
  ctx.lineTo(x + (dir > 0 ? 10 : w - 10), y + 90);
  ctx.closePath();
  ctx.fill();
  // the glow of the dark world around him
  if (chronoCh.blink && chronoCh.blink.t < 20) {
    ctx.fillStyle = `rgba(255, 255, 255, ${1 - chronoCh.blink.t / 20})`;
    ctx.fillRect(x - 10, y - 10, w + 20, h + 20);
  }
  ctx.restore();
}

// ---------- his abilities: light and cards ----------
const abnormalSuits = ['spade', 'heart', 'diamond', 'club'];
const abnormalSuitColors = { spade: '#e3f2fd', heart: '#ff8a80', diamond: '#80d8ff', club: '#b9f6ca' };
const abnormalThoughts = ['Jo jo! Precisamente como lo planee!', 'Inclinate ante mi esgrima de LUZ!', 'Tu no puedes vencer a un guardia TAN distinguido!', 'Esto es un sparring, NADA mas! (mentira)', 'Que reloj tan tozudo!'];

function updateChronoChapter() {
  if (isChronoChapterFight()) {
    updateForestMonsterAbilities();
    updateChronoLightMode();
    updateBlackKnightBoss();
    updateChronoJester();
    updateChronoTitan();
    updateChronoSecret();
  }
  if (!isChronoChapterFight() || !gameStarted || gameOver || arcadeCutscene.active) {
    updateAbnormalProjectiles();
    return;
  }
  if (selectedNormalArcadeLevel === 3 && isHydra(player2) && !chronoCh.rescued && player2.health <= Math.ceil(player2.maxHealth * 0.2) + 0.5) {
    startChronoChapterRescue();
    return;
  }
  const abnormal = player2;
  if (!isAbnormal(abnormal)) return;
  if (chronoCh.banner) {
    chronoCh.banner.t += 1;
    if (chronoCh.banner.t > 180) chronoCh.banner = null;
  }
  if (!chronoCh.phase2 && abnormal.health <= abnormal.maxHealth * 0.5) {
    chronoCh.phase2 = true;
    abnormal.damageMultiplier = originsDamage.abnormal * 1.25;
    showFlametombThought(abnormal, 'BASTA DE CORTESIAS! Es hora de mi CARTA MAESTRA!');
    chronoCh.banner = { text: 'ABNORMAL SE PONE SERIO', sub: 'Nuevo: lluvia de diamantes', t: 0 };
    playTone({ frequency: 330, duration: 0.8, type: 'square', volume: 0.05, slideTo: 660 });
  }
  chronoCh.thoughtTimer -= 1;
  if (chronoCh.thoughtTimer <= 0) {
    chronoCh.thoughtTimer = 700 + Math.floor(Math.random() * 300);
    showFlametombThought(abnormal, abnormalThoughts[Math.floor(Math.random() * abnormalThoughts.length)]);
  }
  chronoCh.abilityTimer -= 1;
  if (chronoCh.abilityTimer <= 0 && canFighterAct(abnormal) && !chronoCh.blink) {
    const list = chronoCh.phase2 ? ['cards', 'pillars', 'blink', 'diamonds'] : ['cards', 'pillars', 'blink'];
    const ability = list[chronoCh.nextAbility % list.length];
    chronoCh.nextAbility += 1;
    chronoCh.abilityTimer = chronoCh.phase2 ? 150 : 210;
    castAbnormalAbility(ability);
  }
  updateAbnormalProjectiles();
}

function castAbnormalAbility(ability) {
  const abnormal = player2;
  const target = player1;
  const fromX = getFighterCenterX(abnormal);
  const fromY = abnormal.position.y + 50;
  if (ability === 'cards') {
    // a fan of three spinning cards of light
    showFlametombThought(abnormal, 'Elige una carta! Cualquiera! (todas duelen)');
    const aim = Math.atan2(target.position.y + target.height / 2 - fromY, getFighterCenterX(target) - fromX);
    [-0.22, 0, 0.22].forEach((spread, index) => {
      chronoCh.cards.push({ x: fromX, y: fromY, vx: Math.cos(aim + spread) * 7, vy: Math.sin(aim + spread) * 7, spin: 0, suit: abnormalSuits[(chronoCh.nextAbility + index) % 4], life: 160, hit: false });
    });
    playTone({ frequency: 880, duration: 0.2, type: 'triangle', volume: 0.05, slideTo: 1320 });
  } else if (ability === 'pillars') {
    // pillars of light falling from the black sky, where you are (and around)
    showFlametombThought(abnormal, 'Que la LUZ te juzgue!');
    const center = getFighterCenterX(target);
    const spots = chronoCh.phase2 ? [center - 130, center, center + 130] : [center - 90, center + 90, center];
    spots.forEach((x, index) => chronoCh.pillars.push({ x: Math.max(30, Math.min(canvas.width - 30, x)), t: -index * 14, hit: false }));
    playTone({ frequency: 520, duration: 0.6, type: 'sine', volume: 0.04, slideTo: 1040 });
  } else if (ability === 'blink') {
    // a white flash: he disappears... and appears behind you with a slash
    chronoCh.blink = { t: 0, fromX: abnormal.position.x, hit: false };
    playNoise({ duration: 0.2, volume: 0.06, filterFrequency: 6000 });
  } else if (ability === 'diamonds') {
    // a rain of diamonds of light
    showFlametombThought(abnormal, 'LLUVIA DE DIAMANTES! Es gratis! (no lo es)');
    for (let drop = 0; drop < 10; drop += 1) {
      chronoCh.diamonds.push({ x: 40 + Math.random() * (canvas.width - 80), y: -20 - drop * 40, vy: 4 + Math.random() * 2, hit: false });
    }
  }
}

function updateAbnormalProjectiles() {
  const target = player1;
  const abnormal = player2;
  const hitsTarget = (x, y, r) => x > target.position.x - r && x < target.position.x + target.width + r && y > target.position.y - r && y < target.position.y + target.height + r;
  chronoCh.cards.forEach((card) => {
    card.x += card.vx;
    card.y += card.vy;
    card.spin += 0.3;
    card.life -= 1;
    if (!card.hit && !gameOver && hitsTarget(card.x, card.y, 10)) {
      card.hit = true;
      card.life = 0;
      applyDamage(abnormal, target, 9, { isSpecial: true });
      updateHealthBars();
      playSound('robotHit');
    }
  });
  chronoCh.cards = chronoCh.cards.filter((card) => card.life > 0 && card.x > -40 && card.x < canvas.width + 40 && card.y < ground + 20);
  chronoCh.pillars.forEach((pillar) => {
    pillar.t += 1;
    if (pillar.t === 50) {
      playNoise({ duration: 0.3, volume: 0.07, filterFrequency: 3000 });
      if (!gameOver && Math.abs(getFighterCenterX(target) - pillar.x) < 40) {
        applyDamage(abnormal, target, 11, { isSpecial: true });
        target.velocity.y = -3;
        updateHealthBars();
      }
    }
  });
  chronoCh.pillars = chronoCh.pillars.filter((pillar) => pillar.t < 75);
  chronoCh.diamonds.forEach((drop) => {
    drop.y += drop.vy;
    if (!drop.hit && !gameOver && hitsTarget(drop.x, drop.y, 8)) {
      drop.hit = true;
      drop.y = ground + 100;
      applyDamage(abnormal, target, 6, { isSpecial: true });
      updateHealthBars();
    }
  });
  chronoCh.diamonds = chronoCh.diamonds.filter((drop) => drop.y < ground + 10);
  const blink = chronoCh.blink;
  if (blink) {
    blink.t += 1;
    if (blink.t === 18) {
      // behind Chrono
      const behind = target.attacksToTheRight ? -1 : 1;
      abnormal.position.x = Math.max(10, Math.min(canvas.width - abnormal.width - 10, getFighterCenterX(target) + behind * 80 - abnormal.width / 2));
      abnormal.attacksToTheRight = behind < 0;
      playNoise({ duration: 0.2, volume: 0.06, filterFrequency: 6000 });
    }
    if (blink.t === 30 && !blink.hit && !gameOver) {
      blink.hit = true;
      if (Math.abs(getFighterCenterX(target) - getFighterCenterX(abnormal)) < 120) {
        applyDamage(abnormal, target, 12, { isSpecial: true });
        target.velocity.y = -3;
        updateHealthBars();
        playSound('robotHit');
      }
    }
    if (blink.t > 45) chronoCh.blink = null;
  }
}

function drawAbnormalSuit(suit, x, y, size, color) {
  ctx.fillStyle = color;
  ctx.beginPath();
  if (suit === 'heart') {
    ctx.moveTo(x, y + size * 0.6);
    ctx.bezierCurveTo(x - size, y - size * 0.2, x - size * 0.4, y - size, x, y - size * 0.3);
    ctx.bezierCurveTo(x + size * 0.4, y - size, x + size, y - size * 0.2, x, y + size * 0.6);
  } else if (suit === 'diamond') {
    ctx.moveTo(x, y - size);
    ctx.lineTo(x + size * 0.65, y);
    ctx.lineTo(x, y + size);
    ctx.lineTo(x - size * 0.65, y);
  } else if (suit === 'club') {
    ctx.arc(x, y - size * 0.4, size * 0.38, 0, Math.PI * 2);
    ctx.moveTo(x - size * 0.4, y + size * 0.1);
    ctx.arc(x - size * 0.4, y + size * 0.1, size * 0.38, 0, Math.PI * 2);
    ctx.moveTo(x + size * 0.4, y + size * 0.1);
    ctx.arc(x + size * 0.4, y + size * 0.1, size * 0.38, 0, Math.PI * 2);
    ctx.fillRect(x - 2, y, 4, size * 0.9);
  } else {
    ctx.moveTo(x, y - size);
    ctx.bezierCurveTo(x + size, y - size * 0.1, x + size * 0.8, y + size * 0.7, x, y + size * 0.3);
    ctx.bezierCurveTo(x - size * 0.8, y + size * 0.7, x - size, y - size * 0.1, x, y - size);
    ctx.fillRect(x - 2, y + size * 0.2, 4, size * 0.7);
  }
  ctx.fill();
}

function drawChronoChapterFx() {
  if (!isChronoChapterFight()) return;
  drawForestMonsterFx();
  const time = performance.now() / 1000;
  ctx.save();
  chronoCh.cards.forEach((card) => {
    ctx.save();
    ctx.translate(card.x, card.y);
    ctx.rotate(card.spin);
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = 14;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-11, -15, 22, 30);
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#1a237e';
    ctx.lineWidth = 2;
    ctx.strokeRect(-11, -15, 22, 30);
    drawAbnormalSuit(card.suit, 0, 0, 7, card.suit === 'heart' || card.suit === 'diamond' ? '#d50000' : '#1a237e');
    ctx.restore();
  });
  chronoCh.pillars.forEach((pillar) => {
    if (pillar.t < 0) return;
    if (pillar.t < 50) {
      const k = pillar.t / 50;
      ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + k * 0.6})`;
      ctx.lineWidth = 2;
      ctx.setLineDash([6, 6]);
      ctx.strokeRect(pillar.x - 30, 0, 60, ground);
      ctx.setLineDash([]);
      drawAbnormalSuit(abnormalSuits[Math.floor(pillar.x) % 4], pillar.x, 40 + k * 20, 12, `rgba(255, 255, 255, ${k})`);
    } else {
      const k = 1 - (pillar.t - 50) / 25;
      const beam = ctx.createLinearGradient(pillar.x - 36, 0, pillar.x + 36, 0);
      beam.addColorStop(0, 'rgba(144, 202, 249, 0)');
      beam.addColorStop(0.5, `rgba(255, 255, 255, ${k})`);
      beam.addColorStop(1, 'rgba(144, 202, 249, 0)');
      ctx.fillStyle = beam;
      ctx.fillRect(pillar.x - 36, 0, 72, ground);
    }
  });
  chronoCh.diamonds.forEach((drop) => {
    ctx.shadowColor = '#80d8ff';
    ctx.shadowBlur = 10;
    drawAbnormalSuit('diamond', drop.x, drop.y, 9, '#e1f5fe');
    ctx.shadowBlur = 0;
  });
  const blink = chronoCh.blink;
  if (blink && blink.t < 18) {
    ctx.fillStyle = `rgba(255, 255, 255, ${0.5 - blink.t / 40})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  if (blink && blink.t >= 24 && blink.t < 36) {
    // the slash
    const x = getFighterCenterX(player2);
    ctx.strokeStyle = `rgba(255, 255, 255, ${1 - (blink.t - 24) / 12})`;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.arc(x, player2.position.y + 60, 70, -1.2, 1.2);
    ctx.stroke();
  }
  if (chronoCh.banner) {
    const banner = chronoCh.banner;
    ctx.globalAlpha = Math.max(0, Math.min(1, banner.t / 15, (180 - banner.t) / 30));
    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.fillRect(0, 186, canvas.width, 74);
    ctx.textAlign = 'center';
    ctx.font = '900 30px Courier New, monospace';
    ctx.fillStyle = '#90caf9';
    ctx.fillText(banner.text, canvas.width / 2, 222);
    ctx.font = '900 15px Courier New, monospace';
    ctx.fillStyle = '#fff';
    ctx.fillText(banner.sub, canvas.width / 2, 248);
    ctx.textAlign = 'left';
    ctx.globalAlpha = 1;
  }
  ctx.restore();
}

// ---------- the dark world ----------
function drawDarkWorldStage() {
  const time = performance.now() / 1000;
  // a sky almost completely black
  const sky = ctx.createLinearGradient(0, 0, 0, ground);
  sky.addColorStop(0, '#000000');
  sky.addColorStop(0.7, '#05030c');
  sky.addColorStop(1, '#0c0820');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, ground);
  // a few faint lights far away, and slow falling specks
  for (let star = 0; star < 30; star += 1) {
    const twinkle = 0.15 + Math.max(0, Math.sin(time * 1.3 + star * 2.1)) * 0.25;
    ctx.fillStyle = `rgba(179, 157, 219, ${twinkle})`;
    ctx.fillRect((star * 137) % canvas.width, (star * 53) % (ground - 200), 2, 2);
  }
  // dark cliffs on the horizon
  ctx.fillStyle = '#0a0716';
  ctx.beginPath();
  ctx.moveTo(0, ground - 90);
  [[90, ground - 140], [180, ground - 110], [260, ground - 170], [380, ground - 120], [470, ground - 150], [560, ground - 100], [680, ground - 180], [790, ground - 130], [900, ground - 160], [1024, ground - 110]].forEach(([x, y]) => ctx.lineTo(x, y));
  ctx.lineTo(canvas.width, ground);
  ctx.lineTo(0, ground);
  ctx.closePath();
  ctx.fill();
  // a far away fountain of light (where everything starts?)
  const fountainX = 760;
  const glow = ctx.createLinearGradient(fountainX - 30, 0, fountainX + 30, 0);
  glow.addColorStop(0, 'rgba(255, 255, 255, 0)');
  glow.addColorStop(0.5, `rgba(255, 255, 255, ${0.08 + Math.sin(time) * 0.03})`);
  glow.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(fountainX - 30, 0, 60, ground - 150);
  // the floor: dark purple stone, with a checkered pattern
  ctx.fillStyle = '#1b1035';
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
  for (let tile = 0; tile < canvas.width / 48 + 1; tile += 1) {
    ctx.fillStyle = tile % 2 ? '#24164a' : '#160c30';
    ctx.fillRect(tile * 48, ground, 48, 18);
  }
  ctx.fillStyle = '#4527a0';
  ctx.fillRect(0, ground - 4, canvas.width, 4);
  // dark plants and crooked clock hands sticking out of the ground
  [[120, 1], [330, -1], [640, 1], [930, -1]].forEach(([x, side], index) => {
    ctx.strokeStyle = '#2a1a55';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(x, ground);
    ctx.lineTo(x + side * 14, ground - 46 - index * 6);
    ctx.stroke();
    ctx.fillStyle = '#2a1a55';
    ctx.beginPath();
    ctx.moveTo(x + side * 14, ground - 52 - index * 6);
    ctx.lineTo(x + side * 6, ground - 36 - index * 6);
    ctx.lineTo(x + side * 22, ground - 38 - index * 6);
    ctx.closePath();
    ctx.fill();
  });
}

// ---------- the intro of level 1 ----------
