function startChronoChapterIntro() {
  if (selectedNormalArcadeLevel === 2) {
    startChronoChapterLevel2Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 3) {
    startChronoChapterLevel3Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 4) {
    startChronoChapterLevel4Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 5) {
    startChronoChapterLevel5Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 6) {
    startChronoChapterLevel6Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 7) {
    startChronoChapterLevel7Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 8) {
    startChronoChapterLevel8Intro();
    return;
  }
  if (selectedNormalArcadeLevel === 9) {
    startChronoChapterLevel9Intro();
    return;
  }
  if (selectedNormalArcadeLevel === chronoSecretLevel) {
    startChronoSecretIntro();
    return;
  }
  if (selectedNormalArcadeLevel !== 1) return;
  const divine = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
  divine.setCharacterType('divineGeneral');
  ch6CutsceneBase('originsIntro', chronoChIntroLines, 'dialog', {
    darkWorld: true,
    gamblerX: 140,
    gamblerTargetX: 140,
    scammerX: 680,
    scammerTargetX: 680,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    laterFade: 0,
    flash: 0,
    riftOpen: 0,
    divineActor: divine,
    divineX: 20,
    divineAlpha: 0,
    descendY: -1,
    skyGlint: 0,
    darkMusic: false,
  });
  startCutsceneLine(0);
}

function updateDarkWorldIntro(cutscene) {
  const line = cutscene.lines[cutscene.lineIndex];
  const firstFrame = cutscene.lastFlagLine !== cutscene.lineIndex;
  cutscene.lastFlagLine = cutscene.lineIndex;
  cutscene.hideEnemy = Boolean(line.noEnemy) || (cutscene.descendY < 0 && !cutscene.outro);
  // Chrono floats
  cutscene.gamblerHop = 40 + Math.sin(cutscene.frame / 12) * 6;
  if (line.arrive && firstFrame) {
    cutscene.flash = 1;
    cutscene.riftOpen = 1;
    playTone({ frequency: 90, duration: 1.8, type: 'sawtooth', volume: 0.05, slideTo: 60 });
  }
  if (typeof line.walk === 'number' && firstFrame) cutscene.gamblerTargetX = Math.min(canvas.width - 420, cutscene.gamblerTargetX + line.walk);
  if (line.rift) cutscene.riftOpen = Math.min(1, cutscene.riftOpen + 0.03);
  else if (!line.arrive) cutscene.riftOpen = Math.max(0, cutscene.riftOpen - 0.02);
  if (line.rift && firstFrame && !cutscene.riftSound) {
    cutscene.riftSound = true;
    playTone({ frequency: 70, duration: 2, type: 'sawtooth', volume: 0.04, slideTo: 50 });
  }
  if (line.divine) {
    cutscene.divineAlpha = Math.min(1, cutscene.divineAlpha + 0.03);
    cutscene.divineX = Math.min(70, cutscene.divineX + 0.4);
  }
  if (line.later) cutscene.laterFade = Math.min(1, cutscene.laterFade + 0.05);
  else cutscene.laterFade = Math.max(0, cutscene.laterFade - 0.04);
  if (line.later) cutscene.divineAlpha = 0;
  if (line.skyGlint) cutscene.skyGlint = Math.min(1, cutscene.skyGlint + 0.02);
  // he comes down from the sky inside a column of light
  if (line.descend) {
    if (firstFrame) {
      cutscene.descendY = 0;
      cutscene.flash = 1;
      playNoise({ duration: 0.8, volume: 0.1, filterFrequency: 5000 });
      playTone({ frequency: 1200, duration: 1.2, type: 'sine', volume: 0.05, slideTo: 300 });
    }
    cutscene.descendY = Math.min(1, cutscene.descendY + 0.012);
    cutscene.scammerY = (1 - cutscene.descendY) * 420;
  } else if (cutscene.descendY >= 0) {
    cutscene.scammerY = 0;
  }
  if (line.music) cutscene.darkMusic = true;
  if (cutscene.forest) updateDarkForestIntro(cutscene, line, firstFrame);
  if (cutscene.rescue) updateChronoChapterRescue(cutscene, line, firstFrame);
  if (cutscene.castle) updateCastleIntro(cutscene, line, firstFrame);
  if (cutscene.reflectScene) updateChronoChapterReflect(cutscene, line, firstFrame);
  if (cutscene.jesterHall) updateChronoLevel6Intro(cutscene, line, firstFrame);
  if (cutscene.overchargeScene) updateChronoOverchargeScene(cutscene, line, firstFrame);
  if (cutscene.ceilingScene) updateChronoJesterCeiling(cutscene, line, firstFrame);
  if (cutscene.knightDuel) updateChronoKnightDuelScene(cutscene, line, firstFrame);
  if (cutscene.darkShotScene) updateChronoDarkShot(cutscene, line, firstFrame);
  if (cutscene.titanIntro) updateChronoTitanIntro(cutscene, line, firstFrame);
  if (cutscene.titanBabies) updateChronoTitanBabies(cutscene, line, firstFrame);
  if (cutscene.titanShot) updateChronoTitanShot(cutscene, line, firstFrame);
  if (cutscene.titan9) updateChronoTitan9Scene(cutscene, line, firstFrame);
  if (cutscene.secretScene) updateChronoSecretScene(cutscene, line, firstFrame);
  if (cutscene.castle && selectedNormalArcadeLevel === 5) updateLevel5Intro(cutscene, line, firstFrame);
  if (cutscene.orderOutro) updateChronoChapterOrderOutro(cutscene, line, firstFrame);
  // the outro: Chrono walks away, Abnormal goes up in his flash, Divine General walks in
  if (line.leave && firstFrame) cutscene.gamblerTargetX = canvas.width + 220;
  if (line.leave) cutscene.chronoLeft = true;
  if (cutscene.chronoLeft) {
    cutscene.gamblerX = line.gone ? canvas.width + 300 : Math.min(canvas.width + 300, cutscene.gamblerX + 3.5);
    cutscene.gamblerTargetX = cutscene.gamblerX;
  }
  if (line.ascend) {
    if (firstFrame) {
      cutscene.flash = 1;
      cutscene.ascendT = 0;
      playNoise({ duration: 0.8, volume: 0.1, filterFrequency: 5000 });
      playTone({ frequency: 300, duration: 1.2, type: 'sine', volume: 0.05, slideTo: 1200 });
    }
    cutscene.ascendT = (cutscene.ascendT || 0) + 1;
    cutscene.scammerY = Math.min(520, cutscene.ascendT * cutscene.ascendT * 0.12);
  }
  if (line.gone) cutscene.hideEnemy = true;
  if (line.divineWalk) cutscene.divineIn = true;
  if (cutscene.divineIn) {
    cutscene.divineAlpha = Math.min(1, cutscene.divineAlpha + 0.04);
    cutscene.divineX = Math.min(330, cutscene.divineX + 2.4);
  }
  if (cutscene.flash > 0) cutscene.flash = Math.max(0, cutscene.flash - 0.03);
}

function drawDarkWorldIntroFx(cutscene) {
  const time = performance.now() / 1000;
  // the rift, on the left
  if (cutscene.riftOpen > 0) {
    const x = 60;
    const y = ground - 100;
    const k = cutscene.riftOpen;
    ctx.save();
    ctx.beginPath();
    for (let point = 0; point <= 20; point += 1) {
      const angle = (point / 20) * Math.PI * 2;
      const jag = 1 + Math.sin(angle * 7 + time * 4) * 0.08;
      const px = x + Math.cos(angle) * 40 * k * jag;
      const py = y + Math.sin(angle) * 100 * k * jag;
      if (point === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = '#12002a';
    ctx.fill();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#b388ff';
    ctx.shadowBlur = 18;
    ctx.stroke();
    ctx.restore();
  }
  // Divine General, coming out of the rift behind him... unnoticed
  if (cutscene.divineAlpha > 0 && cutscene.divineActor) {
    const divine = cutscene.divineActor;
    ctx.save();
    ctx.globalAlpha = cutscene.divineAlpha * 0.85;
    divine.position = { x: cutscene.divineX, y: ground - divine.height };
    divine.attacksToTheRight = true;
    divine.isAttacking = false;
    divine.draw();
    ctx.restore();
  }
  if (cutscene.forest) drawDarkForestIntroFx(cutscene);
  // a glint in the black sky
  if (cutscene.skyGlint > 0 && cutscene.descendY < 0) {
    const x = cutscene.scammerX + 30;
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.skyGlint * (0.6 + Math.sin(time * 8) * 0.4)})`;
    ctx.beginPath();
    ctx.moveTo(x, 40);
    ctx.lineTo(x + 6, 54);
    ctx.lineTo(x, 68);
    ctx.lineTo(x - 6, 54);
    ctx.closePath();
    ctx.fill();
  }
  // the flash he leaves in
  if (cutscene.lines[cutscene.lineIndex].ascend) {
    const x = cutscene.scammerX + player2.width / 2;
    const beam = ctx.createLinearGradient(x - 50, 0, x + 50, 0);
    beam.addColorStop(0, 'rgba(255, 255, 255, 0)');
    beam.addColorStop(0.5, 'rgba(255, 255, 255, 0.6)');
    beam.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = beam;
    ctx.fillRect(x - 50, 0, 100, ground);
  }
  // the column of light he comes down in
  if (cutscene.descendY >= 0 && cutscene.descendY < 1.2) {
    const x = cutscene.scammerX + player2.width / 2;
    const k = cutscene.lines[cutscene.lineIndex].descend ? 1 : Math.max(0, 1 - (cutscene.frame / 40));
    const beam = ctx.createLinearGradient(x - 50, 0, x + 50, 0);
    beam.addColorStop(0, 'rgba(255, 255, 255, 0)');
    beam.addColorStop(0.5, `rgba(255, 255, 255, ${0.55 * k})`);
    beam.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = beam;
    ctx.fillRect(x - 50, 0, 100, ground);
  }
  if (cutscene.laterFade > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${0.88 * cutscene.laterFade})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  if (cutscene.rescue) drawChronoChapterRescueFx(cutscene);
  if (cutscene.castle) drawCastleIntroFx(cutscene);
  if (cutscene.reflectScene) drawChronoChapterReflectFx(cutscene);
  if (cutscene.jesterHall) drawChronoLevel6IntroFx(cutscene);
  if (cutscene.overchargeScene) drawChronoOverchargeSceneFx(cutscene);
  if (cutscene.ceilingScene) drawChronoJesterCeilingFx(cutscene);
  if (cutscene.knightDuel) drawChronoKnightDuelFx(cutscene);
  if (cutscene.darkShotScene) drawChronoDarkShotFx(cutscene);
  if (cutscene.titanIntro) drawChronoTitanIntroFx(cutscene);
  if (cutscene.titanBabies) drawChronoTitanBabiesFx(cutscene);
  if (cutscene.titanShot) drawChronoTitanShotFx(cutscene);
  if (cutscene.titan9) drawChronoTitan9SceneFx(cutscene);
  if (cutscene.secretScene) drawChronoSecretSceneFx(cutscene);
  if (cutscene.castle && selectedNormalArcadeLevel === 5) drawLevel5IntroFx(cutscene);
  if (cutscene.orderOutro) drawChronoChapterOrderOutroFx(cutscene);
  if (cutscene.flash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.flash})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

// what Chrono says when he wins (in the chapter)
function getChapterChronoVictoryPhrase(opponent) {
  if (opponent && opponent.secretVariant === 'babyTitan') return '...Esto recien empieza.';
  if (player1.characterType === 'divineGeneral') return getChapterDivineVictoryPhrase(opponent);
  if (isAbnormal(opponent)) return ['Un sparring "amistoso". Claro.', 'Tus trampas tienen el mismo ritmo que tus chistes. Predecibles.', 'Guardia Supremo... de que, exactamente?'][Math.floor(Math.random() * 3)];
  return 'El tiempo sigue de mi lado. Incluso aca.';
}

// ---------- after the fight: "this isn't over"... Chrono doesn't care ----------
