function buildChronoChapterRescueLines() {
  let last = -1;
  try {
    last = Number(localStorage.getItem('moqueteRiverFact') || -1);
  } catch (error) {
    last = -1;
  }
  let pick = Math.floor(Math.random() * chronoChRiverFacts.length);
  if (pick === last) pick = (pick + 1) % chronoChRiverFacts.length;
  try {
    localStorage.setItem('moqueteRiverFact', String(pick));
  } catch (error) {
    // only this session
  }
  return [...chronoChRescueStart, ...chronoChRiverFacts[pick], ...chronoChRescueEnd];
}

function startChronoChapterRescue() {
  chronoCh.rescued = true;
  forestFx.items = [];
  forestFx.dash = null;
  ch6CutsceneBase('originsIntro', buildChronoChapterRescueLines(), 'dialog', {
    darkWorld: true,
    outro: true,
    noVersus: true,
    rescue: true,
    gamblerX: Math.max(60, Math.min(320, player1.position.x)),
    gamblerTargetX: Math.max(60, Math.min(320, player1.position.x)),
    scammerX: 560,
    scammerTargetX: 560,
    scammerY: 0,
    hideEnemy: false,
    lastFlagLine: -1,
    descendY: 2,
    sphere: null,
    hydraFall: 0,
    hoodedX: canvas.width + 60,
    knightsX: canvas.width + 160,
    riverT: 0,
    riverFadeT: 0,
    rings: [],
    dust: [],
    headsDown: 0,
  });
  startCutsceneLine(0);
  playTone({ frequency: 120, duration: 1.4, type: 'sawtooth', volume: 0.05, slideTo: 70 });
}

function updateChronoChapterRescue(cutscene, line, firstFrame) {
  const hydraX = cutscene.scammerX + player2.width / 2;
  // 1) the sphere gathers above the trees
  if (line.sphereCharge && !cutscene.sphere) {
    cutscene.sphere = { x: 240, y: 230, size: 4, state: 'charge', sparks: [] };
    playTone({ frequency: 60, duration: 3, type: 'sawtooth', volume: 0.05, slideTo: 140 });
  }
  const sphere = cutscene.sphere;
  if (sphere && sphere.state === 'charge') {
    sphere.size = Math.min(30, sphere.size + 0.25);
    for (let spark = 0; spark < 2; spark += 1) {
      const angle = Math.random() * Math.PI * 2;
      sphere.sparks.push({ x: sphere.x + Math.cos(angle) * 90, y: sphere.y + Math.sin(angle) * 90, life: 30 });
    }
  }
  if (sphere) {
    sphere.sparks.forEach((spark) => {
      spark.x += (sphere.x - spark.x) * 0.12;
      spark.y += (sphere.y - spark.y) * 0.12;
      spark.life -= 1;
    });
    sphere.sparks = sphere.sparks.filter((spark) => spark.life > 0);
  }
  // 2) it falls on the beast
  if (line.sphereShot && sphere && sphere.state === 'charge') {
    sphere.state = 'shot';
    playTone({ frequency: 900, duration: 0.4, type: 'sine', volume: 0.05, slideTo: 200 });
  }
  // (if the lines go by too fast, the sphere arrives anyway)
  if (sphere && sphere.state !== 'done' && (line.hydraStagger || line.hydraCollapse || line.hydraDown)) {
    sphere.state = 'shot';
    sphere.x = hydraX;
    sphere.y = ground - 110;
  }
  if (!sphere && (line.hydraStagger || line.hydraCollapse || line.hydraDown)) {
    cutscene.sphere = { x: hydraX, y: ground - 110, size: 30, state: 'shot', sparks: [] };
  }
  if (cutscene.sphere && cutscene.sphere.state === 'shot') {
    const sphere = cutscene.sphere;
    const targetY = ground - 110;
    sphere.x += (hydraX - sphere.x) * 0.16;
    sphere.y += (targetY - sphere.y) * 0.16;
    if (Math.hypot(hydraX - sphere.x, targetY - sphere.y) < 14) {
      sphere.state = 'done';
      cutscene.flash = 0.9;
      cutscene.shake = 22;
      cutscene.hydraHit = 1;
      for (let ring = 0; ring < 3; ring += 1) cutscene.rings.push({ x: hydraX, y: targetY, r: 10 + ring * 20, life: 50 });
      playNoise({ duration: 1.4, volume: 0.16, filterFrequency: 500 });
      playTone({ frequency: 55, duration: 1.6, type: 'sawtooth', volume: 0.1, slideTo: 28 });
    }
  }
  cutscene.rings.forEach((ring) => {
    ring.r += 9;
    ring.life -= 1;
  });
  cutscene.rings = cutscene.rings.filter((ring) => ring.life > 0);
  if (cutscene.hydraHit > 0) cutscene.hydraHit = Math.max(0, cutscene.hydraHit - 0.03);
  // 3) it roars, shaking... 4) and it collapses, head after head
  if (line.hydraStagger) {
    cutscene.staggerT = (cutscene.staggerT || 0) + 1;
    if (firstFrame) {
      playTone({ frequency: 180, duration: 1.2, type: 'sawtooth', volume: 0.08, slideTo: 60 });
      playTone({ frequency: 240, duration: 1.2, type: 'square', volume: 0.04, slideTo: 90 });
    }
    cutscene.shake = Math.max(cutscene.shake || 0, 4);
  }
  if (line.hydraCollapse || line.hydraDown) {
    cutscene.collapseT = (cutscene.collapseT || 0) + 1;
    const heads = Math.min(3, Math.floor(cutscene.collapseT / 25) + 1);
    if (heads > cutscene.headsDown) {
      cutscene.headsDown = heads;
      cutscene.shake = 10;
      playNoise({ duration: 0.4, volume: 0.1, filterFrequency: 300 });
      for (let grain = 0; grain < 14; grain += 1) cutscene.dust.push({ x: hydraX + (Math.random() - 0.5) * 140, y: ground - 4, vx: (Math.random() - 0.5) * 3, vy: -1 - Math.random() * 2, life: 50 });
    }
    cutscene.hydraFall = Math.min(1, cutscene.hydraFall + 0.012);
  }
  cutscene.dust.forEach((grain) => {
    grain.x += grain.vx;
    grain.y += grain.vy;
    grain.life -= 1;
  });
  cutscene.dust = cutscene.dust.filter((grain) => grain.life > 0);
  if (!line.hydraStagger && !line.sphereShot) cutscene.shake = (cutscene.shake || 0) * 0.9;
  cutscene.hideEnemy = Boolean(line.hydraStagger || line.hydraCollapse || line.hydraDown || line.river || (sphere && sphere.state === 'done'));
  if (line.hoodedIn) cutscene.hoodedCome = true;
  if (line.knightsIn) cutscene.knightsCome = true;
  if (cutscene.hoodedCome) cutscene.hoodedX += (680 - cutscene.hoodedX) * 0.08;
  if (cutscene.knightsCome) cutscene.knightsX += (800 - cutscene.knightsX) * 0.08;
  if (line.knightsIn && firstFrame && !cutscene.knightSound) {
    cutscene.knightSound = true;
    [0, 260, 520].forEach((delay) => setTimeout(() => playTone({ frequency: 70, duration: 0.2, type: 'square', volume: 0.05 }), delay));
  }
  if (line.river) cutscene.riverT += 1;
  if (line.riverFade && firstFrame) cutscene.riverFadeT = 1;
  if (cutscene.riverFadeT > 0) cutscene.riverFadeT = Math.max(0, cutscene.riverFadeT - 0.015);
  if (line.river) cutscene.gamblerX = -400;
  cutscene.deepGlow = line.deepGlow ? Math.min(1, (cutscene.deepGlow || 0) + 0.02) : Math.max(0, (cutscene.deepGlow || 0) - 0.02);
}

// the hooded one: the same shape as everyone else (a body with a head on top), all under a dark cloak
function drawHoodedFigure(x, baseY, dir, time) {
  const w = 60;
  const h = 120;
  const left = x - w / 2;
  const top = baseY - h;
  ctx.save();
  // the body: a dark violet rectangle, the cloak falling over it
  ctx.fillStyle = '#1e1230';
  ctx.fillRect(left, top, w, h);
  ctx.fillStyle = '#140b22';
  ctx.fillRect(left, top + 44, 10, h - 44);
  ctx.fillRect(left + w - 10, top + 44, 10, h - 44);
  // the hood: a darker block on the head, with a peak
  ctx.fillStyle = '#2a1840';
  ctx.fillRect(left - 3, top - 6, w + 6, 46);
  ctx.beginPath();
  ctx.moveTo(left + w / 2 - 10, top - 6);
  ctx.lineTo(left + w / 2 + dir * -6, top - 18);
  ctx.lineTo(left + w / 2 + 10, top - 6);
  ctx.fill();
  // the face: only darkness, and two violet eyes
  ctx.fillStyle = '#05020a';
  ctx.fillRect(left + 8 + dir * 3, top + 6, w - 16, 28);
  ctx.fillStyle = `rgba(179, 136, 255, ${0.65 + Math.sin(time * 2) * 0.3})`;
  ctx.fillRect(left + 18 + dir * 5, top + 16, 6, 4);
  ctx.fillRect(left + w - 24 + dir * 5, top + 16, 6, 4);
  // a clasp, a sash
  ctx.fillStyle = '#7e57c2';
  ctx.fillRect(left + w / 2 - 4, top + 44, 8, 8);
  ctx.fillStyle = '#311b4f';
  ctx.fillRect(left, top + 82, w, 8);
  // the frayed hem
  ctx.fillStyle = '#1e1230';
  for (let tear = 0; tear < 5; tear += 1) ctx.fillRect(left + 2 + tear * 12, baseY - 2, 6, 4 + (tear % 2) * 4);
  // a dark sphere floating by the hand
  const sx = x + dir * 44;
  const sy = baseY - 62 + Math.sin(time * 3) * 4;
  const glow = ctx.createRadialGradient(sx, sy, 2, sx, sy, 18);
  glow.addColorStop(0, '#000000');
  glow.addColorStop(0.6, '#311b92');
  glow.addColorStop(1, 'rgba(49, 27, 146, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(sx - 18, sy - 18, 36, 36);
  ctx.restore();
}

// a black knight: a tall rectangle in black armor with gold trim, a helm with a white slit, a cape and a spear
function drawBlackKnight(x, baseY, dir, time) {
  const w = 66;
  const h = 138;
  const left = x - w / 2;
  const top = baseY - h;
  ctx.save();
  // cape behind
  ctx.fillStyle = '#060608';
  ctx.beginPath();
  ctx.moveTo(left + (dir > 0 ? 6 : w - 6), top + 38);
  ctx.lineTo(left + (dir > 0 ? -22 : w + 22) + Math.sin(time * 2) * 3, baseY);
  ctx.lineTo(left + (dir > 0 ? 10 : w - 10), baseY);
  ctx.closePath();
  ctx.fill();
  // the body
  ctx.fillStyle = '#121216';
  ctx.fillRect(left, top, w, h);
  ctx.strokeStyle = '#c9a227';
  ctx.lineWidth = 2;
  ctx.strokeRect(left + 1, top + 1, w - 2, h - 2);
  // the helm: the top block, with a burning white slit and a crown of spikes
  ctx.fillStyle = '#1c1c22';
  ctx.fillRect(left + 4, top + 4, w - 8, 40);
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = '#ffffff';
  ctx.shadowBlur = 10;
  ctx.fillRect(left + 12, top + 22, w - 24, 4);
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#121216';
  for (let spike = 0; spike < 4; spike += 1) {
    ctx.beginPath();
    ctx.moveTo(left + 8 + spike * 14, top);
    ctx.lineTo(left + 15 + spike * 14, top - 14);
    ctx.lineTo(left + 22 + spike * 14, top);
    ctx.fill();
  }
  // the breastplate: gold lines and a dark emblem
  ctx.strokeStyle = '#c9a227';
  ctx.beginPath();
  ctx.moveTo(left + 6, top + 48);
  ctx.lineTo(left + w - 6, top + 48);
  ctx.moveTo(left + w / 2, top + 48);
  ctx.lineTo(left + w / 2, top + 98);
  ctx.moveTo(left + 6, top + 100);
  ctx.lineTo(left + w - 6, top + 100);
  ctx.stroke();
  ctx.fillStyle = '#3a2e0a';
  ctx.beginPath();
  ctx.moveTo(left + w / 2, top + 58);
  ctx.lineTo(left + w / 2 + 10, top + 72);
  ctx.lineTo(left + w / 2, top + 86);
  ctx.lineTo(left + w / 2 - 10, top + 72);
  ctx.closePath();
  ctx.fill();
  // pauldrons with spikes
  ctx.fillStyle = '#1c1c22';
  [left - 6, left + w - 10].forEach((px, index) => {
    ctx.fillRect(px, top + 44, 16, 16);
    ctx.beginPath();
    ctx.moveTo(px + 4, top + 44);
    ctx.lineTo(px + (index ? 18 : -2), top + 32);
    ctx.lineTo(px + 12, top + 44);
    ctx.fill();
  });
  // a long black spear
  const spearX = x + dir * 42;
  ctx.strokeStyle = '#2b2b33';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(spearX, baseY);
  ctx.lineTo(spearX, top - 50);
  ctx.stroke();
  ctx.fillStyle = '#c9a227';
  ctx.beginPath();
  ctx.moveTo(spearX - 7, top - 46);
  ctx.lineTo(spearX, top - 72);
  ctx.lineTo(spearX + 7, top - 46);
  ctx.fill();
  ctx.restore();
}

// the river: black water, slow ripples, faint lights below... and the boat
function drawDarkRiverScene(cutscene) {
  const time = performance.now() / 1000;
  ctx.save();
  ctx.fillStyle = '#020104';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  for (let star = 0; star < 24; star += 1) {
    ctx.fillStyle = `rgba(179, 157, 219, ${0.15 + Math.max(0, Math.sin(time + star)) * 0.2})`;
    ctx.fillRect((star * 151) % canvas.width, (star * 37) % 200, 2, 2);
  }
  if (cutscene.lines[cutscene.lineIndex].castleView) {
    ctx.fillStyle = '#0a0308';
    ctx.fillRect(700, 170, 160, 80);
    [[710, 120], [760, 90], [810, 130]].forEach(([tx, ty]) => {
      ctx.fillRect(tx, ty, 26, 250 - ty);
      ctx.beginPath();
      ctx.moveTo(tx - 4, ty);
      ctx.lineTo(tx + 13, ty - 34);
      ctx.lineTo(tx + 30, ty);
      ctx.fill();
    });
    ctx.fillStyle = 'rgba(255, 112, 67, 0.6)';
    [[719, 140], [769, 110], [819, 150]].forEach(([wx, wy]) => ctx.fillRect(wx, wy, 6, 9));
  }
  ctx.fillStyle = '#07040c';
  ctx.beginPath();
  ctx.moveTo(0, 250);
  ctx.quadraticCurveTo(300, 230, 600, 255);
  ctx.quadraticCurveTo(850, 270, canvas.width, 245);
  ctx.lineTo(canvas.width, 280);
  ctx.lineTo(0, 280);
  ctx.closePath();
  ctx.fill();
  const water = ctx.createLinearGradient(0, 270, 0, canvas.height);
  water.addColorStop(0, '#05030c');
  water.addColorStop(1, '#0d0820');
  ctx.fillStyle = water;
  ctx.fillRect(0, 270, canvas.width, canvas.height - 270);
  ctx.strokeStyle = 'rgba(149, 117, 205, 0.25)';
  ctx.lineWidth = 2;
  for (let ripple = 0; ripple < 16; ripple += 1) {
    let rx = (ripple * 137 - time * 40) % (canvas.width + 200);
    if (rx < -100) rx += canvas.width + 200;
    ctx.beginPath();
    ctx.ellipse(rx, 300 + (ripple % 6) * 40, 40, 3, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  // lights deep under the water (brighter while he speaks of what sleeps there)
  const deep = cutscene.deepGlow || 0;
  for (let light = 0; light < 9; light += 1) {
    let lx = (light * 173 - time * 15) % canvas.width;
    if (lx < 0) lx += canvas.width;
    ctx.fillStyle = `rgba(124, 77, 255, ${0.15 + Math.sin(time * 1.5 + light) * 0.1 + deep * 0.35})`;
    ctx.beginPath();
    ctx.arc(lx, 420 + (light % 3) * 40, 8 + deep * 6, 0, Math.PI * 2);
    ctx.fill();
  }
  const boatX = 380;
  const boatY = 380 + Math.sin(time * 1.4) * 4;
  player1.position = { x: boatX + 30, y: boatY - player1.height + 20 };
  player1.attacksToTheRight = true;
  player1.isAttacking = false;
  player1.draw();
  drawHoodedFigure(boatX + 190, boatY + 18, -1, time);
  ctx.fillStyle = '#2b1a12';
  ctx.beginPath();
  ctx.moveTo(boatX - 20, boatY);
  ctx.lineTo(boatX + 260, boatY);
  ctx.lineTo(boatX + 230, boatY + 34);
  ctx.lineTo(boatX + 10, boatY + 34);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#4e342e';
  ctx.fillRect(boatX - 20, boatY - 4, 280, 6);
  ctx.strokeStyle = '#3e2723';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(boatX + 230, boatY - 50);
  ctx.lineTo(boatX + 260 + Math.sin(time * 1.4) * 10, boatY + 50);
  ctx.stroke();
  ctx.fillStyle = '#1b1b1b';
  ctx.fillRect(boatX - 16, boatY - 34, 4, 30);
  const glow = ctx.createRadialGradient(boatX - 14, boatY - 40, 2, boatX - 14, boatY - 40, 40);
  glow.addColorStop(0, 'rgba(179, 136, 255, 0.8)');
  glow.addColorStop(1, 'rgba(179, 136, 255, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(boatX - 54, boatY - 80, 80, 80);
  ctx.fillStyle = 'rgba(179, 136, 255, 0.12)';
  ctx.fillRect(boatX - 20, boatY + 40, 280, 8);
  ctx.restore();
  player1.position = { x: -400, y: ground - player1.height };
}

function drawChronoChapterRescueFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  if (line.river) {
    drawDarkRiverScene(cutscene);
    if (cutscene.riverFadeT > 0) {
      ctx.fillStyle = `rgba(0, 0, 0, ${cutscene.riverFadeT})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
    return;
  }
  // the beast, after the hit: shaking, roaring... and falling, head by head
  const hit = cutscene.sphere && cutscene.sphere.state === 'done';
  if (hit) {
    ctx.save();
    const pivotX = cutscene.scammerX + player2.width / 2;
    const shakeX = line.hydraStagger ? (Math.random() - 0.5) * 8 : 0;
    ctx.translate(pivotX + shakeX, ground);
    ctx.rotate(-cutscene.hydraFall * 0.15);
    ctx.scale(1, 1 - cutscene.hydraFall * 0.4);
    player2.position = { x: -player2.width / 2, y: -player2.height };
    player2.isAttacking = Boolean(line.hydraStagger);
    drawHydraBeast(player2);
    player2.isAttacking = false;
    ctx.restore();
    player2.position = { x: cutscene.scammerX, y: ground - player2.height };
    if (cutscene.hydraHit > 0) {
      ctx.fillStyle = `rgba(124, 77, 255, ${cutscene.hydraHit * 0.6})`;
      ctx.fillRect(cutscene.scammerX - 30, ground - player2.height - 20, player2.width + 60, player2.height + 20);
    }
  }
  cutscene.rings.forEach((ring) => {
    ctx.strokeStyle = `rgba(179, 136, 255, ${ring.life / 50})`;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(ring.x, ring.y, ring.r, 0, Math.PI * 2);
    ctx.stroke();
  });
  cutscene.dust.forEach((grain) => {
    ctx.fillStyle = `rgba(120, 100, 140, ${grain.life / 50})`;
    ctx.fillRect(grain.x, grain.y, 4, 4);
  });
  // the dark sphere, charging and then falling
  const sphere = cutscene.sphere;
  if (sphere && sphere.state !== 'done') {
    if (sphere.state === 'charge') {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
    sphere.sparks.forEach((spark) => {
      ctx.fillStyle = '#b388ff';
      ctx.fillRect(spark.x - 2, spark.y - 2, 4, 4);
    });
    const size = sphere.size;
    const glow = ctx.createRadialGradient(sphere.x, sphere.y, 2, sphere.x, sphere.y, size * 2.2);
    glow.addColorStop(0, '#000000');
    glow.addColorStop(0.5, '#311b92');
    glow.addColorStop(1, 'rgba(124, 77, 255, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(sphere.x - size * 2.2, sphere.y - size * 2.2, size * 4.4, size * 4.4);
    ctx.strokeStyle = 'rgba(179, 136, 255, 0.85)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(sphere.x, sphere.y, size + Math.sin(time * 10) * 2, 0, Math.PI * 2);
    ctx.stroke();
    if (sphere.state === 'shot') {
      ctx.strokeStyle = 'rgba(124, 77, 255, 0.5)';
      ctx.lineWidth = size;
      ctx.beginPath();
      ctx.moveTo(240, 230);
      ctx.lineTo(sphere.x, sphere.y);
      ctx.stroke();
    }
  }
  if (cutscene.hoodedX < canvas.width + 40) drawHoodedFigure(cutscene.hoodedX, ground, -1, time);
  if (cutscene.knightsX < canvas.width + 140) {
    drawBlackKnight(cutscene.knightsX, ground, -1, time);
    drawBlackKnight(cutscene.knightsX + 100, ground, -1, time + 1);
  }
}

// ================= LEVEL 4: the castle... and the Dark Order =================
// the Dark Order: the same dark knights (and their captain) that troubled Knight in chapter 5
chronoChLevels[4] = { enemies: ['darkKnight', 'darkKnight', 'darkKnight', 'darkKnight', 'darkKnightBoss'], difficulties: ['medium', 'hard', 'hard', 'hard', 'hard'], health: [170, 180, 190, 200, 380] };
const orderMembers = {
  orderThird: { name: 'El Vigia', robe: '#1e0a2e', trim: '#9575cd', symbol: 'eye', size: [64, 128], health: 210, speed: 1.05, damage: 1 },
  orderSecond: { name: 'La Luna', robe: '#14143b', trim: '#90caf9', symbol: 'moon', size: [64, 128], health: 240, speed: 1.1, damage: 1.05 },
  orderLeader: { name: 'El Regente', robe: '#3b0a14', trim: '#c9a227', symbol: 'crown', size: [72, 142], health: 330, speed: 0.95, damage: 1.2 },
};
Object.entries(orderMembers).forEach(([variant, data]) => {
  if (!originsVariants.includes(variant)) originsVariants.push(variant);
  if (!arcadeBossVariants.includes(variant)) arcadeBossVariants.push(variant);
  originsSizes[variant] = data.size;
  originsSpeeds[variant] = data.speed;
  originsDamage[variant] = data.damage;
  originsHealth[variant] = data.health;
  originsNames[variant] = data.name;
});
// the Order's own theme (chapter 5's dark-order.wav), played a little faster and lower: their castle, their rules
reflecterBattleTrackSources.orderBattle = encodeURI('assetsaudio/Marcha de la Orden (Moquete).wav');
reflecterBattleTrackVolumes.orderBattle = 1;
const reflecterBattleTrackRates = {};

function isOrderMember(fighter) {
  return Boolean(fighter && orderMembers[fighter.secretVariant]);
}

// a robed member of the Order: the same block shape as everyone, a white mask with their sign, gold trim
function drawOrderMemberBody(x, y, w, h, variant, dir, time, attacking) {
  const data = orderMembers[variant];
  ctx.save();
  // the robe
  ctx.fillStyle = data.robe;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  ctx.fillRect(x, y + 40, 10, h - 40);
  ctx.fillRect(x + w - 10, y + 40, 10, h - 40);
  // the hood around the mask
  ctx.fillStyle = '#0a0410';
  ctx.fillRect(x - 3, y - 4, w + 6, 42);
  // the mask
  ctx.fillStyle = '#eceff1';
  ctx.fillRect(x + 10 + dir * 2, y + 4, w - 20, 30);
  ctx.fillStyle = '#111';
  ctx.fillRect(x + 18 + dir * 3, y + 14, 6, 3);
  ctx.fillRect(x + w - 24 + dir * 3, y + 14, 6, 3);
  // the sign of each one
  const cx = x + w / 2 + dir * 2;
  ctx.fillStyle = data.trim;
  if (data.symbol === 'eye') {
    ctx.beginPath();
    ctx.ellipse(cx, y + 26, 8, 4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#111';
    ctx.beginPath();
    ctx.arc(cx, y + 26, 2, 0, Math.PI * 2);
    ctx.fill();
  } else if (data.symbol === 'moon') {
    ctx.beginPath();
    ctx.arc(cx, y + 26, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#eceff1';
    ctx.beginPath();
    ctx.arc(cx + 3, y + 24, 5, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.moveTo(cx - 9, y + 30);
    ctx.lineTo(cx - 9, y + 22);
    ctx.lineTo(cx - 4, y + 26);
    ctx.lineTo(cx, y + 20);
    ctx.lineTo(cx + 4, y + 26);
    ctx.lineTo(cx + 9, y + 22);
    ctx.lineTo(cx + 9, y + 30);
    ctx.closePath();
    ctx.fill();
    // a real crown on the hood
    ctx.fillStyle = data.trim;
    for (let spike = 0; spike < 5; spike += 1) {
      ctx.beginPath();
      ctx.moveTo(x + 6 + spike * ((w - 12) / 5), y - 4);
      ctx.lineTo(x + 6 + spike * ((w - 12) / 5) + (w - 12) / 10, y - 18);
      ctx.lineTo(x + 6 + (spike + 1) * ((w - 12) / 5), y - 4);
      ctx.fill();
    }
  }
  // gold trim: collar, sash, hem
  ctx.fillStyle = data.trim;
  ctx.fillRect(x, y + 38, w, 4);
  ctx.fillRect(x + w / 2 - 3, y + 42, 6, h - 54);
  ctx.fillRect(x, y + h - 8, w, 4);
  // a dark aura
  ctx.strokeStyle = `rgba(124, 77, 255, ${0.25 + Math.sin(time * 3 + x) * 0.15})`;
  ctx.lineWidth = 2;
  ctx.strokeRect(x - 4, y - 8, w + 8, h + 10);
  if (attacking) {
    ctx.fillStyle = 'rgba(124, 77, 255, 0.4)';
    ctx.fillRect(x + (dir > 0 ? w : -60), y + 50, 60, 30);
  }
  ctx.restore();
}

function drawOrderMember(fighter) {
  drawOrderMemberBody(fighter.position.x, fighter.position.y, fighter.width, fighter.height, fighter.secretVariant, fighter.attacksToTheRight ? 1 : -1, performance.now() / 1000, false);
  if (fighter.isAttacking) {
    ctx.fillStyle = 'rgba(124, 77, 255, 0.4)';
    const area = fighter.attackArea;
    ctx.fillRect(area.x, area.y, area.width, area.height);
  }
}

// ---------- their abilities ----------
const orderFx = { items: [], dim: 0 };

function isChapterDarkKnight(fighter) {
  return Boolean(isChronoChapterFight() && selectedNormalArcadeLevel === 4 && fighter === player2 && (fighter.secretVariant === 'darkKnight' || fighter.secretVariant === 'darkKnightBoss'));
}

function castOrderAbility(monster) {
  const step = forestFx.step;
  forestFx.step += 1;
  const px = getFighterCenterX(player1);
  const mx = getFighterCenterX(monster);
  const dir = px > mx ? 1 : -1;
  const style = monster.secretVariant === 'darkKnightBoss' ? 'captain' : normalArcadeEnemyIndex % 2 === 1 ? 'blade' : 'lance';
  if (style === 'blade') {
    if (step % 2 === 0) {
      // dark slashes that fly out and come back
      showFlametombThought(monster, 'Corte sombrio!');
      [player1.position.y + 30, player1.position.y + 90].forEach((y) => orderFx.items.push({ kind: 'crescent', x: mx, y, vx: dir * 11, back: -dir * 0.32, life: 160, hit: false }));
    } else {
      // chains out of the floor
      showFlametombThought(monster, 'Quieto ahi, relojito.');
      [px - 70, px + 70].forEach((x, index) => orderFx.items.push({ kind: 'chain', x: Math.max(30, Math.min(canvas.width - 30, x)), t: -index * 10, hit: false }));
    }
  } else if (style === 'lance') {
    if (step % 2 === 0) {
      // a lance thrust that crosses the whole room at his height
      showFlametombThought(monster, 'Te tengo en la mira.');
      orderFx.items.push({ kind: 'gaze', y: player1.position.y + player1.height / 2, t: 0, hit: false });
    } else {
      // the torches go out, and a wave of shadow runs along the floor
      showFlametombThought(monster, 'Apaguen las antorchas!');
      orderFx.dim = 1;
      [-1, 1].forEach((side) => forestFx.items.push({ kind: 'wave', x: mx, dir: side, life: 120, hit: false }));
    }
  } else if (step % 3 === 0) {
    showFlametombThought(monster, 'De rodillas.');
    [px - 80, px, px + 80].forEach((x, index) => orderFx.items.push({ kind: 'chain', x: Math.max(30, Math.min(canvas.width - 30, x)), t: -index * 10, hit: false }));
  } else if (step % 3 === 1) {
    showFlametombThought(monster, 'Orden! Lanzas!');
    for (let spear = 0; spear < 6; spear += 1) orderFx.items.push({ kind: 'spear', x: 80 + Math.random() * (canvas.width - 160), y: -40 - spear * 50, vy: 7, warn: 30, hit: false, life: 200 });
  } else {
    // the captain's slam: a black pillar comes down on you
    showFlametombThought(monster, 'El General no perdona.');
    orderFx.items.push({ kind: 'throne', x: px, t: 0, hit: false });
  }
  playTone({ frequency: 140, duration: 0.5, type: 'sawtooth', volume: 0.04, slideTo: 90 });
}

function updateOrderFx() {
  if (orderFx.dim > 0) orderFx.dim = Math.max(0, orderFx.dim - 0.006);
  const px = getFighterCenterX(player1);
  const py = player1.position.y + player1.height / 2;
  orderFx.items.forEach((item) => {
    if (item.kind === 'gaze') {
      item.t += 1;
      if (item.t < 45) item.y += (py - item.y) * 0.05;
      if (item.t >= 45 && item.t < 70 && !item.hit && Math.abs(py - item.y) < 34) {
        item.hit = true;
        forestHit(14);
      }
      item.life = 75 - item.t;
    } else if (item.kind === 'eye') {
      const angle = Math.atan2(py - item.y, px - item.x);
      item.vx += Math.cos(angle) * 0.12;
      item.vy += Math.sin(angle) * 0.12;
      item.vx *= 0.96;
      item.vy *= 0.96;
      item.x += item.vx;
      item.y += item.vy;
      item.life -= 1;
      if (!item.hit && touchesChrono(item.x, item.y, 10)) {
        item.hit = true;
        item.life = 0;
        forestHit(7);
      }
    } else if (item.kind === 'crescent') {
      item.x += item.vx;
      item.vx += item.back;
      item.life -= 1;
      if (!item.hit && touchesChrono(item.x, item.y, 14)) {
        item.hit = true;
        forestHit(9);
      }
    } else if (item.kind === 'chain') {
      item.t += 1;
      if (item.t === 40 && Math.abs(px - item.x) < 36 && player1.position.y + player1.height > ground - 30) {
        forestHit(10);
        player1.icedSlowTimer = Math.max(player1.icedSlowTimer || 0, 70);
      }
      item.life = 80 - item.t;
    } else if (item.kind === 'spear') {
      if (item.warn > 0) item.warn -= 1;
      else item.y += item.vy;
      if (!item.hit && touchesChrono(item.x, item.y, 6)) {
        item.hit = true;
        item.life = 0;
        forestHit(8);
      }
      if (item.y > ground) item.life = 0;
      else item.life -= 1;
    } else if (item.kind === 'throne') {
      item.t += 1;
      if (item.t < 50) item.x += (px - item.x) * 0.04;
      if (item.t === 55) {
        playNoise({ duration: 0.6, volume: 0.12, filterFrequency: 300 });
        if (Math.abs(px - item.x) < 60) forestHit(18, 6);
      }
      item.life = 85 - item.t;
    }
  });
  orderFx.items = orderFx.items.filter((item) => item.life > 0 && (item.x === undefined || (item.x > -80 && item.x < canvas.width + 80)));
}

function drawOrderFx() {
  const time = performance.now() / 1000;
  ctx.save();
  if (orderFx.dim > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${orderFx.dim * 0.6})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  orderFx.items.forEach((item) => {
    if (item.kind === 'gaze') {
      if (item.t < 45) {
        ctx.strokeStyle = `rgba(179, 136, 255, ${0.3 + (item.t / 45) * 0.6})`;
        ctx.setLineDash([10, 8]);
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, item.y);
        ctx.lineTo(canvas.width, item.y);
        ctx.stroke();
        ctx.setLineDash([]);
      } else {
        const k = 1 - (item.t - 45) / 30;
        const beam = ctx.createLinearGradient(0, item.y - 30, 0, item.y + 30);
        beam.addColorStop(0, 'rgba(124, 77, 255, 0)');
        beam.addColorStop(0.5, `rgba(255, 255, 255, ${k})`);
        beam.addColorStop(1, 'rgba(124, 77, 255, 0)');
        ctx.fillStyle = beam;
        ctx.fillRect(0, item.y - 30, canvas.width, 60);
      }
    } else if (item.kind === 'eye') {
      ctx.fillStyle = '#eceff1';
      ctx.beginPath();
      ctx.ellipse(item.x, item.y, 12, 7, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#7c4dff';
      ctx.beginPath();
      ctx.arc(item.x + item.vx, item.y + item.vy, 4, 0, Math.PI * 2);
      ctx.fill();
    } else if (item.kind === 'crescent') {
      ctx.save();
      ctx.translate(item.x, item.y);
      ctx.rotate(time * 12);
      ctx.fillStyle = '#bbdefb';
      ctx.shadowColor = '#90caf9';
      ctx.shadowBlur = 12;
      ctx.beginPath();
      ctx.arc(0, 0, 16, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(7, -3, 14, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    } else if (item.kind === 'chain') {
      if (item.t < 0) return;
      if (item.t < 40) {
        ctx.fillStyle = `rgba(201, 162, 39, ${0.3 + Math.sin(time * 20) * 0.2})`;
        ctx.fillRect(item.x - 24, ground - 4, 48, 6);
      } else {
        const rise = Math.min(1, (item.t - 40) / 6) * (item.t > 70 ? Math.max(0, 1 - (item.t - 70) / 10) : 1);
        ctx.strokeStyle = '#5d5d66';
        ctx.lineWidth = 3;
        for (let link = 0; link < 8; link += 1) {
          ctx.beginPath();
          ctx.ellipse(item.x + Math.sin(link) * 3, ground - link * 14 * rise, 5, 8, 0, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
    } else if (item.kind === 'spear') {
      if (item.warn > 0) {
        ctx.fillStyle = 'rgba(201, 162, 39, 0.5)';
        ctx.fillRect(item.x - 2, ground - 4, 4, 6);
        return;
      }
      ctx.strokeStyle = '#2b2b33';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(item.x, item.y - 60);
      ctx.lineTo(item.x, item.y);
      ctx.stroke();
      ctx.fillStyle = '#c9a227';
      ctx.beginPath();
      ctx.moveTo(item.x - 5, item.y - 4);
      ctx.lineTo(item.x, item.y + 12);
      ctx.lineTo(item.x + 5, item.y - 4);
      ctx.fill();
    } else if (item.kind === 'throne') {
      if (item.t < 55) {
        ctx.strokeStyle = `rgba(201, 162, 39, ${0.4 + Math.sin(time * 20) * 0.3})`;
        ctx.setLineDash([8, 6]);
        ctx.lineWidth = 2;
        ctx.strokeRect(item.x - 55, 0, 110, ground);
        ctx.setLineDash([]);
      } else {
        const k = 1 - (item.t - 55) / 30;
        ctx.fillStyle = `rgba(10, 4, 16, ${k})`;
        ctx.fillRect(item.x - 55, 0, 110, ground);
        ctx.strokeStyle = `rgba(201, 162, 39, ${k})`;
        ctx.lineWidth = 3;
        ctx.strokeRect(item.x - 55, 0, 110, ground);
      }
    }
  });
  ctx.restore();
}

// ---------- Chrono, powered by the machine (only he notices) ----------
function drawChronoMachineSurge(fighter, strength) {
  if (strength <= 0) return;
  const time = performance.now() / 1000;
  const dir = fighter.attacksToTheRight ? 1 : -1;
  const sx = dir > 0 ? fighter.position.x + fighter.width - 10 : fighter.position.x + 10;
  const sy = fighter.position.y + 18;
  ctx.save();
  for (let spark = 0; spark < 6 * strength; spark += 1) {
    const angle = time * 9 + spark * 1.3;
    const radius = 8 + ((time * 60 + spark * 7) % 24);
    ctx.fillStyle = spark % 2 ? '#ea80fc' : '#ffffff';
    ctx.fillRect(sx + Math.cos(angle) * radius, sy + Math.sin(angle) * radius, 3, 3);
  }
  ctx.strokeStyle = `rgba(179, 136, 255, ${0.25 * strength + Math.sin(time * 8) * 0.1})`;
  ctx.lineWidth = 2;
  ctx.strokeRect(fighter.position.x - 5, fighter.position.y - 5, fighter.width + 10, fighter.height + 10);
  ctx.restore();
}

// ---------- the castle: its outside and its curious rooms ----------
function drawCastleRoomBase(wall, floor) {
  ctx.fillStyle = wall;
  ctx.fillRect(0, 0, canvas.width, ground);
  ctx.fillStyle = floor;
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  for (let tile = 0; tile < canvas.width; tile += 64) ctx.fillRect(tile, ground, 2, canvas.height - ground);
  ctx.fillStyle = '#2a1840';
  ctx.fillRect(0, ground - 6, canvas.width, 6);
}

function drawCastleGateStage() {
  const time = performance.now() / 1000;
  ctx.fillStyle = '#020104';
  ctx.fillRect(0, 0, canvas.width, ground);
  for (let star = 0; star < 20; star += 1) {
    ctx.fillStyle = `rgba(179, 157, 219, ${0.15 + Math.max(0, Math.sin(time + star)) * 0.2})`;
    ctx.fillRect((star * 151) % canvas.width, (star * 37) % 140, 2, 2);
  }
  // the castle wall and its huge gate, very close now
  ctx.fillStyle = '#0d0610';
  ctx.fillRect(380, 60, 644, ground - 60);
  for (let merlon = 0; merlon < 17; merlon += 1) ctx.fillRect(380 + merlon * 40, 40, 24, 24);
  [[420, 0], [960, 0]].forEach(([tx]) => {
    ctx.fillRect(tx - 30, 0, 60, ground);
    ctx.fillStyle = 'rgba(255, 112, 67, 0.45)';
    ctx.fillRect(tx - 4, 80, 8, 14);
    ctx.fillStyle = '#0d0610';
  });
  ctx.fillStyle = '#050206';
  ctx.beginPath();
  ctx.moveTo(620, ground);
  ctx.lineTo(620, 220);
  ctx.arc(700, 220, 80, Math.PI, 0);
  ctx.lineTo(780, ground);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#2a1840';
  ctx.lineWidth = 6;
  ctx.stroke();
  // the dock and the black river
  ctx.fillStyle = '#05030c';
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
  ctx.fillStyle = '#2b1a12';
  ctx.fillRect(0, ground - 6, 380, 10);
  ctx.fillStyle = '#1a0f0a';
  for (let post = 0; post < 5; post += 1) ctx.fillRect(20 + post * 80, ground, 10, 40);
  ctx.fillStyle = '#120a16';
  ctx.fillRect(380, ground - 6, 644, 10);
}

function castleWalkProgress() {
  // how far Chrono has walked through the current room (0..1), for the room's little events
  const cutscene = arcadeCutscene;
  if (!cutscene || !cutscene.active || !cutscene.castle) return 0;
  return Math.max(0, Math.min(1, (cutscene.gamblerX - 100) / 500));
}

function drawCastleClocksStage() {
  const time = performance.now() / 1000;
  const cutscene = arcadeCutscene;
  drawCastleRoomBase('#120c1a', '#0c0812');
  const walk = castleWalkProgress();
  for (let clock = 0; clock < 7; clock += 1) {
    const cx = 80 + clock * 145;
    const cy = 150 + (clock % 2) * 70;
    const near = cutscene && cutscene.active && Math.abs(cutscene.gamblerX + 30 - cx) < 70;
    // the clock he passes by moves forward one second... the only one in the castle
    const woke = near && cutscene.lines[cutscene.lineIndex].tick;
    ctx.fillStyle = '#2a1c10';
    ctx.fillRect(cx - 34, cy - 34, 68, 68);
    ctx.fillStyle = woke ? '#fff8e1' : '#e8dcc2';
    if (woke) {
      ctx.shadowColor = '#4fc3f7';
      ctx.shadowBlur = 20;
    }
    ctx.beginPath();
    ctx.arc(cx, cy, 26, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#111';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx, cy - 20);
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx - 2, cy - 14);
    ctx.stroke();
    ctx.strokeStyle = woke ? '#0288d1' : '#c62828';
    ctx.lineWidth = 1.5;
    const twitch = woke ? 0.1 + ((time * 2) % 1) * 0.1 : -0.1 + (Math.floor(time * 2 + clock) % 2) * 0.1;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.sin(twitch) * 22, cy - Math.cos(twitch) * 22);
    ctx.stroke();
    if (clock % 2 === 0) {
      ctx.strokeStyle = '#4e342e';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(cx, cy + 34);
      ctx.lineTo(cx + Math.sin(twitch * 3) * 10, cy + 110);
      ctx.stroke();
    }
  }
  ctx.fillStyle = `rgba(0, 0, 0, ${0.2 - walk * 0.1})`;
  ctx.fillRect(0, 0, canvas.width, ground);
}

function drawCastleMirrorsStage() {
  const time = performance.now() / 1000;
  const cutscene = arcadeCutscene;
  drawCastleRoomBase('#0e0e18', '#0a0a12');
  for (let mirror = 0; mirror < 5; mirror += 1) {
    const mx = 70 + mirror * 200;
    ctx.fillStyle = '#c9a227';
    ctx.fillRect(mx - 4, 80, 108, 260);
    const glass = ctx.createLinearGradient(mx, 84, mx + 100, 340);
    glass.addColorStop(0, '#2c3448');
    glass.addColorStop(0.5, '#4a5878');
    glass.addColorStop(1, '#1b2030');
    ctx.fillStyle = glass;
    ctx.fillRect(mx, 84, 100, 252);
    // Chrono's reflection: a second late... and in one mirror, it stays behind and waves
    if (cutscene && cutscene.active && cutscene.castle) {
      const history = cutscene.walkHistory || [];
      const late = history.length > 50 ? history[history.length - 50] : cutscene.gamblerX;
      const line = cutscene.lines[cutscene.lineIndex];
      const stuck = line.wave && mirror === 1;
      const reflectX = stuck ? mx + 30 : late + 18 - (mx - 70) * 0 ;
      if (stuck || (reflectX > mx && reflectX < mx + 70)) {
        const rx = stuck ? mx + 30 : reflectX;
        ctx.fillStyle = 'rgba(21, 32, 64, 0.85)';
        ctx.fillRect(rx, 190, 34, 70);
        ctx.fillStyle = 'rgba(0, 229, 255, 0.7)';
        ctx.fillRect(rx + 8, 200, 5, 4);
        ctx.fillRect(rx + 20, 200, 5, 4);
        if (stuck) {
          // the wave
          ctx.save();
          ctx.translate(rx + 34, 210);
          ctx.rotate(-0.8 + Math.sin(time * 8) * 0.5);
          ctx.fillStyle = 'rgba(21, 32, 64, 0.85)';
          ctx.fillRect(0, -3, 22, 6);
          ctx.restore();
        }
      }
    }
    ctx.fillStyle = 'rgba(255, 255, 255, 0.12)';
    ctx.fillRect(mx + 10, 90, 8, 200);
  }
}

function drawCastleDiningStage() {
  const time = performance.now() / 1000;
  const cutscene = arcadeCutscene;
  const line = cutscene && cutscene.active && cutscene.castle ? cutscene.lines[cutscene.lineIndex] : {};
  drawCastleRoomBase('#160a0e', '#0e0608');
  ctx.strokeStyle = '#4e342e';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(512, 0);
  ctx.lineTo(512, 80);
  ctx.stroke();
  ctx.fillStyle = '#3a2a10';
  ctx.fillRect(432, 80, 160, 10);
  // the candles light up, one by one, as he walks by
  const walk = castleWalkProgress();
  for (let candle = 0; candle < 5; candle += 1) {
    ctx.fillStyle = '#d7ccc8';
    ctx.fillRect(440 + candle * 36, 64, 6, 16);
    if (walk > candle * 0.2) {
      ctx.fillStyle = `rgba(255, 171, 64, ${0.6 + Math.sin(time * 8 + candle) * 0.2})`;
      ctx.fillRect(441 + candle * 36, 58, 4, 6);
    }
  }
  ctx.fillStyle = '#3e2418';
  ctx.fillRect(120, ground - 90, 720, 20);
  ctx.fillRect(140, ground - 70, 14, 70);
  ctx.fillRect(806, ground - 70, 14, 70);
  ctx.fillStyle = '#d7ccc8';
  for (let plate = 0; plate < 8; plate += 1) {
    ctx.beginPath();
    ctx.ellipse(170 + plate * 82, ground - 92, 18, 5, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // the king's chair at the head: it creaks, as if someone had just stood up
  const creak = line.creak ? Math.sin(time * 30) * 2 : 0;
  ctx.save();
  ctx.translate(900 + creak, ground);
  ctx.rotate(line.creak ? Math.sin(time * 10) * 0.02 : 0);
  ctx.fillStyle = '#5c0f1a';
  ctx.fillRect(0, -200, 60, 200);
  ctx.fillStyle = '#c9a227';
  ctx.fillRect(0, -206, 60, 8);
  ctx.restore();
  for (let mote = 0; mote < 25; mote += 1) {
    ctx.fillStyle = 'rgba(215, 204, 200, 0.25)';
    ctx.fillRect((mote * 71 + Math.sin(time * 0.5 + mote) * 20) % canvas.width, (mote * 37 + time * 6) % ground, 2, 2);
  }
}

// the gallery: portraits with their faces scratched out... and one big one, of the king and his beast
function drawCastleGalleryStage() {
  const time = performance.now() / 1000;
  drawCastleRoomBase('#100a10', '#0a060a');
  // a long red carpet
  ctx.fillStyle = '#3b0a14';
  ctx.fillRect(0, ground - 2, canvas.width, 6);
  // small portraits, faces scratched out
  [80, 230, 760, 900].forEach((px, index) => {
    ctx.fillStyle = '#c9a227';
    ctx.fillRect(px - 4, 120, 88, 118);
    ctx.fillStyle = ['#2a1c2e', '#1c2a2e', '#2e221c', '#1c1c2e'][index];
    ctx.fillRect(px, 124, 80, 110);
    ctx.fillStyle = '#4a3a4a';
    ctx.fillRect(px + 24, 160, 32, 74);
    ctx.fillRect(px + 28, 136, 24, 24);
    ctx.strokeStyle = '#120a10';
    ctx.lineWidth = 2;
    for (let scratch = 0; scratch < 5; scratch += 1) {
      ctx.beginPath();
      ctx.moveTo(px + 24 + scratch * 5, 134);
      ctx.lineTo(px + 30 + scratch * 5, 162);
      ctx.stroke();
    }
  });
  // the big portrait in the middle: the king, his face covered with a black cloth... and beside him, a huge white beast
  const bx = 380;
  ctx.fillStyle = '#c9a227';
  ctx.fillRect(bx - 6, 60, 272, 270);
  ctx.fillStyle = '#1a0f1e';
  ctx.fillRect(bx, 66, 260, 258);
  // the king, on his throne
  ctx.fillStyle = '#5c0f1a';
  ctx.fillRect(bx + 30, 150, 70, 170);
  ctx.fillStyle = '#2a0a12';
  ctx.fillRect(bx + 42, 180, 46, 140);
  ctx.fillStyle = '#c9a227';
  for (let spike = 0; spike < 4; spike += 1) {
    ctx.beginPath();
    ctx.moveTo(bx + 46 + spike * 10, 140);
    ctx.lineTo(bx + 51 + spike * 10, 126);
    ctx.lineTo(bx + 56 + spike * 10, 140);
    ctx.fill();
  }
  ctx.fillStyle = '#050205';
  ctx.fillRect(bx + 46, 140, 38, 40);
  // the beast: white, enormous, with ribs (it looks a lot like someone Chrono knows)
  ctx.fillStyle = '#f5f5f5';
  ctx.fillRect(bx + 130, 130, 110, 190);
  ctx.strokeStyle = '#111';
  ctx.lineWidth = 3;
  for (let rib = 0; rib < 5; rib += 1) {
    ctx.beginPath();
    ctx.moveTo(bx + 150, 200 + rib * 18);
    ctx.quadraticCurveTo(bx + 185, 190 + rib * 18, bx + 220, 200 + rib * 18);
    ctx.stroke();
  }
  ctx.fillStyle = '#111';
  ctx.fillRect(bx + 160, 150, 12, 10);
  ctx.fillRect(bx + 198, 150, 12, 10);
  ctx.fillRect(bx + 170, 172, 30, 4);
  // a faint glow on the plaque
  ctx.fillStyle = `rgba(201, 162, 39, ${0.5 + Math.sin(time * 2) * 0.2})`;
  ctx.fillRect(bx + 90, 334, 80, 10);
}

function drawOrderChamberStage() {
  const time = performance.now() / 1000;
  // red walls, red light: the Order doesn't clean
  const wall = ctx.createLinearGradient(0, 0, 0, ground);
  wall.addColorStop(0, '#120406');
  wall.addColorStop(1, '#2a0a0c');
  ctx.fillStyle = wall;
  ctx.fillRect(0, 0, canvas.width, ground);
  ctx.fillStyle = '#140507';
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  for (let tile = 0; tile < canvas.width; tile += 64) ctx.fillRect(tile + (tile % 128 ? 6 : 0), ground, 2, canvas.height - ground);
  ctx.fillStyle = '#3a0c10';
  ctx.fillRect(0, ground - 6, canvas.width, 6);
  // cracks in the walls
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.6)';
  ctx.lineWidth = 2;
  [[150, 60], [640, 90], [880, 40]].forEach(([cx, cy]) => {
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + 14, cy + 40);
    ctx.lineTo(cx + 4, cy + 70);
    ctx.lineTo(cx + 22, cy + 110);
    ctx.stroke();
  });
  // pillars: one whole, one leaning, one broken in half
  ctx.fillStyle = '#2a0e12';
  ctx.fillRect(64, 40, 52, ground - 40);
  ctx.save();
  ctx.translate(300, ground);
  ctx.rotate(0.06);
  ctx.fillRect(-26, -(ground - 40), 52, ground - 40);
  ctx.restore();
  ctx.fillRect(698, ground - 160, 52, 160);
  ctx.fillRect(908, 40, 52, ground - 40);
  // the broken top of a pillar on the floor
  ctx.save();
  ctx.translate(780, ground - 14);
  ctx.rotate(1.3);
  ctx.fillRect(-26, -60, 52, 120);
  ctx.restore();
  // torn banners, hanging crooked
  [[195, 0.08], [829, -0.12]].forEach(([bx, tilt]) => {
    ctx.save();
    ctx.translate(bx, 60);
    ctx.rotate(tilt + Math.sin(time * 0.8 + bx) * 0.02);
    ctx.fillStyle = '#3a1216';
    ctx.fillRect(-28, 0, 56, 120);
    ctx.beginPath();
    ctx.moveTo(-28, 120);
    ctx.lineTo(-14, 150);
    ctx.lineTo(-4, 118);
    ctx.lineTo(10, 160);
    ctx.lineTo(28, 120);
    ctx.fill();
    ctx.fillStyle = '#ff5252';
    ctx.beginPath();
    ctx.moveTo(0, 40);
    ctx.lineTo(12, 66);
    ctx.lineTo(0, 92);
    ctx.lineTo(-12, 66);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  });
  // torches with red flames
  [[30, 200], [994, 200], [420, 160], [604, 160]].forEach(([tx, ty], index) => {
    ctx.fillStyle = '#2b1a12';
    ctx.fillRect(tx - 3, ty, 6, 24);
    const flicker = 0.7 + Math.sin(time * 9 + index) * 0.2;
    const glow = ctx.createRadialGradient(tx, ty - 4, 2, tx, ty - 4, 70);
    glow.addColorStop(0, `rgba(255, 61, 0, ${0.5 * flicker})`);
    glow.addColorStop(1, 'rgba(255, 61, 0, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(tx - 70, ty - 74, 140, 140);
    ctx.fillStyle = `rgba(255, 82, 82, ${flicker})`;
    ctx.beginPath();
    ctx.ellipse(tx, ty - 6, 5, 10 + Math.sin(time * 12 + index) * 2, 0, 0, Math.PI * 2);
    ctx.fill();
  });
  // the sealed door
  ctx.fillStyle = '#080203';
  ctx.fillRect(452, 140, 120, ground - 140);
  ctx.strokeStyle = `rgba(255, 82, 82, ${0.45 + Math.sin(time * 2) * 0.2})`;
  ctx.lineWidth = 4;
  ctx.strokeRect(452, 140, 120, ground - 140);
  ctx.beginPath();
  ctx.arc(512, 250, 30, 0, Math.PI * 2);
  ctx.moveTo(482, 250);
  ctx.lineTo(542, 250);
  ctx.moveTo(512, 220);
  ctx.lineTo(512, 280);
  ctx.stroke();
  // mess on the floor: a toppled table, bottles, plates, an abandoned helmet and swords
  ctx.fillStyle = '#3e2418';
  ctx.save();
  ctx.translate(210, ground - 10);
  ctx.rotate(-0.25);
  ctx.fillRect(-60, -8, 120, 12);
  ctx.fillRect(-50, 4, 8, 22);
  ctx.restore();
  [[330, '#2e7d32'], [352, '#6d4c41'], [610, '#2e7d32'], [640, '#4e342e']].forEach(([bx, color], index) => {
    ctx.save();
    ctx.translate(bx, ground - 6);
    ctx.rotate(index % 2 ? 1.4 : 0);
    ctx.fillStyle = color;
    ctx.fillRect(-5, -16, 10, 16);
    ctx.fillRect(-2, -22, 4, 6);
    ctx.restore();
  });
  ctx.fillStyle = '#bdbdbd';
  ctx.beginPath();
  ctx.ellipse(400, ground - 3, 14, 4, 0, 0, Math.PI * 2);
  ctx.ellipse(680, ground - 3, 12, 3, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#455a64';
  ctx.fillRect(560, ground - 18, 24, 18);
  ctx.strokeStyle = '#90a4ae';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(120, ground - 2);
  ctx.lineTo(180, ground - 30);
  ctx.moveTo(860, ground - 2);
  ctx.lineTo(940, ground - 12);
  ctx.stroke();
  // red haze over everything
  ctx.fillStyle = `rgba(120, 10, 10, ${0.12 + Math.sin(time * 0.7) * 0.03})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

