function startChronoChapterLevel4Intro() {
  selectedMap = 'castleGate';
  ch6CutsceneBase('originsIntro', chronoChLevel4Lines, 'dialog', {
    darkWorld: true,
    castle: true,
    versusName: 'ORDEN OSCURA',
    gamblerX: 160,
    gamblerTargetX: 160,
    scammerX: 700,
    scammerTargetX: 700,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    walkHistory: [],
    orderActors: [makeDarkKnightActor('darkKnight', 600), makeDarkKnightActor('darkKnight', 670), makeDarkKnightActor('darkKnightBoss', 750), makeDarkKnightActor('darkKnight', 860), makeDarkKnightActor('darkKnight', 930)],
  });
  startCutsceneLine(0);
}

function updateCastleIntro(cutscene, line, firstFrame) {
  if (line.loc && firstFrame) {
    selectedMap = line.loc;
    cutscene.gamblerX = line.loc === 'castleGate' ? 160 : 60;
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.walkHistory = [];
    cutscene.locFade = 1;
    playTone({ frequency: 220, duration: 0.4, type: 'triangle', volume: 0.03, slideTo: 180 });
  }
  // walking through each room, the knight a few steps ahead
  if (line.walkRoom) {
    const roomEnd = selectedMap === 'castleGallery' ? 200 : selectedMap === 'castleHall' ? 360 : 620;
    cutscene.gamblerX = Math.min(roomEnd, cutscene.gamblerX + 1.1);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    if (cutscene.frame % 28 === 0) playTone({ frequency: 70, duration: 0.08, type: 'square', volume: 0.02 });
  }
  cutscene.walkHistory.push(cutscene.gamblerX);
  if (cutscene.walkHistory.length > 120) cutscene.walkHistory.shift();
  if (line.tick && firstFrame) playTone({ frequency: 1800, duration: 0.05, type: 'square', volume: 0.04 });
  if (line.creak && firstFrame) playTone({ frequency: 90, duration: 0.6, type: 'sawtooth', volume: 0.04, slideTo: 70 });
  if (cutscene.locFade > 0) cutscene.locFade = Math.max(0, cutscene.locFade - 0.04);
  cutscene.gamblerHop = 40 + Math.sin(cutscene.frame / 12) * 6;
  if (line.hoodedLeave) cutscene.hoodedGone = Math.min(1, (cutscene.hoodedGone || 0) + 0.02);
  if (line.knightLeave) cutscene.knightGone = Math.min(1, (cutscene.knightGone || 0) + 0.025);
  if (line.sealed && !cutscene.sealPlayed) {
    cutscene.sealPlayed = true;
    playNoise({ duration: 0.5, volume: 0.08, filterFrequency: 400 });
    playTone({ frequency: 90, duration: 0.8, type: 'square', volume: 0.05, slideTo: 60 });
  }
  if (line.laugh && firstFrame) [0, 180, 360].forEach((delay) => setTimeout(() => playTone({ frequency: 260 - delay / 6, duration: 0.15, type: 'square', volume: 0.04 }), delay));
  cutscene.surgeGlow = line.surge ? Math.min(1, (cutscene.surgeGlow || 0) + 0.03) : 0;
  if (line.surge && cutscene.frame % 9 === 0) playNoise({ duration: 0.06, volume: 0.03, filterFrequency: 6000 });
}

function drawCastleIntroFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  if (line.hooded || line.hoodedLeave) {
    ctx.save();
    ctx.globalAlpha = 1 - (cutscene.hoodedGone || 0);
    drawHoodedFigure(420, ground, -1, time);
    ctx.restore();
  }
  if (line.knight || line.knightLeave) {
    ctx.save();
    ctx.globalAlpha = 1 - (cutscene.knightGone || 0);
    const kx = selectedMap === 'castleGate' ? 560 : selectedMap === 'orderChamber' ? 512 : cutscene.gamblerX + 170;
    drawBlackKnight(kx + (cutscene.knightGone || 0) * 40, ground, 1, time);
    ctx.restore();
  }
  if (line.order && cutscene.orderActors) {
    cutscene.orderActors.forEach((actor, index) => {
      const shake = line.laugh ? Math.abs(Math.sin(time * 18 + index)) * 4 : 0;
      actor.position.y = ground - actor.height - shake;
      actor.attacksToTheRight = false;
      actor.isAttacking = false;
      actor.draw();
    });
  }
  if (cutscene.surgeGlow > 0) drawChronoMachineSurge(player1, cutscene.surgeGlow);
  if (cutscene.locFade > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${cutscene.locFade})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

// ---------- in the middle of the fight: the Rare Machine wakes up ("light mode") ----------
function speakRobotic(text) {
  try {
    if (!('speechSynthesis' in window)) return;
    const voice = new SpeechSynthesisUtterance(text);
    voice.lang = 'es-ES';
    voice.pitch = 0.1;
    voice.rate = 0.85;
    voice.volume = Math.max(0, Math.min(1, audioSettings.master * audioSettings.sfx));
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(voice);
  } catch (error) {
    // no voice: the words on screen are enough
  }
}

function updateChronoLightMode() {
  // (level 5: the machine is already awake in light mode)
  if (isChronoChapterFight() && selectedNormalArcadeLevel === 5 && gameStarted && !gameOver && !arcadeCutscene.active && !player1.machineLight) {
    player1.rareMachine = true;
    player1.machineLight = true;
    player1.machineCooldown = 0;
  }
  if (!(isChronoChapterFight() && selectedNormalArcadeLevel === 4) || gameOver || arcadeCutscene.active) return;
  const mode = chronoCh.lightMode || (chronoCh.lightMode = { state: null, t: 0 });
  // it wakes when the third knight steps in
  if (!mode.state && normalArcadeEnemyIndex >= 3) {
    mode.state = 'boot';
    mode.t = 0;
  }
  if (mode.state === 'boot') {
    mode.t += 1;
    if (mode.t === 30) {
      playTone({ frequency: 220, duration: 0.15, type: 'square', volume: 0.05 });
      setTimeout(() => playTone({ frequency: 330, duration: 0.15, type: 'square', volume: 0.05 }), 160);
      setTimeout(() => playTone({ frequency: 660, duration: 0.3, type: 'square', volume: 0.05 }), 320);
      speakRobotic('Huésped en mundo oscuro. Activando modo luz.');
    }
    if (mode.t === 60) {
      player1.rareMachine = true;
      player1.machineLight = true;
      player1.machineCooldown = 0;
      showFlametombThought(player1, '(...¿La maquina? ¿Otra vez funciona?)');
    }
    if (mode.t > 260) mode.state = 'on';
  }
}

function drawChronoLightMode() {
  const mode = chronoCh.lightMode;
  if (!mode || mode.state !== 'boot' || arcadeCutscene.active) return;
  const t = mode.t;
  const time = performance.now() / 1000;
  ctx.save();
  if (t < 60) {
    ctx.fillStyle = `rgba(255, 245, 157, ${Math.max(0, 0.35 - Math.abs(t - 40) / 60)})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  drawChronoMachineSurge(player1, 1);
  const alpha = Math.min(1, t / 20, (260 - t) / 30);
  ctx.globalAlpha = Math.max(0, alpha);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
  ctx.fillRect(0, 196, canvas.width, 62);
  ctx.font = '900 22px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillStyle = '#ffe082';
  const text = 'HUESPED EN MUNDO OSCURO. ACTIVANDO MODO LUZ.';
  ctx.fillText(text.slice(0, Math.floor(t / 2)), canvas.width / 2 + (Math.random() - 0.5) * 2, 226);
  ctx.font = '700 13px Courier New, monospace';
  ctx.fillStyle = '#fff';
  if (t > 90) ctx.fillText('R: disparar la Maquina Rara (modo luz)', canvas.width / 2, 248);
  ctx.textAlign = 'left';
  ctx.restore();
}

