function startChronoChapterOrderOutro() {
  chronoCh.outroPlayed = true;
  orderFx.items = [];
  forestFx.items = [];
  player1.rareMachine = false;
  player1.scamLabelTimer = 0;
  ch6CutsceneBase('originsIntro', chronoChOrderOutroLines, 'dialog', {
    darkWorld: true,
    outro: true,
    noVersus: true,
    orderOutro: true,
    gamblerX: 220,
    gamblerTargetX: 220,
    scammerX: 700,
    scammerTargetX: 700,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    darkMusic: false,
    orderActors: [makeDarkKnightActor('darkKnight', 600), makeDarkKnightActor('darkKnightBoss', 700), makeDarkKnightActor('darkKnight', 820), makeDarkKnightActor('darkKnight', 890), makeDarkKnightActor('darkKnight', 960)],
    standUp: 0,
    hideT: 0,
    stunGlow: 0,
    chronoFade: 0,
    blackKnightAlpha: 0,
    doorDust: [],
  });
  selectedMap = 'orderChamber';
  startCutsceneLine(0);
}

function updateChronoChapterOrderOutro(cutscene, line, firstFrame) {
  cutscene.hideEnemy = true;
  cutscene.gamblerHop = 40 + Math.sin(cutscene.frame / 12) * 6;
  if (line.rise) cutscene.standUp = Math.min(1, cutscene.standUp + 0.04);
  if (line.door && firstFrame) {
    playTone({ frequency: 70, duration: 2.2, type: 'sawtooth', volume: 0.05, slideTo: 50 });
    playTone({ frequency: 140, duration: 1.8, type: 'triangle', volume: 0.03, slideTo: 110 });
    cutscene.shake = 4;
  }
  if (line.doorClose && firstFrame) {
    playNoise({ duration: 1.2, volume: 0.12, filterFrequency: 250 });
    playTone({ frequency: 45, duration: 1.4, type: 'sine', volume: 0.12, slideTo: 30 });
    cutscene.shake = 14;
    for (let grain = 0; grain < 40; grain += 1) cutscene.doorDust.push({ x: Math.random() * canvas.width, y: -10 - Math.random() * 80, vy: 1 + Math.random() * 2, life: 140 });
  }
  cutscene.doorDust.forEach((grain) => {
    grain.y += grain.vy;
    grain.life -= 1;
  });
  cutscene.doorDust = cutscene.doorDust.filter((grain) => grain.life > 0 && grain.y < ground);
  cutscene.shake = (cutscene.shake || 0) * 0.92;
  if (line.hide) cutscene.hideT = Math.min(1, cutscene.hideT + 0.02);
  if (line.stun && firstFrame && !cutscene.stunPlayed) {
    cutscene.stunPlayed = true;
    [1400, 1000, 700].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.15, type: 'triangle', volume: 0.05, slideTo: frequency * 0.6 }), index * 80));
  }
  if (line.stun) cutscene.stunGlow = Math.min(1, cutscene.stunGlow + 0.05);
  else cutscene.stunGlow = Math.max(0, cutscene.stunGlow - 0.04);
  if (line.chronoLeave) {
    cutscene.gamblerX += (480 - cutscene.gamblerX) * 0.04;
    cutscene.gamblerTargetX = cutscene.gamblerX;
  }
  if (line.chronoGone) cutscene.gamblerX = -400;
  if (line.blackKnightIn) cutscene.blackKnightAlpha = Math.min(1, cutscene.blackKnightAlpha + 0.04);
  if (line.blackKnightOut) cutscene.blackKnightAlpha = Math.max(0, cutscene.blackKnightAlpha - 0.02);
  cutscene.angry = Boolean(line.angry);
}

function drawChronoChapterOrderOutroFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  // the Order: down on one knee, then up... and the knights run to hide
  cutscene.orderActors.forEach((actor, index) => {
    const general = actor.secretVariant === 'darkKnightBoss';
    const hide = general ? 0 : cutscene.hideT;
    if (hide >= 1) return;
    const kneel = (1 - cutscene.standUp) * 18;
    ctx.save();
    ctx.globalAlpha = 1 - hide;
    const baseX = [600, 700, 820, 890, 960][index];
    actor.position = { x: baseX + hide * (index % 2 ? 260 : -360), y: ground - actor.height + kneel };
    actor.attacksToTheRight = false;
    actor.isAttacking = false;
    if (general && cutscene.stunGlow > 0) ctx.filter = `grayscale(${cutscene.stunGlow}) brightness(${1 - cutscene.stunGlow * 0.3})`;
    if (general && cutscene.angry) actor.position.x += (Math.random() - 0.5) * 6;
    actor.draw();
    ctx.filter = 'none';
    ctx.restore();
    // the clock that holds him still
    if (general && cutscene.stunGlow > 0) {
      const cx = actor.position.x + actor.width / 2;
      const cy = actor.position.y + actor.height / 2;
      ctx.save();
      ctx.globalAlpha = cutscene.stunGlow;
      ctx.strokeStyle = '#4fc3f7';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(cx, cy, 80, 0, Math.PI * 2);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx, cy - 60);
      ctx.moveTo(cx, cy);
      ctx.lineTo(cx + Math.cos(time * 0.2) * 40, cy + Math.sin(time * 0.2) * 40);
      ctx.stroke();
      ctx.restore();
    }
  });
  if (cutscene.blackKnightAlpha > 0) {
    ctx.save();
    ctx.globalAlpha = cutscene.blackKnightAlpha;
    drawBlackKnight(512, ground, 1, time);
    ctx.restore();
  }
  cutscene.doorDust.forEach((grain) => {
    ctx.fillStyle = `rgba(160, 120, 110, ${grain.life / 140})`;
    ctx.fillRect(grain.x, grain.y, 3, 3);
  });
  if (line.door || line.doorClose) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.25)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

// ================= LEVEL 5: looking for the way out... and the black knight =================
chronoChLevels[5] = { enemies: ['blackKnightBoss'], difficulties: ['hard'], health: [720] };
['blackKnightBoss'].forEach((variant) => {
  if (!originsVariants.includes(variant)) originsVariants.push(variant);
  if (!arcadeBossVariants.includes(variant)) arcadeBossVariants.push(variant);
});
originsSizes.blackKnightBoss = [66, 138];
originsSpeeds.blackKnightBoss = 1.12;
originsDamage.blackKnightBoss = 1.4;
originsHealth.blackKnightBoss = 560;
originsNames.blackKnightBoss = 'Caballero Negro';
reflecterBattleTrackSources.chaosKing = encodeURI('assetsaudio/Chaos King.mp3');
reflecterBattleTrackVolumes.chaosKing = 0.7;

function isBlackKnightBoss(fighter) {
  return Boolean(fighter && fighter.secretVariant === 'blackKnightBoss');
}

function drawBlackKnightFighter(fighter) {
  const time = performance.now() / 1000;
  const dir = fighter.attacksToTheRight ? 1 : -1;
  drawBlackKnight(fighter.position.x + fighter.width / 2, fighter.position.y + fighter.height, dir, time);
  if (chronoCh.knightRage) {
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.25 + Math.sin(time * 8) * 0.15})`;
    ctx.lineWidth = 2;
    ctx.strokeRect(fighter.position.x - 6, fighter.position.y - 8, fighter.width + 12, fighter.height + 10);
  }
  if (fighter.isAttacking) {
    ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
    const area = fighter.attackArea;
    ctx.fillRect(area.x, area.y, area.width, area.height);
  }
}

function castBlackKnightAbility(monster) {
  const step = forestFx.step;
  forestFx.step += 1;
  const px = getFighterCenterX(player1);
  const mx = getFighterCenterX(monster);
  const rage = chronoCh.knightRage;
  // a knight's moves: the lance lunge (kept), the tower shield, the leaping slam... and, angry, the judgment
  const moves = rage ? ['charge', 'slam', 'shield', 'judgment'] : ['charge', 'shield', 'slam'];
  const move = moves[step % moves.length];
  if (move === 'charge') {
    showFlametombThought(monster, rage ? '¡No hay donde correr!' : 'En guardia.');
    forestFx.dash = { t: 0, dir: px > mx ? 1 : -1, hit: false };
  } else if (move === 'shield') {
    // the tower shield: almost nothing gets through... and whoever hits it gets pushed back
    showFlametombThought(monster, 'Muro de la puerta.');
    chronoCh.knightShield = rage ? 150 : 120;
    playTone({ frequency: 300, duration: 0.4, type: 'square', volume: 0.05, slideTo: 200 });
  } else if (move === 'slam') {
    // he leaps high... and comes down where you are, with a shockwave to each side
    showFlametombThought(monster, '¡Desde arriba!');
    chronoCh.knightSlam = { t: 0, fromX: monster.position.x, toX: Math.max(10, Math.min(canvas.width - monster.width - 10, px - monster.width / 2)), done: false };
    playTone({ frequency: 120, duration: 0.5, type: 'sawtooth', volume: 0.05, slideTo: 300 });
  } else {
    showFlametombThought(monster, 'Juicio.');
    orderFx.items.push({ kind: 'throne', x: px, t: 0, hit: false });
    orderFx.items.push({ kind: 'throne', x: Math.max(60, Math.min(canvas.width - 60, px + (px > mx ? 130 : -130))), t: -15, hit: false });
  }
}

function updateBlackKnightMoves() {
  const knight = player2;
  if (chronoCh.knightShield > 0) {
    chronoCh.knightShield -= 1;
    knight.velocity.x = 0;
  }
  const slam = chronoCh.knightSlam;
  if (slam) {
    slam.t += 1;
    knight.scriptedFlight = true;
    knight.velocity.x = 0;
    knight.velocity.y = 0;
    const k = Math.min(1, slam.t / 40);
    knight.position.x = slam.fromX + (slam.toX - slam.fromX) * k;
    knight.position.y = ground - knight.height - Math.sin(k * Math.PI) * 230;
    if (slam.t === 40 && !slam.done) {
      slam.done = true;
      knight.position.y = ground - knight.height;
      playNoise({ duration: 0.6, volume: 0.13, filterFrequency: 400 });
      playSound('robotHit');
      [-1, 1].forEach((side) => forestFx.items.push({ kind: 'wave', x: getFighterCenterX(knight), dir: side, life: 110, hit: false }));
      if (Math.abs(getFighterCenterX(player1) - getFighterCenterX(knight)) < 70 && player1.position.y + player1.height > ground - 40) forestHit(16, 8);
    }
    if (slam.t > 46) {
      knight.scriptedFlight = false;
      chronoCh.knightSlam = null;
    }
  }
}

// (applyDamage asks this: the raised shield takes most of a hit)
function blackKnightDamageTaken(target) {
  if (!(isChronoChapterFight() && target === player2 && isBlackKnightBoss(target) && chronoCh.knightShield > 0)) return 1;
  chronoCh.shieldFlash = 8;
  return 0.25;
}

function drawBlackKnightMoves() {
  const knight = player2;
  if (!isBlackKnightBoss(knight)) return;
  const time = performance.now() / 1000;
  if (chronoCh.knightShield > 0) {
    // a tall dark shield with a white rim, in front of him
    const dir = getFighterCenterX(player1) > getFighterCenterX(knight) ? 1 : -1;
    const sx = getFighterCenterX(knight) + dir * 42;
    ctx.save();
    ctx.fillStyle = chronoCh.shieldFlash > 0 ? '#e0e0e0' : '#141418';
    ctx.fillRect(sx - 14, knight.position.y + 20, 28, knight.height - 24);
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.6 + Math.sin(time * 10) * 0.3})`;
    ctx.lineWidth = 3;
    ctx.strokeRect(sx - 14, knight.position.y + 20, 28, knight.height - 24);
    ctx.fillStyle = '#c9a227';
    ctx.fillRect(sx - 3, knight.position.y + 50, 6, 50);
    ctx.restore();
    if (chronoCh.shieldFlash > 0) chronoCh.shieldFlash -= 1;
  }
  const slam = chronoCh.knightSlam;
  if (slam && slam.t < 40) {
    // where he will land
    ctx.fillStyle = `rgba(255, 255, 255, ${0.25 + Math.sin(time * 20) * 0.15})`;
    ctx.fillRect(slam.toX - 10, ground - 4, knight.width + 20, 6);
  }
}

