function startChronoChapterLevel5Intro() {
  selectedMap = 'castleArmory';
  ch6CutsceneBase('originsIntro', chronoChLevel5Lines, 'dialog', {
    darkWorld: true,
    castle: true,
    versusName: 'CABALLERO NEGRO',
    gamblerX: 60,
    gamblerTargetX: 60,
    scammerX: 700,
    scammerTargetX: 700,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    walkHistory: [],
    knightX: -200,
    dashT: 0,
    pushT: 0,
    weaponT: 0,
    energy: [],
    rings: [],
  });
  startCutsceneLine(0);
}

function updateLevel5Intro(cutscene, line, firstFrame) {
  // the dash: out of nowhere, from behind, straight into him
  if (line.dashIn && !cutscene.dashing) {
    cutscene.dashing = true;
    cutscene.knightX = -200;
    // (he is always halfway down the hall when it happens)
    cutscene.gamblerX = Math.max(cutscene.gamblerX, 360);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    playTone({ frequency: 120, duration: 0.3, type: 'sawtooth', volume: 0.06, slideTo: 400 });
  }
  if (cutscene.dashing && !cutscene.hitDone) {
    cutscene.dashT += 1;
    cutscene.knightX = Math.min(cutscene.gamblerX - 40, cutscene.knightX + 34);
    if (cutscene.knightX >= cutscene.gamblerX - 40 && !cutscene.hitDone) {
      cutscene.hitDone = true;
      cutscene.shake = 22;
      cutscene.impactFlash = 1;
      playNoise({ duration: 0.6, volume: 0.15, filterFrequency: 700 });
      playSound('robotHit');
    }
  }
  // Chrono is thrown down the hall... and turns around
  if (cutscene.hitDone) {
    cutscene.pushT = Math.min(1, cutscene.pushT + 0.035);
    if (!cutscene.pushFrom) cutscene.pushFrom = cutscene.gamblerX;
    cutscene.gamblerX = cutscene.pushFrom + (760 - cutscene.pushFrom) * Math.sin(cutscene.pushT * Math.PI / 2);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    if (cutscene.pushT < 1) cutscene.gamblerHop = 40 + Math.sin(cutscene.pushT * Math.PI) * 70;
    // (he faces the knight now)
    cutscene.scammerX = 0;
  }
  if (line.step && firstFrame) {
    cutscene.knightX = Math.min(cutscene.knightX + 60, 520);
    playTone({ frequency: 60, duration: 0.25, type: 'square', volume: 0.06 });
    cutscene.shake = Math.max(cutscene.shake || 0, 5);
  }
  if (line.nervous) cutscene.gamblerX += (Math.random() - 0.5) * 2;
  // drawing his weapon: the light gathers, the spear spins, the floor cracks
  if (line.drawWeapon) {
    cutscene.weaponT += 1;
    if (cutscene.weaponT % 3 === 0) {
      const angle = Math.random() * Math.PI * 2;
      cutscene.energy.push({ angle, distance: 180 + Math.random() * 80, life: 40 });
    }
    if (cutscene.weaponT === 1) playTone({ frequency: 90, duration: 3, type: 'sawtooth', volume: 0.05, slideTo: 300 });
    if (cutscene.weaponT % 40 === 0) playTone({ frequency: 300 + cutscene.weaponT * 2, duration: 0.2, type: 'triangle', volume: 0.04 });
    cutscene.shake = Math.max(cutscene.shake || 0, Math.min(6, cutscene.weaponT / 40));
  }
  cutscene.energy.forEach((spark) => {
    spark.distance *= 0.92;
    spark.life -= 1;
  });
  cutscene.energy = cutscene.energy.filter((spark) => spark.life > 0);
  if (line.weaponReady && firstFrame) {
    cutscene.weaponFlash = 1;
    cutscene.shake = 26;
    cutscene.cracks = true;
    for (let ring = 0; ring < 4; ring += 1) cutscene.rings.push({ r: 20 + ring * 30, life: 60 });
    playNoise({ duration: 1, volume: 0.16, filterFrequency: 5000 });
    playTone({ frequency: 1400, duration: 0.6, type: 'triangle', volume: 0.07, slideTo: 500 });
    playTone({ frequency: 50, duration: 1.4, type: 'sawtooth', volume: 0.1, slideTo: 30 });
  }
  cutscene.rings.forEach((ring) => {
    ring.r += 12;
    ring.life -= 1;
  });
  cutscene.rings = cutscene.rings.filter((ring) => ring.life > 0);
  if (cutscene.weaponFlash > 0) cutscene.weaponFlash = Math.max(0, cutscene.weaponFlash - 0.025);
  if (cutscene.impactFlash > 0) cutscene.impactFlash = Math.max(0, cutscene.impactFlash - 0.06);
  cutscene.shake = (cutscene.shake || 0) * 0.9;
}

function drawLevel5IntroFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  const kx = cutscene.knightX;
  if (kx > -150) {
    const centerY = ground - 70;
    // a trail behind the dash
    if (cutscene.dashing && !cutscene.hitDone) {
      for (let ghost = 1; ghost <= 4; ghost += 1) {
        ctx.save();
        ctx.globalAlpha = 0.25 / ghost;
        drawBlackKnight(kx - ghost * 40, ground, 1, time);
        ctx.restore();
      }
    }
    // the gathering light while he draws his weapon
    if (line.drawWeapon || line.weaponReady) {
      const k = Math.min(1, cutscene.weaponT / 200);
      const glow = ctx.createRadialGradient(kx, centerY, 10, kx, centerY, 120 + k * 120);
      glow.addColorStop(0, `rgba(255, 255, 255, ${0.25 + k * 0.35})`);
      glow.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = glow;
      ctx.fillRect(kx - 260, centerY - 260, 520, 520);
      cutscene.energy.forEach((spark) => {
        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.fillRect(kx + Math.cos(spark.angle) * spark.distance, centerY + Math.sin(spark.angle) * spark.distance * 0.6, 3, 3);
      });
      // the spear spinning above his head, faster and faster
      ctx.save();
      ctx.translate(kx, ground - 190);
      ctx.rotate(line.weaponReady ? 0 : cutscene.weaponT * (0.12 + k * 0.3));
      ctx.strokeStyle = '#2b2b33';
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(-90, 0);
      ctx.lineTo(90, 0);
      ctx.stroke();
      ctx.fillStyle = '#ffd54f';
      ctx.beginPath();
      ctx.moveTo(90, -7);
      ctx.lineTo(118, 0);
      ctx.lineTo(90, 7);
      ctx.fill();
      ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + k * 0.5})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, 100, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
    // cracks in the floor once his spear strikes it
    if (cutscene.cracks) {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
      ctx.lineWidth = 2;
      for (let crack = -3; crack <= 3; crack += 1) {
        ctx.beginPath();
        ctx.moveTo(kx, ground);
        ctx.lineTo(kx + crack * 30, ground + 10);
        ctx.lineTo(kx + crack * 60, ground + 20);
        ctx.stroke();
      }
    }
    drawBlackKnight(kx, ground, 1, time);
    // the slit in his helm burns brighter
    if (line.drawWeapon || line.weaponReady) {
      ctx.save();
      ctx.shadowColor = '#ffffff';
      ctx.shadowBlur = 30;
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(kx - 21, ground - 138 + 22, 42, 5);
      ctx.restore();
    }
  }
  cutscene.rings.forEach((ring) => {
    ctx.strokeStyle = `rgba(255, 255, 255, ${ring.life / 60})`;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(kx, ground - 70, ring.r, 0, Math.PI * 2);
    ctx.stroke();
  });
  if (cutscene.impactFlash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.impactFlash * 0.6})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  if (cutscene.weaponFlash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.weaponFlash * 0.85})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

// ================= LEVEL 6: on the way to the king... Shadow Jester =================
chronoChLevels[6] = { enemies: ['shadowJesterCh6'], difficulties: ['hard'], health: [620] };
reflecterBattleTrackSources.jesterCastle = jesterBattleTrackSource;
reflecterBattleTrackVolumes.jesterCastle = 0.6;

function isChronoJesterFight() {
  return isChronoChapterFight() && ((selectedNormalArcadeLevel === 6 && !chronoCh.duelPhase) || selectedNormalArcadeLevel === 7);
}

function configureChronoJester() {
  player2.setCharacterType('gambler', 'shadowJester');
  botDifficulty = 'hard';
  applyBotDifficulty();
  player2.setMaxHealth(620);
  player2.health = player2.maxHealth;
  // (hits harder while Chrono is weak; back to normal after the overcharge)
  player2.damageMultiplier = 1.5;
  // (no final act here: that one belongs to Gambler)
  player2.jesterFinalActUsed = true;
  // Chrono arrives with almost nothing left
  player1.health = Math.round(player1.maxHealth * 0.6);
  player1.damageMultiplier = 0.85;
  player1.rareMachine = false;
  player1.machineLight = false;
  player1.machineBoost = false;
  chronoCh.overcharged = false;
  chronoCh.jesterSlow = 0;
  // (level 7: on the roof he is still overcharged)
  if (selectedNormalArcadeLevel === 7) {
    makeChronoOvercharged();
    player1.health = Math.round(player1.maxHealth * 0.85);
  }
  updateHealthBars();
  updateCombatHudIdentity();
}

// he can't fall before the machine wakes up
function chronoJesterDamageFloor(target) {
  // (level 7: the jester holds at 30% until the dark shot)
  if (isChronoJesterFight() && selectedNormalArcadeLevel === 7 && target === player2 && !chronoCh.darkShotStarted) target.health = Math.max(target.health, Math.ceil(target.maxHealth * 0.3));
  if (!isChronoJesterFight() || target !== player1 || chronoCh.overcharged) return;
  target.health = Math.max(target.health, 1);
}

function updateChronoJester() {
  if (!isChronoJesterFight() || gameOver || arcadeCutscene.active) return;
  // the slowed jester: frozen most frames, free for one now and then (crawling, reacting late)
  if (chronoCh.jesterSlow > 0) {
    chronoCh.jesterSlow -= 1;
    player2.chronoTimeStopTimer = chronoCh.jesterSlow % 12 === 0 ? 0 : 1;
    if (chronoCh.jesterSlow === 0) player2.chronoTimeStopTimer = 0;
  }
  // (level 7: the reset of the fight turns the machine off: it stays awake on the roof)
  if (selectedNormalArcadeLevel === 7 && !player1.rareMachine) {
    player1.rareMachine = true;
    player1.machineLight = true;
    player1.machineBoost = true;
    player1.moveSpeed = playerMoveSpeed * 1.3;
  }
  if (selectedNormalArcadeLevel === 7) {
    [player1, player2].forEach((fighter) => {
      const limit = chronoRoofEdgeX - 26 - fighter.width;
      if (fighter.position.x > limit) {
        fighter.position.x = limit;
        if (fighter.velocity.x > 0) fighter.velocity.x = 0;
      }
    });
  }
  if (selectedNormalArcadeLevel === 7 && !chronoCh.darkShotStarted && player2.health <= Math.ceil(player2.maxHealth * 0.3) + 0.5) {
    chronoCh.darkShotStarted = true;
    startChronoDarkShot();
    return;
  }
  if (selectedNormalArcadeLevel === 6 && !chronoCh.overcharged && !chronoCh.overchargeStarted && player1.health <= player1.maxHealth * 0.2) {
    chronoCh.overchargeStarted = true;
    startChronoOverchargeScene();
  }
}

// ---------- the throne hall ----------
function drawCastleThroneHallStage() {
  const time = performance.now() / 1000;
  drawCastleRoomBase('#0f0812', '#0a050b');
  // a long red carpet to the doors of the throne room
  ctx.fillStyle = '#4a0d1a';
  ctx.fillRect(0, ground - 3, canvas.width, 8);
  ctx.fillStyle = '#c9a227';
  ctx.fillRect(0, ground - 4, canvas.width, 2);
  // the great doors, closed, with a crown above them
  ctx.fillStyle = '#1c0e0a';
  ctx.fillRect(820, 80, 190, ground - 80);
  ctx.strokeStyle = '#c9a227';
  ctx.lineWidth = 4;
  ctx.strokeRect(820, 80, 190, ground - 80);
  ctx.beginPath();
  ctx.moveTo(915, 80);
  ctx.lineTo(915, ground);
  ctx.stroke();
  ctx.fillStyle = '#c9a227';
  for (let spike = 0; spike < 5; spike += 1) {
    ctx.beginPath();
    ctx.moveTo(870 + spike * 20, 74);
    ctx.lineTo(880 + spike * 20, 46);
    ctx.lineTo(890 + spike * 20, 74);
    ctx.fill();
  }
  // a faint tic... tac from behind the doors: light leaking under them, pulsing like a heartbeat
  const beat = Math.pow(Math.max(0, Math.sin(time * 3.2)), 8);
  ctx.fillStyle = `rgba(255, 213, 79, ${0.15 + beat * 0.35})`;
  ctx.fillRect(824, ground - 6, 182, 6);
  // statues of kneeling knights
  [140, 360, 580].forEach((sx) => {
    ctx.fillStyle = '#2b2b33';
    ctx.fillRect(sx - 24, ground - 90, 48, 90);
    ctx.fillRect(sx - 18, ground - 120, 36, 30);
    ctx.fillStyle = '#111';
    ctx.fillRect(sx - 10, ground - 108, 20, 3);
    ctx.fillStyle = '#3a3a44';
    ctx.fillRect(sx - 34, ground - 16, 68, 16);
  });
  if (chronoCh.ceilingBroken) drawChronoCeilingHole();
  // jester confetti stuck everywhere (he was here)
  for (let bit = 0; bit < 30; bit += 1) {
    ctx.fillStyle = ['#ea80fc', '#fdd835', '#b388ff', '#ff4081'][bit % 4];
    ctx.fillRect((bit * 97) % 800, ground - 2 - (bit % 3), 4, 3);
  }
}

