function updateChronoLevel6Intro(cutscene, line, firstFrame) {
  if (line.carried) cutscene.dragX = Math.min(330, cutscene.dragX + 1.2);
  if (line.laughFar && firstFrame) [0, 200, 400].forEach((delay) => setTimeout(() => playSound('jesterLaugh'), delay));
  if (line.jesterIn && firstFrame && !cutscene.jesterPopped) {
    cutscene.jesterPopped = true;
    cutscene.flash = 0.7;
    playNoise({ duration: 0.4, volume: 0.08, filterFrequency: 4000 });
  }
  cutscene.hideEnemy = !(line.jesterIn || cutscene.jesterPopped);
  if (line.knightAside) cutscene.knightAsideT = Math.min(1, cutscene.knightAsideT + 0.03);
  if (line.standUp) {
    if (cutscene.gamblerX < 0) {
      cutscene.gamblerX = Math.max(280, cutscene.dragX - 20);
      cutscene.gamblerTargetX = cutscene.gamblerX;
    }
    cutscene.gamblerX += (Math.random() - 0.5) * 1.5;
  }
  if (cutscene.flash > 0) cutscene.flash = Math.max(0, cutscene.flash - 0.04);
}

function drawChronoLevel6IntroFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  // Chrono on the floor, dragged by the knight
  if (!line.standUp) {
    const savedX = player1.position.x;
    player1.position = { x: cutscene.dragX - 70, y: ground - player1.height };
    player1.isAttacking = false;
    drawDownedFighter(player1);
    player1.position.x = savedX;
  }
  const knightX = cutscene.dragX + 60 + cutscene.knightAsideT * (90 - cutscene.dragX - 60);
  ctx.save();
  if (cutscene.knightAsideT > 0) ctx.globalAlpha = 1 - cutscene.knightAsideT * 0.6;
  drawBlackKnight(knightX, ground, 1, time);
  ctx.restore();
  if (cutscene.flash > 0) {
    ctx.fillStyle = `rgba(234, 128, 252, ${cutscene.flash * 0.5})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

