function startChronoOverchargeScene() {
  orderFx.items = [];
  forestFx.items = [];
  if (typeof clearJesterProjectiles === 'function') clearJesterProjectiles();
  ch6CutsceneBase('originsIntro', chronoOverchargeLines, 'dialog', {
    darkWorld: true,
    midFight: true,
    noVersus: true,
    darkMusic: true,
    overchargeScene: true,
    gamblerX: Math.max(60, Math.min(canvas.width - 300, player1.position.x)),
    gamblerTargetX: Math.max(60, Math.min(canvas.width - 300, player1.position.x)),
    scammerX: Math.max(player1.position.x + 220, Math.min(canvas.width - 140, player2.position.x)),
    scammerTargetX: Math.max(player1.position.x + 220, Math.min(canvas.width - 140, player2.position.x)),
    scammerY: 0,
    hideEnemy: false,
    lastFlagLine: -1,
    descendY: 2,
    absorbT: 0,
    burstT: 0,
    bits: [],
  });
  startCutsceneLine(0);
}

function updateChronoOverchargeScene(cutscene, line, firstFrame) {
  if (line.beaten) cutscene.gamblerX += (Math.random() - 0.5) * 1.2;
  if (line.machineWake && firstFrame) {
    [440, 660, 880].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.15, type: 'square', volume: 0.05 }), index * 140));
    if (typeof speakRobotic === 'function') speakRobotic('Energía restaurada. Disparo fuerte disponible.');
  }
  if (line.absorb) {
    cutscene.absorbT += 1;
    for (let bit = 0; bit < 3; bit += 1) {
      const angle = Math.random() * Math.PI * 2;
      cutscene.bits.push({ angle, dist: 120 + Math.random() * 60, life: 30 });
    }
    if (cutscene.absorbT % 8 === 0) playTone({ frequency: 200 + Math.min(1000, cutscene.absorbT * 6), duration: 0.08, type: 'sawtooth', volume: 0.035 });
    cutscene.shake = Math.max(cutscene.shake || 0, Math.min(8, cutscene.absorbT / 30));
  }
  cutscene.bits.forEach((bit) => {
    bit.dist *= 0.9;
    bit.life -= 1;
  });
  cutscene.bits = cutscene.bits.filter((bit) => bit.life > 0);
  if (line.burst && firstFrame) {
    cutscene.flash = 1;
    cutscene.shake = 30;
    makeChronoOvercharged();
    playNoise({ duration: 1.6, volume: 0.17, filterFrequency: 1500 });
    playTone({ frequency: 80, duration: 1.6, type: 'sawtooth', volume: 0.1, slideTo: 300 });
  }
  if (line.powered) cutscene.gamblerHop = 40 + Math.sin(cutscene.frame / 10) * 8;
  cutscene.shake = (cutscene.shake || 0) * 0.9;
  if (cutscene.flash > 0) cutscene.flash = Math.max(0, cutscene.flash - 0.03);
}

function drawChronoOverchargeSceneFx(cutscene) {
  const cx = player1.position.x + player1.width / 2;
  const cy = player1.position.y + player1.height / 2;
  cutscene.bits.forEach((bit) => {
    ctx.fillStyle = bit.life % 4 < 2 ? '#ffffff' : '#ffd54f';
    ctx.fillRect(cx + Math.cos(bit.angle) * bit.dist - 2, cy + Math.sin(bit.angle) * bit.dist - 2, 4, 4);
  });
  if (cutscene.flash > 0) {
    ctx.fillStyle = `rgba(255, 245, 200, ${cutscene.flash})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

function makeChronoOvercharged() {
  chronoCh.overcharged = true;
  player1.health = Math.round(player1.maxHealth * 0.75);
  player1.damageMultiplier = 2;
  player1.moveSpeed = playerMoveSpeed * 1.3;
  // the machine stays awake (light mode)
  player1.rareMachine = true;
  player1.machineLight = true;
  player1.machineBoost = true;
  player1.machineCooldown = 0;
  player2.damageMultiplier = 1;
  updateHealthBars();
}

// his overcharged look: a golden-white aura, lightning, burning eyes, the machine glowing white
function drawChronoOverchargedLook() {
  if (!((isChronoJesterFight() || isChronoTitanFight()) && chronoCh.overcharged && player1.characterType === 'chrono')) return;
  const fighter = player1;
  const time = performance.now() / 1000;
  const x = fighter.position.x;
  const y = fighter.position.y;
  const w = fighter.width;
  const h = fighter.height;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const aura = ctx.createRadialGradient(x + w / 2, y + h / 2, 10, x + w / 2, y + h / 2, 110);
  aura.addColorStop(0, `rgba(255, 236, 179, ${0.35 + Math.sin(time * 6) * 0.1})`);
  aura.addColorStop(0.6, 'rgba(255, 193, 7, 0.15)');
  aura.addColorStop(1, 'rgba(255, 193, 7, 0)');
  ctx.fillStyle = aura;
  ctx.fillRect(x - 110 + w / 2, y - 110 + h / 2, 220, 220);
  ctx.globalCompositeOperation = 'source-over';
  // rising sparks
  for (let spark = 0; spark < 10; spark += 1) {
    const rise = (time * 80 + spark * 13) % 90;
    ctx.fillStyle = spark % 2 ? '#fff59d' : '#ffffff';
    ctx.fillRect(x + ((spark * 17) % w), y + h - rise, 3, 3);
  }
  // little lightning bolts around him
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
  ctx.lineWidth = 2;
  for (let bolt = 0; bolt < 2; bolt += 1) {
    if (Math.random() < 0.5) continue;
    let bx = x + Math.random() * w;
    let by = y - 10;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    for (let step = 0; step < 5; step += 1) {
      bx += (Math.random() - 0.5) * 20;
      by += 18;
      ctx.lineTo(bx, by);
    }
    ctx.stroke();
  }
  // burning eyes
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = '#ffd54f';
  ctx.shadowBlur = 16;
  ctx.fillRect(x + 14, y + 20, 10, 5);
  ctx.fillRect(x + w - 24, y + 20, 10, 5);
  ctx.restore();
}

function chronoJesterResistsTimeStop(target) {
  if (!(isChronoJesterFight() && target === player2 && isShadowJester(target))) return false;
  chronoCh.jesterSlow = getDebugDuration(chronoTimeStopDuration, target);
  showFlametombThought(target, 'J... a... j... a... ¿c-r-e-i-s-t-e... q-u-e... m-e... p-a-r-a-b-a-s?');
  return true;
}

// the overcharged look, part two: a golden gear spinning behind him and a golden clock face
function drawChronoOverchargedHalo() {
  if (!((isChronoJesterFight() || isChronoTitanFight()) && chronoCh.overcharged && player1.characterType === 'chrono')) return;
  const fighter = player1;
  const time = performance.now() / 1000;
  const cx = fighter.position.x + fighter.width / 2;
  const cy = fighter.position.y + 10;
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(time * 1.5);
  ctx.strokeStyle = 'rgba(255, 213, 79, 0.85)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(0, 0, 26, 0, Math.PI * 2);
  ctx.stroke();
  for (let tooth = 0; tooth < 10; tooth += 1) {
    ctx.save();
    ctx.rotate((tooth / 10) * Math.PI * 2);
    ctx.fillStyle = '#ffd54f';
    ctx.fillRect(-3, -34, 6, 9);
    ctx.restore();
  }
  ctx.restore();
  // the clock on his chest turns gold
  const fx = fighter.position.x + fighter.width / 2;
  const fy = fighter.position.y + 68;
  ctx.save();
  ctx.strokeStyle = '#ffd54f';
  ctx.shadowColor = '#ffd54f';
  ctx.shadowBlur = 12;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(fx, fy, 15, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

