function startChronoJesterCeiling() {
  chronoCh.ceilingDone = true;
  chronoCh.jesterSlow = 0;
  orderFx.items = [];
  forestFx.items = [];
  if (typeof clearJesterProjectiles === 'function') clearJesterProjectiles();
  player1.chronoTimeStopTimer = 0;
  player2.chronoTimeStopTimer = 0;
  player1.rareMachine = false;
  const divine = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
  divine.setCharacterType('divineGeneral');
  ch6CutsceneBase('originsIntro', chronoJesterCeilingLines, 'dialog', {
    darkWorld: true,
    noVersus: true,
    darkMusic: false,
    ceilingScene: true,
    gamblerX: 300,
    gamblerTargetX: 300,
    scammerX: 560,
    scammerTargetX: 560,
    scammerY: 0,
    hideEnemy: false,
    lastFlagLine: -1,
    descendY: 2,
    liftT: 0,
    hallKnightX: 90,
    hallKnightDir: 1,
    hallDivine: divine,
    hallDivineX: -120,
    hallDivineAlpha: 0,
    rubble: [],
    thudT: 0,
    memoryT: 0,
    glowT: 0,
    clashT: 0,
  });
  selectedMap = 'castleThroneHall';
  startCutsceneLine(0);
}

function chronoHallDust(cutscene, count) {
  for (let grain = 0; grain < count; grain += 1) {
    cutscene.rubble.push({ x: chronoCeilingHoleX - 50 + Math.random() * 100, y: 10, vy: 1 + Math.random() * 3, size: 2 + Math.random() * 6, life: 160 });
  }
}

function breakChronoHallCeiling(cutscene) {
  cutscene.ceilingBroken = true;
  chronoCh.ceilingBroken = true;
  cutscene.shake = 26;
  playNoise({ duration: 1.4, volume: 0.18, filterFrequency: 500 });
  playTone({ frequency: 60, duration: 1.2, type: 'sawtooth', volume: 0.1, slideTo: 30 });
  chronoHallDust(cutscene, 50);
}

function updateChronoJesterCeiling(cutscene, line, firstFrame) {
  // Chrono doesn't float here: he's spent
  cutscene.gamblerHop = 0;
  if (line.jesterDown) cutscene.scammerY = 0;
  if (line.jesterRise) {
    cutscene.scammerY = 8 + Math.sin(cutscene.frame / 6) * 8;
    if (firstFrame && line.emote) [0, 160, 320].forEach((delay) => setTimeout(() => playSound('jesterLaugh'), delay));
  }
  // he grabs him: a blink and he's right on top of Chrono
  if (line.grab && firstFrame && !cutscene.grabbed) {
    cutscene.grabbed = true;
    cutscene.flash = 0.5;
    playNoise({ duration: 0.3, volume: 0.08, filterFrequency: 3000 });
  }
  if (line.grab) {
    cutscene.scammerX += (cutscene.gamblerX + 70 - cutscene.scammerX) * 0.25;
    cutscene.scammerTargetX = cutscene.scammerX;
  }
  // ...and up, through the ceiling
  if (line.lift) {
    cutscene.liftT += 1;
    const rise = Math.min(700, cutscene.liftT * cutscene.liftT * 0.09);
    cutscene.gamblerHop = rise;
    cutscene.scammerY = rise;
    if (rise > ground - 40 && !cutscene.ceilingBroken) breakChronoHallCeiling(cutscene);
  }
  // (if the line was skipped fast, the ceiling still breaks)
  if (line.gone && !cutscene.ceilingBroken) breakChronoHallCeiling(cutscene);
  if (line.gone) {
    cutscene.gamblerX = -400;
    cutscene.gamblerTargetX = -400;
    cutscene.hideEnemy = true;
  }
  // the fight goes on upstairs: thuds, dust from the hole
  if (line.above) {
    cutscene.thudT += 1;
    if (cutscene.thudT % 55 === 0) {
      playNoise({ duration: 0.35, volume: 0.1, filterFrequency: 300 });
      cutscene.shake = Math.max(cutscene.shake || 0, 6);
      chronoHallDust(cutscene, 8);
      if (Math.random() < 0.4) playSound('jesterLaugh');
    }
  }
  cutscene.rubble.forEach((bit) => {
    bit.y = Math.min(ground - bit.size, bit.y + bit.vy);
    bit.life -= 1;
  });
  cutscene.rubble = cutscene.rubble.filter((bit) => bit.life > 0);
  // the knight walks under the hole... and turns to face whoever comes in
  if (line.knightCenter) cutscene.hallKnightX += (chronoCeilingHoleX + 60 - cutscene.hallKnightX) * 0.03;
  if (line.knightTurn) {
    cutscene.hallKnightDir = -1;
    cutscene.hallKnightX += (560 - cutscene.hallKnightX) * 0.05;
  }
  if (line.divineWalk || line.divineStop) cutscene.hallDivineAlpha = Math.min(1, cutscene.hallDivineAlpha + 0.03);
  if (line.divineWalk) cutscene.hallDivineX = Math.min(260, cutscene.hallDivineX + 1.2);
  if (line.divineStop) cutscene.hallDivineX += (220 - cutscene.hallDivineX) * 0.05;
  if (line.memory) cutscene.memoryT = Math.min(1, cutscene.memoryT + 0.03);
  else cutscene.memoryT = Math.max(0, cutscene.memoryT - 0.03);
  if (line.divineGlow) cutscene.glowT = Math.min(1, cutscene.glowT + 0.02);
  if (line.divineGlow && firstFrame && !line.knightGlow) playTone({ frequency: 520, duration: 1, type: 'sine', volume: 0.05, slideTo: 880 });
  if (line.knightGlow && firstFrame && !line.clash) playTone({ frequency: 110, duration: 1, type: 'sawtooth', volume: 0.06, slideTo: 70 });
  if (line.clash) {
    cutscene.clashT += 1;
    if (cutscene.clashT === 70) {
      cutscene.flash = 1;
      cutscene.shake = 22;
      playNoise({ duration: 1, volume: 0.16, filterFrequency: 2500 });
      playSound('robotHit');
    }
  }
  cutscene.shake = (cutscene.shake || 0) * 0.92;
}

const chronoCeilingHoleX = 430;

// the hole in the ceiling (it stays there in level 7)
function drawChronoCeilingHole() {
  const time = performance.now() / 1000;
  const x = chronoCeilingHoleX;
  ctx.save();
  ctx.fillStyle = '#020104';
  ctx.beginPath();
  ctx.moveTo(x - 80, 0);
  [[-70, 26], [-46, 18], [-30, 44], [-6, 30], [14, 52], [34, 28], [56, 40], [72, 16], [84, 0]].forEach(([dx, dy]) => ctx.lineTo(x + dx, dy));
  ctx.closePath();
  ctx.fill();
  // faint light from upstairs, flickering with the blows
  ctx.fillStyle = `rgba(234, 128, 252, ${0.06 + Math.max(0, Math.sin(time * 9)) * 0.08})`;
  ctx.beginPath();
  ctx.moveTo(x - 40, 30);
  ctx.lineTo(x + 40, 30);
  ctx.lineTo(x + 110, ground);
  ctx.lineTo(x - 110, ground);
  ctx.closePath();
  ctx.fill();
  // broken beams hanging from the hole (they reach below the dialog box)
  [[-62, 0.35, 190], [58, -0.42, 160], [12, 0.12, 120]].forEach(([dx, tilt, len], index) => {
    ctx.save();
    ctx.translate(x + dx, 20);
    ctx.rotate(tilt + Math.sin(time * 1.6 + index) * 0.03);
    ctx.fillStyle = '#2a1d16';
    ctx.fillRect(-7, 0, 14, len);
    ctx.fillStyle = '#3d2a1f';
    ctx.fillRect(-7, 0, 4, len);
    // the splintered end
    ctx.beginPath();
    ctx.moveTo(-7, len);
    ctx.lineTo(-2, len + 14);
    ctx.lineTo(2, len + 4);
    ctx.lineTo(7, len + 12);
    ctx.lineTo(7, len);
    ctx.closePath();
    ctx.fillStyle = '#2a1d16';
    ctx.fill();
    ctx.restore();
  });
  // cracks running down the wall from the hole
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.7)';
  ctx.lineWidth = 2;
  [[-80, -1], [84, 1]].forEach(([dx, side]) => {
    ctx.beginPath();
    ctx.moveTo(x + dx, 0);
    ctx.lineTo(x + dx + side * 20, 60);
    ctx.lineTo(x + dx + side * 12, 120);
    ctx.lineTo(x + dx + side * 34, 200);
    ctx.stroke();
  });
  // rubble on the carpet
  ctx.fillStyle = '#2b2530';
  [[-60, 10, 18], [-30, 14, 26], [4, 9, 16], [28, 12, 22], [56, 8, 14]].forEach(([dx, h, w]) => ctx.fillRect(x + dx, ground - h, w, h));
  ctx.restore();
}

function drawChronoJesterCeilingFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  // the knight: watching from the side, then under the hole, then facing the General
  ctx.save();
  if (cutscene.glowT > 0 && line.knightGlow) {
    ctx.shadowColor = '#000000';
    ctx.shadowBlur = 30;
  }
  drawBlackKnight(cutscene.hallKnightX, ground, cutscene.hallKnightDir, time);
  ctx.restore();
  if (line.knightGlow) {
    ctx.save();
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + Math.sin(time * 8) * 0.15})`;
    ctx.lineWidth = 2;
    ctx.strokeRect(cutscene.hallKnightX - 40, ground - 146, 80, 146);
    ctx.restore();
  }
  // Divine General, walking in
  if (cutscene.hallDivineAlpha > 0) {
    const divine = cutscene.hallDivine;
    if (cutscene.glowT > 0) {
      const cx = cutscene.hallDivineX + divine.width / 2;
      const aura = ctx.createRadialGradient(cx, ground - divine.height / 2, 10, cx, ground - divine.height / 2, 120);
      aura.addColorStop(0, `rgba(255, 255, 255, ${0.35 * cutscene.glowT})`);
      aura.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = aura;
      ctx.fillRect(cx - 120, ground - divine.height / 2 - 120, 240, 240);
    }
    ctx.save();
    ctx.globalAlpha = cutscene.hallDivineAlpha;
    divine.position = { x: cutscene.hallDivineX, y: ground - divine.height };
    divine.attacksToTheRight = true;
    divine.isAttacking = false;
    divine.draw();
    ctx.restore();
  }
  // the clash: both of them, a light and a shadow meeting in the middle
  if (line.clash && cutscene.clashT < 70) {
    const k = cutscene.clashT / 70;
    const mid = (cutscene.hallDivineX + 40 + cutscene.hallKnightX) / 2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = `rgba(255, 255, 255, ${k * 0.4})`;
    ctx.fillRect(cutscene.hallDivineX + 40, ground - 90, (mid - cutscene.hallDivineX - 40) * k, 8);
    ctx.restore();
    ctx.fillStyle = `rgba(0, 0, 0, ${k * 0.6})`;
    ctx.fillRect(mid + (cutscene.hallKnightX - 40 - mid) * (1 - k), ground - 90, (cutscene.hallKnightX - 40 - mid) * k, 8);
  }
  cutscene.rubble.forEach((bit) => {
    ctx.fillStyle = `rgba(90, 80, 95, ${Math.min(1, bit.life / 60)})`;
    ctx.fillRect(bit.x, bit.y, bit.size, bit.size);
  });
  // the memory: the day of the banishment, in a cold sepia
  if (cutscene.memoryT > 0) {
    ctx.fillStyle = `rgba(80, 60, 30, ${cutscene.memoryT * 0.35})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.globalAlpha = cutscene.memoryT * 0.25;
    ctx.fillStyle = '#000';
    for (let bar = 0; bar < canvas.height; bar += 4) ctx.fillRect(0, bar, canvas.width, 1);
    ctx.restore();
  }
}

// ================= LEVEL 6, second part: the banished General against the guardian of the door =================
reflecterBattleTrackSources.desterrado = encodeURI('assetsaudio/El Desterrado (Moquete).wav');
