// ================= LEVEL 7: on the roof... the dark shot, and the light that came out of it =================
// the roof ends at chronoRoofEdgeX: beyond it, the long drop to the ground (where the shot lands)
const chronoRoofEdgeX = 800;
const chronoRoofImpactX = 925;

function drawCastleRoofStage() {
  const time = performance.now() / 1000;
  const sky = ctx.createLinearGradient(0, 0, 0, ground);
  sky.addColorStop(0, '#020104');
  sky.addColorStop(0.7, '#0b0612');
  sky.addColorStop(1, '#1a0d24');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // a few cold stars that blink out of rhythm
  for (let star = 0; star < 40; star += 1) {
    const blink = Math.sin(time * (0.7 + (star % 5) * 0.3) + star) > 0.2 ? 1 : 0.3;
    ctx.fillStyle = `rgba(230, 220, 255, ${0.5 * blink})`;
    ctx.fillRect((star * 131) % canvas.width, (star * 53) % 260, 2, 2);
  }
  // other towers of the castle in the distance
  ctx.fillStyle = '#0d0a12';
  [[40, 250, 70], [180, 200, 50], [760, 180, 60], [900, 240, 80]].forEach(([tx, top, w]) => {
    ctx.fillRect(tx, top, w, ground - top);
    ctx.beginPath();
    ctx.moveTo(tx - 8, top);
    ctx.lineTo(tx + w / 2, top - 60);
    ctx.lineTo(tx + w + 8, top);
    ctx.fill();
  });
  ctx.fillStyle = 'rgba(255, 213, 79, 0.5)';
  [[60, 300], [200, 260], [790, 230], [930, 290]].forEach(([wx, wy]) => ctx.fillRect(wx, wy, 6, 10));
  drawChronoTitanStageLayer();
  // the roof: dark slate, the battlements on the edge
  ctx.fillStyle = '#17121d';
  ctx.fillRect(0, ground, chronoRoofEdgeX, canvas.height - ground);
  ctx.strokeStyle = '#231b2b';
  ctx.lineWidth = 2;
  for (let row = 0; row < 4; row += 1) {
    ctx.beginPath();
    ctx.moveTo(0, ground + 12 + row * 14);
    ctx.lineTo(chronoRoofEdgeX, ground + 12 + row * 14);
    ctx.stroke();
  }
  ctx.fillStyle = '#211a28';
  ctx.fillRect(0, ground - 4, chronoRoofEdgeX, 6);
  for (let merlon = 0; merlon < chronoRoofEdgeX - 30; merlon += 64) ctx.fillRect(merlon, ground - 22, 34, 20);
  // the edge: the corner of the roof and the wall falling down into the dark
  ctx.fillStyle = '#2a2131';
  ctx.fillRect(chronoRoofEdgeX - 26, ground - 40, 26, 40);
  const drop = ctx.createLinearGradient(0, ground - 30, 0, canvas.height);
  drop.addColorStop(0, 'rgba(26, 13, 36, 0)');
  drop.addColorStop(1, '#030106');
  ctx.fillStyle = drop;
  ctx.fillRect(chronoRoofEdgeX, ground - 30, canvas.width - chronoRoofEdgeX, canvas.height - ground + 30);
  ctx.fillStyle = '#100c15';
  ctx.fillRect(chronoRoofEdgeX - 6, ground, 10, canvas.height - ground);
  // far, far below: a faint mist over the ground
  ctx.fillStyle = `rgba(120, 100, 140, ${0.08 + Math.sin(time) * 0.03})`;
  ctx.fillRect(chronoRoofEdgeX + 4, canvas.height - 14, canvas.width - chronoRoofEdgeX, 14);
  // the hole they came up through
  ctx.fillStyle = '#030205';
  ctx.beginPath();
  ctx.ellipse(chronoCeilingHoleX, ground + 8, 70, 9, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(234, 128, 252, 0.08)';
  ctx.fillRect(chronoCeilingHoleX - 60, ground + 2, 120, 10);
  // the black wind
  ctx.strokeStyle = 'rgba(180, 160, 200, 0.08)';
  for (let gust = 0; gust < 6; gust += 1) {
    const gx = ((time * 220 + gust * 190) % (canvas.width + 200)) - 100;
    ctx.beginPath();
    ctx.moveTo(gx, 80 + gust * 60);
    ctx.lineTo(gx + 90, 78 + gust * 60);
    ctx.stroke();
  }
}

