function playChronoFaroSound() {
  if (typeof Audio === 'undefined') return;
  try {
    if (!chronoFaroSound.audio) chronoFaroSound.audio = new Audio(chronoFaroSource);
    const audio = chronoFaroSound.audio;
    audio.currentTime = 0;
    audio.volume = Math.min(1, 1 * audioSettings.master * Math.max(0.4, audioSettings.sfx));
    const played = audio.play();
    if (played && played.catch) played.catch(() => {});
  } catch (error) {
    // no audio: the scene still plays
  }
}

