function updateChronoDarkShot(cutscene, line, firstFrame) {
  // the machine drinks something black: the roof goes dark around it
  if (line.darkCharge) {
    cutscene.darkK = Math.min(line.darkMax ? 1 : 0.6, cutscene.darkK + 0.005);
    for (let bit = 0; bit < (line.darkMax ? 5 : 2); bit += 1) {
      const angle = Math.random() * Math.PI * 2;
      cutscene.darkBits.push({ angle, dist: 160 + Math.random() * 140, life: 40 });
    }
    if (cutscene.frame % 7 === 0) playTone({ frequency: 70 + cutscene.darkK * 160, duration: 0.14, type: 'sawtooth', volume: 0.05 });
    if (line.darkMax && Math.random() < 0.12) cutscene.darkBolts.push({ life: 8, seed: Math.random() * 1000 });
    cutscene.shake = Math.max(cutscene.shake || 0, cutscene.darkK * (line.darkMax ? 7 : 3));
  }
  cutscene.darkBits.forEach((bit) => {
    bit.dist *= 0.92;
    bit.life -= 1;
  });
  cutscene.darkBits = cutscene.darkBits.filter((bit) => bit.life > 0);
  cutscene.darkBolts.forEach((bolt) => { bolt.life -= 1; });
  cutscene.darkBolts = cutscene.darkBolts.filter((bolt) => bolt.life > 0);
  // the shot: an inverted flash and a black beam
  if (line.darkShoot && firstFrame && !cutscene.shotPlayed) {
    cutscene.shotPlayed = true;
    cutscene.invert = 1;
    cutscene.shake = 30;
    cutscene.darkK = 0;
    playNoise({ duration: 1.6, volume: 0.2, filterFrequency: 600 });
    playTone({ frequency: 60, duration: 1.6, type: 'sawtooth', volume: 0.13, slideTo: 30 });
    playTone({ frequency: 900, duration: 0.6, type: 'square', volume: 0.04, slideTo: 120 });
  }
  if (cutscene.invert > 0) cutscene.invert = Math.max(0, cutscene.invert - 0.06);
  // slow motion: the beam crawls, the jester floats over it
  const slow = line.slowMo ? 0.25 : 1;
  if (line.darkShoot || line.impact) cutscene.beamK = Math.min(1, cutscene.beamK + 0.06 * slow);
  else cutscene.beamK = Math.max(0, cutscene.beamK - 0.1);
  if (line.dodge) {
    cutscene.jumpY = Math.min(260, (cutscene.jumpY || 0) + 12 * slow);
    cutscene.scammerX += (560 - cutscene.scammerX) * 0.05 * slow;
    cutscene.scammerTargetX = cutscene.scammerX;
    if (cutscene.frame % 4 === 0) cutscene.trail.push({ x: cutscene.scammerX, y: cutscene.jumpY, life: 26 });
    if (line.slowMo && cutscene.frame % 20 === 0) playTone({ frequency: 120, duration: 0.5, type: 'sine', volume: 0.05, slideTo: 90 });
  }
  // (the engine puts him back on the floor every frame: keep his own height)
  cutscene.scammerY = cutscene.jumpY || 0;
  cutscene.trail.forEach((ghost) => { ghost.life -= 1; });
  cutscene.trail = cutscene.trail.filter((ghost) => ghost.life > 0);
  if (line.holdLanded || line.jesterLeave) {
    cutscene.jumpY = Math.max(0, (cutscene.jumpY || 0) - 16);
    cutscene.scammerX += (560 - cutscene.scammerX) * 0.2;
    cutscene.scammerTargetX = cutscene.scammerX;
  }
  // the music dies when the shot misses
  if (line.fadeMusic) cutscene.musicFade = Math.max(0, cutscene.musicFade - 1 / 150);
  // (far below: the impact arrives a moment later, muffled)
  if (line.impact) {
    cutscene.impactT = (cutscene.impactT || 0) + 1;
    if (cutscene.impactT === 50) {
      cutscene.shake = 12;
      playNoise({ duration: 0.9, volume: 0.1, filterFrequency: 200 });
      playTone({ frequency: 45, duration: 1, type: 'sine', volume: 0.1, slideTo: 30 });
    }
  }
  // a silence... and something under the roof, getting closer
  if (line.rumble) {
    cutscene.rumbleT += 1;
    cutscene.shake = Math.max(cutscene.shake || 0, Math.min(6, cutscene.rumbleT / 40));
    if (cutscene.rumbleT % 24 === 0) playTone({ frequency: 40 + Math.min(40, cutscene.rumbleT / 8), duration: 0.5, type: 'sine', volume: 0.08 });
  }
  // the lighthouse: ABRUPT
  if (line.pillar) {
    if (!cutscene.pillarStarted) {
      cutscene.pillarStarted = true;
      cutscene.flash = 1.6;
      cutscene.shake = 60;
      cutscene.pillarWidth = 1;
      cutscene.shockRings = [0, 1, 2, 3, 4].map((ring) => ({ r: 10 + ring * 40, life: 70 - ring * 6 }));
      for (let chunk = 0; chunk < 40; chunk += 1) {
        cutscene.debrisUp.push({ x: chronoRoofImpactX + (Math.random() - 0.5) * 80, y: canvas.height, vx: (Math.random() - 0.5) * 14, vy: -8 - Math.random() * 16, size: 3 + Math.random() * 8, life: 120 });
      }
      playChronoFaroSound();
      playNoise({ duration: 1.5, volume: 0.25, filterFrequency: 3000 });
    }
    cutscene.pillarT += 1;
    cutscene.shake = Math.max(cutscene.shake || 0, line.pillarHit ? 14 : 6);
  }
  cutscene.shockRings.forEach((ring) => {
    ring.r += 16;
    ring.life -= 1;
  });
  cutscene.shockRings = cutscene.shockRings.filter((ring) => ring.life > 0);
  cutscene.debrisUp.forEach((chunk) => {
    chunk.x += chunk.vx;
    chunk.y += chunk.vy;
    chunk.vy += 0.4;
    chunk.life -= 1;
  });
  cutscene.debrisUp = cutscene.debrisUp.filter((chunk) => chunk.life > 0 && chunk.y < canvas.height + 20);
  if (line.jesterLeave) {
    cutscene.jesterOut = Math.min(1, cutscene.jesterOut + 0.02);
    if (firstFrame) [0, 200, 400].forEach((delay) => setTimeout(() => playSound('jesterLaugh'), delay));
  }
  if (line.jesterGone) cutscene.hideEnemy = true;
  // Abnormal: drops in his own light... and leaves the same way
  if (line.abnIn) {
    cutscene.abnT += 1;
    if (firstFrame && unlockChronoSecretLevel()) cutscene.secretNotice = 240;
    if (firstFrame) {
      cutscene.abnY = 420;
      playNoise({ duration: 0.6, volume: 0.08, filterFrequency: 5000 });
      playTone({ frequency: 1200, duration: 1, type: 'sine', volume: 0.05, slideTo: 300 });
    }
    cutscene.abnY = Math.max(0, cutscene.abnY - 14);
  } else if (line.abnLeave) {
    if (firstFrame) {
      cutscene.abnLeaveT = 0;
      playTone({ frequency: 300, duration: 1, type: 'sine', volume: 0.05, slideTo: 1200 });
    }
    cutscene.abnLeaveT = (cutscene.abnLeaveT || 0) + 1;
    cutscene.abnY = cutscene.abnLeaveT > 60 ? Math.min(600, (cutscene.abnLeaveT - 60) * (cutscene.abnLeaveT - 60) * 0.15) : 0;
  } else if (line.abn) {
    cutscene.abnY = 0;
  }
  updateChronoCameoMusic(cutscene, line);
  if ((line.smoke || line.abnLeave) && firstFrame) stopChronoCameoMusic();
  if (line.abnShock && firstFrame) playTone({ frequency: 880, duration: 0.25, type: 'square', volume: 0.04, slideTo: 1400 });
  // the light goes out... and the smoke comes up, slowly
  if (line.smoke) {
    if (firstFrame && !cutscene.offPlayed) {
      cutscene.offPlayed = true;
      if (chronoFaroSound.audio) chronoFaroSound.audio.pause();
      playTone({ frequency: 200, duration: 0.6, type: 'sine', volume: 0.08, slideTo: 40 });
    }
    cutscene.pillarFade = Math.max(0, cutscene.pillarFade - 0.1);
    cutscene.smokeT = Math.min(line.smokeFull ? 1 : 0.75, cutscene.smokeT + 0.0025);
    if (cutscene.frame % 30 === 0) playTone({ frequency: 45, duration: 0.9, type: 'sine', volume: 0.07, slideTo: 38 });
  }
  if (cutscene.flash > 0) cutscene.flash = Math.max(0, cutscene.flash - 0.025);
  cutscene.shake = (cutscene.shake || 0) * 0.93;
}

function drawChronoDarkShotFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  const mx = cutscene.gamblerX + player1.width + 10;
  const my = ground - player1.height - (cutscene.gamblerHop || 0) + 25;
  // the roof goes dark while the machine charges
  if (cutscene.darkK > 0) {
    const vignette = ctx.createRadialGradient(mx, my, 40, mx, my, 700);
    vignette.addColorStop(0, 'rgba(0, 0, 0, 0)');
    vignette.addColorStop(1, `rgba(0, 0, 0, ${cutscene.darkK * 0.75})`);
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  cutscene.darkBits.forEach((bit) => {
    ctx.fillStyle = bit.life % 4 < 2 ? '#000000' : '#ffffff';
    ctx.fillRect(mx + Math.cos(bit.angle) * bit.dist - 3, my + Math.sin(bit.angle) * bit.dist - 3, 6, 6);
  });
  // black lightning with a white edge
  cutscene.darkBolts.forEach((bolt) => {
    let bx = mx;
    let by = my;
    const angle = (bolt.seed % 6.28);
    ctx.beginPath();
    ctx.moveTo(bx, by);
    for (let step = 0; step < 7; step += 1) {
      bx += Math.cos(angle) * 30 + (Math.random() - 0.5) * 30;
      by += Math.sin(angle) * 30 + (Math.random() - 0.5) * 30;
      ctx.lineTo(bx, by);
    }
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 6;
    ctx.stroke();
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 3;
    ctx.stroke();
  });
  if (cutscene.darkK > 0) {
    const r = 8 + cutscene.darkK * 46 + Math.sin(time * 20) * 3;
    ctx.save();
    ctx.fillStyle = '#000000';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(mx, my, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.beginPath();
    ctx.arc(mx, my, r + 10 + Math.sin(time * 9) * 4, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }
  // the dark beam: black, with a white edge, into the roof where the jester was
  if (cutscene.beamK > 0) {
    // (through the jester's spot, over the edge of the roof, down to the ground)
    const passX = chronoRoofEdgeX;
    const passY = ground - 34;
    const reach = (canvas.height + 80 - my) / Math.max(1, passY - my);
    const tx = mx + (passX - mx) * reach;
    const ty = my + (passY - my) * reach;
    const ex = mx + (tx - mx) * cutscene.beamK;
    const ey = my + (ty - my) * cutscene.beamK;
    const thick = 70 + Math.sin(time * 30) * 6;
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = thick + 10;
    ctx.beginPath();
    ctx.moveTo(mx, my);
    ctx.lineTo(ex, ey);
    ctx.stroke();
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = thick;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(179, 136, 255, 0.55)';
    ctx.lineWidth = 8;
    ctx.stroke();
    // white rings running along it
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.lineWidth = 3;
    for (let ring = 0; ring < 5; ring += 1) {
      const along = ((time * (line.slowMo ? 0.6 : 2.5) + ring / 5) % 1) * cutscene.beamK;
      ctx.beginPath();
      ctx.ellipse(mx + (tx - mx) * along, my + (ty - my) * along, 12, thick * 0.7, Math.atan2(ty - my, tx - mx), 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }
  // the jester's afterimages, leaping over it
  cutscene.trail.forEach((ghost) => {
    ctx.save();
    ctx.globalAlpha = (ghost.life / 26) * 0.35;
    ctx.fillStyle = '#7e57c2';
    ctx.fillRect(ghost.x, ground - player2.height - ghost.y, player2.width, player2.height);
    ctx.restore();
  });
  // slow motion bars
  if (line.slowMo) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.fillRect(0, 0, canvas.width, 40);
    ctx.fillRect(0, canvas.height - 40, canvas.width, 40);
  }
  // the hole the dark shot left in the roof (cracks of light before it opens)
  if (line.rumble && cutscene.rumbleT > 0) {
    // a light growing down there, past the edge
    const k = Math.min(1, cutscene.rumbleT / 160);
    const below = ctx.createRadialGradient(chronoRoofImpactX, canvas.height + 30, 5, chronoRoofImpactX, canvas.height + 30, 60 + k * 200);
    below.addColorStop(0, `rgba(255, 255, 240, ${0.4 + k * 0.6})`);
    below.addColorStop(1, 'rgba(255, 255, 240, 0)');
    ctx.fillStyle = below;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = `rgba(255, 255, 240, ${k * 0.6})`;
    ctx.lineWidth = 2;
    for (let ray = 0; ray < 5; ray += 1) {
      if (Math.random() < 0.5) continue;
      const rx = chronoRoofImpactX + (ray - 2) * 26;
      ctx.beginPath();
      ctx.moveTo(rx, canvas.height);
      ctx.lineTo(rx + (Math.random() - 0.5) * 20, canvas.height - 60 - k * 200);
      ctx.stroke();
    }
  }
  // the lighthouse: a huge column of light up to the sky, beams sweeping the whole sky
  if ((line.pillar || line.smoke) && cutscene.pillarFade > 0) {
    const x = chronoRoofImpactX;
    const k = cutscene.pillarFade;
    const pulse = 1 + Math.sin(time * 10) * 0.05;
    const width = 210 * pulse;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const column = ctx.createLinearGradient(x - width * 1.8, 0, x + width * 1.8, 0);
    column.addColorStop(0, 'rgba(255, 255, 255, 0)');
    column.addColorStop(0.35, `rgba(255, 250, 220, ${0.45 * k})`);
    column.addColorStop(0.5, `rgba(255, 255, 255, ${k})`);
    column.addColorStop(0.65, `rgba(255, 250, 220, ${0.45 * k})`);
    column.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = column;
    ctx.fillRect(x - width * 1.8, 0, width * 3.6, canvas.height);
    // the white-hot core
    ctx.fillStyle = `rgba(255, 255, 255, ${k})`;
    ctx.fillRect(x - width * 0.22, 0, width * 0.44, canvas.height);
    // the lighthouse beams: long, wide, turning
    const angle = time * 1.1;
    [0, Math.PI].forEach((offset) => {
      const a = angle + offset;
      const reach = 1600 * Math.cos(a);
      const spread = 90 + 160 * Math.abs(Math.sin(a));
      const beam = ctx.createLinearGradient(x, 140, x + reach, 140);
      beam.addColorStop(0, `rgba(255, 255, 230, ${0.75 * k})`);
      beam.addColorStop(1, 'rgba(255, 255, 230, 0)');
      ctx.fillStyle = beam;
      ctx.beginPath();
      ctx.moveTo(x, 140);
      ctx.lineTo(x + reach, 140 - spread);
      ctx.lineTo(x + reach, 140 + spread);
      ctx.closePath();
      ctx.fill();
    });
    // rays shooting up into the sky
    for (let ray = 0; ray < 9; ray += 1) {
      const rx = x + (ray - 4) * 46 + Math.sin(time * 3 + ray) * 10;
      ctx.fillStyle = `rgba(255, 255, 255, ${0.25 * k})`;
      ctx.fillRect(rx - 3, 0, 6, canvas.height);
    }
    const glow = ctx.createRadialGradient(x, canvas.height, 10, x, canvas.height, 360);
    glow.addColorStop(0, `rgba(255, 255, 255, ${k})`);
    glow.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - 360, canvas.height - 360, 720, 720);
    ctx.restore();
  }
  cutscene.shockRings.forEach((ring) => {
    ctx.strokeStyle = `rgba(255, 255, 255, ${ring.life / 70})`;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.ellipse(chronoRoofImpactX, canvas.height - 10, ring.r, ring.r * 0.35, 0, 0, Math.PI * 2);
    ctx.stroke();
  });
  cutscene.debrisUp.forEach((chunk) => {
    ctx.fillStyle = '#211a28';
    ctx.fillRect(chunk.x, chunk.y, chunk.size, chunk.size);
  });
  // the jester leaving: he fades, bowing, into confetti
  if (line.jesterLeave && cutscene.jesterOut > 0) {
    for (let bit = 0; bit < 14; bit += 1) {
      ctx.fillStyle = ['#ea80fc', '#fdd835', '#b388ff', '#ff4081'][bit % 4];
      ctx.fillRect(cutscene.scammerX + 30 + Math.sin(bit * 2 + time * 4) * 60 * cutscene.jesterOut, ground - 60 - bit * 8 - cutscene.jesterOut * 80, 4, 4);
    }
  }
  // what came out of the hole: pure black smoke, edged in white, rising slowly
  if (line.smoke) {
    ctx.fillStyle = `rgba(0, 0, 0, ${0.25 + cutscene.smokeT * 0.2})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    drawChronoRoofSmoke(chronoRoofImpactX, cutscene.smokeT, time);
  }
  drawChronoAbnormalCameo(cutscene, line, time);
  // the inverted flash of the shot
  if (cutscene.invert > 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'difference';
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.invert})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.restore();
  }
  if (cutscene.flash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${Math.min(1, cutscene.flash)})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

function drawChronoRoofSmoke(x, k, time) {
  const base = canvas.height + 20;
  const height = 420 * k;
  const puffs = [];
  for (let puff = 0; puff < 16; puff += 1) {
    const along = puff / 15;
    if (along * 420 > height) break;
    const r = 34 + Math.sin(along * Math.PI) * 26 - along * 10;
    const sway = Math.sin(time * 1.3 + puff * 0.8) * (8 + along * 18);
    puffs.push({ px: x + sway, py: base - along * 420, r: r + Math.sin(time * 2 + puff) * 4 });
  }
  // first the white edge, then the black on top: one smoke, outlined
  ctx.save();
  ctx.fillStyle = '#ffffff';
  puffs.forEach(({ px, py, r }) => {
    ctx.beginPath();
    ctx.arc(px, py, r + 3, 0, Math.PI * 2);
    ctx.fill();
  });
  ctx.fillStyle = '#000000';
  puffs.forEach(({ px, py, r }) => {
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fill();
  });
  // wisps peeling off the top
  for (let wisp = 0; wisp < 6; wisp += 1) {
    const rise = (time * 30 + wisp * 25) % 80;
    const wx = x + Math.sin(time + wisp * 1.7) * 40;
    const wy = base - height - rise;
    ctx.globalAlpha = Math.max(0, 1 - rise / 80) * k;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(wx, wy, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.arc(wx, wy, 7, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

// ================= LEVEL 8: the titan =================
reflecterBattleTrackSources.guardian = encodeURI('assetsaudio/68. GUARDIAN (DELTARUNE Chapter 3+4 Soundtrack) - Toby Fox.mp3');
reflecterBattleTrackVolumes.guardian = 0.7;

['babyTitan', 'titanBody'].forEach((variant) => {
  if (!originsVariants.includes(variant)) originsVariants.push(variant);
  if (!arcadeBossVariants.includes(variant)) arcadeBossVariants.push(variant);
});
originsSizes.babyTitan = [62, 116];
originsSpeeds.babyTitan = 1.15;
originsDamage.babyTitan = 1.05;
originsHealth.babyTitan = 230;
originsNames.babyTitan = 'Bebe Titan';
originsSizes.titanBody = [60, 120];
originsSpeeds.titanBody = 0.01;
originsDamage.titanBody = 1;
originsHealth.titanBody = 10000;
originsNames.titanBody = 'TITAN';

const chronoTitan = { visible: false, rise: 0, look: 1, eyeGlow: 1, recoil: 0, attacks: [], next: 150, dodgeLeft: 0, step: 0, bar: null };
const chronoTitanDodgeFrames = 2400;
const chronoTitanX = 760;
const chronoTitanHeadY = 150;

function isChronoTitanFight() {
  return isChronoChapterFight() && (selectedNormalArcadeLevel === 8 || selectedNormalArcadeLevel === 9);
}

function isBabyTitan(fighter) {
  return Boolean(fighter && fighter.secretVariant === 'babyTitan');
}

function resetChronoTitan() {
  Object.assign(chronoTitan, { visible: false, rise: 0, look: 1, eyeGlow: 1, recoil: 0, attacks: [], next: 150, dodgeLeft: chronoTitanDodgeFrames, step: 0, bar: null, power: 1, shotNumber: 0, slowT: 0, slowAcc: 0, rushLeft: 0 });
}

// ---------- the titan: pure black, edged in white ----------
function titanPath(points) {
  ctx.beginPath();
  points.forEach(([px, py], index) => (index ? ctx.lineTo(px, py) : ctx.moveTo(px, py)));
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
}

function drawDarkTitan(cx, headY, s, look, time, eyeGlow = 1) {
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 4;
  const breathe = Math.sin(time * 0.9) * 6 * s;
  const y = headY + breathe;
  // the smoke it is still made of, rising off its shoulders
  for (let puff = 0; puff < 14; puff += 1) {
    const side = puff % 2 ? 1 : -1;
    const rise = (time * 25 + puff * 37) % 220;
    const px = cx + side * (220 + (puff * 29) % 160) * s + Math.sin(time + puff) * 10;
    const py = y + 240 * s - rise * s;
    const r = (26 - rise / 12) * s;
    if (r <= 2) continue;
    ctx.globalAlpha = Math.max(0, 1 - rise / 220);
    ctx.beginPath();
    ctx.arc(px, py, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  // shoulders and chest
  titanPath([
    [cx - 470 * s, y + 900 * s], [cx - 430 * s, y + 330 * s], [cx - 380 * s, y + 250 * s],
    [cx - 150 * s, y + 220 * s], [cx - 80 * s, y + 250 * s], [cx + 80 * s, y + 250 * s],
    [cx + 150 * s, y + 220 * s], [cx + 380 * s, y + 250 * s], [cx + 430 * s, y + 330 * s], [cx + 470 * s, y + 900 * s],
  ]);
  // spiked pauldrons
  [-1, 1].forEach((side) => {
    const px = cx + side * 320 * s;
    const py = y + 250 * s;
    titanPath([[px - 110 * s, py + 40 * s], [px - 90 * s, py - 30 * s], [px, py - 60 * s], [px + 90 * s, py - 30 * s], [px + 110 * s, py + 40 * s]]);
    [-60, 0, 60].forEach((dx, index) => {
      titanPath([[px + (dx - 18) * s, py - 30 * s - (index === 1 ? 20 : 0) * s], [px + (dx + side * 10) * s, py - (110 + (index === 1 ? 50 : 0)) * s], [px + (dx + 18) * s, py - 30 * s - (index === 1 ? 20 : 0) * s]]);
    });
  });
  // the white seams of light across its chest, pulsing
  ctx.save();
  ctx.strokeStyle = `rgba(255, 255, 255, ${0.35 + Math.sin(time * 2.4) * 0.25})`;
  ctx.lineWidth = 3;
  ctx.shadowColor = '#ffffff';
  ctx.shadowBlur = 12;
  [[-1, 0], [1, 0.4], [-0.5, 0.8], [0.6, 1.2]].forEach(([dir, off]) => {
    ctx.beginPath();
    ctx.moveTo(cx, y + (300 + off * 60) * s);
    ctx.lineTo(cx + dir * 70 * s, y + (340 + off * 60) * s);
    ctx.lineTo(cx + dir * 40 * s, y + (400 + off * 60) * s);
    ctx.lineTo(cx + dir * 130 * s, y + (450 + off * 60) * s);
    ctx.stroke();
  });
  ctx.restore();
  // the neck
  titanPath([[cx - 70 * s, y + 260 * s], [cx - 60 * s, y + 190 * s], [cx + 60 * s, y + 190 * s], [cx + 70 * s, y + 260 * s]]);
  // the head: a crown of horns, a long jaw
  titanPath([
    [cx - 125 * s, y + 70 * s], [cx - 200 * s, y - 70 * s], [cx - 95 * s, y + 10 * s], [cx - 60 * s, y - 45 * s],
    [cx - 25 * s, y + 5 * s], [cx, y - 80 * s], [cx + 25 * s, y + 5 * s], [cx + 60 * s, y - 45 * s],
    [cx + 95 * s, y + 10 * s], [cx + 200 * s, y - 70 * s], [cx + 125 * s, y + 70 * s],
    [cx + 115 * s, y + 160 * s], [cx + 60 * s, y + 225 * s], [cx, y + 245 * s], [cx - 60 * s, y + 225 * s], [cx - 115 * s, y + 160 * s],
  ]);
  // the mouth: a jagged grin
  const mouthY = y + 178 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 72 * s, mouthY);
  for (let tooth = 0; tooth <= 12; tooth += 1) {
    ctx.lineTo(cx - 72 * s + tooth * 12 * s, mouthY + (tooth % 2 ? 14 : 0) * s);
  }
  ctx.moveTo(cx - 66 * s, mouthY + 24 * s);
  for (let tooth = 0; tooth <= 11; tooth += 1) {
    ctx.lineTo(cx - 66 * s + tooth * 12 * s, mouthY + (tooth % 2 ? 10 : 24) * s);
  }
  ctx.stroke();
  // the eyes: two burning white slits; the hottest point of each one slides (inside it) to where it looks
  [-1, 1].forEach((side) => {
    const ex = cx + side * 58 * s;
    const ey = y + 105 * s;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(ex - side * 50 * s, ey - 22 * s);
    ctx.lineTo(ex + side * 40 * s, ey + 2 * s);
    ctx.lineTo(ex - side * 44 * s, ey + 12 * s);
    ctx.closePath();
    if (eyeGlow <= 0) {
      ctx.fillStyle = '#000000';
      ctx.fill();
      ctx.restore();
      return;
    }
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = 30 * eyeGlow;
    ctx.fillStyle = '#cfcfcf';
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.clip();
    const hx = ex + look * 22 * s;
    const hy = ey - 4 * s;
    const core = ctx.createRadialGradient(hx, hy, 1, hx, hy, 30 * s);
    core.addColorStop(0, '#ffffff');
    core.addColorStop(0.5, 'rgba(255, 255, 255, 0.9)');
    core.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = core;
    ctx.fillRect(ex - 70 * s, ey - 40 * s, 140 * s, 70 * s);
    ctx.restore();
  });
  ctx.restore();
}

// a giant fist: black, knuckles edged in white
function drawTitanFist(x, y, w, h, down, noArm = false) {
  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 4;
  ctx.lineJoin = 'round';
  // the arm going up (or to the right)
  if (noArm) {
    // (a fighter's fist: its arm is drawn apart)
  } else if (down) {
    ctx.fillRect(x + w * 0.2, -20, w * 0.6, y + 30);
    ctx.strokeRect(x + w * 0.2, -20, w * 0.6, y + 30);
  } else {
    ctx.fillRect(x + w - 10, y + h * 0.2, canvas.width + 400, h * 0.6);
    ctx.strokeRect(x + w - 10, y + h * 0.2, canvas.width + 400, h * 0.6);
  }
  ctx.beginPath();
  ctx.roundRect ? ctx.roundRect(x, y, w, h, 26) : ctx.rect(x, y, w, h);
  ctx.fill();
  ctx.stroke();
  // the knuckles: four bumps on the striking side, and a thumb
  for (let knuckle = 0; knuckle < 4; knuckle += 1) {
    ctx.beginPath();
    if (down) ctx.arc(x + (w / 4) * (knuckle + 0.5), y + h - 4, w / 9, 0, Math.PI);
    else ctx.arc(x + 4, y + (h / 4) * (knuckle + 0.5), h / 9, Math.PI / 2, Math.PI * 1.5);
    ctx.fill();
    ctx.stroke();
  }
  ctx.beginPath();
  if (down) ctx.ellipse(x + w - 6, y + h * 0.4, w * 0.12, h * 0.25, -0.3, 0, Math.PI * 2);
  else ctx.ellipse(x + w * 0.35, y + h - 6, w * 0.25, h * 0.12, 0.3, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  // fingers
  for (let finger = 1; finger < 4; finger += 1) {
    ctx.beginPath();
    if (down) {
      ctx.moveTo(x + (w / 4) * finger, y + h * 0.45);
      ctx.lineTo(x + (w / 4) * finger, y + h);
    } else {
      ctx.moveTo(x, y + (h / 4) * finger);
      ctx.lineTo(x + w * 0.55, y + (h / 4) * finger);
    }
    ctx.stroke();
  }
  ctx.restore();
}

// an open hand, sweeping the roof
function drawTitanHand(x, y, w, h) {
  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 4;
  ctx.fillRect(x + w - 10, y + h * 0.15, canvas.width + 600, h * 0.7);
  ctx.strokeRect(x + w - 10, y + h * 0.15, canvas.width + 600, h * 0.7);
  ctx.beginPath();
  ctx.moveTo(x + w, y);
  for (let finger = 0; finger < 4; finger += 1) {
    const fy = y + (h / 4) * finger;
    ctx.lineTo(x + 20, fy + 2);
    ctx.lineTo(x, fy + h / 8);
    ctx.lineTo(x + 20, fy + h / 4 - 2);
  }
  ctx.lineTo(x + w, y + h);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

// the baby titans: Chrono's size, the same black and white
function drawBabyTitan(fighter) {
  const x = fighter.position.x;
  const y = fighter.position.y;
  const w = fighter.width;
  const h = fighter.height;
  const time = performance.now() / 1000;
  const dir = fighter.attacksToTheRight ? 1 : -1;
  const cx = x + w / 2;
  const bob = Math.sin(time * 6 + x) * 2;
  ctx.save();
  ctx.lineJoin = 'round';
  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 3;
  // body
  titanPath([[x + 6, y + h], [x + 2, y + 52 + bob], [x + 12, y + 40 + bob], [x + w - 12, y + 40 + bob], [x + w - 2, y + 52 + bob], [x + w - 6, y + h]]);
  // little spiked shoulders
  [x + 6, x + w - 6].forEach((sx) => titanPath([[sx - 10, y + 50 + bob], [sx, y + 30 + bob], [sx + 10, y + 50 + bob]]));
  // head with three horns
  const hy = y + bob;
  titanPath([[cx - 22, hy + 16], [cx - 32, hy - 6], [cx - 14, hy + 8], [cx, hy - 10], [cx + 14, hy + 8], [cx + 32, hy - 6], [cx + 22, hy + 16], [cx + 18, hy + 40], [cx, hy + 46], [cx - 18, hy + 40]]);
  // eyes
  ctx.save();
  ctx.fillStyle = '#ffffff';
  ctx.shadowColor = '#ffffff';
  ctx.shadowBlur = 10;
  [-1, 1].forEach((side) => {
    ctx.beginPath();
    ctx.moveTo(cx + side * 4 + dir * 3, hy + 20);
    ctx.lineTo(cx + side * 16 + dir * 3, hy + 16);
    ctx.lineTo(cx + side * 13 + dir * 3, hy + 25);
    ctx.closePath();
    ctx.fill();
  });
  ctx.restore();
  // teeth
  ctx.beginPath();
  ctx.moveTo(cx - 10, hy + 33);
  for (let tooth = 0; tooth <= 5; tooth += 1) ctx.lineTo(cx - 10 + tooth * 4, hy + 33 + (tooth % 2 ? 4 : 0));
  ctx.stroke();
  // the arm swinging when it hits
  if (fighter.isAttacking) {
    const area = fighter.attackArea;
    titanPath([[cx, y + 56], [area.x + (dir > 0 ? area.width : 0), area.y + area.height / 2 - 8], [area.x + (dir > 0 ? area.width : 0), area.y + area.height / 2 + 8], [cx, y + 72]]);
  }
  ctx.restore();
}

// ---------- the titan's attacks ----------
// phase 'dodge': it isn't even looking at him. Phase 'dodge2' (after the first shot): it IS looking, and it hurts more.
const chronoTitanDodge2Frames = 2100;

function titanHitChrono(damage, knock = 0, kind = null) {
  if (gameOver) return;
  const adapt = kind && typeof getTitanAdaptScale === 'function' ? getTitanAdaptScale(kind) : 1;
  applyDamage(player2, player1, damage * (chronoTitan.power || 1) * adapt, { isSpecial: true });
  if (kind && typeof recordTitanAdapt === 'function') recordTitanAdapt(kind);
  if (knock) player1.velocity.y = Math.min(player1.velocity.y, -knock);
  updateHealthBars();
}

function updateTitanAttacks() {
  const p = player1;
  const pBottom = p.position.y + p.height;
  chronoTitan.attacks.forEach((attack) => {
    attack.t += 1;
    if (attack.kind === 'fist') {
      const hitAt = Math.round(62 * (attack.warn || 1));
      if (attack.t === hitAt) {
        chronoTitan.shake = 14;
        playNoise({ duration: 0.7, volume: 0.15, filterFrequency: 300 });
        playSound('robotHit');
        if (!attack.hit && Math.abs(getFighterCenterX(p) - attack.x) < 115 + (getTitanHitBox(p).w - p.width) / 2 && pBottom > ground - 70) {
          attack.hit = true;
          titanHitChrono(22, 10, 'fist');
        }
      }
      attack.done = attack.t > hitAt + 48 + (attack.stay || 0);
    } else if (attack.kind === 'sweep') {
      if (attack.t > 45) {
        attack.x -= attack.speed || 20;
        if (attack.t % 10 === 0) playNoise({ duration: 0.1, volume: 0.05, filterFrequency: 500 });
        const hb = getTitanHitBox(p);
        if (!attack.hit && hb.x + hb.w > attack.x && hb.x < attack.x + 170 && pBottom > ground - 62) {
          attack.hit = true;
          titanHitChrono(16, 6, 'sweep');
          p.velocity.x = -10;
        }
      }
      attack.done = attack.x < -400;
    } else if (attack.kind === 'clap') {
      // (nerfed: a longer warning, slower hands, lower hands, less damage... and only the hand itself hurts:
      // once you jump over it, you are safe)
      if (attack.t > 75) {
        attack.left += 10;
        attack.right -= 10;
        const leftEdge = attack.left + 340;
        const rightEdge = attack.right;
        const low = pBottom > ground - 48;
        const hb = getTitanHitBox(p);
        const inLeftHand = hb.x < leftEdge && hb.x + hb.w > leftEdge - 150;
        const inRightHand = hb.x + hb.w > rightEdge && hb.x < rightEdge + 150;
        if (!attack.hit && low && (inLeftHand || inRightHand)) {
          attack.hit = true;
          titanHitChrono(14, 7, 'clap');
        }
        if (leftEdge >= rightEdge && !attack.clapped) {
          attack.clapped = true;
          chronoTitan.shake = 18;
          playNoise({ duration: 0.6, volume: 0.16, filterFrequency: 900 });
          playSound('robotHit');
        }
      }
      attack.done = attack.clapped && attack.t > 75 + 70;
    } else if (attack.kind === 'rain') {
      attack.drops.forEach((drop) => {
        if (drop.done) return;
        drop.y += attack.speed || 9;
        const hb = getTitanHitBox(p);
        const inGiant = (p.giantScale || 1) > 1.2 && drop.x > hb.x - 14 && drop.x < hb.x + hb.w + 14 && drop.y > hb.top && drop.y < hb.bottom;
        if (!drop.hit && (inGiant || Math.hypot(drop.x - getFighterCenterX(p), drop.y - (p.position.y + p.height / 2)) < 40)) {
          drop.hit = true;
          drop.done = true;
          titanHitChrono(8, 0, 'rain');
        }
        if (drop.y >= ground - 12) {
          drop.done = true;
          playTone({ frequency: 120, duration: 0.15, type: 'sine', volume: 0.04, slideTo: 60 });
        }
      });
      attack.done = attack.drops.every((drop) => drop.done);
    }
  });
  chronoTitan.attacks = chronoTitan.attacks.filter((attack) => !attack.done);
}

function drawTitanAttacks() {
  const time = performance.now() / 1000;
  chronoTitan.attacks.forEach((attack) => {
    if (attack.kind === 'fist') {
      const hitAt = Math.round(62 * (attack.warn || 1));
      // a shadow growing on the roof... then the fist
      if (attack.t < hitAt) {
        const k = Math.max(0, attack.t) / hitAt;
        ctx.fillStyle = `rgba(0, 0, 0, ${0.3 + k * 0.5})`;
        ctx.strokeStyle = `rgba(255, 255, 255, ${0.3 + Math.sin(time * 20) * 0.2 + k * 0.3})`;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.ellipse(attack.x, ground + 4, 40 + k * 80, 8 + k * 6, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
      if (attack.t > hitAt - 22) {
        const fall = Math.min(1, (attack.t - (hitAt - 22)) / 22);
        const stay = attack.stay || 0;
        const rise = attack.t > hitAt + 18 + stay ? (attack.t - hitAt - 18 - stay) / 30 : 0;
        const fy = -260 + (ground - 160 + 260) * fall - rise * (ground + 100);
        drawTitanFist(attack.x - 110, fy, 220, 170, true);
        if (attack.t >= hitAt && attack.t < hitAt + 10) {
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
          ctx.lineWidth = 4;
          ctx.beginPath();
          ctx.ellipse(attack.x, ground, (attack.t - hitAt + 2) * 22, (attack.t - hitAt + 2) * 5, 0, 0, Math.PI * 2);
          ctx.stroke();
        }
      }
    } else if (attack.kind === 'sweep') {
      if (attack.t <= 45) {
        if (attack.t < 0) return;
        ctx.fillStyle = `rgba(255, 255, 255, ${0.4 + Math.sin(time * 18) * 0.4})`;
        ctx.font = '900 46px Courier New, monospace';
        ctx.fillText('!', titanArenaRight() - 60, ground - 80);
        ctx.fillRect(0, ground - 30, titanArenaRight(), 3);
      } else {
        drawTitanHand(attack.x, ground - 62, 170, 62);
      }
    } else if (attack.kind === 'clap') {
      if (attack.t <= 75) {
        ctx.fillStyle = `rgba(255, 255, 255, ${0.4 + Math.sin(time * 18) * 0.4})`;
        ctx.font = '900 46px Courier New, monospace';
        ctx.fillText('!', 20, ground - 80);
        ctx.fillText('!', titanArenaRight() - 60, ground - 80);
        ctx.fillRect(0, ground - 30, titanArenaRight(), 3);
      }
      // the left hand (mirrored) and the right hand
      drawTitanHandMirrored(attack.left + 340, ground - 48, 170, 48);
      drawTitanHand(attack.right, ground - 48, 170, 48);
    } else if (attack.kind === 'rain') {
      attack.drops.forEach((drop) => {
        if (drop.done) return;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.45)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(drop.x, ground + 2, 16, 4, 0, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(drop.x, drop.y, 16, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      });
    }
  });
}

// ---------- the fight ----------
function configureChronoTitanEnemy() {
  if (chronoCh.titanPhase === 'babies' || chronoCh.titanPhase === 'babies2' || chronoCh.titanPhase === 'babyRush') {
    player2.setCharacterType('normal', 'babyTitan');
    botDifficulty = 'hard';
    applyBotDifficulty();
    player2.setMaxHealth(originsHealth.babyTitan);
    player2.health = player2.maxHealth;
    player2.darkDealDone = true;
    player2.scriptedFlight = false;
    player2.damageMultiplier = originsDamage.babyTitan * (chronoCh.titanPhase === 'babies2' ? 1.15 : 1);
  } else {
    player2.setCharacterType('normal', 'titanBody');
    player2.setMaxHealth(10000);
    player2.health = chronoTitan.bar ? chronoTitan.bar.value : player2.maxHealth;
    player2.darkDealDone = true;
    player2.scriptedFlight = true;
    player2.damageMultiplier = 1;
    player2.position = { x: canvas.width + 400, y: ground - player2.height };
    if (chronoCh.titanPhase === 'dodge') {
      // Chrono comes from the roof of level 7: still overcharged
      makeChronoOvercharged();
      player1.health = Math.round(player1.maxHealth * 0.9);
    }
  }
  updateHealthBars();
  updateCombatHudIdentity();
}

function updateChronoTitan() {
  if (!isChronoTitanFight()) return;
  if (!gameStarted || gameOver || arcadeCutscene.active) return;
  if (selectedNormalArcadeLevel === 9) {
    updateChronoTitan9();
    return;
  }
  if (!player1.rareMachine) {
    player1.rareMachine = true;
    player1.machineLight = true;
    player1.machineBoost = true;
    player1.moveSpeed = playerMoveSpeed * 1.3;
  }
  chronoTitan.visible = true;
  chronoTitan.rise = 1;
  if (chronoTitan.shake > 0) chronoTitan.shake *= 0.88;
  if (chronoTitan.recoil > 0) chronoTitan.recoil *= 0.92;
  [player1, player2].forEach((fighter) => {
    if (fighter.secretVariant === 'titanBody') return;
    const limit = chronoRoofEdgeX - 26 - fighter.width;
    if (fighter.position.x > limit) {
      fighter.position.x = limit;
      if (fighter.velocity.x > 0) fighter.velocity.x = 0;
    }
  });
  if (player2.secretVariant === 'titanBody') {
    player2.scriptedFlight = true;
    player2.position = { x: canvas.width + 400, y: ground - player2.height };
    player2.velocity = { x: 0, y: 0 };
    player2.health = chronoTitan.bar ? chronoTitan.bar.value : player2.maxHealth;
    if (chronoCh.titanPhase === 'box') return;
    if (chronoCh.titanPhase === 'dodge2') {
      // now it follows him with its eyes
      const target = (getFighterCenterX(player1) - chronoTitanX) / 400;
      chronoTitan.look += (Math.max(-1, Math.min(1, target)) - chronoTitan.look) * 0.05;
      chronoTitan.eyeGlow = 1.6 + Math.sin(performance.now() / 300) * 0.3;
    } else {
      chronoTitan.look = 0.75 + Math.sin(performance.now() / 1400) * 0.25;
    }
    chronoTitan.dodgeLeft -= 1;
    chronoTitan.next -= getChronoTitanTimeScale();
    if (chronoTitan.next <= 0 && chronoTitan.dodgeLeft > 90) castTitanAttack();
    stepTitanAttacks();
    if (chronoTitan.dodgeLeft <= 0 && chronoTitan.attacks.length === 0) startChronoTitanBabiesScene(chronoCh.titanPhase === 'dodge2' ? 4 : 2);
    return;
  }
  // after the box: one baby... and the big one attacking for real, for a short while
  if (chronoCh.titanPhase === 'babyRush') {
    const target = (getFighterCenterX(player1) - chronoTitanX) / 400;
    chronoTitan.look += (Math.max(-1, Math.min(1, target)) - chronoTitan.look) * 0.05;
    chronoTitan.rushLeft -= 1;
    chronoTitan.next -= getChronoTitanTimeScale();
    if (chronoTitan.next <= 0 && chronoTitan.rushLeft > 60) {
      castTitanAttack();
      chronoTitan.next = 125;
    }
    stepTitanAttacks();
    if (chronoTitan.rushLeft <= 0) {
      chronoTitan.attacks = [];
      startChronoTitanAfterBox(false);
    }
    return;
  }
  // with the babies: the big one only slams now and then
  chronoTitan.look = Math.max(-0.4, chronoTitan.look - 0.002);
  chronoTitan.next -= getChronoTitanTimeScale();
  if (chronoTitan.next <= 0) {
    chronoTitan.attacks.push({ kind: 'fist', x: Math.max(60, Math.min(chronoRoofEdgeX - 80, 80 + Math.random() * (chronoRoofEdgeX - 200))), t: 0, hit: false });
    chronoTitan.next = chronoCh.titanPhase === 'babies2' ? 330 : 420;
  }
  stepTitanAttacks();
}

function drawChronoTitanFx() {
  if (!isChronoTitanFight()) return;
  if (selectedNormalArcadeLevel === 9) {
    drawChronoTitan9Fx();
    return;
  }
  if (!arcadeCutscene.active) drawTitanAttacks();
  if (!arcadeCutscene.active && !gameOver) drawChronoTitanSlowFx(null);
  if (!arcadeCutscene.active && !gameOver && chronoCh.titanPhase === 'babyRush') {
    const seconds = Math.max(0, Math.ceil(chronoTitan.rushLeft / 60));
    ctx.save();
    ctx.fillStyle = 'rgba(40, 0, 20, 0.7)';
    ctx.fillRect(canvas.width / 2 - 230, 118, 460, 40);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.strokeRect(canvas.width / 2 - 230, 118, 460, 40);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 18px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`¡AGUANTA! 0:${String(seconds).padStart(2, '0')}  (o derrota al bebe)`, canvas.width / 2, 144);
    ctx.textAlign = 'left';
    ctx.restore();
  }
  if (!arcadeCutscene.active && !gameOver && player2.secretVariant === 'titanBody' && chronoCh.titanPhase !== 'box') {
    const seconds = Math.max(0, Math.ceil(chronoTitan.dodgeLeft / 60));
    const angry = chronoCh.titanPhase === 'dodge2';
    ctx.save();
    ctx.fillStyle = angry ? 'rgba(40, 0, 20, 0.7)' : 'rgba(0, 0, 0, 0.6)';
    ctx.fillRect(canvas.width / 2 - 190, 118, 380, 40);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.strokeRect(canvas.width / 2 - 190, 118, 380, 40);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 20px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`${angry ? '¡EL TITAN TE MIRA!' : '¡ESQUIVA AL TITAN!'}  ${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`, canvas.width / 2, 145);
    ctx.textAlign = 'left';
    ctx.restore();
  }
  drawTitanBossBar();
}

// ---------- Chrono's SLOW (Q) in the dodge parts: everything the titan throws moves slower ----------
const chronoTitanSlowFrames = 300;
const chronoTitanSlowScale = 0.4;

function isChronoTitanDodgePart() {
  return isChronoTitanFight() && player2.secretVariant === 'titanBody';
}

// (called by activateChronoSlow: in the dodge parts the zone would be useless, the titan is not on the roof)
function chronoTitanTimeSlow(attacker) {
  if (attacker !== player1 || !isChronoTitanDodgePart()) return false;
  startChronoTitanSlow(attacker);
  return true;
}

function startChronoTitanSlow(attacker) {
  chronoTitan.slowT = chronoTitanSlowFrames;
  attacker.chronoSlowCooldown = getDebugCooldown(chronoSlowCooldown, attacker);
  playSound('gravityOrb');
  [900, 600, 400].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.25, type: 'triangle', volume: 0.05, slideTo: frequency * 0.5 }), index * 90));
  if (typeof recordSpecialUsed === 'function') recordSpecialUsed(attacker);
}

function getChronoTitanTimeScale() {
  return chronoTitan.slowT > 0 ? chronoTitanSlowScale : 1;
}

function stepTitanAttacks() {
  const scale = getChronoTitanTimeScale();
  if (chronoTitan.slowT > 0) chronoTitan.slowT -= 1;
  chronoTitan.slowAcc = (chronoTitan.slowAcc || 0) + scale;
  while (chronoTitan.slowAcc >= 1) {
    chronoTitan.slowAcc -= 1;
    updateTitanAttacks();
  }
}

// in the box: Q slows the box's attacks (the box has its own clock)
function getTitanBoxTimeScale(round) {
  if (!round || !(round.config && round.config.titanBox)) return 1;
  // (in the laser box, Q shoots instead)
  if (round.config.laserMode) return 1;
  const chrono = round.target;
  if (chrono.chronoSlowCooldown > 0) chrono.chronoSlowCooldown -= 1;
  if (keys.q && round.stage === 'phase' && chrono.characterType === 'chrono' && chrono.chronoSlowCooldown <= 0 && !(chronoTitan.slowT > 0)) {
    startChronoTitanSlow(chrono);
    dodgeRoundCaption('¡TIEMPO LENTO!', '#80deea');
  }
  if (chronoTitan.slowT > 0) chronoTitan.slowT -= 1;
  return chronoTitan.slowT > 0 ? chronoTitanSlowScale : 1;
}

// the slowed time: a cold blue tint and a clock turning slowly
function drawChronoTitanSlowFx(box) {
  if (!(chronoTitan.slowT > 0)) return;
  const time = performance.now() / 1000;
  const k = Math.min(1, chronoTitan.slowT / 30);
  ctx.save();
  ctx.globalAlpha = k;
  if (box) {
    ctx.strokeStyle = 'rgba(128, 222, 234, 0.8)';
    ctx.lineWidth = 6;
    ctx.strokeRect(box.x - 10, box.y - 10, box.width + 20, box.height + 20);
  } else {
    ctx.fillStyle = 'rgba(38, 198, 218, 0.12)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    const cx = canvas.width / 2;
    const cy = canvas.height / 2;
    ctx.strokeStyle = 'rgba(224, 247, 250, 0.25)';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(cx, cy, 240, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(time * 0.4) * 200, cy + Math.sin(time * 0.4) * 200);
    ctx.stroke();
  }
  ctx.fillStyle = '#e0f7fa';
  ctx.font = '900 16px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillText(`TIEMPO LENTO ${Math.ceil(chronoTitan.slowT / 60)}`, canvas.width / 2, box ? box.y + box.height + 46 : 178);
  ctx.textAlign = 'left';
  ctx.restore();
}

function drawChronoTitanStageLayer() {
  if (!(isChronoTitanFight() && chronoTitan.visible)) return;
  // (during the box attack it is drawn above the box instead)
  if (typeof dodgeRound !== 'undefined' && dodgeRound.active && dodgeRound.config && dodgeRound.config.titanBox) return;
  const time = performance.now() / 1000;
  const shake = (chronoTitan.shake || 0) * (Math.random() - 0.5);
  const flee = chronoTitan.fleeK || 0;
  const headY = chronoTitanHeadY + (1 - chronoTitan.rise) * 640 + shake - (chronoTitan.recoil || 0) * 20 + flee * 520;
  const cx = chronoTitanX + shake + (chronoTitan.recoil || 0) * 30 + flee * 260;
  drawDarkTitan(cx, headY, 1, chronoTitan.look, time, chronoTitan.eyeGlow);
  if (chronoTitan.scar) drawTitanScar(cx, headY, 1, time);
}

// ---------- the boss bar: 10 000 ----------
function drawTitanBossBar(y = 214) {
  const bar = chronoTitan.bar;
  if (!bar) return;
  bar.t += 1;
  bar.shown += (bar.value - bar.shown) * 0.04;
  if (Math.abs(bar.value - bar.shown) < 1) bar.shown = bar.value;
  const x = 80;
  const w = canvas.width - 160;
  ctx.save();
  ctx.globalAlpha = Math.min(1, bar.t / 20);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.8)';
  ctx.fillRect(x - 10, y - 30, w + 20, 62);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 3;
  ctx.strokeRect(x - 10, y - 30, w + 20, 62);
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 18px Courier New, monospace';
  ctx.fillText('TITAN', x, y - 10);
  ctx.textAlign = 'right';
  ctx.fillText(`${Math.round(bar.shown)} / ${bar.max}`, x + w, y - 10);
  ctx.textAlign = 'left';
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(x, y, w, 20);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(x, y, w * (bar.shown / bar.max), 20);
  ctx.fillStyle = '#7e57c2';
  ctx.fillRect(x, y, w * (bar.value / bar.max), 20);
  ctx.strokeStyle = '#ffffff';
  ctx.strokeRect(x, y, w, 20);
  if (bar.hitT > 0) {
    bar.hitT -= 1;
    ctx.globalAlpha = Math.min(1, bar.hitT / 30);
    ctx.font = '900 54px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffd54f';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 6;
    const ty = y + 80 - (120 - bar.hitT) * 0.3;
    ctx.strokeText(`-${bar.lastHit}`, canvas.width / 2, ty);
    ctx.fillText(`-${bar.lastHit}`, canvas.width / 2, ty);
    ctx.textAlign = 'left';
  }
  ctx.restore();
}

// ---------- the intro: the stairs, the fist, the roof ----------
const chronoTitanFistSource = encodeURI('assetsaudio/Puño del titan (Moquete).wav');
const chronoTitanFistSound = { audio: null };

function playChronoTitanFistSound() {
  if (typeof Audio === 'undefined') return;
  try {
    if (!chronoTitanFistSound.audio) chronoTitanFistSound.audio = new Audio(chronoTitanFistSource);
    const audio = chronoTitanFistSound.audio;
    audio.currentTime = 0;
    audio.volume = Math.min(1, audioSettings.master * Math.max(0.4, audioSettings.sfx));
    const played = audio.play();
    if (played && played.catch) played.catch(() => {});
  } catch (error) {
    // no audio: the scene still plays
  }
}

