function updateChronoTitanIntro(cutscene, line, firstFrame) {
  cutscene.hideEnemy = true;
  if (line.dgWalk) cutscene.dgX = Math.min(300, cutscene.dgX + 1.1);
  if (line.rumbleSoft && cutscene.frame % 20 === 0) playTone({ frequency: 60, duration: 0.15, type: 'square', volume: 0.04 });
  if (line.chronoRun) {
    if (firstFrame) cutscene.gamblerX = canvas.width + 60;
    cutscene.gamblerX -= 9;
    if (cutscene.gamblerX < -300) cutscene.gamblerX = -300;
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.gamblerHop = 10 + Math.abs(Math.sin(cutscene.frame / 3)) * 12;
  }
  if (line.chronoGone) {
    cutscene.gamblerX = -400;
    cutscene.gamblerTargetX = -400;
  }
  // the footsteps of something enormous: each one louder, the lights die, dust falls from the ceiling
  if (line.beat && firstFrame) {
    const k = line.beat / 4;
    cutscene.shake = 10 + k * 22;
    cutscene.flicker = 30;
    playTone({ frequency: 46 - line.beat * 3, duration: 0.9, type: 'sine', volume: 0.08 + k * 0.1, slideTo: 28 });
    playNoise({ duration: 0.5, volume: 0.05 + k * 0.08, filterFrequency: 220 });
    for (let grain = 0; grain < 20 + line.beat * 15; grain += 1) cutscene.ceilingDust.push({ x: Math.random() * canvas.width, y: -10 - Math.random() * 40, vy: 1.5 + Math.random() * 2.5, life: 160 });
  }
  if (cutscene.flicker > 0) cutscene.flicker -= 1;
  if (line.dgTurn && !line.fist) cutscene.dgX = Math.max(160, cutscene.dgX - 0.6);
  if (line.cracks) cutscene.crackK = Math.min(1, cutscene.crackK + 0.01);
  if (line.silence) {
    // a breath of silence... the cracks glowing brighter
    cutscene.crackK = Math.min(1, cutscene.crackK + 0.006);
    if (cutscene.frame % 40 === 0) playTone({ frequency: 1800, duration: 0.3, type: 'sine', volume: 0.015 });
  }
  cutscene.ceilingDust.forEach((grain) => {
    grain.y += grain.vy;
    grain.life -= 1;
  });
  cutscene.ceilingDust = cutscene.ceilingDust.filter((grain) => grain.life > 0 && grain.y < ground);
  // THE FIST
  if (line.fist) {
    cutscene.fistT += 1;
    const t = cutscene.fistT;
    if (t === 1) {
      // (Enter waits until the blow is over)
      cutscene.holdLine = cutscene.lineIndex;
      playChronoTitanFistSound();
    }
    if (t === 14) {
      cutscene.flash = 1;
      cutscene.shake = 70;
      cutscene.wallBroken = true;
      cutscene.impactRings = [0, 1, 2, 3].map((ring) => ({ r: 20 + ring * 30, life: 50 - ring * 5 }));
      playNoise({ duration: 1.2, volume: 0.2, filterFrequency: 900 });
      for (let chunk = 0; chunk < 70; chunk += 1) {
        cutscene.wallDebris.push({ x: 640 + Math.random() * 260, y: 60 + Math.random() * (ground - 120), vx: -5 - Math.random() * 14, vy: -9 + Math.random() * 7, size: 4 + Math.random() * 16, life: 180 });
      }
      // a few huge chunks flying at the camera
      for (let chunk = 0; chunk < 7; chunk += 1) {
        cutscene.bigChunks.push({ x: 700 + Math.random() * 120, y: 160 + Math.random() * 200, vx: -6 - Math.random() * 10, vy: -4 + Math.random() * 6, size: 30, grow: 1.04 + Math.random() * 0.03, spin: Math.random() * 6, life: 70 });
      }
    }
    if (t > 14 && t < 110) cutscene.shake = Math.max(cutscene.shake || 0, 14 - (t - 14) * 0.12);
    if (t > 30) cutscene.dustK = Math.min(1, cutscene.dustK + 0.03);
    if (t === 120) cutscene.holdLine = -1;
  }
  cutscene.impactRings.forEach((ring) => {
    ring.r += 22;
    ring.life -= 1;
  });
  cutscene.impactRings = cutscene.impactRings.filter((ring) => ring.life > 0);
  cutscene.bigChunks.forEach((chunk) => {
    chunk.x += chunk.vx;
    chunk.y += chunk.vy;
    chunk.size *= chunk.grow;
    chunk.spin += 0.08;
    chunk.life -= 1;
  });
  cutscene.bigChunks = cutscene.bigChunks.filter((chunk) => chunk.life > 0);
  if (line.wallBroken) cutscene.wallBroken = true;
  if (line.dust) cutscene.dustK = Math.max(0, cutscene.dustK - 0.006);
  if (line.eyePeek) {
    cutscene.dustK = Math.max(0, cutscene.dustK - 0.02);
    cutscene.eyeOpen = Math.min(1, cutscene.eyeOpen + 0.015);
    if (firstFrame && !cutscene.eyeSound) {
      cutscene.eyeSound = true;
      playTone({ frequency: 70, duration: 2.5, type: 'sine', volume: 0.1, slideTo: 45 });
    }
  }
  // the General thrown back by the blast, on one knee
  if (line.fist && cutscene.fistT > 14) cutscene.dgX = Math.max(40, cutscene.dgX - 6);
  cutscene.wallDebris.forEach((chunk) => {
    chunk.x += chunk.vx;
    chunk.y = Math.min(ground - chunk.size, chunk.y + chunk.vy);
    chunk.vy += 0.4;
    chunk.vx *= 0.97;
    chunk.life -= 1;
  });
  cutscene.wallDebris = cutscene.wallDebris.filter((chunk) => chunk.life > 0);
  if (line.roof && firstFrame) {
    selectedMap = 'castleRoof';
    cutscene.gamblerX = 60;
    cutscene.gamblerTargetX = 60;
    cutscene.wallBroken = false;
    cutscene.wallDebris = [];
    cutscene.ceilingDust = [];
    cutscene.dustK = 0;
    cutscene.flash = 0.6;
  }
  if (line.roofRun) {
    cutscene.gamblerX = Math.min(540, cutscene.gamblerX + 3);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.gamblerHop = 10 + Math.abs(Math.sin(cutscene.frame / 3)) * 10;
  }
  if (line.titanRise) {
    chronoTitan.visible = true;
    chronoTitan.rise = Math.min(1, chronoTitan.rise + 0.008);
    cutscene.shake = Math.max(cutscene.shake || 0, 6);
    if (cutscene.frame % 14 === 0) playTone({ frequency: 38 + chronoTitan.rise * 20, duration: 0.5, type: 'sawtooth', volume: 0.07 });
    if (cutscene.gamblerX < 520) cutscene.gamblerX = Math.min(540, cutscene.gamblerX + 3);
  }
  if (line.titanLooks) {
    chronoTitan.look = Math.max(-1, chronoTitan.look - 0.05);
    chronoTitan.rise = Math.min(1, chronoTitan.rise + 0.02);
  }
  if (line.backStep) {
    cutscene.gamblerX = Math.max(420, cutscene.gamblerX - 0.8);
    cutscene.gamblerTargetX = cutscene.gamblerX;
  }
  if (line.roar && firstFrame) {
    cutscene.shake = 40;
    chronoTitan.eyeGlow = 2.5;
    playSound('titanRoar');
    playTone({ frequency: 55, duration: 2.4, type: 'sawtooth', volume: 0.14, slideTo: 30 });
    playNoise({ duration: 2, volume: 0.15, filterFrequency: 500 });
  }
  if (line.titanAway) chronoTitan.look = Math.min(1, chronoTitan.look + 0.03);
  if (chronoTitan.eyeGlow > 1) chronoTitan.eyeGlow = Math.max(1, chronoTitan.eyeGlow - 0.01);
  cutscene.shake = (cutscene.shake || 0) * 0.92;
}

const chronoTitanHolePoints = [[880, 60], [800, 30], [720, 110], [660, 90], [690, 200], [630, 260], [680, 340], [640, 420], [700, ground]];

function drawChronoTitanIntroFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  // the lights die with every footstep
  if (cutscene.flicker > 0 && selectedMap === 'castleStairs') {
    ctx.fillStyle = `rgba(0, 0, 0, ${Math.random() < 0.5 ? 0.6 : 0.2})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  // the General on the stairs (thrown back, down on one knee after the blast)
  if (selectedMap === 'castleStairs' && cutscene.dgActor) {
    const divine = cutscene.dgActor;
    divine.position = { x: cutscene.dgX, y: ground - divine.height };
    divine.attacksToTheRight = true;
    divine.isAttacking = false;
    if (line.dgDown) {
      ctx.save();
      ctx.translate(cutscene.dgX + divine.width / 2, ground);
      ctx.scale(1, 0.82);
      ctx.translate(-(cutscene.dgX + divine.width / 2), -ground);
      divine.draw();
      ctx.restore();
    } else {
      divine.draw();
    }
  }
  // the cracks spreading over the right wall, glowing white
  if (cutscene.crackK > 0 && !cutscene.wallBroken && selectedMap === 'castleStairs') {
    ctx.save();
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.4 + cutscene.crackK * 0.6})`;
    ctx.shadowColor = '#ffffff';
    ctx.shadowBlur = 10 * cutscene.crackK;
    ctx.lineWidth = 2 + cutscene.crackK * 2;
    for (let crack = 0; crack < 9; crack += 1) {
      const angle = Math.PI * 0.55 + (crack / 8) * Math.PI * 0.9;
      const len = 60 + cutscene.crackK * 260;
      let cx = 820;
      let cy = 260;
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      for (let step = 1; step <= 5; step += 1) {
        cx = 820 + Math.cos(angle) * len * (step / 5) + Math.sin(crack * 7 + step) * 18;
        cy = 260 + Math.sin(angle) * len * (step / 5) + Math.cos(crack * 5 + step) * 18;
        ctx.lineTo(cx, cy);
      }
      ctx.stroke();
    }
    ctx.restore();
  }
  // the broken wall: the night outside... and the eye
  if (cutscene.wallBroken && selectedMap === 'castleStairs') {
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(canvas.width, 40);
    chronoTitanHolePoints.forEach(([px, py]) => ctx.lineTo(px, py));
    ctx.lineTo(canvas.width, ground);
    ctx.closePath();
    ctx.fillStyle = '#05030a';
    ctx.fill();
    ctx.clip();
    if (cutscene.eyeOpen > 0) drawDarkTitan(1010, 60, 2.2, -0.6, time, 0.6 + cutscene.eyeOpen * 1.4);
    else drawDarkTitan(1010, 60, 2.2, -0.6, time, 0);
    // (the eye opening: a black lid closing over it until it opens)
    if (cutscene.eyeOpen < 1) {
      ctx.fillStyle = '#000000';
      ctx.fillRect(800, 210, 300, 40 * (1 - cutscene.eyeOpen));
      ctx.fillRect(800, 280 - 40 * (1 - cutscene.eyeOpen), 300, 40 * (1 - cutscene.eyeOpen));
    }
    ctx.restore();
    ctx.strokeStyle = '#3a2a44';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(canvas.width, 40);
    chronoTitanHolePoints.forEach(([px, py]) => ctx.lineTo(px, py));
    ctx.stroke();
  }
  // the fist
  if (line.fist && cutscene.fistT > 0) {
    const t = cutscene.fistT;
    const out = t < 14 ? Math.pow(t / 14, 3) : t < 80 ? 1 : Math.max(0, 1 - (t - 80) / 30);
    drawTitanFist(canvas.width + 40 - out * 560, 170, 320, 250, false);
  }
  cutscene.wallDebris.forEach((chunk) => {
    ctx.fillStyle = '#2a1e36';
    ctx.fillRect(chunk.x, chunk.y, chunk.size, chunk.size);
    ctx.strokeStyle = '#140c1c';
    ctx.strokeRect(chunk.x, chunk.y, chunk.size, chunk.size);
  });
  cutscene.ceilingDust.forEach((grain) => {
    ctx.fillStyle = `rgba(170, 150, 180, ${grain.life / 160})`;
    ctx.fillRect(grain.x, grain.y, 3, 3);
  });
  cutscene.impactRings.forEach((ring) => {
    ctx.strokeStyle = `rgba(255, 255, 255, ${ring.life / 50})`;
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.arc(760, 290, ring.r, 0, Math.PI * 2);
    ctx.stroke();
  });
  // the dust cloud filling the stairs
  if (cutscene.dustK > 0) {
    ctx.fillStyle = `rgba(60, 48, 70, ${cutscene.dustK * 0.85})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    for (let puff = 0; puff < 14; puff += 1) {
      ctx.fillStyle = `rgba(90, 76, 100, ${cutscene.dustK * 0.5})`;
      ctx.beginPath();
      ctx.arc((puff * 97 + time * 20) % canvas.width, 120 + (puff * 53) % 380, 60 + (puff % 4) * 20, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // the huge chunks, flying at the camera
  cutscene.bigChunks.forEach((chunk) => {
    ctx.save();
    ctx.translate(chunk.x, chunk.y);
    ctx.rotate(chunk.spin);
    ctx.fillStyle = '#1e1428';
    ctx.strokeStyle = '#3a2a44';
    ctx.lineWidth = 3;
    ctx.fillRect(-chunk.size / 2, -chunk.size / 2, chunk.size, chunk.size * 0.8);
    ctx.strokeRect(-chunk.size / 2, -chunk.size / 2, chunk.size, chunk.size * 0.8);
    ctx.restore();
  });
  // the IMPACT FRAME: black and white, the fist in silhouette
  if (line.fist && cutscene.fistT >= 6 && cutscene.fistT < 14) {
    ctx.fillStyle = cutscene.fistT % 4 < 2 ? '#ffffff' : '#000000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = cutscene.fistT % 4 < 2 ? '#000000' : '#ffffff';
    ctx.fillRect(canvas.width - 520, 190, 560, 210);
    ctx.beginPath();
    ctx.ellipse(canvas.width - 520, 295, 60, 110, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // letterbox while it happens
  if (line.silence || line.fist) {
    ctx.fillStyle = '#000000';
    ctx.fillRect(0, 0, canvas.width, 44);
    ctx.fillRect(0, canvas.height - 44, canvas.width, 44);
  }
}

// ---------- mid fight: the babies (2 the first time, 4 the second) ----------
function buildChronoTitanBabiesLines(count) {
  if (count === 1) {
    return [
      { speaker: 'darkTitan', text: '.........', openHand: true },
      { speaker: 'origNarrator', text: 'El titan abre la mano una vez mas. Cae una sola gota... y se levanta chillando.', openHand: true, drops: true },
      { speaker: 'chrono', text: '¿Uno solo? ...¿Y por que la mano grande sigue levantada?', babiesUp: true, emote: { who: 'gambler', symbol: '?' } },
      { speaker: 'origNarrator', text: 'Porque esta vez, el titan tambien ataca.', babiesUp: true },
    ];
  }
  if (count > 2) {
    return [
      { speaker: 'darkTitan', text: '.........', openHand: true },
      { speaker: 'origNarrator', text: 'Otra vez la mano abierta. Pero esta vez caen CUATRO gotas.', openHand: true, drops: true },
      { speaker: 'chrono', text: '¿Cuatro? ¿CUATRO? ¡¿Cuantos bebes tenes?!', babiesUp: true, emote: { who: 'gambler', symbol: '!?' } },
      { speaker: 'chrono', text: '...Esta bien. Vengan. De a uno, por favor.', babiesUp: true },
    ];
  }
  return [
    { speaker: 'origNarrator', text: 'El titan deja de golpear. Gira la cabeza... y abre la mano sobre el techo.', openHand: true },
    { speaker: 'origNarrator', text: 'De sus dedos caen dos gotas negras. Tocan el techo... y se levantan.', openHand: true, drops: true },
    { speaker: 'chrono', text: '¿Bebes? ¿El titan tiene... BEBES?', babiesUp: true, emote: { who: 'gambler', symbol: '?!' } },
    { speaker: 'chrono', text: 'Bueno. Por lo menos a estos les puedo pegar.', babiesUp: true },
  ];
}

function startChronoTitanBabiesScene(count = 2) {
  chronoTitan.attacks = [];
  chronoCh.titanPhase = 'babiesScene';
  chronoCh.titanBabyCount = count;
  ch6CutsceneBase('originsIntro', buildChronoTitanBabiesLines(count), 'dialog', {
    darkWorld: true,
    midFight: true,
    noVersus: true,
    darkMusic: true,
    titanBabies: true,
    babyCount: count,
    gamblerX: Math.max(60, Math.min(420, player1.position.x)),
    gamblerTargetX: Math.max(60, Math.min(420, player1.position.x)),
    scammerX: 2000,
    scammerTargetX: 2000,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    dropT: 0,
  });
  startCutsceneLine(0);
}

function updateChronoTitanBabies(cutscene, line, firstFrame) {
  cutscene.hideEnemy = true;
  chronoTitan.look = Math.max(-0.3, chronoTitan.look - 0.02);
  if (line.drops) cutscene.dropT = Math.min(80, cutscene.dropT + 1);
  if (line.drops && cutscene.dropT === 60) {
    cutscene.shake = 12;
    playNoise({ duration: 0.4, volume: 0.1, filterFrequency: 300 });
  }
  if (line.babiesUp) cutscene.dropT = 80;
  cutscene.shake = (cutscene.shake || 0) * 0.9;
}

function drawChronoTitanBabiesFx(cutscene) {
  const line = cutscene.lines[cutscene.lineIndex];
  if (!line.openHand && !line.drops && !line.babiesUp) return;
  drawTitanHand(500, 40, 260, 110);
  if (!line.drops && !line.babiesUp) return;
  const k = Math.min(1, cutscene.dropT / 60);
  const spots = cutscene.babyCount > 2 ? [520, 600, 680, 750] : cutscene.babyCount === 1 ? [650] : [600, 700];
  spots.forEach((bx, index) => {
    if (cutscene.dropT >= 60 || line.babiesUp) {
      const stand = line.babiesUp ? 1 : Math.min(1, (cutscene.dropT - 60) / 20);
      const baby = cutscene.babyActor || (cutscene.babyActor = (() => {
        const actor = new Fighter({ x: 0, y: 0, color: '#000000', attacksToTheRight: false });
        actor.setCharacterType('normal', 'babyTitan');
        actor.width = originsSizes.babyTitan[0];
        actor.height = originsSizes.babyTitan[1];
        return actor;
      })());
      baby.position = { x: bx - baby.width / 2 + index * 4, y: ground - baby.height * stand };
      baby.attacksToTheRight = false;
      baby.isAttacking = false;
      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, canvas.width, ground);
      ctx.clip();
      drawBabyTitan(baby);
      ctx.restore();
    } else {
      ctx.fillStyle = '#000000';
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(bx, 150 + k * (ground - 170) - index * 8, 18, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  });
}

// (a cutscene ended in the middle of the level: restart the fight loop with the next "enemy")
function resumeChronoTitanFight(phase, enemies, heal = 0) {
  if (animationId) {
    cancelAnimationFrame(animationId);
    animationId = null;
  }
  chronoCh.titanPhase = phase;
  normalArcadeEnemiesRemaining = enemies;
  normalArcadeEnemyIndex = 0;
  const hp = player1.health;
  startNextNormalArcadeEnemy();
  player1.health = Math.min(player1.maxHealth, hp + heal);
  updateHealthBars();
}

function startChronoTitanBabies() {
  const count = chronoCh.titanBabyCount || 2;
  if (count === 1) {
    chronoTitan.rushLeft = 1200;
    // (the baby hits too: the big one hits a little softer here)
    chronoTitan.power = 1.1;
    chronoTitan.next = 70;
    resumeChronoTitanFight('babyRush', 1, 20);
    player2.position.x = 600;
    chronoCh.banner = { text: 'UN BEBE... Y EL TITAN', sub: 'Esquiva sus golpes 20 segundos, o derrota al bebe antes.', t: 0 };
    return;
  }
  chronoTitan.next = count > 2 ? 330 : 420;
  resumeChronoTitanFight(count > 2 ? 'babies2' : 'babies', count, 25);
  player2.position.x = 600;
  chronoCh.banner = count > 2
    ? { text: 'CUATRO BEBES TITAN', sub: 'Mas rapidos. Mas enojados. De a uno.', t: 0 }
    : { text: 'BEBES TITAN', sub: 'Dos. Del tamaño de Chrono. Igual de negros.', t: 0 };
}

// ---------- after the babies: the light shot... and the bar ----------
function buildChronoTitanShotLines(shot) {
  if (shot === 2) {
    return [
      { speaker: 'chrono', text: '(*jadea*)... Cuatro... cuatro bebes. No siento los engranajes.', tired: true },
      { speaker: 'chrono', text: 'Maquina... otra vez. A la cara.', aimTitan: true },
      { speaker: 'machine', text: 'Modo luz. Carga maxima. ...Otra vez.', aimTitan: true },
      { speaker: 'chrono', text: '¡¡FUEGO!!', fireTitan: true },
      { speaker: 'origNarrator', text: '...', fireTitan: true, titanHit: true },
      { speaker: 'origNarrator', text: 'Otros mil. Le quedan ocho mil.', bar: true },
      { speaker: 'darkTitan', text: '.........', bar: true, titanAngry: true },
      { speaker: 'origNarrator', text: 'El titan junta sus dos manos alrededor de Chrono... y lo encierra.', bar: true, titanAngry: true, closeHands: true },
      { speaker: 'chrono', text: '¿Q-que...? ¡¿Una CAJA?!', bar: true, titanAngry: true, closeHands: true, emote: { who: 'gambler', symbol: '!?' } },
    ];
  }
  return [
    { speaker: 'chrono', text: '(*jadea*)... Dos menos. Queda... el grande.', tired: true },
    { speaker: 'chrono', text: 'Maquina. Modo luz. Todo lo que tengas... directo a la cara.', aimTitan: true },
    { speaker: 'machine', text: 'Modo luz. Carga maxima. Objetivo: ...demasiado grande para calcular.', aimTitan: true },
    { speaker: 'chrono', text: '¡¡FUEGO!!', fireTitan: true },
    { speaker: 'origNarrator', text: '...', fireTitan: true, titanHit: true },
    { speaker: 'chrono', text: '¡Le di! ¡Le di de lleno!', bar: true, emote: { who: 'gambler', symbol: '!' } },
    { speaker: 'chrono', text: '...¿Mil? ¿Solo... MIL?', bar: true },
    { speaker: 'origNarrator', text: 'Nueve mil. Le quedan nueve mil.', bar: true },
    { speaker: 'darkTitan', text: '.........', bar: true, titanTurns: true },
    { speaker: 'chrono', text: '...Ahora si me esta mirando.', bar: true, titanTurns: true },
  ];
}

function startChronoTitanShot(shot = 1) {
  chronoTitan.attacks = [];
  chronoTitan.shotNumber = shot;
  forestFx.items = [];
  forestFx.dash = null;
  chronoCh.titanPhase = 'shotScene';
  ch6CutsceneBase('originsIntro', buildChronoTitanShotLines(shot), 'dialog', {
    darkWorld: true,
    midFight: true,
    noVersus: true,
    darkMusic: true,
    titanShot: true,
    shotNumber: shot,
    gamblerX: Math.max(60, Math.min(420, player1.position.x)),
    gamblerTargetX: Math.max(60, Math.min(420, player1.position.x)),
    scammerX: 2000,
    scammerTargetX: 2000,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    chargeK: 0,
    beamK: 0,
    goldBits: [],
    handsK: 0,
  });
  selectedMap = 'castleRoof';
  startCutsceneLine(0);
}

function updateChronoTitanShot(cutscene, line, firstFrame) {
  cutscene.hideEnemy = true;
  if (line.aimTitan) {
    cutscene.chargeK = Math.min(1, cutscene.chargeK + 0.008);
    for (let bit = 0; bit < 3; bit += 1) cutscene.goldBits.push({ angle: Math.random() * Math.PI * 2, dist: 120 + Math.random() * 100, life: 30 });
    if (cutscene.frame % 6 === 0) playTone({ frequency: 300 + cutscene.chargeK * 900, duration: 0.08, type: 'square', volume: 0.035 });
  }
  cutscene.goldBits.forEach((bit) => {
    bit.dist *= 0.9;
    bit.life -= 1;
  });
  cutscene.goldBits = cutscene.goldBits.filter((bit) => bit.life > 0);
  if (line.fireTitan && firstFrame && !cutscene.fired) {
    cutscene.fired = true;
    cutscene.flash = 1;
    cutscene.shake = 30;
    cutscene.chargeK = 0;
    playNoise({ duration: 2, volume: 0.2, filterFrequency: 1500 });
    playTone({ frequency: 70, duration: 2, type: 'sawtooth', volume: 0.12, slideTo: 40 });
  }
  if (line.fireTitan) cutscene.beamK = Math.min(1, cutscene.beamK + 0.07);
  else cutscene.beamK = Math.max(0, cutscene.beamK - 0.08);
  if (line.titanHit && firstFrame && !cutscene.hitDone) {
    cutscene.hitDone = true;
    chronoTitan.recoil = 3;
    chronoTitan.eyeGlow = 2;
    playSound('titanRoar');
    cutscene.shake = 26;
    applyChronoTitanShotDamage(cutscene.shotNumber || 1);
    playTone({ frequency: 220, duration: 0.5, type: 'square', volume: 0.06, slideTo: 110 });
  }
  if (line.titanTurns || line.titanAngry) {
    chronoTitan.look = Math.max(-1, chronoTitan.look - 0.04);
    chronoTitan.eyeGlow = Math.min(line.titanAngry ? 3 : 2.5, chronoTitan.eyeGlow + 0.02);
    if (firstFrame) playTone({ frequency: 40, duration: 2.5, type: 'sine', volume: 0.12, slideTo: 32 });
  }
  if (line.titanAngry && firstFrame && !cutscene.angryRoar) {
    cutscene.angryRoar = true;
    playSound('titanRoar');
    cutscene.shake = 34;
  }
  if (line.closeHands) cutscene.handsK = Math.min(1, cutscene.handsK + 0.025);
  if (chronoTitan.recoil > 0) chronoTitan.recoil *= 0.95;
  cutscene.shake = (cutscene.shake || 0) * 0.92;
}

function drawChronoTitanShotFx(cutscene) {
  const time = performance.now() / 1000;
  const mx = cutscene.gamblerX + player1.width + 10;
  const my = ground - player1.height - (cutscene.gamblerHop || 0) + 25;
  cutscene.goldBits.forEach((bit) => {
    ctx.fillStyle = bit.life % 4 < 2 ? '#ffffff' : '#ffd54f';
    ctx.fillRect(mx + Math.cos(bit.angle) * bit.dist - 2, my + Math.sin(bit.angle) * bit.dist - 2, 5, 5);
  });
  if (cutscene.chargeK > 0) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(mx, my, 2, mx, my, 20 + cutscene.chargeK * 50);
    glow.addColorStop(0, 'rgba(255, 255, 255, 1)');
    glow.addColorStop(1, 'rgba(255, 213, 79, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(mx - 80, my - 80, 160, 160);
    ctx.restore();
  }
  if (cutscene.beamK > 0) {
    const tx = chronoTitanX;
    const ty = chronoTitanHeadY + 110;
    const ex = mx + (tx - mx) * cutscene.beamK;
    const ey = my + (ty - my) * cutscene.beamK;
    ctx.save();
    ctx.lineCap = 'round';
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(255, 171, 0, 0.5)';
    ctx.lineWidth = 90 + Math.sin(time * 30) * 6;
    ctx.beginPath();
    ctx.moveTo(mx, my);
    ctx.lineTo(ex, ey);
    ctx.stroke();
    ctx.strokeStyle = '#ffd54f';
    ctx.lineWidth = 56;
    ctx.stroke();
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 22;
    ctx.stroke();
    if (cutscene.beamK >= 1) {
      const burst = ctx.createRadialGradient(tx, ty, 5, tx, ty, 200);
      burst.addColorStop(0, 'rgba(255, 255, 255, 1)');
      burst.addColorStop(1, 'rgba(255, 213, 79, 0)');
      ctx.fillStyle = burst;
      ctx.fillRect(tx - 200, ty - 200, 400, 400);
    }
    ctx.restore();
  }
  // the hands closing around Chrono (into the box)
  if (cutscene.handsK > 0) {
    const k = cutscene.handsK;
    const cx = cutscene.gamblerX + player1.width / 2;
    drawTitanHandMirrored(cx - 90 - (1 - k) * 500, ground - 260, 170, 250);
    drawTitanHand(cx + 90 + (1 - k) * 500, ground - 260, 170, 250);
    if (k >= 1) {
      ctx.fillStyle = `rgba(0, 0, 0, ${0.3 + Math.sin(time * 6) * 0.1})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
  }
  drawTitanBossBar();
}

// ---------- the titan's BOX ATTACK: a huge box, the titan above it, its hands moving the box ----------
const titanBoxRect = { x: 172, y: 236, width: 680, height: 300 };
dodgeRoundThemes.titanBox = {
  title: 'BOX ATTACK DEL TITAN!',
  border: ['#ffffff', '#7e57c2'],
  phaseFrames: 560,
  titanBox: true,
  phases: [
    { pattern: 'titSqueeze', caption: 'LAS MANOS APRIETAN LA CAJA!' },
    { pattern: 'titShake', caption: 'EL TITAN SACUDE LA CAJA!' },
    { pattern: 'titFists', caption: 'PUÑOS SOBRE LA CAJA!' },
    { pattern: 'titEyes', caption: 'LA MIRADA DEL TITAN!' },
    { pattern: 'titTilt', caption: 'LA CAJA SE DA VUELTA!' },
    { pattern: 'titFinal', caption: 'OSCURIDAD TOTAL!' },
  ],
};

function spawnTitanBoxPattern(pattern, t, push, box, soul) {
  if (!pattern.startsWith('tit')) return false;
  if (['titBombs', 'titSpikes', 'titBombsSpikes'].includes(pattern)) return spawnTitanBox9Pattern(pattern, t, push, box, soul);
  if (spawnTitanBox9bPattern(pattern, t, push, box, soul)) return true;
  const round = dodgeRound;
  const base = titanBoxRect;
  const target = round.boxTarget;
  const drop = (speed = 4.4, warn = 20) => push({ type: 'drop', sprite: 'titDrop', x: target.x + 20 + Math.random() * (target.width - 40), y: target.y - 20, vy: speed + Math.random() * 1.4, r: 12, warn });
  const aimed = (x, y, speed, r = 10) => {
    const angle = Math.atan2(soul.y - y, soul.x - x);
    push({ type: 'aimed', sprite: 'titOrb', x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, r });
  };
  if (pattern === 'titSqueeze') {
    // the hands squeeze the box from the sides... and let go
    const squeeze = (Math.sin(t / 50) + 1) / 2;
    const width = base.width - squeeze * 380;
    Object.assign(target, { x: base.x + (base.width - width) / 2, width, y: base.y, height: base.height });
    round.titanHands = { mode: 'sides', k: squeeze };
    if (t % 18 === 0) drop();
    if (t % 70 === 35) {
      const side = Math.random() < 0.5 ? -1 : 1;
      push({ type: 'side', sprite: 'titSpike', x: side < 0 ? target.x - 20 : target.x + target.width + 20, y: target.y + 20 + Math.random() * (target.height - 40), vx: -side * 6, vy: 0, r: 11 });
    }
  } else if (pattern === 'titShake') {
    // it shakes the whole box around
    const shakeX = Math.sin(t / 9) * 90 + Math.sin(t / 23) * 40;
    const shakeY = Math.cos(t / 13) * 30;
    Object.assign(target, { x: base.x + 80 + shakeX, y: base.y + shakeY, width: base.width - 160, height: base.height - 40 });
    round.titanHands = { mode: 'grip', k: 1 };
    round.shake = Math.max(round.shake, 3);
    if (t % 30 === 0) {
      const side = Math.random() < 0.5 ? -1 : 1;
      push({ type: 'side', sprite: 'titSpike', x: side < 0 ? target.x - 20 : target.x + target.width + 20, y: target.y + 20 + Math.random() * (target.height - 40), vx: -side * 6.5, vy: 0, r: 11 });
    }
    if (t % 44 === 22) aimed(target.x + target.width / 2, target.y + 10, 4.6);
  } else if (pattern === 'titFists') {
    Object.assign(target, { ...base });
    round.titanHands = { mode: 'up', k: 1 };
    // fists falling on columns (warned), and a row punch now and then
    if (t % 55 === 0) push({ type: 'beam', sprite: 'titFist', orient: 'v', pos: Math.max(target.x + 50, Math.min(target.x + target.width - 50, soul.x + (Math.random() - 0.5) * 120)), size: 96, warn: 40, active: 22, life: 90, dmgScale: 1.3 });
    if (t % 55 === 27) push({ type: 'beam', sprite: 'titFist', orient: 'v', pos: target.x + 50 + Math.random() * (target.width - 100), size: 96, warn: 40, active: 22, life: 90, dmgScale: 1.3 });
    if (t % 120 === 90) push({ type: 'beam', sprite: 'titFistRow', orient: 'h', pos: Math.max(target.y + 40, Math.min(target.y + target.height - 40, soul.y)), size: 80, warn: 44, active: 20, life: 90, dmgScale: 1.3 });
    if (t % 26 === 13) drop(5.2, 16);
  } else if (pattern === 'titEyes') {
    // its eyes, right above the box: sweeping beams and dark orbs out of them
    Object.assign(target, { ...base });
    round.titanHands = { mode: 'rest', k: 1 };
    const eyeL = { x: canvas.width / 2 - 44, y: base.y - 70 };
    const eyeR = { x: canvas.width / 2 + 44, y: base.y - 70 };
    if (t % 80 === 0) push({ type: 'beam', sprite: 'titEye', orient: 'v', pos: Math.max(target.x + 30, Math.min(target.x + target.width - 30, soul.x)), size: 60, warn: 34, active: 26, life: 90 });
    if (t % 80 === 40) push({ type: 'beam', sprite: 'titEye', orient: 'h', pos: Math.max(target.y + 30, Math.min(target.y + target.height - 30, soul.y)), size: 60, warn: 34, active: 26, life: 90 });
    if (t % 24 === 0) {
      aimed(eyeL.x, eyeL.y + 60, 4.4);
      aimed(eyeR.x, eyeR.y + 60, 4.4);
    }
  } else if (pattern === 'titTilt') {
    // the box turns: tall and narrow, then long and flat
    const tall = Math.floor(t / 160) % 2 === 0;
    if (tall) Object.assign(target, { x: canvas.width / 2 - 140, y: base.y - 50, width: 280, height: base.height + 50 });
    else Object.assign(target, { x: base.x - 60, y: base.y + 110, width: base.width + 120, height: 160 });
    round.titanHands = { mode: tall ? 'sides' : 'grip', k: tall ? 1 : 0.4 };
    if (tall) {
      if (t % 70 === 10) {
        const gapWidth = 80;
        push({ type: 'wall', sprite: 'titWall', gapX: target.x + 16 + Math.random() * (target.width - 32 - gapWidth), gapWidth, y: target.y - 30, vy: 3.6, h: 22, warn: 30 });
      }
    } else if (t % 22 === 0) {
      const side = Math.random() < 0.5 ? -1 : 1;
      push({ type: 'side', sprite: 'titSpike', x: side < 0 ? target.x - 20 : target.x + target.width + 20, y: target.y + 20 + Math.random() * (target.height - 40), vx: -side * 7.5, vy: 0, r: 11 });
    }
  } else if (pattern === 'titFinal') {
    // everything: the box shrinks slowly, rings of darkness, drops, fists
    const shrink = Math.min(1, t / 420);
    const width = base.width - shrink * 300;
    const height = base.height - shrink * 110;
    Object.assign(target, { x: canvas.width / 2 - width / 2, y: base.y + (base.height - height) / 2, width, height });
    round.titanHands = { mode: 'sides', k: shrink };
    if (t % 90 === 0) push({ type: 'ring', sprite: 'titRing', x: target.x + target.width / 2, y: target.y + target.height / 2, radius: 10, speed: 2.8, gap: Math.random() * Math.PI * 2, gapSize: 1.1, life: 450, warn: 50 });
    if (t % 22 === 0) drop(5);
    if (t % 75 === 40) push({ type: 'beam', sprite: 'titFist', orient: 'v', pos: Math.max(target.x + 40, Math.min(target.x + target.width - 40, soul.x)), size: 80, warn: 38, active: 20, life: 90, dmgScale: 1.3 });
  }
  return true;
}

function drawTitanBoxItem(item, box) {
  if (!item.sprite || !item.sprite.startsWith('tit')) return false;
  if (drawTitanBox9bItem(item, box)) return true;
  if (item.type === 'bomb9') {
    // a charged sphere: its blast radius shown around it, tightening as it is about to go off
    ctx.save();
    if (item.fuse > 0) {
      const k = 1 - item.fuse / 95;
      ctx.strokeStyle = `rgba(206, 147, 216, ${0.3 + k * 0.6})`;
      ctx.lineWidth = 2 + k * 2;
      ctx.setLineDash([8, 6]);
      ctx.beginPath();
      ctx.arc(item.x, item.y, item.blastR, 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = `rgba(171, 71, 188, ${k * 0.18})`;
      ctx.fill();
      ctx.shadowColor = '#e1bee7';
      ctx.shadowBlur = 8 + k * 16;
      ctx.fillStyle = '#000000';
      ctx.strokeStyle = item.fuse % 10 < 5 && k > 0.6 ? '#e1bee7' : '#ffffff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(item.x, item.y, item.r + Math.sin(item.fuse / 3) * 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    } else {
      const k = item.blast / 18;
      const glow = ctx.createRadialGradient(item.x, item.y, 4, item.x, item.y, item.blastR);
      glow.addColorStop(0, `rgba(255, 255, 255, ${k})`);
      glow.addColorStop(0.5, `rgba(171, 71, 188, ${k * 0.8})`);
      glow.addColorStop(1, 'rgba(0, 0, 0, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(item.x, item.y, item.blastR, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
    return true;
  }
  if (item.type === 'spike9') {
    // a spike of darkness out of the floor
    const h = item.h * item.grow;
    const bottom = box.y + box.height;
    ctx.save();
    ctx.fillStyle = '#000000';
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#ab47bc';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.moveTo(item.x - item.w / 2, bottom);
    ctx.lineTo(item.x - item.w * 0.15, bottom - h * 0.55);
    ctx.lineTo(item.x, bottom - h);
    ctx.lineTo(item.x + item.w * 0.15, bottom - h * 0.6);
    ctx.lineTo(item.x + item.w / 2, bottom);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    return true;
  }
  ctx.save();
  ctx.fillStyle = '#000000';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 3;
  if (item.type === 'beam') {
    if (item.sprite === 'titEye') {
      // its gaze: a band of pure darkness, violet at the edges, with white cracks running through it
      const vertical = item.orient === 'v';
      const len = vertical ? box.height : box.width;
      const time = performance.now() / 1000;
      ctx.save();
      if (vertical) {
        ctx.translate(item.pos, box.y);
      } else {
        ctx.translate(box.x, item.pos);
        ctx.rotate(-Math.PI / 2);
        ctx.scale(-1, 1);
      }
      const half = item.size / 2;
      ctx.shadowColor = '#7e57c2';
      ctx.shadowBlur = 18;
      ctx.fillStyle = '#4a148c';
      ctx.fillRect(-half, 0, item.size, len);
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#000000';
      ctx.fillRect(-half + 6, 0, item.size - 12, len);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
      ctx.lineWidth = 2;
      for (let crack = 0; crack < 2; crack += 1) {
        ctx.beginPath();
        ctx.moveTo((crack ? 1 : -1) * half * 0.35, 0);
        for (let step = 1; step <= 10; step += 1) {
          ctx.lineTo((crack ? 1 : -1) * half * 0.35 + Math.sin(step * 2.3 + time * 20 + crack) * half * 0.3, (len / 10) * step);
        }
        ctx.stroke();
      }
      ctx.restore();
    } else if (item.orient === 'v') {
      // a fist coming down through the box
      drawTitanFist(item.pos - item.size / 2, box.y + box.height - item.size * 0.9, item.size, item.size * 0.8, true);
    } else {
      ctx.save();
      drawTitanFist(box.x - 20, item.pos - item.size / 2, box.width * 0.4, item.size, false);
      ctx.restore();
    }
  } else if (item.type === 'wall') {
    ctx.fillRect(box.x, item.y, item.gapX - box.x, item.h);
    ctx.strokeRect(box.x, item.y, item.gapX - box.x, item.h);
    ctx.fillRect(item.gapX + item.gapWidth, item.y, box.x + box.width - item.gapX - item.gapWidth, item.h);
    ctx.strokeRect(item.gapX + item.gapWidth, item.y, box.x + box.width - item.gapX - item.gapWidth, item.h);
  } else if (item.type === 'ring') {
    // a ring of darkness: violet glow, black core
    ctx.shadowColor = '#b388ff';
    ctx.shadowBlur = 14;
    ctx.lineWidth = 13;
    ctx.strokeStyle = '#7e57c2';
    ctx.beginPath();
    ctx.arc(item.x, item.y, item.radius, item.gap + item.gapSize / 2, item.gap - item.gapSize / 2 + Math.PI * 2);
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.lineWidth = 6;
    ctx.strokeStyle = '#12002a';
    ctx.stroke();
  } else if (item.sprite === 'titSpike') {
    const dir = item.vx > 0 ? 1 : -1;
    ctx.beginPath();
    ctx.moveTo(item.x + dir * 18, item.y);
    ctx.lineTo(item.x - dir * 14, item.y - 10);
    ctx.lineTo(item.x - dir * 8, item.y);
    ctx.lineTo(item.x - dir * 14, item.y + 10);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else {
    ctx.beginPath();
    ctx.arc(item.x, item.y, item.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  }
  ctx.restore();
  return true;
}

// the warnings of the titan's box: its own (not Light Warrior's lines of light)
function drawTitanBoxWarning(item, box) {
  if (!item.sprite || !item.sprite.startsWith('tit')) return false;
  const time = performance.now() / 1000;
  const pulse = 0.45 + Math.sin(time * 14) * 0.3;
  ctx.save();
  if (item.type === 'beam' && item.sprite === 'titFist' && item.orient === 'v') {
    // the shadow of the fist on the floor of the box, growing
    const k = 1 - item.warn / 40;
    ctx.fillStyle = `rgba(0, 0, 0, ${0.4 + k * 0.4})`;
    ctx.strokeStyle = `rgba(255, 255, 255, ${pulse})`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.ellipse(item.pos, box.y + box.height - 10, item.size * (0.25 + k * 0.3), 8 + k * 4, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.setLineDash([10, 8]);
    ctx.strokeRect(item.pos - item.size / 2, box.y, item.size, box.height);
    ctx.setLineDash([]);
  } else if (item.type === 'beam') {
    // the gaze / the side punch: a violet band blinking where it will hit, and an eye mark at its start
    ctx.fillStyle = `rgba(126, 87, 194, ${pulse * 0.45})`;
    ctx.strokeStyle = `rgba(179, 136, 255, ${pulse + 0.2})`;
    ctx.lineWidth = 2;
    ctx.setLineDash([10, 8]);
    if (item.orient === 'v') {
      ctx.fillRect(item.pos - item.size / 2, box.y, item.size, box.height);
      ctx.strokeRect(item.pos - item.size / 2, box.y, item.size, box.height);
    } else {
      ctx.fillRect(box.x, item.pos - item.size / 2, box.width, item.size);
      ctx.strokeRect(box.x, item.pos - item.size / 2, box.width, item.size);
    }
    ctx.setLineDash([]);
    const mx = item.orient === 'v' ? item.pos : box.x + 18;
    const my = item.orient === 'v' ? box.y + 16 : item.pos;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(mx - 14, my);
    ctx.quadraticCurveTo(mx, my - 9, mx + 14, my);
    ctx.quadraticCurveTo(mx, my + 9, mx - 14, my);
    ctx.fill();
  } else if (item.type === 'spike9') {
    // the floor cracks in violet where the spike will come out
    const k = 1 - item.warn / 36;
    const bottom = box.y + box.height;
    ctx.fillStyle = `rgba(126, 87, 194, ${pulse * 0.4})`;
    ctx.fillRect(item.x - item.w / 2, bottom - item.h, item.w, item.h);
    ctx.strokeStyle = `rgba(206, 147, 216, ${pulse + 0.2})`;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(item.x - item.w / 2, bottom - 4);
    ctx.lineTo(item.x - 6, bottom - 10 - k * 14);
    ctx.lineTo(item.x, bottom - 4);
    ctx.lineTo(item.x + 6, bottom - 12 - k * 14);
    ctx.lineTo(item.x + item.w / 2, bottom - 4);
    ctx.stroke();
  } else if (item.type === 'ring') {
    // a dark point growing at the center before the ring comes out
    const k = 1 - item.warn / 50;
    ctx.strokeStyle = `rgba(179, 136, 255, ${pulse + 0.2})`;
    ctx.lineWidth = 3;
    ctx.setLineDash([6, 6]);
    ctx.beginPath();
    ctx.arc(item.x, item.y, 20 + k * 30, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#12002a';
    ctx.strokeStyle = '#7e57c2';
    ctx.beginPath();
    ctx.arc(item.x, item.y, 6 + k * 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 22px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText('!', item.x, item.y - 30 - k * 30);
    ctx.textAlign = 'left';
  } else if (item.type === 'wall') {
    ctx.fillStyle = `rgba(126, 87, 194, ${pulse})`;
    ctx.fillRect(box.x, box.y + 2, item.gapX - box.x, 8);
    ctx.fillRect(item.gapX + item.gapWidth, box.y + 2, box.x + box.width - item.gapX - item.gapWidth, 8);
  } else if (item.type === 'drop') {
    ctx.fillStyle = `rgba(179, 136, 255, ${pulse})`;
    ctx.beginPath();
    ctx.arc(item.x, box.y + 8, 7, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.restore();
    return false;
  }
  ctx.restore();
  return true;
}

// the titan above the box, with its hands on the box
function drawTitanBoxScene(round) {
  const time = performance.now() / 1000;
  const box = round.box;
  // the head above the box, looking straight down at Chrono's soul
  const soul = getDodgeSoulCenter();
  const look = Math.max(-1, Math.min(1, (soul.x - canvas.width / 2) / 300));
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, canvas.width, box.y + 6);
  ctx.clip();
  drawDarkTitan(canvas.width / 2, box.y - 225, 0.85, look, time, 1.8 + Math.sin(time * 4) * 0.3);
  ctx.restore();
  drawChronoTitanSlowFx(box);
  if (round.config.laserMode) {
    ctx.save();
    ctx.fillStyle = '#ffd54f';
    ctx.font = '900 15px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText('MODO LASER: mantene Q para disparar', canvas.width / 2, box.y + box.height + 46);
    ctx.restore();
  }
  // its hands on the box
  const hands = round.titanHands || { mode: 'rest', k: 1 };
  const handH = Math.min(150, box.height * 0.6);
  const midY = box.y + box.height / 2 - handH / 2;
  if (hands.mode === 'sides' || hands.mode === 'grip') {
    drawTitanHandMirrored(box.x - 4, midY, 150, handH);
    drawTitanHand(box.x + box.width + 4, midY, 150, handH);
  } else if (hands.mode === 'up') {
    drawTitanFist(box.x - 150, box.y - 140, 130, 110, true);
    drawTitanFist(box.x + box.width + 20, box.y - 140, 130, 110, true);
  }
}

