function startChronoTitan9Scene(kind, lines, extra = {}) {
  ch6CutsceneBase('originsIntro', lines, 'dialog', {
    darkWorld: true,
    midFight: kind !== 'end',
    outro: kind === 'end',
    noVersus: true,
    darkMusic: true,
    titan9: kind,
    gamblerX: Math.max(60, Math.min(420, player1.characterType === 'chrono' ? player1.position.x : 140)),
    gamblerTargetX: Math.max(60, Math.min(420, player1.characterType === 'chrono' ? player1.position.x : 140)),
    scammerX: 2000,
    scammerTargetX: 2000,
    scammerY: 0,
    hideEnemy: true,
    lastFlagLine: -1,
    descendY: 2,
    t9: 0,
    t9Debris: [],
    t9Green: [],
    dgY: -400,
    ...extra,
  });
  selectedMap = extra.map || 'castleRuins';
  startCutsceneLine(0);
}

function startChronoTitan9Box() {
  chronoTitan.attacks = [];
  chronoCh.titanPhase = 'box';
  if (startDodgeRound('titanBox9', player2, player1)) {
    const box = { ...titanBoxRect };
    dodgeRound.boxTarget = box;
    dodgeRound.soul.x = box.x + box.width / 2 - dodgeRound.soul.width / 2;
    dodgeRound.soul.y = box.y + box.height / 2 - dodgeRound.soul.height / 2;
    dodgeRound.titanHands = { mode: 'rest', k: 1 };
    playSound('titanRoar');
  }
}

function startChronoTitan9Tired() {
  chronoCh.titanPhase = 'tiredScene';
  startChronoTitan9Scene('tired', chronoTitan9TiredLines);
}

function startChronoTitan9DgBabies() {
  // the General takes over; Chrono rests
  const chronoHealth = player1.health;
  chronoTitan.restActor = (() => {
    const actor = new Fighter({ x: 0, y: 0, color: '#448aff', attacksToTheRight: true });
    actor.setCharacterType('chrono');
    actor.machineLook = true;
    return actor;
  })();
  chronoTitan.chronoHealth = chronoHealth;
  makeChapterDivineGeneral(player1);
  player1.divineAdaptations = {};
  chronoTitan.lastStacks = 0;
  resumeChronoTitanFight('dgBabies', 10, 0);
  player1.health = player1.maxHealth;
  player1.position.x = 220;
  player2.position.x = 640;
  chronoCh.banner = { text: 'DIVINE GENERAL VS 10 BEBES TITAN', sub: 'Cada bebe vencido y cada adaptacion lo curan', t: 0 };
  updateHealthBars();
}

function startChronoTitan9Heal() {
  chronoCh.titanPhase = 'healScene';
  // back to Chrono (the General is drawn next to him in the scene)
  makeChapterChrono(player1);
  player1.scamLabelTimer = 0;
  player1.health = Math.max(1, Math.min(player1.maxHealth, chronoTitan.chronoHealth || player1.maxHealth * 0.3));
  startChronoTitan9Scene('heal', chronoTitan9HealLines, { gamblerX: 120, gamblerTargetX: 120 });
}

function startChronoTitan9Team() {
  makeChapterChrono(player1);
  player1.rareMachine = true;
  player1.machineLight = true;
  player1.machineBoost = true;
  chronoCh.overcharged = true;
  player1.damageMultiplier = 2;
  chronoTitan.next = 90;
  chronoTitan.dodgeLeft = 1;
  chronoTitan.step = 0;
  chronoTitan.power = 1.2;
  const actor = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
  actor.setCharacterType('divineGeneral');
  chronoTitan.ally = { actor, x: 60, cd: 0, swing: 0, faceRight: true, shout: null };
  resumeChronoTitanFight('team', 1, 0);
  player1.health = player1.maxHealth;
  player1.moveSpeed = playerMoveSpeed * 1.3;
  player1.position.x = 260;
  chronoCh.banner = { text: 'CHRONO Y DIVINE GENERAL VS TITAN', sub: 'Golpeen sus puños cuando caen al piso. La maquina, a la cara.', t: 0 };
  updateHealthBars();
}

function startChronoTitan9End() {
  chronoCh.outroPlayed = true;
  chronoCh.titanPhase = 'end';
  startChronoTitan9Scene('end', chronoTitan9EndLines, { gamblerX: Math.max(60, Math.min(420, player1.position.x)), gamblerTargetX: Math.max(60, Math.min(420, player1.position.x)) });
}

function endChronoTitan9Scene(kind) {
  if (kind === 'tired') startChronoTitan9DgBabies();
  else if (kind === 'heal') startChronoTitan9Team();
  else if (kind === 'laser') startChronoTitan9LaserBox();
  else if (kind === 'punch') startChronoTitan9DgDodge();
  else if (kind === 'beam') startChronoTitan9Clash();
  else if (kind === 'giant') startChronoTitan9Giant();
}

function updateChronoTitan9Scene(cutscene, line, firstFrame) {
  cutscene.hideEnemy = true;
  cutscene.t9 += 1;
  chronoTitan.visible = true;
  chronoTitan.rise = 1;
  const cx = cutscene.gamblerX + player1.width / 2;
  chronoTitan.look += (Math.max(-1, Math.min(1, (cx - chronoTitanX) / 400)) - chronoTitan.look) * 0.05;
  if (line.chaseRun) {
    cutscene.gamblerX = Math.max(120, cutscene.gamblerX - 3.2);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.gamblerHop = 8 + Math.abs(Math.sin(cutscene.frame / 3)) * 10;
    cutscene.shake = Math.max(cutscene.shake || 0, 3);
    if (cutscene.frame % 30 === 0) playTone({ frequency: 45, duration: 0.4, type: 'sine', volume: 0.08 });
  }
  if (line.tired) cutscene.gamblerHop = Math.sin(cutscene.frame / 8) * 3;
  if (line.fistDown && firstFrame && !cutscene.fistDone) {
    cutscene.fistDone = true;
    cutscene.fistT9 = 0;
    playChronoTitanFistSound();
  }
  if (line.fistDown) {
    cutscene.fistT9 = (cutscene.fistT9 || 0) + 1;
    if (cutscene.fistT9 === 18) {
      cutscene.shake = 40;
      cutscene.flash = 0.7;
      for (let chunk = 0; chunk < 40; chunk += 1) cutscene.t9Debris.push({ x: cutscene.gamblerX - 160 + Math.random() * 200, y: ground - 10, vx: (Math.random() - 0.5) * 12, vy: -6 - Math.random() * 10, size: 4 + Math.random() * 10, life: 120 });
    }
  }
  cutscene.t9Debris.forEach((chunk) => {
    chunk.x += chunk.vx;
    chunk.y = Math.min(ground - chunk.size, chunk.y + chunk.vy);
    chunk.vy += 0.4;
    chunk.life -= 1;
  });
  cutscene.t9Debris = cutscene.t9Debris.filter((chunk) => chunk.life > 0);
  if (line.roar && firstFrame) {
    cutscene.shake = 36;
    chronoTitan.eyeGlow = 2.5;
    playSound('titanRoar');
    playTone({ frequency: 55, duration: 2.2, type: 'sawtooth', volume: 0.13, slideTo: 30 });
  }
  if (line.recoil && firstFrame) {
    chronoTitan.recoil = 4;
    cutscene.shake = 30;
    playSound('titanRoar');
  }
  if (chronoTitan.recoil > 0) chronoTitan.recoil *= 0.97;
  if (line.drops10) cutscene.dropT = Math.min(100, (cutscene.dropT || 0) + 1);
  if (line.dgArrive) {
    if (firstFrame) {
      cutscene.dgY = -400;
      playNoise({ duration: 0.6, volume: 0.08, filterFrequency: 5000 });
      playTone({ frequency: 1200, duration: 1.2, type: 'sine', volume: 0.05, slideTo: 300 });
    }
    cutscene.dgY = Math.min(0, cutscene.dgY + 10);
    if (cutscene.dgY === 0 && !cutscene.dgLanded) {
      cutscene.dgLanded = true;
      cutscene.flash = 0.8;
      cutscene.shake = 14;
    }
  }
  if (line.dgHere || line.dgFront) cutscene.dgY = 0;
  if (line.toOutside && firstFrame) {
    selectedMap = 'castleOutskirts';
    cutscene.flash = 0.8;
    cutscene.shake = 30;
    playChronoTitanFistSound();
  }
  if (line.grow) {
    cutscene.dgScale = Math.min(chronoTitanGiantScale, (cutscene.dgScale || 1) + 0.02);
    if (cutscene.frame % 10 === 0 && cutscene.dgScale < chronoTitanGiantScale) playTone({ frequency: 200 + cutscene.dgScale * 120, duration: 0.15, type: 'triangle', volume: 0.04 });
    cutscene.shake = Math.max(cutscene.shake || 0, 3);
  }
  if (cutscene.titan9 === 'end') {
    updateChronoTitan9Final(cutscene, line, firstFrame);
    updateChronoTitan9FinalExtra(cutscene, line, firstFrame);
  }
  if (line.chronoDown) {
    cutscene.gamblerX = -400;
    cutscene.gamblerTargetX = -400;
  }
  if (line.laserUnlock && firstFrame) {
    cutscene.flash = 0.6;
    [880, 1100, 1320].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.15, type: 'square', volume: 0.05 }), index * 120));
  }
  if (line.closeHands) cutscene.handsK = Math.min(1, (cutscene.handsK || 0) + 0.025);
  // it heals with green energy
  if (line.greenTitan) {
    for (let bit = 0; bit < 4; bit += 1) cutscene.t9Green.push({ x: chronoTitanX + (Math.random() - 0.5) * 600, y: chronoTitanHeadY + 80 + Math.random() * 300, vy: -1.5 - Math.random() * 2, life: 60 });
    if (cutscene.frame % 10 === 0) playTone({ frequency: 300 + Math.random() * 200, duration: 0.2, type: 'sine', volume: 0.04 });
  }
  if (line.barHeal && firstFrame && chronoTitan.bar && chronoTitan.bar.value < chronoTitan9HealTo) {
    chronoTitan.healPop = 90;
    chronoTitan.bar.value = chronoTitan9HealTo;
    playTone({ frequency: 440, duration: 1.2, type: 'sine', volume: 0.06, slideTo: 880 });
  }
  if (chronoTitan.healPop > 0) chronoTitan.healPop -= 1;
  if (line.punchCharge) {
    cutscene.punchK = Math.min(1, (cutscene.punchK || 0) + 0.01);
    cutscene.shake = Math.max(cutscene.shake || 0, cutscene.punchK * 5);
    if (cutscene.frame % 8 === 0) playTone({ frequency: 60 + cutscene.punchK * 120, duration: 0.1, type: 'sawtooth', volume: 0.05 });
  }
  if (line.bigPunch) {
    cutscene.punchT = (cutscene.punchT || 0) + 1;
    if (cutscene.punchT === 1) {
      cutscene.holdLine = cutscene.lineIndex;
      playChronoTitanFistSound();
    }
    if (cutscene.punchT === 16) {
      if (player1.characterType === 'chrono') player1.brokenLook = true;
      cutscene.flash = 1;
      cutscene.shake = 60;
      for (let chunk = 0; chunk < 50; chunk += 1) cutscene.t9Debris.push({ x: 480 + (Math.random() - 0.5) * 200, y: ground - 10, vx: (Math.random() - 0.5) * 16, vy: -6 - Math.random() * 12, size: 4 + Math.random() * 12, life: 120 });
    }
    if (cutscene.punchT === 110) cutscene.holdLine = -1;
  }
  if (line.mouthCharge) {
    cutscene.mouthK = Math.min(1, (cutscene.mouthK || 0) + 0.006);
    if (cutscene.frame % 6 === 0) playTone({ frequency: 50 + cutscene.mouthK * 80, duration: 0.12, type: 'sawtooth', volume: 0.05 });
    cutscene.shake = Math.max(cutscene.shake || 0, cutscene.mouthK * 6);
  }
  if (line.cutFlash && firstFrame) {
    cutscene.flash = 1;
    playTone({ frequency: 1500, duration: 0.6, type: 'triangle', volume: 0.06, slideTo: 300 });
  }
  if (line.deflect) cutscene.deflectT = (cutscene.deflectT || 0) + 1;
  if (line.deflect && firstFrame) {
    cutscene.flash = 1;
    cutscene.shake = 40;
    playNoise({ duration: 2, volume: 0.2, filterFrequency: 1500 });
  }
  // green lights rising out of Chrono: he heals
  if (line.green) {
    for (let bit = 0; bit < 2; bit += 1) cutscene.t9Green.push({ x: cx + (Math.random() - 0.5) * 50, y: ground - Math.random() * 110, vy: -1 - Math.random() * 1.5, life: 60 });
    if (cutscene.frame % 12 === 0) playTone({ frequency: 520 + Math.random() * 300, duration: 0.2, type: 'sine', volume: 0.03 });
  }
  cutscene.t9Green.forEach((bit) => {
    bit.y += bit.vy;
    bit.life -= 1;
  });
  cutscene.t9Green = cutscene.t9Green.filter((bit) => bit.life > 0);
  if (chronoTitan.eyeGlow > 1) chronoTitan.eyeGlow = Math.max(1, chronoTitan.eyeGlow - 0.01);
  cutscene.shake = (cutscene.shake || 0) * 0.92;
}

function drawChronoTitan9SceneFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  // the fist behind Chrono in the chase
  if (line.fistDown && cutscene.fistT9 > 0) {
    const t = cutscene.fistT9;
    const fall = Math.min(1, t / 18);
    const rise = t > 70 ? (t - 70) / 30 : 0;
    const fx = cutscene.gamblerX + 120;
    drawTitanFist(fx - 110, -260 + (ground - 160 + 260) * fall - rise * (ground + 100), 220, 170, true);
  }
  cutscene.t9Debris.forEach((chunk) => {
    ctx.fillStyle = '#2a1e36';
    ctx.fillRect(chunk.x, chunk.y, chunk.size, chunk.size);
  });
  // the ten drops
  if (line.drops10 || line.openHand) {
    drawTitanHand(560, 40, 260, 110);
    drawTitanHandMirrored(470, 40, 260, 110);
  }
  if (line.drops10) {
    const k = Math.min(1, (cutscene.dropT || 0) / 60);
    for (let drop = 0; drop < 10; drop += 1) {
      const bx = 380 + drop * 55;
      if (k >= 1) {
        const baby = cutscene.babyActor || (cutscene.babyActor = (() => {
          const actor = new Fighter({ x: 0, y: 0, color: '#000000', attacksToTheRight: false });
          actor.setCharacterType('normal', 'babyTitan');
          actor.width = originsSizes.babyTitan[0];
          actor.height = originsSizes.babyTitan[1];
          return actor;
        })());
        baby.position = { x: bx - baby.width / 2, y: ground - baby.height };
        baby.attacksToTheRight = false;
        baby.isAttacking = false;
        drawBabyTitan(baby);
      } else {
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(bx, 150 + k * (ground - 170) - (drop % 3) * 20, 16, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      }
    }
  }
  // Divine General: down in a column of light, then at Chrono's side
  // Chrono on the floor
  if (line.chronoDown) {
    const downed = player1.characterType === 'chrono' ? player1 : chronoTitan.restActor;
    if (downed) {
      const saved = { ...downed.position };
      downed.position = { x: cutscene.chronoDownX !== undefined && cutscene.chronoDownX !== null ? cutscene.chronoDownX : 60, y: ground - downed.height };
      downed.isAttacking = false;
      // (next to a giant General he looks as small as he is)
      drawSmallDownedFighter(downed, (cutscene.dgScale || 1) > 1.2 ? 0.55 : 1);
      downed.position = saved;
    }
  }
  // two babies on its shoulders
  if (line.shoulderBabies) {
    const baby = cutscene.babyActor || (cutscene.babyActor = (() => {
      const actor = new Fighter({ x: 0, y: 0, color: '#000000', attacksToTheRight: false });
      actor.setCharacterType('normal', 'babyTitan');
      actor.width = originsSizes.babyTitan[0];
      actor.height = originsSizes.babyTitan[1];
      return actor;
    })());
    [chronoTitanX - 330, chronoTitanX + 300].forEach((bx) => {
      baby.position = { x: bx - baby.width / 2, y: chronoTitanHeadY + 190 - baby.height };
      baby.attacksToTheRight = false;
      baby.isAttacking = false;
      drawBabyTitan(baby);
    });
  }
  if (line.closeHands) {
    const k = cutscene.handsK || 0;
    const cx = Math.max(60, cutscene.gamblerX) + player1.width / 2;
    drawTitanHandMirrored(cx - 90 - (1 - k) * 500, ground - 260, 170, 250);
    drawTitanHand(cx + 90 + (1 - k) * 500, ground - 260, 170, 250);
  }
  // the titan glowing green
  if (line.greenTitan) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(chronoTitanX, chronoTitanHeadY + 200, 20, chronoTitanX, chronoTitanHeadY + 200, 420);
    glow.addColorStop(0, `rgba(105, 240, 174, ${0.25 + Math.sin(time * 5) * 0.08})`);
    glow.addColorStop(1, 'rgba(105, 240, 174, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(chronoTitanX - 420, chronoTitanHeadY - 220, 840, 840);
    ctx.restore();
  }
  if (chronoTitan.healPop > 0) {
    ctx.save();
    ctx.globalAlpha = Math.min(1, chronoTitan.healPop / 30);
    ctx.font = '900 46px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#69f0ae';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 6;
    ctx.strokeText(`+${chronoTitan9HealTo - chronoTitan9TeamGoal + 1}`, canvas.width / 2, 300 - (90 - chronoTitan.healPop) * 0.4);
    ctx.fillText(`+${chronoTitan9HealTo - chronoTitan9TeamGoal + 1}`, canvas.width / 2, 300 - (90 - chronoTitan.healPop) * 0.4);
    ctx.restore();
  }
  // the green punch: raised... and down, right in the middle
  if (line.punchCharge) {
    const k = cutscene.punchK || 0;
    ctx.save();
    ctx.shadowColor = '#69f0ae';
    ctx.shadowBlur = 20 + k * 30;
    drawTitanFist(370, -60 - k * 40, 240, 190, true);
    ctx.restore();
  }
  if (line.bigPunch && cutscene.punchT > 0) {
    const t = cutscene.punchT;
    const fall = Math.min(1, t / 16);
    ctx.save();
    ctx.shadowColor = '#69f0ae';
    ctx.shadowBlur = 40;
    drawTitanFist(370, -100 + (ground - 200 + 100) * fall, 240, 190, true);
    ctx.restore();
  }
  // the black light in its mouth
  if (line.mouthCharge) {
    const k = cutscene.mouthK || 0;
    const mouth = getTitanMouth();
    ctx.save();
    ctx.fillStyle = '#000000';
    ctx.strokeStyle = '#e040fb';
    ctx.lineWidth = 4;
    ctx.shadowColor = '#e040fb';
    ctx.shadowBlur = 20 + k * 40;
    ctx.beginPath();
    ctx.arc(mouth.x, mouth.y, 12 + k * 46, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    for (let bit = 0; bit < 10; bit += 1) {
      const angle = time * 3 + bit * 0.63;
      const dist = 120 * (1 - ((time * 2 + bit / 10) % 1));
      ctx.fillStyle = bit % 2 ? '#ffffff' : '#e040fb';
      ctx.fillRect(mouth.x + Math.cos(angle) * dist - 2, mouth.y + Math.sin(angle) * dist - 2, 4, 4);
    }
    ctx.restore();
  }
  // the deflected laser, thrown into the sky
  if (line.deflect && cutscene.deflectT < 120) {
    const mouth = getTitanMouth();
    const k = Math.min(1, cutscene.deflectT / 20);
    ctx.save();
    ctx.lineCap = 'round';
    ctx.strokeStyle = `rgba(224, 64, 251, ${1 - cutscene.deflectT / 120})`;
    ctx.lineWidth = 70;
    ctx.beginPath();
    ctx.moveTo(mouth.x, mouth.y);
    ctx.lineTo(mouth.x - 120 * k, mouth.y - 600 * k);
    ctx.stroke();
    ctx.strokeStyle = `rgba(0, 0, 0, ${1 - cutscene.deflectT / 120})`;
    ctx.lineWidth = 44;
    ctx.stroke();
    ctx.restore();
  }
  if (line.swordUp) {
    const x = cutscene.dgFixedX !== null && cutscene.dgFixedX !== undefined ? cutscene.dgFixedX : 240;
    const glow = ctx.createRadialGradient(x + 40, ground - 80, 10, x + 40, ground - 80, 140);
    glow.addColorStop(0, `rgba(255, 213, 79, ${0.4 + Math.sin(time * 8) * 0.1})`);
    glow.addColorStop(1, 'rgba(255, 213, 79, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(x - 100, ground - 220, 280, 280);
  }
  if ((line.dgArrive || line.dgHere || line.dgFront) && cutscene.dgY > -400) {
    const actor = cutscene.dgActor || (cutscene.dgActor = (() => {
      const divine = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
      divine.setCharacterType('divineGeneral');
      return divine;
    })());
    const x = cutscene.dgFixedX !== null && cutscene.dgFixedX !== undefined ? cutscene.dgFixedX : Math.min(canvas.width - 300, cutscene.gamblerX + 110);
    if (line.dgArrive) {
      const beam = ctx.createLinearGradient(x - 40, 0, x + actor.width + 40, 0);
      beam.addColorStop(0, 'rgba(255, 255, 255, 0)');
      beam.addColorStop(0.5, 'rgba(255, 255, 255, 0.55)');
      beam.addColorStop(1, 'rgba(255, 255, 255, 0)');
      ctx.fillStyle = beam;
      ctx.fillRect(x - 40, 0, actor.width + 80, ground);
    }
    actor.position = { x, y: ground - actor.height + cutscene.dgY };
    actor.attacksToTheRight = true;
    actor.isAttacking = false;
    actor.giantScale = cutscene.dgScale || 1;
    if (line.glowDG || line.grow) {
      const scale = actor.giantScale;
      const glow = ctx.createRadialGradient(x + actor.width / 2, ground - actor.height * scale * 0.5, 10, x + actor.width / 2, ground - actor.height * scale * 0.5, 90 * scale);
      glow.addColorStop(0, `rgba(255, 245, 200, ${0.4 + Math.sin(time * 6) * 0.1})`);
      glow.addColorStop(1, 'rgba(255, 245, 200, 0)');
      ctx.fillStyle = glow;
      ctx.fillRect(x + actor.width / 2 - 90 * scale, ground - actor.height * scale * 0.5 - 90 * scale, 180 * scale, 180 * scale);
    }
    if (line.dgTired && Math.floor(time * 2) % 2 === 0) {
      ctx.fillStyle = '#90caf9';
      ctx.fillRect(x + actor.width + 4, ground - actor.height + 10, 4, 8);
    }
    actor.draw();
  }
  cutscene.t9Green.forEach((bit) => {
    ctx.fillStyle = `rgba(105, 240, 174, ${bit.life / 60})`;
    ctx.fillRect(bit.x - 3, bit.y - 3, 6, 6);
  });
  if (line.green) {
    const cx = cutscene.gamblerX + player1.width / 2;
    const glow = ctx.createRadialGradient(cx, ground - 60, 5, cx, ground - 60, 90);
    glow.addColorStop(0, `rgba(105, 240, 174, ${0.35 + Math.sin(time * 6) * 0.1})`);
    glow.addColorStop(1, 'rgba(105, 240, 174, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(cx - 90, ground - 150, 180, 180);
  }
  if (cutscene.titan9 === 'end') drawChronoTitan9FinalFx(cutscene);
  if (!(cutscene.titan9 === 'end' && (selectedMap === 'kingThrone' || chronoTitan.visible === false))) drawTitanBossBar();
}

// ================= LEVEL 9, part two: the laser box, the green punch, the General alone, the broken box, the clash =================
const chronoTitan9DgFrames = 2700;
const chronoTitan9HealTo = 7300;
const titanAdaptNames = { fist: 'PUÑO', sweep: 'BARRIDO', rain: 'LLUVIA', clap: 'APLAUSO' };

// ---------- the laser box: Chrono can shoot (Q), two babies come in to fight ----------
dodgeRoundThemes.titanBoxLaser = {
  title: 'BOX ATTACK: MODO LASER! (Q dispara)',
  border: ['#ffffff', '#ffd54f'],
  phaseFrames: 460,
  titanBox: true,
  laserMode: true,
  phases: [
    { pattern: 'titBombs', caption: 'ROMPE LAS ESFERAS CON EL LASER (Q)... Y LO QUE PASE, LE PEGA AL TITAN!' },
    { pattern: 'titSpikes', caption: 'PICOS DE OSCURIDAD: EL LASER TAMBIEN LOS ROMPE!' },
    { pattern: 'titBabyA', caption: 'UN BEBE ENTRA A LA CAJA: DISPARALE (Q)!', frames: 620 },
    { pattern: 'titSqueeze', caption: 'LAS MANOS APRIETAN!' },
    { pattern: 'titBombsSpikes', caption: 'TODO JUNTO!' },
    { pattern: 'titBabyB', caption: 'EL OTRO BEBE: DISPARALE (Q)!', frames: 620 },
  ],
};

// ---------- the broken box (against the General): it breaks the box, giant lasers from its hands and mouth ----------
dodgeRoundThemes.titanBoxBreak = {
  title: 'BOX ATTACK FINAL DEL TITAN!',
  border: ['#ffffff', '#e040fb'],
  phaseFrames: 520,
  titanBox: true,
  phases: [
    { pattern: 'titHandLasers', caption: 'LASERS DE SUS MANOS!' },
    { pattern: 'titBreak', caption: 'EL TITAN AGARRA LA CAJA...', frames: 560 },
    { pattern: 'titMouthLaser', caption: 'LASERS DE SU BOCA!' },
    { pattern: 'titHandLasers2', caption: 'LAS DOS MANOS!' },
    { pattern: 'titLaserStorm', caption: 'TORMENTA DE LASERS!', frames: 600 },
  ],
};

function spawnTitanBox9bPattern(pattern, t, push, box, soul) {
  const round = dodgeRound;
  const base = titanBoxRect;
  const target = round.boxTarget;
  const drop = (speed = 4.6) => push({ type: 'drop', sprite: 'titDrop', x: target.x + 20 + Math.random() * (target.width - 40), y: target.y - 20, vy: speed + Math.random(), r: 12, warn: 18 });
  if (pattern === 'titBabyA' || pattern === 'titBabyB') {
    Object.assign(target, { ...base });
    if (t === 1) push({ type: 'babyT', custom: true, sprite: 'titBabyT', x: target.x + target.width / 2, y: target.y + 46, vx: 2.6, hp: 12, maxHp: 12, fire: 0, r: 26, life: 600, hurt: 0 });
    if (t % 34 === 0) drop(4.2);
    return true;
  }
  if (pattern === 'titHandLasers' || pattern === 'titHandLasers2') {
    Object.assign(target, { ...base });
    round.titanHands = { mode: 'grip', k: 1 };
    const rate = pattern === 'titHandLasers2' ? 58 : 72;
    if (t % rate === 0) push({ type: 'beam', sprite: 'titHandLaser', orient: 'h', pos: Math.max(target.y + 45, Math.min(target.y + target.height - 45, soul.y)), size: 86, warn: 44, active: 34, life: 100, dmgScale: 1.3 });
    if (pattern === 'titHandLasers2' && t % rate === Math.floor(rate / 2)) {
      // two rows at once, with a band free in between
      const free = target.y + 50 + Math.random() * (target.height - 100);
      [target.y + 40, target.y + target.height - 40].forEach((row) => {
        if (Math.abs(row - free) > 70) push({ type: 'beam', sprite: 'titHandLaser', orient: 'h', pos: row, size: 70, warn: 44, active: 30, life: 100, dmgScale: 1.3 });
      });
    }
    if (t % 40 === 20) drop();
    return true;
  }
  if (pattern === 'titBreak') {
    // it grabs the box... breaks it open... and the whole screen is the box, for a while
    if (t < 70) {
      Object.assign(target, { ...base });
      round.titanHands = { mode: 'sides', k: Math.min(1, t / 70) };
      round.shake = Math.max(round.shake, t / 12);
    } else if (t === 70) {
      round.boxBroken = true;
      round.shake = 30;
      Object.assign(target, { x: 30, y: 116, width: canvas.width - 60, height: ground + 20 - 116 });
      for (let shard = 0; shard < 50; shard += 1) {
        const angle = Math.random() * Math.PI * 2;
        round.sparks.push({ x: base.x + Math.random() * base.width, y: base.y + (Math.random() < 0.5 ? 0 : base.height), vx: Math.cos(angle) * 9, vy: Math.sin(angle) * 9, life: 40, rock: true });
      }
      dodgeRoundCaption('¡ROMPIO LA CAJA!', '#ff5252');
      playSound('omegaKickImpact');
      playNoise({ duration: 1.2, volume: 0.2, filterFrequency: 600 });
    } else if (t < 420) {
      round.titanHands = { mode: 'up', k: 1 };
      // the hard part: fists all over the open screen
      if (t % 26 === 0) push({ type: 'beam', sprite: 'titFist', orient: 'v', pos: Math.max(target.x + 60, Math.min(target.x + target.width - 60, soul.x + (Math.random() - 0.5) * 90)), size: 110, warn: 34, active: 20, life: 80, dmgScale: 1.4 });
      if (t % 26 === 13) push({ type: 'beam', sprite: 'titFist', orient: 'v', pos: target.x + 60 + Math.random() * (target.width - 120), size: 110, warn: 34, active: 20, life: 80, dmgScale: 1.4 });
      if (t % 90 === 45) push({ type: 'beam', sprite: 'titHandLaser', orient: 'h', pos: Math.max(target.y + 50, Math.min(target.y + target.height - 50, soul.y)), size: 90, warn: 46, active: 30, life: 100, dmgScale: 1.3 });
    } else if (t === 420) {
      round.boxBroken = false;
      Object.assign(target, { ...base });
      dodgeRoundCaption('LA CAJA SE REARMA...', '#e1bee7');
    }
    return true;
  }
  if (pattern === 'titMouthLaser') {
    Object.assign(target, { ...base });
    round.titanHands = { mode: 'rest', k: 1 };
    // straight down from its mouth, where you are... and a fan of orbs out of it
    if (t % 62 === 0) push({ type: 'beam', sprite: 'titMouthLaser', orient: 'v', pos: Math.max(target.x + 40, Math.min(target.x + target.width - 40, soul.x)), size: 84, warn: 40, active: 34, life: 100, dmgScale: 1.3 });
    if (t % 62 === 31) {
      const mouth = { x: canvas.width / 2, y: target.y + 4 };
      for (let shot = 0; shot < 7; shot += 1) {
        const angle = Math.PI * 0.2 + (shot / 6) * Math.PI * 0.6;
        push({ type: 'aimed', sprite: 'titOrb', x: mouth.x, y: mouth.y, vx: Math.cos(angle) * 3.8, vy: Math.sin(angle) * 3.8, r: 10 });
      }
    }
    return true;
  }
  if (pattern === 'titLaserStorm') {
    Object.assign(target, { ...base });
    round.titanHands = { mode: 'grip', k: 1 };
    if (t % 48 === 0) push({ type: 'beam', sprite: 'titMouthLaser', orient: 'v', pos: Math.max(target.x + 40, Math.min(target.x + target.width - 40, soul.x)), size: 80, warn: 38, active: 30, life: 100, dmgScale: 1.3 });
    if (t % 48 === 24) push({ type: 'beam', sprite: 'titHandLaser', orient: 'h', pos: Math.max(target.y + 40, Math.min(target.y + target.height - 40, soul.y)), size: 80, warn: 38, active: 30, life: 100, dmgScale: 1.3 });
    if (t % 120 === 60) push({ type: 'ring', sprite: 'titRing', x: target.x + target.width / 2, y: target.y + target.height / 2, radius: 10, speed: 3, gap: Math.random() * Math.PI * 2, gapSize: 1.1, life: 450, warn: 50 });
    return true;
  }
  return false;
}

// the babies inside the laser box
function updateTitanBabyTarget(item, round, center, soulRadius, box) {
  item.x += item.vx;
  if (item.x < box.x + item.r || item.x > box.x + box.width - item.r) item.vx *= -1;
  item.y = box.y + 46 + Math.sin(round.frame / 14) * 10;
  item.fire += 1;
  if (item.hurt > 0) item.hurt -= 1;
  if (item.fire % 46 === 0) {
    const angle = Math.atan2(center.y - item.y, center.x - item.x);
    [-0.25, 0, 0.25].forEach((spread) => round.items.push({ type: 'aimed', sprite: 'titOrb', x: item.x, y: item.y + 14, vx: Math.cos(angle + spread) * 4, vy: Math.sin(angle + spread) * 4, r: 9, warn: 0, life: 160 }));
  }
  if (Math.hypot(center.x - item.x, center.y - item.y) < item.r + soulRadius) hurtDodgeTarget(1);
}

// Chrono's lasers (Q): straight up from his soul
function updateDrawTitanLasers(round) {
  round.titanLasers = round.titanLasers || [];
  round.laserCd = Math.max(0, (round.laserCd || 0) - 1);
  if (keys.q && round.stage === 'phase' && round.laserCd <= 0) {
    const soul = getDodgeSoulCenter();
    round.titanLasers.push({ x: soul.x, y: soul.y - 10, life: 50 });
    round.laserCd = 8;
    playTone({ frequency: 1300, duration: 0.05, type: 'square', volume: 0.025, slideTo: 1800 });
  }
  round.titanLasers.forEach((laser) => {
    laser.y -= 14;
    laser.life -= 1;
    round.items.forEach((item) => {
      if (item.type !== 'babyT' || item.life <= 0 || laser.life <= 0) return;
      if (Math.abs(laser.x - item.x) < item.r && Math.abs(laser.y - item.y) < item.r + 8) {
        laser.life = 0;
        item.hp -= 1;
        item.hurt = 6;
        playTone({ frequency: 300, duration: 0.08, type: 'square', volume: 0.04, slideTo: 150 });
        if (item.hp <= 0) {
          item.life = 0;
          round.shake = 16;
          for (let puff = 0; puff < 24; puff += 1) {
            const angle = Math.random() * Math.PI * 2;
            round.sparks.push({ x: item.x, y: item.y, vx: Math.cos(angle) * 5, vy: Math.sin(angle) * 5, life: 30, rock: true });
          }
          dodgeRoundCaption('¡BEBE TITAN DERRIBADO!', '#ffd54f');
          playNoise({ duration: 0.6, volume: 0.12, filterFrequency: 500 });
          // the phase ends soon after
          const phase = round.config.phases[round.phaseIndex];
          const frames = (phase && phase.frames) || round.config.phaseFrames;
          round.phaseFrame = Math.max(round.phaseFrame, frames - 60);
        }
      }
    });
    // bombs, drops and spikes break with a shot
    round.items.forEach((item) => {
      if (laser.life <= 0 || item.life <= 0 || item.warn > 0) return;
      let hit = false;
      if (item.type === 'bomb9' && item.fuse > 0) hit = Math.hypot(laser.x - item.x, laser.y - item.y) < item.r + 8;
      else if (item.type === 'drop') hit = Math.hypot(laser.x - item.x, laser.y - item.y) < (item.r || 12) + 8;
      else if (item.type === 'spike9') hit = Math.abs(laser.x - item.x) < item.w / 2 && laser.y > round.box.y + round.box.height - item.h * (item.grow || 0);
      if (!hit) return;
      laser.life = 0;
      item.life = 0;
      for (let shard = 0; shard < 10; shard += 1) {
        const angle = Math.random() * Math.PI * 2;
        round.sparks.push({ x: laser.x, y: laser.y, vx: Math.cos(angle) * 4, vy: Math.sin(angle) * 4, life: 20 });
      }
      round.laserBreaks = (round.laserBreaks || 0) + 1;
      playTone({ frequency: 900, duration: 0.06, type: 'square', volume: 0.035, slideTo: 400 });
    });
    if (laser.y < round.box.y - 10 && laser.life > 0) {
      // a shot that leaves the box goes on... into the titan's face
      laser.life = 0;
      round.laserFace = (round.laserFace || 0) + 1;
      if (round.laserFace % 3 === 0) {
        damageTitanBar(6, chronoTitanX + (Math.random() - 0.5) * 120, chronoTitanHeadY + 120);
        chronoTitan.recoil = Math.max(chronoTitan.recoil || 0, 0.4);
      }
    }
  });
  round.titanLasers = round.titanLasers.filter((laser) => laser.life > 0);
  ctx.save();
  ctx.shadowColor = '#ffd54f';
  ctx.shadowBlur = 10;
  ctx.fillStyle = '#fff8e1';
  round.titanLasers.forEach((laser) => ctx.fillRect(laser.x - 2, laser.y - 12, 4, 24));
  ctx.restore();
}

// ---------- drawing the new things in the boxes ----------
function drawTitanBox9bItem(item, box) {
  if (item.type === 'babyT') {
    const fake = { position: { x: item.x - 31, y: item.y - 40 }, width: 62, height: 80, attacksToTheRight: item.vx > 0, isAttacking: false };
    ctx.save();
    if (item.hurt > 0) ctx.globalAlpha = 0.6;
    drawBabyTitan(fake);
    ctx.restore();
    // its health
    ctx.fillStyle = '#000';
    ctx.fillRect(item.x - 30, item.y - 52, 60, 6);
    ctx.fillStyle = '#ffd54f';
    ctx.fillRect(item.x - 30, item.y - 52, 60 * (item.hp / item.maxHp), 6);
    return true;
  }
  if (item.type === 'beam' && (item.sprite === 'titHandLaser' || item.sprite === 'titMouthLaser')) {
    const vertical = item.orient === 'v';
    const time = performance.now() / 1000;
    const wob = Math.sin(time * 40) * 4;
    ctx.save();
    ctx.shadowColor = '#e040fb';
    ctx.shadowBlur = 26;
    const fill = (size, color) => {
      ctx.fillStyle = color;
      if (vertical) ctx.fillRect(item.pos - size / 2, box.y, size, box.height);
      else ctx.fillRect(box.x, item.pos - size / 2, box.width, size);
    };
    fill(item.size + wob, 'rgba(123, 31, 162, 0.85)');
    ctx.shadowBlur = 0;
    fill(item.size * 0.6, '#ea80fc');
    fill(item.size * 0.25, '#ffffff');
    ctx.restore();
    return true;
  }
  return false;
}

