function startChronoSecretScene(lines, extra = {}) {
  const divine = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
  divine.setCharacterType('divineGeneral');
  ch6CutsceneBase('originsIntro', lines, 'dialog', {
    darkWorld: true,
    secretScene: true,
    gamblerX: 260,
    gamblerTargetX: 260,
    scammerX: 680,
    scammerTargetX: 680,
    scammerY: 0,
    hideEnemy: false,
    lastFlagLine: -1,
    descendY: 2,
    secretDg: divine,
    secretDgX: 120,
    ...extra,
  });
  selectedMap = 'abnormalArena';
  startCutsceneLine(0);
}

function startChronoSecretIntro() {
  startChronoSecretScene(chronoSecretIntroLines, { versusName: 'ABNORMAL' });
}

function updateChronoSecretScene(cutscene, line, firstFrame) {
  if (cutscene.lines === chronoSecretOmegaLines) {
    updateChronoSecretOmega(cutscene, line, firstFrame);
    if (line.dgForest || line.tempus) return;
  }
  // Chrono is still broken from the titan: no floating, a little shaky
  cutscene.gamblerHop = Math.sin(cutscene.frame / 8) * 2;
  if (line.dgStep) cutscene.secretDgX += (200 - cutscene.secretDgX) * 0.08;
  if (line.dgBack) cutscene.secretDgX += (90 - cutscene.secretDgX) * 0.08;
  if (line.mazeFlash && firstFrame) {
    cutscene.flash = 0.8;
    [523, 659, 784, 1046].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.18, type: 'square', volume: 0.05 }), index * 90));
  }
  if (line.abnDown) cutscene.scammerY = -14;
  if (cutscene.flash > 0) cutscene.flash = Math.max(0, cutscene.flash - 0.03);
}

function drawChronoSecretSceneFx(cutscene) {
  const line = cutscene.lines[cutscene.lineIndex];
  if (cutscene.lines === chronoSecretOmegaLines) drawChronoSecretOmegaFx(cutscene);
  const time = performance.now() / 1000;
  if (line.dgHere && cutscene.secretDg) {
    const divine = cutscene.secretDg;
    divine.position = { x: cutscene.secretDgX, y: ground - divine.height };
    divine.attacksToTheRight = true;
    divine.isAttacking = false;
    divine.draw();
  }
  // the hooded one, a memory in Abnormal's head
  if (line.hoodedMemory) {
    ctx.save();
    ctx.globalAlpha = 0.55 + Math.sin(time * 3) * 0.1;
    ctx.fillStyle = 'rgba(20, 10, 40, 0.6)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (typeof drawHoodedFigure === 'function') drawHoodedFigure(canvas.width / 2, ground - 40, 1, time);
    ctx.restore();
  }
}

