// ================= Abnormal's BOX ATTACK: the distinguished maze =================
const abnormalGrid = { active: false };

function generateAbnormalMaze(cols, rows, loops) {
  const grid = [];
  for (let row = 0; row < rows; row += 1) grid.push(new Array(cols).fill(1));
  const stack = [[1, 1]];
  grid[1][1] = 0;
  while (stack.length) {
    const [cx, cy] = stack[stack.length - 1];
    const options = [[2, 0], [-2, 0], [0, 2], [0, -2]]
      .map(([dx, dy]) => [cx + dx, cy + dy, dx, dy])
      .filter(([nx, ny]) => nx > 0 && ny > 0 && nx < cols - 1 && ny < rows - 1 && grid[ny][nx] === 1);
    if (!options.length) {
      stack.pop();
      continue;
    }
    const [nx, ny, dx, dy] = options[Math.floor(Math.random() * options.length)];
    grid[cy + dy / 2][cx + dx / 2] = 0;
    grid[ny][nx] = 0;
    stack.push([nx, ny]);
  }
  // a few extra openings: more than one way through
  for (let row = 1; row < rows - 1; row += 1) {
    for (let col = 1; col < cols - 1; col += 1) {
      if (grid[row][col] === 1 && (row + col) % 2 === 1 && Math.random() < loops) grid[row][col] = 0;
    }
  }
  return grid;
}

function abnormalMazeDistances(grid, cols, rows, sx, sy) {
  const dist = grid.map((row) => row.map(() => -1));
  const prev = grid.map((row) => row.map(() => null));
  const queue = [[sx, sy]];
  dist[sy][sx] = 0;
  while (queue.length) {
    const [x, y] = queue.shift();
    [[1, 0], [-1, 0], [0, 1], [0, -1]].forEach(([dx, dy]) => {
      const nx = x + dx;
      const ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= cols || ny >= rows || grid[ny][nx] === 1 || dist[ny][nx] >= 0) return;
      dist[ny][nx] = dist[y][x] + 1;
      prev[ny][nx] = [x, y];
      queue.push([nx, ny]);
    });
  }
  return { dist, prev };
}

const abnormalGridStages = {
  1: { cols: 11, rows: 7, cell: 46, y: 190, loops: 0.06, fog: 2.6, redEvery: 0, staticReds: 0, redDamage: 0.1, greens: 0, chaser: false },
  2: { cols: 17, rows: 11, cell: 36, y: 150, loops: 0.12, fog: 3.1, redEvery: 4, staticReds: 0.07, redDamage: 0.1, greens: 0, chaser: false },
  3: { cols: 19, rows: 11, cell: 34, y: 150, loops: 0.1, fog: 3, redEvery: 3, staticReds: 0.12, redDamage: 0.18, greens: 3, chaser: false },
  4: { cols: 19, rows: 11, cell: 34, y: 150, loops: 0.16, fog: 3.2, redEvery: 4, staticReds: 0.08, redDamage: 0.18, greens: 2, chaser: true },
  5: { cols: 19, rows: 11, cell: 34, y: 150, loops: 0.14, fog: 3, redEvery: 4, staticReds: 0.08, redDamage: 0.2, greens: 3, chaser: true, mazeRules: true },
  6: { cols: 21, rows: 11, cell: 32, y: 150, loops: 0.16, fog: 3, redEvery: 4, staticReds: 0.08, redDamage: 0.2, greens: 3, chaser: true, mazeRules: true },
};

function startAbnormalGrid(stage) {
  const conf = abnormalGridStages[stage];
  const { cols, rows, cell } = conf;
  const grid = generateAbnormalMaze(cols, rows, conf.loops);
  const { dist, prev } = abnormalMazeDistances(grid, cols, rows, 1, 1);
  // the golden block: the farthest place from the start
  let goal = [1, 1];
  dist.forEach((row, y) => row.forEach((d, x) => {
    if (d > dist[goal[1]][goal[0]]) goal = [x, y];
  }));
  const path = [];
  let step = goal;
  while (step) {
    path.unshift(step);
    step = prev[step[1]][step[0]];
  }
  const onPath = new Set(path.map(([x, y]) => `${x},${y}`));
  const reds = [];
  // red blocks that blink, on the way (you have to time them)
  if (conf.redEvery) {
    path.forEach(([x, y], index) => {
      if (index > 2 && index < path.length - 2 && index % conf.redEvery === 0) reds.push({ x, y, blink: true, phase: Math.floor(Math.random() * 140) });
    });
  }
  // still ones, in the dead ends and corners off the path
  const offPath = [];
  for (let y = 1; y < rows - 1; y += 1) {
    for (let x = 1; x < cols - 1; x += 1) {
      if (grid[y][x] === 1 || onPath.has(`${x},${y}`) || (x === 1 && y === 1)) continue;
      offPath.push([x, y]);
      if (!conf.staticReds) continue;
      const open = [[1, 0], [-1, 0], [0, 1], [0, -1]].filter(([dx, dy]) => grid[y + dy][x + dx] === 0).length;
      if ((open === 1 && Math.random() < 0.6) || Math.random() < conf.staticReds) reds.push({ x, y, blink: false });
    }
  }
  // green blocks: they heal (once each)
  const greens = [];
  const free = offPath.filter(([x, y]) => !reds.some((red) => red.x === x && red.y === y));
  for (let green = 0; green < conf.greens && free.length; green += 1) {
    const [x, y] = free.splice(Math.floor(Math.random() * free.length), 1)[0];
    greens.push({ x, y, taken: false });
  }
  // the chaser: it starts halfway along the path... and comes for you
  let chaser = null;
  if (conf.chaser) {
    const [cx, cy] = path[Math.floor(path.length * 0.55)] || goal;
    chaser = { x: cx, y: cy, drawX: cx, drawY: cy, startX: cx, startY: cy, timer: 60, speed: 26 };
  }
  Object.assign(abnormalGrid, {
    active: true,
    stage,
    conf,
    cols,
    rows,
    cell,
    x: Math.round(canvas.width / 2 - (cols * cell) / 2),
    y: conf.y,
    grid,
    goal,
    reds,
    greens,
    chaser,
    px: 1,
    py: 1,
    drawX: 1,
    drawY: 1,
    lastX: 1,
    lastY: 1,
    moveCd: 0,
    held: {},
    hurt: 0,
    shake: 0,
    frame: 0,
    intro: 80,
    won: 0,
    talk: null,
    healFx: 0,
    goldHeal: 0,
    visited: new Set(['1,1']),
    hits: 0,
    mrule: null,
    mruleT: 0,
    mruleCard: 0,
    mruleIndex: -1,
    slide: null,
  });
  resetKeys();
  playSound('judgeFinalStart');
}

// ---------- the rules of the maze (5th and 6th): Abnormal rewrites the box while you are inside ----------
const abnormalMazeRules = [
  { id: 'mirror', title: 'LOS CONTROLES ESTAN AL REVES', who: 'abn' },
  { id: 'reshuffle', title: 'LAS PAREDES SE BARAJAN', who: 'all' },
  { id: 'light', title: 'SE ENCIENDEN LAS LUCES (SIN NIEBLA)', who: 'chrono' },
  { id: 'slide', title: 'EL PISO ES DE HIELO (TE DESLIZAS HASTA CHOCAR)', who: 'all' },
  { id: 'goalMove', title: 'EL BLOQUE DORADO SE MUDA', who: 'abn' },
  { id: 'fast', title: 'EL RELOJITO CORRE EL DOBLE', who: 'chrono' },
  { id: 'redStorm', title: 'TORMENTA DE CUBOS ROJOS', who: 'abn' },
  { id: 'greenRain', title: 'LLUVIA DE CUBOS VERDES', who: 'chrono' },
  { id: 'dark', title: 'APAGON (CASI NO SE VE NADA)', who: 'abn' },
  { id: 'slow', title: 'EL RELOJITO ANDA EN CAMARA LENTA', who: 'abn' },
  { id: 'chaserNap', title: 'EL CUBO NEGRO SE TOMA UNA SIESTA', who: 'chrono', needsChaser: true },
  { id: 'chaserRage', title: 'EL CUBO NEGRO SE ENOJA (EL DOBLE DE RAPIDO)', who: 'abn', needsChaser: true },
];
const abnormalMazeRuleFrames = 300;

function abnormalMazeFreeCells(g, farFromPlayer = 0) {
  const { dist } = abnormalMazeDistances(g.grid, g.cols, g.rows, g.px, g.py);
  const cells = [];
  for (let y = 1; y < g.rows - 1; y += 1) {
    for (let x = 1; x < g.cols - 1; x += 1) {
      if (g.grid[y][x] === 1 || dist[y][x] < farFromPlayer) continue;
      if (x === g.px && y === g.py) continue;
      cells.push([x, y]);
    }
  }
  return { cells, dist };
}

function applyAbnormalMazeRule(g, rule) {
  g.mrule = rule;
  g.mruleT = 0;
  g.mruleCard = 90;
  g.slide = null;
  [440, 554, 659].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.12, type: 'square', volume: 0.04 }), index * 70));
  if (rule.id === 'reshuffle') {
    // a new maze, the same size; Chrono stays where he is, the golden block goes far away
    g.grid = generateAbnormalMaze(g.cols, g.rows, g.conf.loops);
    g.grid[g.py][g.px] = 0;
    if (g.px % 2 === 0 && g.py % 2 === 1) g.grid[g.py][g.px - 1] = 0;
    if (g.py % 2 === 0 && g.px % 2 === 1) g.grid[g.py - 1][g.px] = 0;
    if (g.px % 2 === 0 && g.py % 2 === 0) {
      g.grid[g.py][g.px - 1] = 0;
      g.grid[g.py][g.px - 1 - (g.px > 1 ? 1 : 0)] = 0;
    }
    const { cells, dist } = abnormalMazeFreeCells(g, 0);
    let goal = cells[0] || [1, 1];
    cells.forEach(([x, y]) => {
      if (dist[y][x] > dist[goal[1]][goal[0]]) goal = [x, y];
    });
    g.goal = goal;
    g.reds = g.reds.filter((red) => g.grid[red.y][red.x] === 0 && dist[red.y][red.x] > 0);
    g.greens = g.greens.filter((green) => g.grid[green.y][green.x] === 0 && dist[green.y][green.x] > 0);
    if (g.chaser && (g.grid[g.chaser.y][g.chaser.x] === 1 || dist[g.chaser.y][g.chaser.x] < 0)) {
      const far = cells.filter(([x, y]) => dist[y][x] > 8);
      const [cx, cy] = far[Math.floor(Math.random() * far.length)] || goal;
      Object.assign(g.chaser, { x: cx, y: cy, drawX: cx, drawY: cy, startX: cx, startY: cy });
    }
    g.visited = new Set([`${g.px},${g.py}`]);
    g.shake = 10;
    playNoise({ duration: 0.5, volume: 0.08, filterFrequency: 1200 });
  } else if (rule.id === 'goalMove') {
    const { cells, dist } = abnormalMazeFreeCells(g, 8);
    if (cells.length) {
      cells.sort((a, b) => dist[b[1]][b[0]] - dist[a[1]][a[0]]);
      g.goal = cells[Math.floor(Math.random() * Math.min(6, cells.length))];
    }
  } else if (rule.id === 'redStorm') {
    const { cells } = abnormalMazeFreeCells(g, 2);
    for (let red = 0; red < 8 && cells.length; red += 1) {
      const [x, y] = cells.splice(Math.floor(Math.random() * cells.length), 1)[0];
      if (x === g.goal[0] && y === g.goal[1]) continue;
      g.reds.push({ x, y, blink: true, phase: Math.floor(Math.random() * 140), storm: true });
    }
  } else if (rule.id === 'greenRain') {
    const { cells } = abnormalMazeFreeCells(g, 1);
    for (let green = 0; green < 4 && cells.length; green += 1) {
      const [x, y] = cells.splice(Math.floor(Math.random() * cells.length), 1)[0];
      g.greens.push({ x, y, taken: false });
    }
  }
}

function endAbnormalMazeRule(g) {
  const rule = g.mrule;
  if (!rule) return;
  // (the storm of reds goes away with its rule)
  if (rule.id === 'redStorm') g.reds = g.reds.filter((red) => !red.storm);
  g.slide = null;
}

function updateAbnormalMazeRules(g) {
  if (!g.conf.mazeRules || g.intro > 0 || g.won > 0 || g.talk) return;
  if (g.mruleCard > 0) g.mruleCard -= 1;
  g.mruleT += 1;
  if (!g.mrule || g.mruleT >= abnormalMazeRuleFrames) {
    endAbnormalMazeRule(g);
    let next = null;
    const list = g.stage === 6 ? abnormalMazeRules6 : abnormalMazeRules;
    for (let tries = 0; tries < list.length && !next; tries += 1) {
      g.mruleIndex = (g.mruleIndex + 1) % list.length;
      const candidate = list[g.mruleIndex];
      if (candidate.needsChaser && !g.chaser) continue;
      next = candidate;
    }
    applyAbnormalMazeRule(g, next);
  }
}

function getAbnormalMazeRuleId(g) {
  return g.conf.mazeRules && g.mrule ? g.mrule.id : null;
}

function drawAbnormalMazeRule(g, by) {
  if (!g.conf.mazeRules || !g.mrule) return;
  const rule = g.mrule;
  const color = rule.who === 'abn' ? '#90caf9' : rule.who === 'chrono' ? '#69f0ae' : '#ffd54f';
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(5, 10, 30, 0.85)';
  ctx.fillRect(canvas.width / 2 - 280, by - 92, 560, 40);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(canvas.width / 2 - 280, by - 92, 560, 40);
  ctx.fillStyle = color;
  ctx.font = '900 11px Courier New, monospace';
  ctx.fillText('REGLA DEL LABERINTO', canvas.width / 2, by - 78);
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 14px Courier New, monospace';
  ctx.fillText(rule.title, canvas.width / 2, by - 61);
  ctx.fillStyle = color;
  ctx.fillRect(canvas.width / 2 - 280, by - 54, 560 * Math.max(0, 1 - g.mruleT / abnormalMazeRuleFrames), 2);
  if (g.mruleCard > 0) {
    ctx.globalAlpha = Math.min(1, g.mruleCard / 20);
    ctx.font = '900 26px Courier New, monospace';
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#000';
    ctx.strokeText(rule.title, canvas.width / 2, by + (g.rows * g.cell) / 2);
    ctx.fillStyle = color;
    ctx.fillText(rule.title, canvas.width / 2, by + (g.rows * g.cell) / 2);
  }
  ctx.restore();
}

function isAbnormalRedOn(red, frame) {
  if (!red.blink) return true;
  return (frame + red.phase) % 140 < 70;
}

function isAbnormalRedWarning(red, frame) {
  if (!red.blink) return false;
  const t = (frame + red.phase) % 140;
  return t >= 140 - 28;
}

function hurtAbnormalGrid(ratio) {
  const g = abnormalGrid;
  const damage = Math.max(4, player1.health * ratio);
  player1.health = Math.max(1, player1.health - damage);
  g.hurt = 50;
  g.shake = 12;
  g.hits += 1;
  playSound('judgeFinalHurt');
  updateHealthBars();
}

function finishAbnormalGrid() {
  const stage = abnormalGrid.stage;
  abnormalGrid.active = false;
  if (stage >= 6) chronoCh.secretBox3Done = true;
  else if (stage >= 4) chronoCh.secretBox2Done = true;
  else chronoCh.secretBoxDone = true;
  [player1, player2].forEach((fighter) => {
    fighter.velocity.x = 0;
    fighter.velocity.y = 0;
    fighter.isAttacking = false;
    fighter.position.y = ground - fighter.height;
  });
  player1.position.x = 220;
  player2.position.x = 700;
  resetKeys();
  jesterWhiteFade = 30;
  showFlametombThought(player2, stage >= 6 ? '¡¿NI CON LAS REGLAS?! ...Bien. Volvamos a las reglas de AFUERA.' : stage >= 4 ? '¡¿TAMBIEN ESE?! ...Ya veras. YA VERAS.' : '¡¿OTRA VEZ?! ...¡Muy bien! ¡A la antigua!');
  // (after the maze, a new rule outside right away)
  if (stage >= 6 && chronoRuleState.active) chronoRuleState.t = 99999;
  updateHealthBars();
}

// (the chaser takes the shortest way to Chrono, one square at a time)
function stepAbnormalChaser(g) {
  const c = g.chaser;
  const { prev } = abnormalMazeDistances(g.grid, g.cols, g.rows, g.px, g.py);
  const back = prev[c.y][c.x];
  if (back) {
    c.x = back[0];
    c.y = back[1];
  }
}

function updateAbnormalGrid() {
  const g = abnormalGrid;
  g.frame += 1;
  if (g.intro > 0) g.intro -= 1;
  if (g.hurt > 0) g.hurt -= 1;
  if (g.healFx > 0) g.healFx -= 1;
  g.shake *= 0.85;
  if (g.talk) {
    g.talk.t += 1;
    if (g.talk.t > 150) {
      g.talk = null;
      startAbnormalGrid(g.stage + 1);
      return;
    }
  } else if (g.won > 0) {
    g.won += 1;
    if (g.won > 70) {
      if (g.stage === 1 || g.stage === 3 || g.stage === 5) {
        g.talk = {
          t: 0,
          text: g.stage === 1 ? '¿Lo... lo encontraste? ¡IMPOSIBLE! ¡Fue suerte! ¡SEGUNDO NIVEL!' : g.stage === 3 ? '¡¿OTRA VEZ?! ¡NIVEL CUATRO! ¡Y esta vez... ALGUIEN te va a perseguir!' : '¡NIVEL SEIS! ¡Ahora las reglas cambian LA CAJA MISMA! ¡JO JO JO!',
        };
        playSound('judgeFinalStart');
      } else {
        finishAbnormalGrid();
        return;
      }
    }
  } else if (g.intro <= 0) {
    // one square at a time: up, down and to the sides
    const dirs = [['w', 0, -1], ['ArrowUp', 0, -1], ['s', 0, 1], ['ArrowDown', 0, 1], ['a', -1, 0], ['ArrowLeft', -1, 0], ['d', 1, 0], ['ArrowRight', 1, 0]];
    updateAbnormalMazeRules(g);
    const mrule = getAbnormalMazeRuleId(g);
    updateAbnormalMazeChaos(g, mrule);
    if (g.moveCd > 0) g.moveCd -= 1;
    let moved = false;
    // ice: sliding until a wall
    if (g.slide) {
      if (g.moveCd <= 0) {
        const nx = g.px + g.slide.dx;
        const ny = g.py + g.slide.dy;
        if (nx < 0 || ny < 0 || nx >= g.cols || ny >= g.rows || g.grid[ny][nx] === 1) {
          g.slide = null;
        } else {
          g.lastX = g.px;
          g.lastY = g.py;
          g.px = nx;
          g.py = ny;
          g.visited.add(`${nx},${ny}`);
          g.moveCd = 4;
          playTone({ frequency: 900, duration: 0.03, type: 'sine', volume: 0.02 });
        }
      }
      moved = true;
    }
    dirs.forEach(([key, baseDx, baseDy]) => {
      const down = Boolean(keys[key]);
      const fresh = down && !g.held[key];
      g.held[key] = down;
      if (moved || !down || (!fresh && g.moveCd > 0)) return;
      const dx = mrule === 'mirror' ? -baseDx : baseDx;
      const dy = mrule === 'mirror' ? -baseDy : baseDy;
      const nx = g.px + dx;
      const ny = g.py + dy;
      if (nx < 0 || ny < 0 || nx >= g.cols || ny >= g.rows || g.grid[ny][nx] === 1) {
        if (fresh) playTone({ frequency: 120, duration: 0.05, type: 'square', volume: 0.03 });
        // (the red walls hurt)
        if (fresh && mrule === 'wallsRed' && g.hurt === 0) hurtAbnormalGrid(0.08);
        return;
      }
      g.lastX = g.px;
      g.lastY = g.py;
      g.px = nx;
      g.py = ny;
      g.visited.add(`${nx},${ny}`);
      g.moveCd = mrule === 'fast' ? (fresh ? 6 : 4) : mrule === 'slow' ? (fresh ? 22 : 18) : fresh ? 12 : 8;
      if (mrule === 'slide') {
        g.slide = { dx, dy };
        g.moveCd = 4;
      }
      moved = true;
      playTone({ frequency: 520 + (g.px + g.py) * 6, duration: 0.04, type: 'triangle', volume: 0.025 });
    });
    // red blocks hurt (and throw you back a square)
    const red = g.reds.find((block) => block.x === g.px && block.y === g.py && isAbnormalRedOn(block, g.frame));
    if (red && g.hurt === 0) {
      hurtAbnormalGrid(g.conf.redDamage);
      g.px = g.lastX;
      g.py = g.lastY;
    }
    // green blocks heal
    const green = g.greens.find((block) => !block.taken && block.x === g.px && block.y === g.py);
    if (green && getAbnormalMazeRuleId(g) === 'greensBad') {
      green.taken = true;
      hurtAbnormalGrid(0.12);
    } else if (green) {
      green.taken = true;
      const heal = Math.round(player1.maxHealth * 0.12);
      player1.health = Math.min(player1.maxHealth, player1.health + heal);
      g.healFx = 50;
      playTone({ frequency: 660, duration: 0.3, type: 'triangle', volume: 0.05, slideTo: 990 });
      updateHealthBars();
    }
    // the chaser: faster and faster
    if (g.chaser) {
      const c = g.chaser;
      c.timer -= 1;
      if (mrule === 'chaserNap') c.timer = Math.max(c.timer, 2);
      if (c.timer <= 0) {
        stepAbnormalChaser(g);
        c.speed = Math.max(13, c.speed - 0.35);
        c.timer = mrule === 'chaserRage' ? c.speed / 2 : c.speed;
      }
      if (c.x === g.px && c.y === g.py && g.hurt === 0) {
        hurtAbnormalGrid(0.15);
        // it goes back to where it started, and waits a moment
        c.x = c.startX;
        c.y = c.startY;
        c.timer = 70;
      }
      c.drawX += (c.x - c.drawX) * 0.3;
      c.drawY += (c.y - c.drawY) * 0.3;
    }
    if (g.px === g.goal[0] && g.py === g.goal[1]) {
      g.won = 1;
      // the golden block gives back 80% of the health
      const before = player1.health;
      player1.health = Math.min(player1.maxHealth, player1.health + player1.maxHealth * 0.8);
      g.goldHeal = Math.round(player1.health - before);
      g.healFx = 60;
      updateHealthBars();
      playSound('achievement');
    }
  }
  g.drawX += (g.px - g.drawX) * 0.35;
  g.drawY += (g.py - g.drawY) * 0.35;
  drawAbnormalGrid();
}

function drawAbnormalGrid() {
  const g = abnormalGrid;
  const time = performance.now() / 1000;
  ctx.save();
  ctx.translate((Math.random() - 0.5) * g.shake, (Math.random() - 0.5) * g.shake);
  drawStage();
  ctx.fillStyle = 'rgba(2, 4, 16, 0.78)';
  ctx.fillRect(-20, -20, canvas.width + 40, canvas.height + 40);
  // Abnormal, watching from the side, very pleased with himself
  const saved = { ...player2.position };
  player2.position = { x: canvas.width - 110, y: ground - player2.height };
  player2.attacksToTheRight = false;
  player2.isAttacking = false;
  player2.draw();
  player2.position = saved;
  const { x: bx, y: by, cell, cols, rows } = g;
  const w = cols * cell;
  const h = rows * cell;
  const chaosRule = getAbnormalMazeRuleId(g);
  const tf = getAbnormalBoxTransform(g, chaosRule);
  ctx.save();
  ctx.translate(tf.cx + tf.dx, tf.cy + tf.dy);
  ctx.rotate(tf.rot);
  ctx.scale(tf.sx, tf.sy);
  ctx.translate(-tf.cx, -tf.cy);
  ctx.fillStyle = '#050a1e';
  ctx.fillRect(bx, by, w, h);
  ctx.strokeStyle = g.stage >= 3 ? '#ff8a80' : '#e3f2fd';
  ctx.lineWidth = 4;
  ctx.shadowColor = g.stage >= 3 ? '#e53935' : '#90caf9';
  ctx.shadowBlur = 12;
  ctx.strokeRect(bx - 4, by - 4, w + 8, h + 8);
  ctx.shadowBlur = 0;
  abnormalSuits.forEach((suit, index) => {
    const cx = index % 2 ? bx + w + 4 : bx - 4;
    const cy = index > 1 ? by + h + 4 : by - 4;
    drawAbnormalSuit(suit, cx, cy, 12, abnormalSuitColors[suit]);
  });
  for (let row = 0; row < rows; row += 1) {
    for (let col = 0; col < cols; col += 1) {
      if (g.grid[row][col] !== 1) continue;
      const cx = bx + col * cell;
      const cy = by + row * cell;
      ctx.fillStyle = chaosRule === 'wallsRed' ? '#8e1b1b' : '#123a8c';
      ctx.fillRect(cx + 2, cy + 2, cell - 4, cell - 4);
      ctx.strokeStyle = '#e3f2fd';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(cx + 2, cy + 2, cell - 4, cell - 4);
      if ((row * 7 + col * 3) % 5 === 0) drawAbnormalSuit(abnormalSuits[(row + col) % 4], cx + cell / 2, cy + cell / 2, cell * 0.18, 'rgba(227, 242, 253, 0.6)');
    }
  }
  g.reds.forEach((red) => {
    const cx = bx + red.x * cell;
    const cy = by + red.y * cell;
    if (isAbnormalRedOn(red, g.frame)) {
      ctx.fillStyle = `rgba(229, 57, 53, ${0.85 + Math.sin(time * 10) * 0.15})`;
      ctx.fillRect(cx + 4, cy + 4, cell - 8, cell - 8);
      ctx.strokeStyle = '#ffcdd2';
      ctx.lineWidth = 2;
      ctx.strokeRect(cx + 4, cy + 4, cell - 8, cell - 8);
      drawAbnormalSuit('heart', cx + cell / 2, cy + cell / 2, cell * 0.2, '#ffffff');
    } else {
      ctx.strokeStyle = isAbnormalRedWarning(red, g.frame) ? `rgba(255, 82, 82, ${0.5 + Math.sin(time * 30) * 0.4})` : 'rgba(229, 57, 53, 0.25)';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 4]);
      ctx.strokeRect(cx + 6, cy + 6, cell - 12, cell - 12);
      ctx.setLineDash([]);
    }
  });
  // green blocks (healing)
  g.greens.forEach((green) => {
    if (green.taken) return;
    const cx = bx + green.x * cell;
    const cy = by + green.y * cell;
    ctx.save();
    ctx.shadowColor = '#69f0ae';
    ctx.shadowBlur = 12 + Math.sin(time * 5) * 4;
    ctx.fillStyle = '#43a047';
    ctx.fillRect(cx + 6, cy + 6, cell - 12, cell - 12);
    ctx.restore();
    ctx.fillStyle = '#e8f5e9';
    ctx.fillRect(cx + cell / 2 - 2, cy + 10, 4, cell - 20);
    ctx.fillRect(cx + 10, cy + cell / 2 - 2, cell - 20, 4);
  });
  // the golden block
  const gx = bx + g.goal[0] * cell;
  const gy = by + g.goal[1] * cell;
  ctx.save();
  ctx.shadowColor = '#ffd54f';
  ctx.shadowBlur = 16 + Math.sin(time * 5) * 6;
  ctx.fillStyle = '#ffd54f';
  ctx.fillRect(gx + 5, gy + 5, cell - 10, cell - 10);
  ctx.restore();
  ctx.fillStyle = '#fff8e1';
  ctx.font = `900 ${Math.round(cell * 0.45)}px Courier New, monospace`;
  ctx.textAlign = 'center';
  ctx.fillText('★', gx + cell / 2, gy + cell * 0.65);
  ctx.textAlign = 'left';
  // the fog
  const mruleDraw = getAbnormalMazeRuleId(g);
  const radius = mruleDraw === 'light' ? 99 : mruleDraw === 'dark' ? 1.7 : g.conf.fog;
  for (let row = 0; row < rows; row += 1) {
    for (let col = 0; col < cols; col += 1) {
      const distance = Math.hypot(col - g.drawX, row - g.drawY);
      if (distance <= radius - 1) continue;
      const fog = Math.min(1, (distance - (radius - 1)) / 1.2);
      const seen = g.visited.has(`${col},${row}`);
      ctx.fillStyle = `rgba(0, 0, 0, ${fog * (seen ? 0.55 : 0.94)})`;
      ctx.fillRect(bx + col * cell, by + row * cell, cell, cell);
    }
  }
  // the chaser: a black card with a red eye (it can be seen through the fog)
  if (g.chaser) {
    const c = g.chaser;
    const cx = bx + c.drawX * cell + cell / 2;
    const cy = by + c.drawY * cell + cell / 2;
    const size = cell * 0.7;
    ctx.save();
    ctx.shadowColor = '#ff1744';
    ctx.shadowBlur = 16;
    ctx.fillStyle = '#0a0a0f';
    ctx.fillRect(cx - size / 2, cy - size / 2, size, size);
    ctx.strokeStyle = '#ff5252';
    ctx.lineWidth = 2;
    ctx.strokeRect(cx - size / 2, cy - size / 2, size, size);
    ctx.fillStyle = '#ff1744';
    ctx.beginPath();
    ctx.ellipse(cx, cy, size * 0.25, size * 0.12 + Math.abs(Math.sin(time * 4)) * 2, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }
  // Chrono (a little one)
  if (!(g.hurt > 0 && Math.floor(g.hurt / 4) % 2 === 0)) {
    const sx = bx + g.drawX * cell + cell / 2;
    const sy = by + g.drawY * cell + cell / 2;
    const size = cell * 0.62;
    if (g.healFx > 0) {
      ctx.fillStyle = `rgba(105, 240, 174, ${g.healFx / 60})`;
      ctx.beginPath();
      ctx.arc(sx, sy, size, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = '#448aff';
    ctx.fillRect(sx - size / 2, sy - size / 2, size, size);
    ctx.fillStyle = '#05070d';
    ctx.fillRect(sx - size / 2 + 3, sy - size / 2 + 3, size - 6, size * 0.28);
    ctx.fillStyle = '#26c6da';
    ctx.fillRect(sx - size * 0.28, sy - size / 2 + 5, 3, 3);
    ctx.fillRect(sx + size * 0.18, sy - size / 2 + 5, 3, 3);
    ctx.fillStyle = '#e0f7fa';
    ctx.beginPath();
    ctx.arc(sx, sy + size * 0.12, size * 0.2, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  ctx.textAlign = 'center';
  ctx.font = '900 22px Courier New, monospace';
  ctx.lineWidth = 5;
  ctx.strokeStyle = '#000';
  const titles = { 1: 'EL LABERINTO DISTINGUIDO', 2: '¡SEGUNDO NIVEL!', 3: '¡NIVEL TRES!', 4: '¡NIVEL CUATRO!', 5: '¡NIVEL CINCO!', 6: '¡NIVEL SEIS!' };
  drawAbnormalMazeRule(g, by);
  ctx.fillStyle = g.stage === 1 ? '#90caf9' : g.stage >= 5 ? '#ea80fc' : g.stage === 4 ? '#ff1744' : '#ff8a80';
  ctx.strokeText(titles[g.stage], canvas.width / 2, by - 22);
  ctx.fillText(titles[g.stage], canvas.width / 2, by - 22);
  ctx.font = '900 13px Courier New, monospace';
  ctx.fillStyle = '#ffffff';
  const helps = {
    1: 'encontra el bloque dorado - W A S D / flechas, de a un casillero',
    2: 'el bloque dorado otra vez... y cuidado con los bloques ROJOS',
    3: 'los ROJOS pegan mas fuerte... los VERDES curan',
    4: '¡RAPIDO! el cubo negro te persigue: llega al bloque dorado',
    5: 'las reglas cambian cada 5 segundos... ¡y el cubo negro te persigue!',
    6: '¡ahora las reglas cambian LA CAJA MISMA!',
  };
  ctx.fillText(helps[g.stage], canvas.width / 2, by + h + 26);
  if (g.won > 0 && !g.talk) {
    ctx.font = '900 30px Courier New, monospace';
    ctx.fillStyle = '#ffd54f';
    ctx.strokeText('¡BLOQUE DORADO!', canvas.width / 2, by + h / 2);
    ctx.fillText('¡BLOQUE DORADO!', canvas.width / 2, by + h / 2);
    if (g.goldHeal > 0) {
      ctx.font = '900 20px Courier New, monospace';
      ctx.fillStyle = '#69f0ae';
      ctx.strokeText(`+${g.goldHeal} VIDA`, canvas.width / 2, by + h / 2 + 30);
      ctx.fillText(`+${g.goldHeal} VIDA`, canvas.width / 2, by + h / 2 + 30);
    }
  }
  if (g.talk) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.85)';
    ctx.fillRect(80, by + h / 2 - 50, canvas.width - 160, 90);
    ctx.strokeStyle = '#90caf9';
    ctx.lineWidth = 3;
    ctx.strokeRect(80, by + h / 2 - 50, canvas.width - 160, 90);
    ctx.fillStyle = '#90caf9';
    ctx.font = '900 14px Courier New, monospace';
    ctx.fillText('ABNORMAL', canvas.width / 2, by + h / 2 - 24);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 17px Courier New, monospace';
    ctx.fillText(g.talk.text.slice(0, Math.floor(g.talk.t * 1.6)), canvas.width / 2, by + h / 2 + 8);
  }
  ctx.textAlign = 'left';
  ctx.restore();
}

// ================= RULE MANIPULATION: Abnormal writes the rules of the fight =================
const chronoRuleFrames = 480;

function rollChronoRuleFrames() {
  return 360 + Math.floor(Math.random() * 121);
}
const chronoRules = [
  { id: 'abnHalf', title: 'EL GUARDIA SUPREMO RECIBE LA MITAD DE DAÑO', who: 'abn', comment: 'Distinguidamente justo.' },
  { id: 'vampire', title: 'EL RELOJITO ROBA VIDA (COMO SCAMMER) - HASTA EL FINAL', who: 'chrono', comment: 'Un poquito de vida. Y esta regla... se queda. Distinguidamente.' },
  { id: 'chronoDouble', title: 'EL RELOJITO PEGA EL DOBLE', who: 'chrono', comment: 'Por cortesia. No te acostumbres.' },
  { id: 'lowGravity', title: 'LA GRAVEDAD ES OPCIONAL', who: 'all', comment: '¡JO JO! ¡Saltos elegantes!' },
  { id: 'oops', title: 'LOS GOLPES DE ABNORMAL CURAN AL RELOJITO', who: 'chrono', comment: '¡¿QUE?! ¡NO! ¡ME EQUIVOQUE AL ESCRIBIRLA!' },
  { id: 'abnSpeed', title: 'ABNORMAL ES 60% MAS RAPIDO', who: 'abn', comment: '¡Velocidad DISTINGUIDA!' },
  { id: 'luck', title: 'ABNORMAL TIENE LA SUERTE DE GAMBLER (A VECES ESQUIVA)', who: 'abn', comment: '¡La casa siempre gana! ...¿Asi se dice?' },
  { id: 'fireFists', title: 'LOS GOLPES DEL RELOJITO QUEMAN (COMO FIRE MASTER)', who: 'chrono', comment: '¡Ay! ¡AY! ¡¿Quien escribio esa?! ...Yo.' },
  { id: 'giant', title: 'ABNORMAL ES GIGANTE (Y PEGA MAS FUERTE)', who: 'abn', comment: '¡Contemplad mi magnificencia!' },
  { id: 'hats', title: 'TODOS LLEVAN SOMBRERO DE FIESTA', who: 'all', comment: 'Porque si. Las reglas son las reglas.' },
  { id: 'teleport', title: 'ABNORMAL SE TELETRANSPORTA (COMO SHADOW JESTER)', who: 'abn', comment: '¡Ahora me ves! ¡Ahora... tambien me ves, pero en otro lado!' },
  { id: 'smallArena', title: 'LA PISTA ES MAS CHICA', who: 'all', comment: '¡Sin escapatoria, relojito!' },
  { id: 'kaioken', title: 'EL RELOJITO USA KAIOKEN (COMO NORMAL): MAS FUERTE, PERO LE CUESTA VIDA', who: 'chrono', comment: '¡Un poder prestado! ¡Cuidado, que quema!' },
  { id: 'adapt', title: 'ABNORMAL SE ADAPTA (COMO DIVINE GENERAL): CADA GOLPE DUELE MENOS', who: 'abn', comment: 'Disculpe, General. Se la tome prestada.' },
  { id: 'noJump', title: 'PROHIBIDO SALTAR (SOLO PARA EL RELOJITO)', who: 'abn', comment: '¡Los pies en el suelo, como un caballero!' },
  { id: 'statsUp', title: 'TODOS LOS STATS DEL RELOJITO +50%', who: 'chrono', comment: 'Para que me sigas el ritmo. Distinguido de mi parte.' },
  { id: 'stillHeal', title: 'QUIEN SE QUEDE QUIETO, SE CURA', who: 'all', comment: '¡Pero yo NUNCA me quedo quieto! ¡JO JO!' },
];
const chronoRuleState = { active: false, index: -1, t: 0, card: 0, number: 0 };

function startChronoRules() {
  Object.assign(chronoRuleState, { active: true, index: -1, t: chronoRuleFrames, duration: chronoRuleFrames, card: 0, number: 0 });
}

function getChronoRuleList() {
  return chronoRuleState.powers ? chronoPowers : chronoRules;
}

function getChronoRule() {
  return chronoRuleState.active && chronoRuleState.index >= 0 ? getChronoRuleList()[chronoRuleState.index] : null;
}

function endChronoRule(rule) {
  if (!rule) return;
  if (chronoRuleState.powers) endChronoPower(rule);
  if (rule.id === 'giant') {
    player2.giantScale = 1;
    player2.damageMultiplier = 1.15;
  }
  const base = chronoRuleState.base;
  if (base) {
    player1.moveSpeed = base.p1;
    player2.moveSpeed = base.p2;
  }
}

function applyChronoRule(rule) {
  // (stealing life is permanent: once written, it stays until the end of the fight)
  if (rule.id === 'vampire') chronoCh.vampireForever = true;
  chronoRuleState.base = { p1: player1.moveSpeed, p2: player2.moveSpeed };
  if (chronoRuleState.powers) applyChronoPower(rule);
  chronoRuleState.adaptHits = 0;
  if (rule.id === 'abnSpeed') player2.moveSpeed *= 1.6;
  if (rule.id === 'kaioken') player1.moveSpeed *= 1.3;
  if (rule.id === 'statsUp') player1.moveSpeed *= 1.5;
  if (rule.id === 'giant') {
    player2.giantScale = 1.7;
    player2.damageMultiplier = 1.15 * 1.3;
  }
  chronoRuleState.card = 130;
  chronoRuleState.number += 1;
  // every new rule he writes... gives him back a little health
  if (isChronoSecretFight() && player2.health > 0) {
    const heal = 100;
    player2.health = Math.min(player2.maxHealth, player2.health + heal);
    showScamLabel(player2, `+${heal}`);
    updateHealthBars();
  }
  showFlametombThought(player2, rule.comment);
  [392, 523, 659].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.14, type: 'square', volume: 0.05 }), index * 90));
}

function updateChronoRules() {
  const state = chronoRuleState;
  if (!state.active) return;
  state.t += 1;
  if (state.card > 0) state.card -= 1;
  if (state.t >= (state.duration || chronoRuleFrames)) {
    endChronoRule(getChronoRule());
    const list = getChronoRuleList();
    state.index = (state.index + 1) % list.length;
    // (already permanent: skip it)
    if (list[state.index].id === 'vampire' && chronoCh.vampireForever) state.index = (state.index + 1) % list.length;
    if (list[state.index].id === 'hp999' && chronoCh.hp999Forever) state.index = (state.index + 1) % list.length;
    state.t = 0;
    state.duration = rollChronoRuleFrames();
    applyChronoRule(list[state.index]);
    const newRule = getChronoRule();
    if (newRule && newRule.id === 'mapShuffle') state.duration = 1200;
    if (newRule && newRule.id === 'menuMap') state.duration = 1e9;
  }
  const rule = getChronoRule();
  if (!rule) return;
  if (state.powers) {
    updateChronoPower(rule, state);
    return;
  }
  if (rule.id === 'lowGravity') {
    // half the gravity for everyone
    [player1, player2].forEach((fighter) => {
      if (fighter.position.y + fighter.height < ground - 1) fighter.velocity.y -= gravity * 0.5;
    });
  } else if (rule.id === 'smallArena') {
    [player1, player2].forEach((fighter) => {
      fighter.position.x = Math.max(210, Math.min(canvas.width - 210 - fighter.width, fighter.position.x));
    });
  } else if (rule.id === 'teleport') {
    // every second and a half: to the other side of Chrono, in a puff of cards
    if (state.t % 90 === 45 && canFighterAct(player2)) {
      const side = getFighterCenterX(player2) > getFighterCenterX(player1) ? -1 : 1;
      player2.position.x = Math.max(20, Math.min(canvas.width - 20 - player2.width, getFighterCenterX(player1) + side * 140 - player2.width / 2));
      player2.attacksToTheRight = side < 0;
      state.poof = { x: getFighterCenterX(player2), y: player2.position.y + player2.height / 2, t: 20 };
      playNoise({ duration: 0.2, volume: 0.06, filterFrequency: 4000 });
    }
  } else if (rule.id === 'kaioken') {
    // the power costs health (never the last bit)
    if (player1.health > 20) player1.health -= 0.05;
    if (state.t % 10 === 0) updateHealthBars();
  } else if (rule.id === 'noJump') {
    if (player1.velocity.y < 0) player1.velocity.y = 0;
  } else if (rule.id === 'stillHeal') {
    [player1, player2].forEach((fighter) => {
      const still = Math.abs(fighter.velocity.x) < 0.2 && !fighter.isAttacking && fighter.position.y + fighter.height >= ground - 1;
      if (still && fighter.health > 0) fighter.health = Math.min(fighter.maxHealth, fighter.health + 0.12);
    });
    if (state.t % 10 === 0) updateHealthBars();
  }
}

// (applyDamage asks this while a rule is on)
function chronoRuleDamageScale(attacker, target) {
  if (!isChronoSecretFight()) return 1;
  // the permanent rule: every hit of Chrono's heals him
  if (chronoCh.vampireForever && attacker === player1 && target === player2) {
    player1.health = Math.min(player1.maxHealth, player1.health + 5);
    showScamLabel(player1, '+5');
  }
  const rule = getChronoRule();
  if (!rule) return 1;
  if (rule.id === 'abnHalf' && target === player2) return 0.5;
  if (rule.id === 'chronoDouble' && attacker === player1) return 2;
  if (rule.id === 'cardShield' && target === player1) return 0.5;
  if (rule.id === 'luck' && target === player2 && Math.random() < 0.35) {
    showScamLabel(player2, '¡ESQUIVADO!');
    return 0;
  }
  if (rule.id === 'fireFists' && attacker === player1 && target === player2) {
    chronoRuleState.burn = 30;
    return 1.5;
  }
  if (rule.id === 'kaioken' && attacker === player1) return 1.6;
  if (rule.id === 'statsUp') {
    if (attacker === player1) return 1.5;
    if (target === player1) return 0.67;
  }
  if (rule.id === 'adapt' && target === player2) {
    chronoRuleState.adaptHits = (chronoRuleState.adaptHits || 0) + 1;
    return Math.max(0.3, 1 - chronoRuleState.adaptHits * 0.12);
  }
  if (rule.id === 'oops' && attacker === player2 && target === player1) {
    player1.health = Math.min(player1.maxHealth, player1.health + 6);
    showScamLabel(player1, '+6');
    return 0;
  }
  return 1;
}

function drawChronoRuleExtras(rule, state) {
  const time = performance.now() / 1000;
  if (rule.id === 'hats') {
    [player1, player2].forEach((fighter, index) => {
      const scale = fighter.giantScale || 1;
      const cx = fighter.position.x + fighter.width / 2;
      const top = fighter.position.y + fighter.height - fighter.height * scale;
      ctx.fillStyle = index ? '#ff4081' : '#ffd54f';
      ctx.beginPath();
      ctx.moveTo(cx - 16 * scale, top + 2);
      ctx.lineTo(cx, top - 40 * scale);
      ctx.lineTo(cx + 16 * scale, top + 2);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(cx, top - 40 * scale, 5 * scale, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = index ? '#ffd54f' : '#40c4ff';
      for (let dot = 0; dot < 3; dot += 1) ctx.fillRect(cx - 6 * scale + dot * 5 * scale, top - 12 * scale - dot * 9 * scale, 3 * scale, 3 * scale);
    });
  }
  if (rule.id === 'kaioken') {
    const cx = player1.position.x + player1.width / 2;
    const glow = ctx.createRadialGradient(cx, player1.position.y + 60, 10, cx, player1.position.y + 60, 90);
    glow.addColorStop(0, `rgba(255, 23, 68, ${0.35 + Math.sin(time * 14) * 0.1})`);
    glow.addColorStop(1, 'rgba(255, 23, 68, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(cx - 90, player1.position.y - 30, 180, 180);
  }
  if (rule.id === 'fireFists') {
    for (let flame = 0; flame < 5; flame += 1) {
      const fx = player1.position.x + (player1.attacksToTheRight ? player1.width : 0) + (Math.random() - 0.5) * 14;
      const fy = player1.position.y + 50 - Math.random() * 20;
      ctx.fillStyle = flame % 2 ? '#ff9100' : '#ffea00';
      ctx.fillRect(fx, fy, 4, 6);
    }
    if (state.burn > 0) {
      state.burn -= 1;
      for (let flame = 0; flame < 6; flame += 1) {
        ctx.fillStyle = flame % 2 ? '#ff3d00' : '#ffab00';
        ctx.fillRect(player2.position.x + Math.random() * player2.width, player2.position.y + Math.random() * player2.height, 5, 7);
      }
    }
  }
  if (rule.id === 'adapt') {
    ctx.strokeStyle = 'rgba(255, 235, 59, 0.6)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.ellipse(player2.position.x + player2.width / 2, player2.position.y + player2.height / 2, player2.width * 0.8, player2.height * 0.5, 0, 0, Math.PI * 2);
    ctx.stroke();
  }
  if (state.poof && state.poof.t > 0) {
    state.poof.t -= 1;
    for (let card = 0; card < 8; card += 1) {
      const a = (card / 8) * Math.PI * 2;
      const d = (20 - state.poof.t) * 4;
      drawAbnormalSuit(abnormalSuits[card % 4], state.poof.x + Math.cos(a) * d, state.poof.y + Math.sin(a) * d, 7, abnormalSuitColors[abnormalSuits[card % 4]]);
    }
  }
}

// the FINAL RULE: the fight does not end until he decides it
const chronoFinalRuleHits = 100;
const chronoFinalRuleQuips = ['¡No cuenta!', '¡Eso no lo decidi yo!', 'Todavia no...', '¡REGLA FINAL! ¡REGLA FINAL!', '¡Ese golpe fue... ilegal!', 'Jo... jo... no siento nada...', '¡Cuando YO diga!', '¡Un Guardia Supremo no cae sin permiso!'];

function chronoFinalRuleHit() {
  if (!chronoCh.finalRule || chronoCh.abnDecided) return;
  chronoCh.finalHits = (chronoCh.finalHits || 0) + 1;
  showFlametombThought(player2, chronoFinalRuleQuips[chronoCh.finalHits % chronoFinalRuleQuips.length]);
  if (chronoCh.finalHits >= chronoFinalRuleHits) chronoCh.abnDecided = true;
}

function drawChronoFinalRule() {
  if (!chronoCh.finalRule) return;
  const left = Math.max(0, 1 - (chronoCh.finalHits || 0) / chronoFinalRuleHits);
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(40, 0, 10, 0.85)';
  ctx.fillRect(canvas.width / 2 - 300, 164, 600, 40);
  ctx.strokeStyle = '#ff5252';
  ctx.lineWidth = 2;
  ctx.strokeRect(canvas.width / 2 - 300, 164, 600, 40);
  ctx.fillStyle = '#ff8a80';
  ctx.font = '900 13px Courier New, monospace';
  ctx.fillText('REGLA FINAL: LA PELEA NO TERMINA HASTA QUE ABNORMAL LO DECIDA', canvas.width / 2, 181);
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 11px Courier New, monospace';
  ctx.fillText('PACIENCIA DE ABNORMAL', canvas.width / 2 - 200, 197);
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(canvas.width / 2 - 120, 190, 400, 8);
  ctx.fillStyle = '#ff5252';
  ctx.fillRect(canvas.width / 2 - 120, 190, 400 * left, 8);
  ctx.restore();
}

function drawChronoRules() {
  drawChronoFinalRule();
  if (chronoCh.vampireForever) {
    ctx.save();
    ctx.textAlign = 'left';
    ctx.fillStyle = 'rgba(0, 30, 10, 0.8)';
    ctx.fillRect(16, 112, 196, 22);
    ctx.strokeStyle = '#69f0ae';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(16, 112, 196, 22);
    ctx.fillStyle = '#69f0ae';
    ctx.font = '900 11px Courier New, monospace';
    ctx.fillText('REGLA FIJA: ROBO DE VIDA', 26, 127);
    ctx.restore();
  }
  const state = chronoRuleState;
  const rule = getChronoRule();
  if (!rule) return;
  drawChronoRuleExtras(rule, state);
  if (state.powers) drawChronoPowerExtras(rule);
  const time = performance.now() / 1000;
  const color = rule.who === 'abn' ? '#90caf9' : rule.who === 'chrono' ? '#69f0ae' : '#ffd54f';
  const whoText = rule.who === 'abn' ? 'A FAVOR DE ABNORMAL' : rule.who === 'chrono' ? 'A FAVOR DEL RELOJITO' : 'PARA TODOS';
  // the narrow arena: curtains closing in
  if (rule.id === 'smallArena') {
    ctx.fillStyle = 'rgba(13, 22, 64, 0.92)';
    ctx.fillRect(0, 0, 205, ground);
    ctx.fillRect(canvas.width - 205, 0, 205, ground);
    ctx.fillStyle = '#e3f2fd';
    ctx.fillRect(203, 0, 3, ground);
    ctx.fillRect(canvas.width - 206, 0, 3, ground);
  }
  // the active rule, always on top
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(5, 10, 30, 0.8)';
  ctx.fillRect(canvas.width / 2 - 300, 112, 600, 46);
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(canvas.width / 2 - 300, 112, 600, 46);
  ctx.fillStyle = color;
  ctx.font = '900 12px Courier New, monospace';
  ctx.fillText(state.powers ? `PODER DE ABNORMAL - CAMBIO ${state.number} (${whoText})` : `MANIPULACION DE REGLAS - REGLA ${state.number} (${whoText})`, canvas.width / 2, 128);
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 14px Courier New, monospace';
  ctx.fillText(rule.title, canvas.width / 2, 147);
  ctx.fillStyle = color;
  ctx.fillRect(canvas.width / 2 - 300, 156, 600 * Math.max(0, 1 - state.t / (state.duration || chronoRuleFrames)), 2);
  // the new rule, as a big card for a moment
  if (state.card > 0) {
    const k = Math.min(1, state.card / 20, (130 - state.card) / 15);
    ctx.globalAlpha = Math.max(0, k);
    const cw = 360;
    const ch = 200;
    const cx = canvas.width / 2 - cw / 2;
    const cy = 268 + (1 - k) * 30;
    ctx.fillStyle = '#f5f5f5';
    ctx.fillRect(cx, cy, cw, ch);
    ctx.strokeStyle = color;
    ctx.lineWidth = 5;
    ctx.strokeRect(cx, cy, cw, ch);
    drawAbnormalSuit(abnormalSuits[state.number % 4], cx + 26, cy + 30, 14, '#0d1640');
    drawAbnormalSuit(abnormalSuits[state.number % 4], cx + cw - 26, cy + ch - 30, 14, '#0d1640');
    ctx.fillStyle = '#0d1640';
    ctx.font = '900 16px Courier New, monospace';
    ctx.fillText(`REGLA ${state.number}`, canvas.width / 2, cy + 46);
    ctx.font = '900 15px Courier New, monospace';
    const words = rule.title.split(' ');
    let lineText = '';
    let lineY = cy + 92;
    words.forEach((word) => {
      if ((lineText + ' ' + word).length > 26) {
        ctx.fillText(lineText, canvas.width / 2, lineY);
        lineText = word;
        lineY += 22;
      } else {
        lineText = lineText ? `${lineText} ${word}` : word;
      }
    });
    ctx.fillText(lineText, canvas.width / 2, lineY);
    ctx.fillStyle = color === '#ffd54f' ? '#b8860b' : color === '#69f0ae' ? '#2e7d32' : '#1565c0';
    ctx.font = '900 12px Courier New, monospace';
    ctx.fillText(whoText, canvas.width / 2, cy + ch - 18);
    void time;
  }
  ctx.restore();
}

// ================= the chaos rules of the 6th maze: they move the box itself =================
const abnormalMazeRules6 = [
  { id: 'boxDrift', title: 'LA CAJA SE PASEA POR LA PANTALLA', who: 'abn' },
  { id: 'wallsRed', title: 'LAS PAREDES SON ROJAS (CHOCARLAS DUELE)', who: 'abn' },
  { id: 'redsWalk', title: 'LOS CUBOS ROJOS CAMINAN', who: 'abn' },
  { id: 'boxUpside', title: 'LA CAJA ESTA DE CABEZA', who: 'all' },
  { id: 'greensBad', title: 'LOS VERDES AHORA QUITAN VIDA', who: 'abn' },
  { id: 'light', title: 'SE ENCIENDEN LAS LUCES (SIN NIEBLA)', who: 'chrono' },
  { id: 'goalRun', title: 'EL BLOQUE DORADO HUYE DE VOS', who: 'abn' },
  { id: 'boxMirror', title: 'LA CAJA SE VE EN EL ESPEJO', who: 'all' },
  { id: 'shrink', title: 'LA CAJA SE ENCOGE', who: 'all' },
  { id: 'chaserNap', title: 'EL CUBO NEGRO SE TOMA UNA SIESTA', who: 'chrono', needsChaser: true },
  { id: 'boxShake', title: 'TERREMOTO EN LA CAJA', who: 'all' },
  { id: 'greenRain', title: 'LLUVIA DE CUBOS VERDES', who: 'chrono' },
];

function updateAbnormalMazeChaos(g, mrule) {
  if (!mrule) return;
  if (mrule === 'redsWalk' && g.frame % 34 === 0) {
    g.reds.forEach((red) => {
      const options = [[1, 0], [-1, 0], [0, 1], [0, -1]]
        .map(([dx, dy]) => [red.x + dx, red.y + dy])
        .filter(([x, y]) => x > 0 && y > 0 && x < g.cols - 1 && y < g.rows - 1 && g.grid[y][x] === 0 && !(x === g.goal[0] && y === g.goal[1]) && !g.reds.some((other) => other.x === x && other.y === y));
      if (!options.length) return;
      const [x, y] = options[Math.floor(Math.random() * options.length)];
      red.x = x;
      red.y = y;
    });
  }
  if (mrule === 'goalRun' && g.frame % 50 === 0) {
    const { dist } = abnormalMazeDistances(g.grid, g.cols, g.rows, g.px, g.py);
    const [gx, gy] = g.goal;
    let best = null;
    [[1, 0], [-1, 0], [0, 1], [0, -1]].forEach(([dx, dy]) => {
      const x = gx + dx;
      const y = gy + dy;
      if (x <= 0 || y <= 0 || x >= g.cols - 1 || y >= g.rows - 1 || g.grid[y][x] === 1) return;
      if (!best || dist[y][x] > dist[best[1]][best[0]]) best = [x, y];
    });
    if (best && dist[best[1]][best[0]] >= dist[gy][gx]) g.goal = best;
  }
  if (mrule === 'boxShake') g.shake = Math.max(g.shake, 7);
}

// the transform of the whole box under the chaos rules
function getAbnormalBoxTransform(g, mrule) {
  const time = performance.now() / 1000;
  const w = g.cols * g.cell;
  const h = g.rows * g.cell;
  const cx = g.x + w / 2;
  const cy = g.y + h / 2;
  const t = { cx, cy, dx: 0, dy: 0, rot: 0, sx: 1, sy: 1 };
  if (mrule === 'boxDrift') {
    t.dx = Math.sin(time * 0.9) * 140;
    t.dy = Math.sin(time * 1.3) * 40;
  } else if (mrule === 'boxUpside') {
    t.rot = Math.PI;
  } else if (mrule === 'boxMirror') {
    t.sx = -1;
  } else if (mrule === 'shrink') {
    const k = 0.62 + Math.sin(time * 1.5) * 0.08;
    t.sx = k;
    t.sy = k;
  }
  return t;
}

