const chronoPowerMaps = ['alpha', 'foundry', 'desert', 'neon', 'casino', 'military', 'arcaneLibrary', 'clockTower', 'ancientRuins', 'jungle', 'darkRoom', 'normalArcade', 'fireArcade', 'gamblerArcade', 'gamblerAlley', 'jesterRift', 'enchantedForest', 'villageRoad', 'villagePlaza', 'hotSprings', 'robledalJail', 'robledalAlley', 'lanternHill', 'lightSkyPlatform', 'farolTop', 'shaolinTemple', 'medievalCastle', 'scamShowroom', 'robotFactory', 'factoryRoof', 'factoryVault', 'factoryHidden', 'farolBridge', 'farolRift', 'cobaltAftermath', 'originsMarket', 'originsMarketDusk', 'originsRooftops', 'originsStation', 'originsNight', 'originsCastle', 'cobaltEdge', 'sorcererLibrary', 'burningLibrary', 'darkWorld', 'redForest', 'violetForest', 'castleGate', 'castleClocks', 'castleMirrors', 'castleDining', 'castleGallery', 'castleArmory', 'castleStairs', 'castleHall', 'castleThroneHall', 'castleRoof', 'castleRuins', 'kingThrone', 'castleOutskirts', 'orderChamber', 'originsRooftopsDark', 'originsAlleyDark'];
const chronoPowerAlly = { actor: null, x: 0, cd: 0, swing: 0 };

function startChronoPowers() {
  endChronoRule(getChronoRule());
  chronoRuleState.powers = true;
  chronoRuleState.index = -1;
  chronoRuleState.t = 99999;
}

function applyChronoPower(rule) {
  const state = chronoRuleState;
  state.saved = { maxHealth: player2.maxHealth, health: player2.health, dmg: player2.damageMultiplier };
  if (rule.id === 'hp999') {
    // (this one stays until the end of the fight)
    chronoCh.hp999Forever = true;
    player2.setMaxHealth(999);
    player2.health = 999;
  } else if (rule.id === 'hpX2') {
    player2.setMaxHealth(Math.round(state.saved.maxHealth * 2));
    player2.health = Math.min(player2.maxHealth, Math.max(1, player2.health * 2));
  } else if (rule.id === 'dmgX3') {
    player2.damageMultiplier = state.saved.dmg * 3;
  } else if (rule.id === 'abnSpeedX2') {
    player2.moveSpeed *= 2;
  } else if (rule.id === 'menuMap') {
    startAbnMenuFight();
  } else if (rule.id === 'upsideMap') {
    selectedMap = 'abnormalUpside';
  } else if (rule.id === 'dgJoin') {
    if (!chronoPowerAlly.actor) {
      const actor = new Fighter({ x: 0, y: 0, color: '#ffffff', attacksToTheRight: true });
      actor.setCharacterType('divineGeneral');
      chronoPowerAlly.actor = actor;
    }
    chronoPowerAlly.x = -80;
    chronoPowerAlly.cd = 30;
  } else if (rule.id === 'dgSwap') {
    state.chronoHealth = player1.health;
    makeChapterDivineGeneral(player1);
    player1.divineAdaptations = { melee: 1, special: 1 };
    jesterWhiteFade = 20;
  }
  updateHealthBars();
  updateCombatHudIdentity();
}

function endChronoPower(rule) {
  const state = chronoRuleState;
  if (!rule || !state.saved) return;
  if (rule.id === 'hpX2') {
    // back to what he had (a little less, if he was hit a lot)
    const lostRatio = Math.max(0, 1 - player2.health / player2.maxHealth);
    player2.setMaxHealth(state.saved.maxHealth);
    player2.health = Math.max(1, Math.min(state.saved.maxHealth, state.saved.health * (1 - lostRatio * 0.5)));
  }
  if (rule.id === 'dmgX3') player2.damageMultiplier = state.saved.dmg;
  if (rule.id === 'menuMap') cleanupAbnMenuFight();
  if (rule.id === 'mapShuffle' || rule.id === 'menuMap' || rule.id === 'upsideMap') selectedMap = 'abnormalArena';
  if (rule.id === 'dgSwap') {
    makeChapterChrono(player1);
    player1.brokenLook = true;
    player1.rareMachine = true;
    player1.machineLight = true;
    player1.health = Math.max(1, Math.min(player1.maxHealth, state.chronoHealth || player1.maxHealth * 0.5));
    jesterWhiteFade = 20;
  }
  updateHealthBars();
  updateCombatHudIdentity();
}

function updateChronoPower(rule, state) {
  if (rule.id === 'mapShuffle' && state.t % 200 === 0) {
    selectedMap = chronoPowerMaps[Math.floor(Math.random() * chronoPowerMaps.length)];
    jesterWhiteFade = 8;
  } else if (rule.id === 'noCooldown') {
    chronoCh.abilityTimer = Math.min(chronoCh.abilityTimer, 40);
  } else if (rule.id === 'menuMap') {
    updateAbnMenuPlatforms();
    updateAbnMenuCursor();
  } else if (rule.id === 'bouncy') {
    [player1, player2].forEach((fighter) => {
      if (fighter.position.y + fighter.height >= ground - 1 && fighter.velocity.y >= 0) {
        fighter.velocity.y = -13;
        if (fighter === player1) playTone({ frequency: 300, duration: 0.08, type: 'sine', volume: 0.03, slideTo: 600 });
      }
    });
  } else if (rule.id === 'wrap') {
    if (player1.position.x <= 0 && keys.a) player1.position.x = canvas.width - player1.width - 2;
    else if (player1.position.x >= canvas.width - player1.width && keys.d) player1.position.x = 2;
    if (player2.position.x <= 0 && player2.velocity.x < 0) player2.position.x = canvas.width - player2.width - 2;
    else if (player2.position.x >= canvas.width - player2.width && player2.velocity.x > 0) player2.position.x = 2;
  } else if (rule.id === 'dgJoin') {
    // the General fights at Chrono's side
    const ally = chronoPowerAlly;
    ally.cd = Math.max(0, ally.cd - 1);
    ally.swing = Math.max(0, ally.swing - 1);
    const target = getFighterCenterX(player2) + (ally.x < player2.position.x ? -80 : 60);
    ally.x += Math.max(-5, Math.min(5, target - ally.x));
    if (Math.abs(target - ally.x) < 20 && ally.cd <= 0 && canFighterAct(player2)) {
      ally.cd = 45;
      ally.swing = 12;
      applyDamage(ally.actor, player2, 9, { isSpecial: false });
      updateHealthBars();
    }
  }
}

function drawChronoPowerExtras(rule) {
  if (rule.id === 'menuMap') drawAbnMenuCursor();
  if (rule.id === 'dgJoin' && chronoPowerAlly.actor) {
    const actor = chronoPowerAlly.actor;
    actor.position = { x: chronoPowerAlly.x - actor.width / 2, y: ground - actor.height };
    actor.attacksToTheRight = chronoPowerAlly.x < getFighterCenterX(player2);
    actor.isAttacking = chronoPowerAlly.swing > 0;
    if (actor.isAttacking) {
      const dir = actor.attacksToTheRight ? 1 : -1;
      actor.attackArea = { x: dir > 0 ? actor.position.x + actor.width : actor.position.x - 70, y: actor.position.y + 30, width: 70, height: 30 };
    }
    actor.draw();
  }
}

// the "menu" of the game, as a stage
function drawAbnormalMenuStage() {
  const time = performance.now() / 1000;
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#1a237e');
  sky.addColorStop(1, '#0d0d2b');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.save();
  ctx.textAlign = 'center';
  ctx.font = '900 84px Courier New, monospace';
  ctx.lineWidth = 8;
  ctx.strokeStyle = '#000';
  ctx.fillStyle = '#ffd54f';
  const wobble = Math.sin(time * 2) * 4;
  ctx.strokeText('MOQUETE', canvas.width / 2, 120 + wobble);
  ctx.fillText('MOQUETE', canvas.width / 2, 120 + wobble);
  ctx.font = '900 16px Courier New, monospace';
  ctx.fillStyle = '#90caf9';
  ctx.fillText('(edicion del Guardia Supremo)', canvas.width / 2, 148);
  ['JUGAR', 'MODOS DE JUEGO', 'OPCIONES', 'SALIR (NO PUEDES)'].forEach((label, index) => {
    const by = 190 + index * 58;
    ctx.fillStyle = index === Math.floor(time) % 4 ? '#3949ab' : '#1e2a78';
    ctx.fillRect(canvas.width / 2 - 150, by, 300, 44);
    ctx.strokeStyle = '#e3f2fd';
    ctx.lineWidth = 3;
    ctx.strokeRect(canvas.width / 2 - 150, by, 300, 44);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 18px Courier New, monospace';
    ctx.fillText(label, canvas.width / 2, by + 28);
  });
  ctx.restore();
  // the "floor": the bottom edge of the menu window
  ctx.fillStyle = '#e3f2fd';
  ctx.fillRect(0, ground, canvas.width, 4);
  ctx.fillStyle = '#0d0d2b';
  ctx.fillRect(0, ground + 4, canvas.width, canvas.height - ground);
  ctx.fillStyle = '#90caf9';
  ctx.font = '900 12px Courier New, monospace';
  ctx.fillText('v3.6 - todos los derechos reservados al Guardia Supremo', 20, canvas.height - 14);
}

// the map upside down: the stage is drawn flipped
function drawAbnormalUpsideStage() {
  // the floor stays where it is (it is where they stand); everything above it hangs upside down
  drawAbnormalArenaStage();
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, canvas.width, ground);
  ctx.clip();
  ctx.fillStyle = '#081232';
  ctx.fillRect(0, 0, canvas.width, ground);
  ctx.translate(0, ground);
  ctx.scale(1, -1);
  drawAbnormalArenaStage();
  ctx.restore();
}

