const abnMenuScreens = ['titleScreen', 'oldDaysScreen', 'characterScreen', 'mapScreen', 'settingsScreen', 'gameModesScreen', 'arcadeChaptersScreen', 'arcadeLevelsScreen', 'debugScreen', 'secretGuideScreen', 'secretCharactersScreen', 'eventGuideScreen', 'achievementsScreen', 'statsScreen', 'scammerIntroScreen', 'scamChallengeScreen', 'scammerShopScreen', 'infoScreen', 'guideScreen', 'opinionScreen'];
