function showAbnMenuScreen(id) {
  abnMenuFight.screen = id;
  if (id === 'scammerShopScreen' && typeof renderScammerShop === 'function') renderScammerShop();
  if (typeof abnMenuReactions !== 'undefined' && abnMenuReactions[id]) abnMenuFight.reaction = { ...abnMenuReactions[id], t: 260 };
  abnMenuScreens.forEach((screenId) => {
    const screen = document.getElementById(screenId);
    if (screen) screen.classList.toggle('hidden', screenId !== id);
  });
  playTone({ frequency: 660, duration: 0.06, type: 'square', volume: 0.03 });
}

function startAbnMenuFight() {
  if (abnMenuFight.active) return;
  abnMenuFight.active = true;
  selectedMap = 'gameMenu';
  document.body.classList.add('abn-menu-fight');
  mainMenu.classList.remove('hidden');
  showAbnMenuScreen('titleScreen');
  // the way back: Abnormal's hall, among the maps
  const grid = document.querySelector('#mapScreen .map-grid');
  if (grid && !abnMenuFight.hallButton) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'map-option abn-hall-option';
    button.dataset.map = 'abnormalArena';
    button.innerHTML = '<span>Salon de Abnormal</span><span class="map-preview abn-hall-preview" aria-hidden="true"><span class="map-sky"></span><span class="map-platform"></span><span class="map-detail"></span></span>';
    grid.prepend(button);
    abnMenuFight.hallButton = button;
  }
  abnMenuFight.listener = (event) => {
    if (!abnMenuFight.active) return;
    const button = event.target.closest && event.target.closest('button');
    if (!button || !mainMenu.contains(button)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    handleAbnMenuClick(button);
  };
  document.addEventListener('click', abnMenuFight.listener, true);
  showFlametombThought(player2, '¡Bienvenido al MENU, relojito! Para volver... tendras que encontrar mi salon.');
}

function cleanupAbnMenuFight() {
  if (!abnMenuFight.active) return;
  abnMenuFight.active = false;
  document.body.classList.remove('abn-menu-fight');
  if (abnMenuFight.listener) document.removeEventListener('click', abnMenuFight.listener, true);
  abnMenuFight.listener = null;
  if (abnMenuFight.hallButton) abnMenuFight.hallButton.remove();
  abnMenuFight.hallButton = null;
  document.querySelectorAll('.abn-hover, .abn-locked').forEach((button) => button.classList.remove('abn-hover', 'abn-locked'));
  mainMenu.style.filter = '';
  abnMenuFight.locks = [];
  abnMenuFight.themeT = 0;
  abnMenuFight.cursor = null;
  abnMenuFight.reaction = null;
  // the menu goes back to how it was: hidden, on its title screen
  abnMenuScreens.forEach((screenId) => {
    const screen = document.getElementById(screenId);
    if (screen) screen.classList.toggle('hidden', screenId !== 'titleScreen');
  });
  if (!document.body.classList.contains('menu-open')) mainMenu.classList.add('hidden');
  if (selectedMap === 'gameMenu') selectedMap = 'abnormalArena';
}

// the buttons of the menu are platforms
function updateAbnMenuPlatforms() {
  if (!abnMenuFight.active) return;
  const canvasRect = canvas.getBoundingClientRect();
  if (!canvasRect.width) return;
  const sx = canvas.width / canvasRect.width;
  const sy = canvas.height / canvasRect.height;
  const screen = document.getElementById(abnMenuFight.screen);
  if (!screen) return;
  const platforms = [];
  screen.querySelectorAll('button').forEach((button) => {
    const r = button.getBoundingClientRect();
    if (!r.width || !r.height) return;
    const top = (r.top - canvasRect.top) * sy;
    if (top < 60 || top > ground - 20) return;
    platforms.push({ x: (r.left - canvasRect.left) * sx, w: r.width * sx, top });
  });
  abnMenuFight.platforms = platforms;
  [player1, player2].forEach((fighter) => {
    const bottom = fighter.position.y + fighter.height;
    const prev = fighter.abnPrevBottom === undefined ? bottom : fighter.abnPrevBottom;
    fighter.abnPrevBottom = bottom;
    if (fighter.velocity.y < 0) return;
    const cx = fighter.position.x + fighter.width / 2;
    platforms.forEach((platform) => {
      if (cx < platform.x || cx > platform.x + platform.w) return;
      if (prev <= platform.top + 2 && bottom >= platform.top - 1) {
        fighter.position.y = platform.top - fighter.height;
        fighter.velocity.y = 0;
        fighter.abnPrevBottom = platform.top;
      }
    });
  });
}

// (the stage while the menu is behind: nothing, the canvas is see-through)
function drawGameMenuStage() {
  // the floor: the bottom edge of the menu window
  ctx.fillStyle = 'rgba(227, 242, 253, 0.9)';
  ctx.fillRect(0, ground, canvas.width, 4);
  (abnMenuFight.platforms || []).forEach((platform) => {
    ctx.fillStyle = 'rgba(255, 213, 79, 0.55)';
    ctx.fillRect(platform.x, platform.top - 3, platform.w, 3);
  });
}

