const abnMenuBackTargets = { mapBackButton: 'characterScreen', arcadeLevelsBackButton: 'arcadeChaptersScreen', arcadeChaptersBackButton: 'gameModesScreen' };

function handleAbnMenuClick(button, fromAbnormal = false) {
  const id = button.id || '';
  if (!fromAbnormal && button.classList.contains('abn-locked')) {
    showFlametombThought(player2, '¡Ese boton esta BLOQUEADO! ¡Por decreto distinguido!');
    playTone({ frequency: 140, duration: 0.2, type: 'square', volume: 0.05 });
    return;
  }
  if (button.classList.contains('abn-hall-option')) {
    if (fromAbnormal) return;
    showFlametombThought(player2, '¡Mi salon! ¡Hogar, dulce y distinguido hogar!');
    jesterWhiteFade = 30;
    chronoRuleState.t = 99999;
    chronoRuleState.duration = 1;
    return;
  }
  if (abnMenuLinks[id]) {
    showAbnMenuScreen(abnMenuLinks[id]);
    return;
  }
  if (/BackButton$/.test(id) || id === 'backButton') {
    showAbnMenuScreen(abnMenuBackTargets[id] || 'titleScreen');
    return;
  }
  if (abnMenuFight.screen === 'gameModesScreen') {
    showAbnMenuScreen('arcadeChaptersScreen');
    return;
  }
  if (abnMenuFight.screen === 'arcadeChaptersScreen') {
    showAbnMenuScreen('arcadeLevelsScreen');
    return;
  }
  if (abnMenuFight.screen === 'arcadeLevelsScreen') {
    showFlametombThought(player2, '¡No se puede jugar un nivel ADENTRO de un nivel! ...¿O si?');
    return;
  }
  if (button.classList.contains('character-option')) {
    showAbnMenuScreen('mapScreen');
    return;
  }
  if (button.classList.contains('map-option')) {
    showFlametombThought(player2, '¡Esa no! ¡Elegi MI salon!');
    playTone({ frequency: 180, duration: 0.15, type: 'square', volume: 0.04 });
    return;
  }
  showFlametombThought(player2, abnMenuQuips[Math.floor(Math.random() * abnMenuQuips.length)]);
  playTone({ frequency: 180, duration: 0.15, type: 'square', volume: 0.04 });
}

function getAbnMenuButtons() {
  const screen = document.getElementById(abnMenuFight.screen);
  if (!screen) return [];
  const list = [];
  screen.querySelectorAll('button').forEach((button) => {
    if (button.classList.contains('abn-hall-option')) return;
    const r = button.getBoundingClientRect();
    if (!r.width || !r.height) return;
    list.push(button);
  });
  if (abnMenuFight.screen === 'titleScreen') {
    const trash = document.getElementById('secretTrashButton');
    if (trash && trash.getBoundingClientRect().width) list.push(trash);
  }
  return list;
}

function buttonToCanvas(button) {
  const canvasRect = canvas.getBoundingClientRect();
  const r = button.getBoundingClientRect();
  const sx = canvas.width / canvasRect.width;
  const sy = canvas.height / canvasRect.height;
  return { x: (r.left - canvasRect.left + r.width / 2) * sx, y: (r.top - canvasRect.top + r.height / 2) * sy };
}

// what he does next: open things, close things, grab Chrono, poke him, scroll, lock a button, hide his own hall...
function pickAbnMenuAction(c) {
  const buttons = getAbnMenuButtons();
  const roll = Math.random();
  if (roll < 0.14) return { kind: 'grab' };
  if (roll < 0.24) return { kind: 'poke' };
  if (roll < 0.32) return { kind: 'scroll' };
  if (roll < 0.42 && buttons.length) return { kind: 'lock', button: buttons[Math.floor(Math.random() * buttons.length)] };
  if (roll < 0.48 && abnMenuFight.hallButton) return { kind: 'hideHall' };
  if (roll < 0.54) return { kind: 'theme' };
  if (!buttons.length) return null;
  const backs = buttons.filter((button) => /BackButton$/.test(button.id || '') || button.id === 'backButton');
  const forward = buttons.filter((button) => !backs.includes(button));
  const pool = backs.length && (Math.random() < 0.4 || !forward.length) ? backs : forward;
  let target = pool[Math.floor(Math.random() * pool.length)];
  const trash = buttons.find((button) => button.id === 'secretTrashButton');
  if (trash && Math.random() < 0.3) target = trash;
  return { kind: 'click', button: target };
}

function updateAbnMenuCursor() {
  const c = abnMenuFight.cursor || (abnMenuFight.cursor = { x: canvas.width - 140, y: 300, action: null, timer: 120, grab: 0 });
  if (abnMenuFight.reaction) {
    abnMenuFight.reaction.t -= 1;
    if (abnMenuFight.reaction.t <= 0) abnMenuFight.reaction = null;
  }
  if (abnMenuFight.themeT > 0) {
    abnMenuFight.themeT -= 1;
    mainMenu.style.filter = `hue-rotate(${(abnMenuFight.themeT * 4) % 360}deg) saturate(1.6)`;
    if (abnMenuFight.themeT === 0) mainMenu.style.filter = '';
  }
  (abnMenuFight.locks || []).forEach((lock) => {
    lock.t -= 1;
    if (lock.t <= 0) lock.button.classList.remove('abn-locked');
  });
  abnMenuFight.locks = (abnMenuFight.locks || []).filter((lock) => lock.t > 0);
  // carrying Chrono around
  if (c.grab > 0) {
    c.grab -= 1;
    c.x += Math.sin(c.grab / 9) * 6;
    c.y = Math.max(120, Math.min(ground - 160, c.y + Math.cos(c.grab / 13) * 3));
    player1.position.x = Math.max(0, Math.min(canvas.width - player1.width, c.x - player1.width / 2));
    player1.position.y = c.y + 10;
    player1.velocity.x = 0;
    player1.velocity.y = 0;
    if (c.grab === 0) {
      showFlametombThought(player2, '¡Y... lo suelto! ¡Jo jo!');
      playTone({ frequency: 600, duration: 0.3, type: 'sine', volume: 0.04, slideTo: 200 });
    }
    return;
  }
  c.timer -= 1;
  if (!c.action && c.timer <= 0) {
    c.action = pickAbnMenuAction(c);
    if (c.action && c.action.button) c.action.button.classList.add('abn-hover');
    c.timer = 60;
  }
  const action = c.action;
  if (!action) return;
  let goal = null;
  if (action.kind === 'grab' || action.kind === 'poke') goal = { x: player1.position.x + player1.width / 2, y: player1.position.y + 10 };
  else if (action.button) goal = buttonToCanvas(action.button);
  else goal = { x: c.x, y: c.y };
  c.x += (goal.x - c.x) * 0.09;
  c.y += (goal.y - c.y) * 0.09;
  if (Math.hypot(goal.x - c.x, goal.y - c.y) > 8) return;
  c.clickFx = 14;
  playTone({ frequency: 1200, duration: 0.05, type: 'square', volume: 0.04 });
  if (action.button) action.button.classList.remove('abn-hover');
  if (action.kind === 'click') {
    handleAbnMenuClick(action.button, true);
  } else if (action.kind === 'grab') {
    c.grab = 110;
    showFlametombThought(player2, '¡Te tengo, relojito! ¡A pasear!');
  } else if (action.kind === 'poke') {
    applyDamage(player2, player1, 6, { isSpecial: true });
    showScamLabel(player1, '¡CLICK!');
    updateHealthBars();
  } else if (action.kind === 'scroll') {
    const screen = document.getElementById(abnMenuFight.screen);
    if (screen) screen.scrollTop = screen.scrollTop > 40 ? 0 : 220;
    const grid = document.querySelector(`#${abnMenuFight.screen} .map-grid, #${abnMenuFight.screen} .shop-items`);
    if (grid) grid.scrollTop = grid.scrollTop > 40 ? 0 : 260;
    showFlametombThought(player2, '¡Scroll! ¡Las plataformas se mueven! ¡Jo jo!');
  } else if (action.kind === 'lock') {
    action.button.classList.add('abn-locked');
    abnMenuFight.locks = abnMenuFight.locks || [];
    abnMenuFight.locks.push({ button: action.button, t: 480 });
    showFlametombThought(player2, '¡Ese boton queda BLOQUEADO! ¡Por un rato!');
  } else if (action.kind === 'hideHall') {
    const grid = abnMenuFight.hallButton.parentElement;
    if (grid) {
      const others = Array.from(grid.children).filter((child) => child !== abnMenuFight.hallButton);
      const spot = others[Math.floor(Math.random() * others.length)];
      if (spot) grid.insertBefore(abnMenuFight.hallButton, Math.random() < 0.5 ? spot : spot.nextSibling);
    }
    showFlametombThought(player2, '¿Mi salon? Lo movi. ¡Buena suerte encontrandolo! ¡JO JO!');
  } else if (action.kind === 'theme') {
    abnMenuFight.themeT = 360;
    showFlametombThought(player2, '¡Cambio de colores! ¡Edicion Distinguida!');
  }
  c.action = null;
  c.timer = 150 + Math.floor(Math.random() * 90);
}

function drawAbnMenuCursor() {
  const c = abnMenuFight.cursor;
  if (!c) return;
  ctx.save();
  ctx.translate(c.x, c.y);
  if (c.clickFx > 0) {
    c.clickFx -= 1;
    ctx.strokeStyle = `rgba(144, 202, 249, ${c.clickFx / 14})`;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, 30 - c.clickFx, 0, Math.PI * 2);
    ctx.stroke();
  }
  if (c.grab > 0) {
    // the hand closes around Chrono
    ctx.fillStyle = '#e3f2fd';
    ctx.strokeStyle = '#1e3a8a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    for (let finger = 0; finger < 4; finger += 1) ctx.fillRect(-12 + finger * 7, 6, 5, 12);
  } else {
    ctx.fillStyle = '#1e3a8a';
    ctx.strokeStyle = '#e3f2fd';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(0, 34);
    ctx.lineTo(9, 26);
    ctx.lineTo(16, 40);
    ctx.lineTo(22, 37);
    ctx.lineTo(15, 23);
    ctx.lineTo(26, 23);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }
  ctx.strokeStyle = '#e3f2fd';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(10, 14);
  ctx.quadraticCurveTo(26, -6, 22, -20);
  ctx.stroke();
  drawAbnormalSuit('spade', 7, 18, 4, '#e3f2fd');
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 10px Courier New, monospace';
  ctx.fillText('ABNORMAL', 18, 54);
  ctx.restore();
  const reaction = abnMenuFight.reaction;
  if (reaction) {
    ctx.save();
    ctx.globalAlpha = Math.min(1, reaction.t / 20);
    ctx.fillStyle = 'rgba(10, 10, 20, 0.88)';
    ctx.fillRect(140, 230, canvas.width - 280, 74);
    ctx.strokeStyle = reaction.color;
    ctx.lineWidth = 3;
    ctx.strokeRect(140, 230, canvas.width - 280, 74);
    ctx.fillStyle = reaction.color;
    ctx.font = '900 13px Courier New, monospace';
    ctx.fillText(reaction.speaker, 156, 250);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 14px Courier New, monospace';
    const words = reaction.text.split(' ');
    let lineText = '';
    let lineY = 272;
    words.forEach((word) => {
      if ((lineText + ' ' + word).length > 82) {
        ctx.fillText(lineText, 156, lineY);
        lineText = word;
        lineY += 20;
      } else {
        lineText = lineText ? `${lineText} ${word}` : word;
      }
    });
    ctx.fillText(lineText, 156, lineY);
    ctx.restore();
  }
}

