// the sound of something falling from very, very high
function playChronoFallWhistle() {
  playTone({ frequency: 1500, duration: 1.6, type: 'sine', volume: 0.05, slideTo: 300 });
}

function playChronoFallImpact() {
  playNoise({ duration: 0.9, volume: 0.18, filterFrequency: 350 });
  playTone({ frequency: 70, duration: 0.8, type: 'sine', volume: 0.14, slideTo: 30 });
  // metal parts bouncing around
  [0, 140, 260, 360, 440].forEach((delay, index) => setTimeout(() => playTone({ frequency: 900 + index * 180, duration: 0.12, type: 'square', volume: 0.04 - index * 0.006, slideTo: 600 + index * 100 }), 120 + delay));
}

function updateChronoSecretOmega(cutscene, line, firstFrame) {
  const time = performance.now() / 1000;
  cutscene.omegaCards = cutscene.omegaCards || [];
  if (line.omegaCharge) {
    const k = line.omegaCharge;
    if (cutscene.omegaCards.length < 30 + k * 12) cutscene.omegaCards.push({ a: Math.random() * Math.PI * 2, r: 320, suit: abnormalSuits[cutscene.omegaCards.length % 4], h: Math.random() });
    cutscene.shake = Math.max(cutscene.shake || 0, k * 3);
    if (cutscene.frame % Math.max(3, 12 - k * 2) === 0) playTone({ frequency: 180 + k * 120 + Math.random() * 60, duration: 0.1, type: 'sawtooth', volume: 0.045 });
    cutscene.scammerY = Math.min(50, (cutscene.scammerY || 0) + 0.3);
    cutscene.chargeGlow = Math.min(1, (cutscene.chargeGlow || 0) + 0.004 * k);
  }
  if (line.cracks) cutscene.crackK = Math.min(1, (cutscene.crackK || 0) + 0.01);
  if (line.omegaPillar) {
    cutscene.pillarK = Math.min(1, (cutscene.pillarK || 0) + 0.03);
    cutscene.shake = Math.max(cutscene.shake || 0, 10);
    if (firstFrame) playTone({ frequency: 2000, duration: 1.5, type: 'sine', volume: 0.06, slideTo: 400 });
  }
  if (line.omegaBurst) {
    cutscene.burstT = (cutscene.burstT || 0) + 1;
    if (cutscene.burstT === 1) {
      cutscene.holdLine = cutscene.lineIndex;
      cutscene.flash = 1.4;
      cutscene.shake = 70;
      cutscene.rings = [0, 1, 2, 3, 4].map((ring) => ({ r: 10 + ring * 30, life: 60 - ring * 6 }));
      playNoise({ duration: 2.6, volume: 0.24, filterFrequency: 2200 });
      playTone({ frequency: 55, duration: 2.4, type: 'sawtooth', volume: 0.14, slideTo: 30 });
      [262, 330, 392, 523, 659, 784, 1046].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.7, type: 'square', volume: 0.05 }), 300 + index * 80));
      player2.giantScale = 1.5;
    }
    // the blast throws Chrono and the General back
    cutscene.knockT = Math.min(60, (cutscene.knockT || 0) + 1);
    if (cutscene.burstT === 100) cutscene.holdLine = -1;
  }
  if (line.knockback || line.omegaBurst) {
    cutscene.gamblerX += (30 - cutscene.gamblerX) * 0.12;
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.secretDgX += (-20 - cutscene.secretDgX) * 0.12;
    if (cutscene.frame % 3 === 0) {
      cutscene.dust = cutscene.dust || [];
      cutscene.dust.push({ x: cutscene.gamblerX + 30, y: ground - 4, vx: 3 + Math.random() * 3, life: 30 });
      cutscene.dust.push({ x: cutscene.secretDgX + 30, y: ground - 4, vx: 3 + Math.random() * 3, life: 30 });
    }
  }
  (cutscene.dust || []).forEach((puff) => {
    puff.x += puff.vx;
    puff.life -= 1;
  });
  cutscene.dust = (cutscene.dust || []).filter((puff) => puff.life > 0);
  (cutscene.rings || []).forEach((ring) => {
    ring.r += 18;
    ring.life -= 1;
  });
  cutscene.rings = (cutscene.rings || []).filter((ring) => ring.life > 0);
  if (line.omega || line.omegaBurst) {
    player2.giantScale = 1.5;
    cutscene.scammerY = 46 + Math.sin(time * 2) * 10;
    cutscene.pillarK = Math.max(0.35, (cutscene.pillarK || 0) - 0.01);
    if (cutscene.frame % 40 === 0) playTone({ frequency: 880 + Math.random() * 400, duration: 0.3, type: 'triangle', volume: 0.02 });
  }
  if (line.omegaTitle && firstFrame) playTone({ frequency: 110, duration: 1.8, type: 'sawtooth', volume: 0.09, slideTo: 220 });
  cutscene.omegaCards.forEach((card) => {
    card.a += line.omega ? 0.02 : 0.05 + (line.omegaCharge || 0) * 0.015;
    card.r = line.omega ? 150 + Math.sin(time * 2 + card.h * 6) * 12 : Math.max(90, card.r - 1.6);
  });
  if (line.detransform) {
    player2.giantScale = Math.max(1, (player2.giantScale || 1) - 0.01);
    cutscene.scammerY = Math.max(0, (cutscene.scammerY || 0) - 0.6);
    cutscene.pillarK = Math.max(0, (cutscene.pillarK || 0) - 0.02);
    if (firstFrame) {
      cutscene.flash = 0.7;
      playTone({ frequency: 784, duration: 1.2, type: 'triangle', volume: 0.05, slideTo: 196 });
    }
    cutscene.omegaCards.forEach((card) => {
      card.falling = true;
    });
  }
  if (line.cardRain) {
    player2.giantScale = 1;
    cutscene.scammerY = 0;
    cutscene.pillarK = 0;
  }
  cutscene.omegaCards.forEach((card) => {
    if (card.falling) {
      card.fy = (card.fy === undefined ? 200 + Math.sin(card.a) * 120 : card.fy) + 2.5;
      card.fx = card.fx === undefined ? cutscene.scammerX + 30 + Math.cos(card.a) * card.r : card.fx + Math.sin(time * 3 + card.h * 9) * 1.2;
    }
  });
  cutscene.omegaCards = cutscene.omegaCards.filter((card) => !card.falling || card.fy < ground);
  if (line.portalOut) {
    cutscene.whiteK = Math.min(1, (cutscene.whiteK || 0) + 0.012);
    if (firstFrame) playTone({ frequency: 300, duration: 2, type: 'sine', volume: 0.06, slideTo: 1500 });
  }
  // the General in the Bosque Lumina
  if (line.dgForest) {
    if (selectedMap !== 'enchantedForest') {
      selectedMap = 'enchantedForest';
      cutscene.whiteK = 1;
      cutscene.omegaCards = [];
      cutscene.crackK = 0;
      cutscene.dgFallY = 520;
    }
    cutscene.whiteK = Math.max(0, (cutscene.whiteK || 0) - 0.03);
    cutscene.hideEnemy = true;
    cutscene.gamblerX = -400;
    cutscene.gamblerTargetX = -400;
    if (line.dgFall) cutscene.dgFallY = Math.max(0, cutscene.dgFallY - 9);
    if (line.dgBush && firstFrame) {
      cutscene.dgFallY = 0;
      playNoise({ duration: 0.5, volume: 0.1, filterFrequency: 1200 });
    }
  }
  if (line.tempus) {
    if (selectedMap !== 'tempusLobby') {
      selectedMap = 'tempusLobby';
      cutscene.fadeT = 1;
      cutscene.whiteK = 0;
      cutscene.omegaCards = [];
      cutscene.reflActor = (() => {
        const actor = new Fighter({ x: 0, y: 0, color: '#26c6da', attacksToTheRight: false });
        actor.setCharacterType('reflecter');
        return actor;
      })();
      cutscene.robotActors = ['rustyGuard', 'scrapDrone', 'clockworkReject', 'overloadUnit', 'rustyGuard'].map((id) => (typeof makeRobotActor === 'function' ? makeRobotActor(id) : null)).filter(Boolean);
    }
    cutscene.fadeT = Math.max(0, (cutscene.fadeT || 0) - 0.03);
    cutscene.hideEnemy = true;
    if (!line.chronoStand && !line.chronoHere && !line.chronoWalk && !line.chronoGoneTempus) {
      cutscene.gamblerX = -400;
      cutscene.gamblerTargetX = -400;
    }
  }
  if (line.chronoFalling && firstFrame && !cutscene.whistled) {
    cutscene.whistled = true;
    playChronoFallWhistle();
  }
  if (line.chronoDrop) {
    if (firstFrame) {
      cutscene.dropY = 520;
      cutscene.holdLine = cutscene.lineIndex;
    }
    cutscene.dropY = Math.max(0, cutscene.dropY - 20);
    if (cutscene.dropY === 0 && !cutscene.dropLanded) {
      cutscene.dropLanded = true;
      cutscene.shake = 34;
      cutscene.flash = 0.4;
      playChronoFallImpact();
      cutscene.debris = Array.from({ length: 24 }, () => ({ x: 340 + (Math.random() - 0.5) * 80, y: ground - 6, vx: (Math.random() - 0.5) * 10, vy: -4 - Math.random() * 7, life: 60 }));
    }
    if (cutscene.dropLanded) cutscene.dropHold = (cutscene.dropHold || 0) + 1;
    if (cutscene.dropHold === 40) cutscene.holdLine = -1;
  }
  (cutscene.debris || []).forEach((bit) => {
    bit.x += bit.vx;
    bit.y = Math.min(ground - 3, bit.y + bit.vy);
    bit.vy += 0.4;
    bit.life -= 1;
  });
  cutscene.debris = (cutscene.debris || []).filter((bit) => bit.life > 0);
  if (line.chronoStand) {
    cutscene.standK = Math.min(1, (cutscene.standK || 0) + 0.02);
    if (cutscene.standK >= 1) {
      cutscene.gamblerX = 320;
      cutscene.gamblerTargetX = 320;
      cutscene.gamblerHop = 0;
    }
  }
  if (line.chronoHere) {
    cutscene.gamblerX = 320;
    cutscene.gamblerTargetX = 320;
    cutscene.gamblerHop = 0;
  }
  if (line.chronoWalk) {
    cutscene.gamblerX = Math.max(-200, cutscene.gamblerX - 1.4);
    cutscene.gamblerTargetX = cutscene.gamblerX;
    cutscene.gamblerHop = -2 + Math.abs(Math.sin(cutscene.frame / 10)) * 2;
  }
  if (line.chronoGoneTempus) cutscene.gamblerX = Math.max(-300, cutscene.gamblerX - 1.4);
  if (line.soldierPanic) cutscene.shake = Math.max(cutscene.shake || 0, 3);
  cutscene.shake = (cutscene.shake || 0) * 0.92;
}

function drawOmegaAbnormalLook(cutscene, ax, ay, time) {
  const scale = player2.giantScale || 1;
  const top = ground - player2.height * scale - (cutscene.scammerY || 0);
  ctx.save();
  // the pillar of light still falling on him
  if ((cutscene.pillarK || 0) > 0) {
    ctx.globalCompositeOperation = 'lighter';
    const w = 150 * cutscene.pillarK;
    const beam = ctx.createLinearGradient(ax - w, 0, ax + w, 0);
    beam.addColorStop(0, 'rgba(255, 255, 255, 0)');
    beam.addColorStop(0.5, `rgba(255, 250, 220, ${0.55 * cutscene.pillarK})`);
    beam.addColorStop(1, 'rgba(255, 255, 255, 0)');
    ctx.fillStyle = beam;
    ctx.fillRect(ax - w, 0, w * 2, ground);
    ctx.globalCompositeOperation = 'source-over';
  }
  // a huge golden-white aura
  ctx.globalCompositeOperation = 'lighter';
  const aura = ctx.createRadialGradient(ax, ay, 10, ax, ay, 260);
  aura.addColorStop(0, `rgba(255, 245, 210, ${0.55 + Math.sin(time * 6) * 0.1})`);
  aura.addColorStop(0.45, 'rgba(144, 202, 249, 0.3)');
  aura.addColorStop(1, 'rgba(144, 202, 249, 0)');
  ctx.fillStyle = aura;
  ctx.fillRect(ax - 260, ay - 260, 520, 520);
  ctx.globalCompositeOperation = 'source-over';
  // three halo rings of runes (cards' suits), turning in different directions
  [[150, 0.6, '#ffd54f'], [190, -0.4, '#e3f2fd'], [230, 0.25, '#90caf9']].forEach(([r, speed, color], index) => {
    ctx.save();
    ctx.translate(ax, ay);
    ctx.scale(1, 0.32);
    ctx.rotate(time * speed);
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.stroke();
    for (let rune = 0; rune < 8; rune += 1) {
      const a = (rune / 8) * Math.PI * 2;
      ctx.save();
      ctx.translate(Math.cos(a) * r, Math.sin(a) * r);
      ctx.scale(1, 3);
      drawAbnormalSuit(abnormalSuits[(rune + index) % 4], 0, 0, 7, color);
      ctx.restore();
    }
    ctx.restore();
  });
  // wings of light: long feathers made of light, beating slowly
  [-1, 1].forEach((side) => {
    for (let feather = 0; feather < 9; feather += 1) {
      const a = -Math.PI / 2 + side * (0.25 + feather * 0.17) + Math.sin(time * 1.6) * 0.06 * side;
      const len = 150 + feather * 18;
      ctx.save();
      ctx.translate(ax + side * 22, ay - 30);
      ctx.rotate(a + Math.PI / 2);
      const grad = ctx.createLinearGradient(0, 0, 0, -len);
      grad.addColorStop(0, 'rgba(255, 248, 225, 0.95)');
      grad.addColorStop(1, feather % 2 ? 'rgba(255, 213, 79, 0)' : 'rgba(144, 202, 249, 0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.moveTo(-10, 0);
      ctx.quadraticCurveTo(-16, -len * 0.6, 0, -len);
      ctx.quadraticCurveTo(16, -len * 0.6, 10, 0);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  });
  // lightning arcs around him
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
  ctx.lineWidth = 2;
  for (let bolt = 0; bolt < 3; bolt += 1) {
    if (Math.random() < 0.5) continue;
    let bx = ax + (Math.random() - 0.5) * 120;
    let by = top - 20;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    for (let step = 0; step < 6; step += 1) {
      bx += (Math.random() - 0.5) * 34;
      by += 30;
      ctx.lineTo(bx, by);
    }
    ctx.stroke();
  }
  // motes of light rising
  for (let mote = 0; mote < 20; mote += 1) {
    const rise = (time * 60 + mote * 37) % 260;
    ctx.fillStyle = mote % 2 ? '#fff8e1' : '#ffd54f';
    ctx.fillRect(ax - 110 + ((mote * 47) % 220), ground - rise, 3, 3);
  }
  // a floating crown of light with a star
  ctx.fillStyle = '#ffd54f';
  ctx.strokeStyle = '#fff8e1';
  ctx.lineWidth = 2;
  const cy = top - 24 + Math.sin(time * 3) * 4;
  ctx.beginPath();
  ctx.moveTo(ax - 40, cy);
  [[-30, -36], [-14, -14], [0, -54], [14, -14], [30, -36], [40, 0]].forEach(([dx, dy]) => ctx.lineTo(ax + dx, cy + dy));
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 18px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillText('★', ax, cy - 58);
  ctx.textAlign = 'left';
  ctx.restore();
}

function drawChronoSecretOmegaFx(cutscene) {
  const time = performance.now() / 1000;
  const line = cutscene.lines[cutscene.lineIndex];
  const ax = cutscene.scammerX + player2.width / 2;
  const ay = ground - player2.height * (player2.giantScale || 1) / 2 - (cutscene.scammerY || 0);
  // cracks in the floor
  if ((cutscene.crackK || 0) > 0 && selectedMap === 'abnormalArena') {
    ctx.strokeStyle = `rgba(255, 245, 210, ${0.4 + cutscene.crackK * 0.5})`;
    ctx.lineWidth = 2 + cutscene.crackK * 2;
    for (let crack = 0; crack < 10; crack += 1) {
      const dir = crack % 2 ? 1 : -1;
      const len = (40 + crack * 30) * cutscene.crackK;
      ctx.beginPath();
      ctx.moveTo(ax, ground + 4);
      ctx.lineTo(ax + dir * len * 0.5, ground + 8 + (crack % 3) * 6);
      ctx.lineTo(ax + dir * len, ground + 4 + (crack % 4) * 7);
      ctx.stroke();
    }
  }
  if (line.ruleCard) {
    ctx.save();
    const cw = 380;
    const ch = 210;
    const cx = canvas.width / 2 - cw / 2;
    const cy = 260;
    ctx.fillStyle = '#f5f5f5';
    ctx.fillRect(cx, cy, cw, ch);
    ctx.strokeStyle = '#ea80fc';
    ctx.lineWidth = 6;
    ctx.strokeRect(cx, cy, cw, ch);
    drawAbnormalSuit('spade', cx + 28, cy + 32, 16, '#0d1640');
    drawAbnormalSuit('spade', cx + cw - 28, cy + ch - 32, 16, '#0d1640');
    ctx.fillStyle = '#6a1b9a';
    ctx.font = '900 18px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText('REGLA FINAL (DE VERDAD)', canvas.width / 2, cy + 52);
    ctx.fillStyle = '#0d1640';
    ctx.font = '900 16px Courier New, monospace';
    ctx.fillText('ABNORMAL SE TRANSFORMA', canvas.width / 2, cy + 104);
    ctx.fillText('EN OMEGA ABNORMAL', canvas.width / 2, cy + 128);
    ctx.textAlign = 'left';
    ctx.restore();
  }
  // the glow building up while he charges
  if ((cutscene.chargeGlow || 0) > 0 && !line.omega && !line.detransform && !line.cardRain && selectedMap === 'abnormalArena') {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = ctx.createRadialGradient(ax, ay, 4, ax, ay, 80 + cutscene.chargeGlow * 120);
    glow.addColorStop(0, `rgba(255, 245, 210, ${0.6 * cutscene.chargeGlow})`);
    glow.addColorStop(1, 'rgba(144, 202, 249, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(ax - 220, ay - 220, 440, 440);
    ctx.restore();
  }
  if (line.omegaPillar || line.omega || line.omegaBurst) drawOmegaAbnormalLook(cutscene, ax, ay, time);
  (cutscene.omegaCards || []).forEach((card) => {
    const x = card.falling ? card.fx : ax + Math.cos(card.a) * card.r;
    const y = card.falling ? card.fy : ay + Math.sin(card.a) * card.r * 0.6;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(card.a * 2);
    ctx.fillStyle = '#f5f5f5';
    ctx.fillRect(-9, -13, 18, 26);
    ctx.strokeStyle = '#0d1640';
    ctx.lineWidth = 1.5;
    ctx.strokeRect(-9, -13, 18, 26);
    drawAbnormalSuit(card.suit, 0, 0, 5, card.suit === 'heart' || card.suit === 'diamond' ? '#c62828' : '#0d1640');
    ctx.restore();
  });
  (cutscene.rings || []).forEach((ring) => {
    ctx.strokeStyle = `rgba(255, 255, 255, ${ring.life / 60})`;
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.ellipse(ax, ay, ring.r, ring.r * 0.6, 0, 0, Math.PI * 2);
    ctx.stroke();
  });
  (cutscene.dust || []).forEach((puff) => {
    ctx.fillStyle = `rgba(200, 200, 220, ${puff.life / 40})`;
    ctx.beginPath();
    ctx.arc(puff.x, puff.y, 8 + (30 - puff.life) / 3, 0, Math.PI * 2);
    ctx.fill();
  });
  if (line.omegaTitle || line.omegaBurst) {
    ctx.save();
    ctx.textAlign = 'center';
    ctx.font = '900 70px Courier New, monospace';
    const k = line.omegaBurst ? Math.min(1, (cutscene.burstT || 0) / 30) : 1;
    ctx.globalAlpha = k;
    ctx.lineWidth = 12;
    ctx.strokeStyle = '#0d1640';
    ctx.strokeText('OMEGA ABNORMAL', canvas.width / 2, 250);
    const shine = (time * 0.6) % 1;
    const grad = ctx.createLinearGradient(canvas.width / 2 - 340, 0, canvas.width / 2 + 340, 0);
    grad.addColorStop(0, '#ffd54f');
    grad.addColorStop(Math.max(0, shine - 0.08), '#ffd54f');
    grad.addColorStop(shine, '#ffffff');
    grad.addColorStop(Math.min(1, shine + 0.08), '#ffd54f');
    grad.addColorStop(1, '#ffd54f');
    ctx.fillStyle = grad;
    ctx.fillText('OMEGA ABNORMAL', canvas.width / 2, 250);
    ctx.font = '900 14px Courier New, monospace';
    ctx.fillStyle = '#90caf9';
    ctx.fillText('(forma completamente innecesaria)', canvas.width / 2, 278);
    ctx.restore();
  }
  // the General, in the Bosque Lumina
  if (line.dgForest && cutscene.secretDg) {
    const divine = cutscene.secretDg;
    const x = 460;
    if (line.dgBush) {
      // upside down, legs out of a bush
      ctx.save();
      ctx.translate(x + divine.width / 2, ground - 20);
      ctx.rotate(Math.PI);
      divine.position = { x: -divine.width / 2, y: -divine.height + 30 };
      divine.attacksToTheRight = true;
      divine.isAttacking = false;
      divine.draw();
      ctx.restore();
      ctx.fillStyle = '#2e7d32';
      [[-30, 0, 46], [10, -10, 52], [44, 2, 40]].forEach(([dx, dy, r]) => {
        ctx.beginPath();
        ctx.arc(x + divine.width / 2 + dx, ground - 30 + dy, r, 0, Math.PI * 2);
        ctx.fill();
      });
    } else {
      divine.position = { x, y: ground - divine.height - (line.dgFall ? cutscene.dgFallY || 0 : 0) };
      divine.attacksToTheRight = true;
      divine.isAttacking = false;
      divine.draw();
      if (line.dgUp) {
        ctx.fillStyle = '#43a047';
        for (let leaf = 0; leaf < 5; leaf += 1) ctx.fillRect(x + 10 + leaf * 12, ground - divine.height - 4 + (leaf % 2) * 6, 6, 4);
      }
    }
  }
  // Tempus: Reflecter and the soldiers
  if (line.tempus) {
    (cutscene.robotActors || []).forEach((robot, index) => {
      const panic = line.soldierPanic ? Math.sin(time * 20 + index) * 4 : 0;
      robot.position = { x: 660 + index * 66 + panic, y: ground - robot.height - (line.soldierTalk === index ? Math.abs(Math.sin(time * 8)) * 6 : 0) };
      robot.attacksToTheRight = false;
      robot.isAttacking = false;
      robot.draw();
    });
    if (cutscene.reflActor) {
      const refl = cutscene.reflActor;
      refl.position = { x: 520, y: ground - refl.height };
      refl.attacksToTheRight = !(line.chronoDrop || line.chronoLying || line.chronoStand || line.chronoHere || line.chronoWalk || line.chronoGoneTempus);
      refl.isAttacking = false;
      refl.draw();
    }
    // Chrono falling... and lying on the floor
    if (line.chronoDrop || line.chronoLying || (line.chronoStand && (cutscene.standK || 0) < 1)) {
      const landed = line.chronoDrop ? cutscene.dropY || 0 : 0;
      const saved = { ...player1.position };
      if (line.chronoDrop && landed > 0) {
        player1.position = { x: 320, y: ground - player1.height - landed };
        player1.isAttacking = false;
        player1.draw();
      } else {
        const k = line.chronoStand ? cutscene.standK || 0 : 0;
        ctx.save();
        ctx.translate(320 + player1.width / 2, ground);
        ctx.rotate(-Math.PI / 2 * (1 - k));
        player1.position = { x: -player1.width / 2, y: -player1.height };
        player1.isAttacking = false;
        player1.draw();
        ctx.restore();
        if (line.chronoLying) {
          ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
          ctx.font = '900 16px Courier New, monospace';
          ctx.fillText('@', 360 + Math.sin(time * 4) * 10, ground - 70 + Math.cos(time * 4) * 6);
          ctx.fillText('*', 380 + Math.cos(time * 4) * 12, ground - 80 + Math.sin(time * 4) * 6);
        }
      }
      player1.position = saved;
    }
    (cutscene.debris || []).forEach((bit) => {
      ctx.fillStyle = '#90a4ae';
      ctx.fillRect(bit.x, bit.y, 4, 4);
    });
    if (line.chronoWalk && cutscene.gamblerX > -100) {
      const hx = cutscene.gamblerX + player1.width / 2;
      ctx.fillStyle = 'rgba(120, 120, 130, 0.85)';
      [[-16, 0, 14], [0, -6, 18], [16, 0, 14]].forEach(([dx, dy, r]) => {
        ctx.beginPath();
        ctx.arc(hx + dx, ground - player1.height - 30 + dy, r, 0, Math.PI * 2);
        ctx.fill();
      });
      if (Math.random() < 0.3) {
        ctx.fillStyle = '#90caf9';
        ctx.fillRect(hx - 10 + Math.random() * 20, ground - player1.height - 18, 2, 6);
      }
    }
  }
  if ((cutscene.whiteK || 0) > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${cutscene.whiteK})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  if ((cutscene.fadeT || 0) > 0) {
    ctx.fillStyle = `rgba(0, 0, 0, ${cutscene.fadeT})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

// ---------- a new place in Tempus: the main lobby ----------
function drawTempusLobbyStage() {
  const time = performance.now() / 1000;
  const wall = ctx.createLinearGradient(0, 0, 0, ground);
  wall.addColorStop(0, '#1c2733');
  wall.addColorStop(1, '#2c3e50');
  ctx.fillStyle = wall;
  ctx.fillRect(0, 0, canvas.width, ground);
  // steel panels
  ctx.strokeStyle = 'rgba(144, 164, 174, 0.25)';
  ctx.lineWidth = 2;
  for (let panel = 0; panel < canvas.width; panel += 96) ctx.strokeRect(panel + 4, 40, 88, ground - 160);
  // the giant logo: a clock with the name, its hands ticking
  const lx = canvas.width / 2;
  ctx.fillStyle = '#0d1b2a';
  ctx.beginPath();
  ctx.arc(lx, 150, 90, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#26c6da';
  ctx.lineWidth = 6;
  ctx.stroke();
  for (let mark = 0; mark < 12; mark += 1) {
    const a = (mark / 12) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(lx + Math.cos(a) * 70, 150 + Math.sin(a) * 70);
    ctx.lineTo(lx + Math.cos(a) * 84, 150 + Math.sin(a) * 84);
    ctx.stroke();
  }
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(lx, 150);
  ctx.lineTo(lx + Math.cos(Math.floor(time) * Math.PI / 30 - Math.PI / 2) * 64, 150 + Math.sin(Math.floor(time) * Math.PI / 30 - Math.PI / 2) * 64);
  ctx.stroke();
  ctx.fillStyle = '#26c6da';
  ctx.fillRect(lx - 170, 250, 340, 34);
  ctx.fillStyle = '#0d1b2a';
  ctx.font = '900 22px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillText('TEMPUS CORP.', lx, 274);
  ctx.textAlign = 'left';
  // glass elevator tubes with cabins going up and down
  [70, canvas.width - 130].forEach((ex, index) => {
    ctx.fillStyle = 'rgba(178, 235, 242, 0.12)';
    ctx.fillRect(ex, 30, 60, ground - 30);
    ctx.strokeStyle = 'rgba(178, 235, 242, 0.5)';
    ctx.strokeRect(ex, 30, 60, ground - 30);
    const cabin = 60 + ((Math.sin(time * 0.5 + index * 2) + 1) / 2) * (ground - 160);
    ctx.fillStyle = '#455a64';
    ctx.fillRect(ex + 4, cabin, 52, 70);
    ctx.fillStyle = '#ffd54f';
    ctx.fillRect(ex + 10, cabin + 10, 40, 18);
  });
  // the "employee of the month" banner
  ctx.fillStyle = '#37474f';
  ctx.fillRect(200, 60, 150, 110);
  ctx.strokeStyle = '#ffd54f';
  ctx.strokeRect(200, 60, 150, 110);
  ctx.fillStyle = '#ffd54f';
  ctx.font = '900 11px Courier New, monospace';
  ctx.fillText('EMPLEADO DEL MES', 214, 80);
  ctx.fillStyle = '#90a4ae';
  ctx.fillRect(250, 92, 50, 50);
  ctx.fillStyle = '#ff5252';
  ctx.fillRect(262, 108, 26, 6);
  ctx.fillStyle = '#ffffff';
  ctx.fillText('ROBOT #42', 240, 160);
  // a security camera that follows... nothing
  ctx.fillStyle = '#263238';
  ctx.fillRect(canvas.width - 300, 40, 40, 20);
  ctx.fillStyle = Math.floor(time * 2) % 2 ? '#ff1744' : '#4a0010';
  ctx.beginPath();
  ctx.arc(canvas.width - 270, 50, 4, 0, Math.PI * 2);
  ctx.fill();
  // the reception desk
  ctx.fillStyle = '#263238';
  ctx.fillRect(lx - 140, ground - 70, 280, 70);
  ctx.fillStyle = '#26c6da';
  ctx.fillRect(lx - 140, ground - 74, 280, 6);
  ctx.fillStyle = '#90a4ae';
  ctx.font = '900 12px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillText('RECEPCION - "EL TIEMPO ES DINERO"', lx, ground - 36);
  ctx.textAlign = 'left';
  // plants
  [170, canvas.width - 220].forEach((px) => {
    ctx.fillStyle = '#5d4037';
    ctx.fillRect(px, ground - 40, 30, 40);
    ctx.fillStyle = '#2e7d32';
    [[-6, -54], [15, -66], [34, -52]].forEach(([dx, dy]) => {
      ctx.beginPath();
      ctx.ellipse(px + dx, ground + dy, 12, 26, dx / 30, 0, Math.PI * 2);
      ctx.fill();
    });
  });
  // the glossy floor
  const floor = ctx.createLinearGradient(0, ground, 0, canvas.height);
  floor.addColorStop(0, '#546e7a');
  floor.addColorStop(1, '#263238');
  ctx.fillStyle = floor;
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
  for (let tile = 0; tile < canvas.width; tile += 64) {
    ctx.beginPath();
    ctx.moveTo(tile, ground);
    ctx.lineTo(tile - 30, canvas.height);
    ctx.stroke();
  }
  ctx.fillStyle = '#26c6da';
  ctx.fillRect(0, ground, canvas.width, 3);
}

function drawLightWorldStage() {
  const time = performance.now() / 1000;
  const sky = ctx.createLinearGradient(0, 0, 0, ground);
  sky.addColorStop(0, '#fff8e1');
  sky.addColorStop(0.6, '#e3f2fd');
  sky.addColorStop(1, '#bbdefb');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, ground);
  for (let cloud = 0; cloud < 6; cloud += 1) {
    const cx = ((time * 10 + cloud * 200) % (canvas.width + 200)) - 100;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
    ctx.beginPath();
    ctx.ellipse(cx, 90 + (cloud % 3) * 60, 90, 24, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = '#fffde7';
  ctx.fillRect(0, ground, canvas.width, canvas.height - ground);
}

