function renderAbnormalRulesTable(quote) {
  const modal = abnRulesTable.modal;
  if (!modal) return;
  const rules = getAbnormalRules();
  const hand = modal.querySelector('.abn-rules-hand');
  hand.innerHTML = '';
  rules.forEach((id, index) => {
    const info = abnRuleCardInfo[id];
    const rule = getAbnAllRules().find((item) => item.id === id);
    const tag = abnRuleWhoTags[rule.who] || abnRuleWhoTags.all;
    const card = document.createElement('button');
    card.type = 'button';
    card.className = `abn-slot-card suit-${index}${index === abnRulesTable.slot ? ' selected' : ''}`;
    card.innerHTML = `
      <span class="abn-slot-key">${index + 1}</span>
      <span class="abn-slot-suit" aria-hidden="true">${abnSlotSymbols[index]}</span>
      <strong>${info.name}</strong>
      <small class="${tag.cls}">${tag.label}</small>
      <span class="abn-slot-corner" aria-hidden="true">${abnSlotSymbols[index]}</span>`;
    card.addEventListener('click', () => {
      abnRulesTable.slot = index;
      renderAbnormalRulesTable(`Carta ${index + 1}: elegi su nueva regla abajo.`);
    });
    hand.appendChild(card);
  });
  const deck = modal.querySelector('.abn-rules-deck');
  deck.innerHTML = '';
  getAbnAllRules().forEach((rule) => {
    const info = abnRuleCardInfo[rule.id];
    const tag = abnRuleWhoTags[rule.who] || abnRuleWhoTags.all;
    const used = rules.indexOf(rule.id);
    const card = document.createElement('button');
    card.type = 'button';
    card.className = `abn-rule-card ${tag.cls}${used >= 0 ? ` in-hand suit-${used}` : ''}${info.fresh ? ' fresh' : ''}`;
    card.innerHTML = `
      <small>${tag.label}</small>${info.fresh ? '<em class="abn-rule-new">NUEVA</em>' : ''}
      <strong>${info.name}</strong>
      <span>${info.desc}</span>
      ${used >= 0 ? `<b class="abn-rule-badge">${used + 1}</b>` : ''}`;
    card.addEventListener('click', () => {
      const current = getAbnormalRules();
      const slot = abnRulesTable.slot;
      const other = current.indexOf(rule.id);
      // (a card already in the hand trades places with the chosen one)
      if (other >= 0 && other !== slot) current[other] = current[slot];
      current[slot] = rule.id;
      saveAbnormalRules(current);
      abnRulesTable.slot = (slot + 1) % 4;
      playTone({ frequency: 520 + slot * 90, duration: 0.09, type: 'square', volume: 0.04 });
      renderAbnormalRulesTable(`"${rule.comment}"`);
    });
    deck.appendChild(card);
  });
  modal.querySelector('.abn-rules-quote').innerText = quote || '"¡JO JO! Una buena mano gana cualquier pelea. Una MALA mano... tambien, si la juego yo."';
}

