// ================= playing AS Abnormal: his rules on 1, 2, 3 and 4 =================
const abnPlay = { rule: null, t: 0, cooldowns: [0, 0, 0, 0], owner: null, base: null, adaptHits: 0, card: 0 };
const abnPlayRuleFrames = 360;
const abnPlayCooldown = 900;

function isAbnormalPlayer(fighter) {
  return Boolean(fighter && fighter.secretVariant === 'abnormal' && !(typeof isChronoChapterFight === 'function' && isChronoChapterFight()));
}

function getAbnPlayOpponent() {
  return abnPlay.owner === player1 ? player2 : player1;
}

function endAbnPlayRule() {
  if (!abnPlay.rule) return;
  const owner = abnPlay.owner;
  const opponent = getAbnPlayOpponent();
  if (abnPlay.base) {
    owner.moveSpeed = abnPlay.base.owner;
    opponent.moveSpeed = abnPlay.base.opponent;
  }
  owner.giantScale = 1;
  opponent.giantScale = 1;
  abnPlay.bomb = null;
  abnPlay.cards = [];
  abnPlay.rule = null;
}

function tryAbnPlayerRule(slot) {
  if (!gameStarted || gameOver || arcadeCutscene.active || !isAbnormalPlayer(player1)) return false;
  const index = slot - 1;
  if (abnPlay.cooldowns[index] > 0) {
    showFlametombThought(player1, '¡Esa regla todavia se esta escribiendo!');
    return true;
  }
  const id = getAbnormalRules()[index];
  const rule = getAbnAllRules().find((item) => item.id === id);
  if (!rule) return true;
  endAbnPlayRule();
  abnPlay.owner = player1;
  abnPlay.rule = rule;
  abnPlay.t = 0;
  abnPlay.card = 100;
  abnPlay.adaptHits = 0;
  abnPlay.cooldowns[index] = abnPlayCooldown;
  const opponent = getAbnPlayOpponent();
  abnPlay.base = { owner: player1.moveSpeed, opponent: opponent.moveSpeed };
  if (id === 'abnSpeed') player1.moveSpeed *= 1.6;
  if (id === 'kaioken') opponent.moveSpeed *= 1.3;
  if (id === 'statsUp') opponent.moveSpeed *= 1.5;
  if (id === 'giant') player1.giantScale = 1.5;
  if (id === 'tiny') opponent.giantScale = 0.55;
  if (id === 'mirrorControls') abnPlay.prevX = opponent.position.x;
  if (id === 'cardRain') abnPlay.cards = [];
  if (id === 'hotPotato') abnPlay.bomb = opponent;
  if (id === 'shareLife') {
    // (one moment: both health bars meet in the middle)
    const ratio = (player1.health / player1.maxHealth + opponent.health / opponent.maxHealth) / 2;
    player1.health = Math.max(1, player1.maxHealth * ratio);
    opponent.health = Math.max(1, opponent.maxHealth * ratio);
    abnPlay.flash = 1;
    updateHealthBars();
  }
  showFlametombThought(player1, rule.comment);
  [392, 523, 659].forEach((frequency, index2) => setTimeout(() => playTone({ frequency, duration: 0.14, type: 'square', volume: 0.05 }), index2 * 90));
  return true;
}

function updateAbnPlayerRules() {
  // (the Supreme Guard plays fair... ish: no boss health outside his hall fight)
  [player1, player2].forEach((fighter) => {
    if (isAbnormalPlayer(fighter) && !normalArcadeActive && fighter.maxHealth > 160 && !fighter.dwGiantSaved) {
      fighter.setMaxHealth(160);
      fighter.health = Math.min(fighter.health, 160);
      updateHealthBars();
    }
  });
  abnPlay.cooldowns = abnPlay.cooldowns.map((value) => Math.max(0, value - 1));
  if (abnPlay.card > 0) abnPlay.card -= 1;
  const rule = abnPlay.rule;
  if (!rule) return;
  if (gameOver || !isAbnormalPlayer(abnPlay.owner)) {
    endAbnPlayRule();
    return;
  }
  abnPlay.t += 1;
  if (abnPlay.t >= abnPlayRuleFrames) {
    endAbnPlayRule();
    return;
  }
  const owner = abnPlay.owner;
  const opponent = getAbnPlayOpponent();
  updateAbnExtraRule(rule, owner, opponent);
  if (rule.id === 'lowGravity') {
    [owner, opponent].forEach((fighter) => {
      if (fighter.position.y + fighter.height < ground - 1) fighter.velocity.y -= gravity * 0.5;
    });
  } else if (rule.id === 'smallArena') {
    [owner, opponent].forEach((fighter) => {
      fighter.position.x = Math.max(210, Math.min(canvas.width - 210 - fighter.width, fighter.position.x));
    });
  } else if (rule.id === 'teleport' && abnPlay.t % 90 === 45) {
    const side = getFighterCenterX(owner) > getFighterCenterX(opponent) ? -1 : 1;
    owner.position.x = Math.max(20, Math.min(canvas.width - 20 - owner.width, getFighterCenterX(opponent) + side * 120 - owner.width / 2));
    owner.attacksToTheRight = side < 0;
    playNoise({ duration: 0.2, volume: 0.06, filterFrequency: 4000 });
  } else if (rule.id === 'kaioken') {
    if (opponent.health > 20) opponent.health -= 0.05;
  } else if (rule.id === 'noJump') {
    if (opponent.velocity.y < 0 && opponent.position.y + opponent.height >= ground - 2) opponent.velocity.y = 0;
  } else if (rule.id === 'stillHeal') {
    [owner, opponent].forEach((fighter) => {
      if (Math.abs(fighter.velocity.x) < 0.2 && !fighter.isAttacking && fighter.position.y + fighter.height >= ground - 1) fighter.health = Math.min(fighter.maxHealth, fighter.health + 0.12);
    });
  }
  if (abnPlay.t % 10 === 0) updateHealthBars();
}

// (applyDamage asks this)
function abnPlayerRuleScale(attacker, target) {
  const rule = abnPlay.rule;
  if (!rule || !abnPlay.owner) return 1;
  const owner = abnPlay.owner;
  const opponent = getAbnPlayOpponent();
  switch (rule.id) {
    case 'abnHalf':
      return target === owner ? 0.5 : 1;
    case 'chronoDouble':
      return attacker === opponent ? 2 : 1;
    case 'luck':
      if (target === owner && Math.random() < 0.35) {
        showScamLabel(owner, '¡ESQUIVADO!');
        return 0;
      }
      return 1;
    case 'fireFists':
      return attacker === opponent ? 1.5 : 1;
    case 'giant':
      return attacker === owner ? 1.3 : 1;
    case 'vampire':
      if (attacker === opponent) opponent.health = Math.min(opponent.maxHealth, opponent.health + 5);
      return 1;
    case 'kaioken':
      return attacker === opponent ? 1.6 : 1;
    case 'adapt':
      if (target !== owner) return 1;
      abnPlay.adaptHits += 1;
      return Math.max(0.3, 1 - abnPlay.adaptHits * 0.12);
    case 'oops':
      if (attacker === owner && target === opponent) {
        opponent.health = Math.min(opponent.maxHealth, opponent.health + 6);
        return 0;
      }
      return 1;
    case 'tiny':
      return attacker === opponent ? 0.5 : 1;
    case 'disco':
      return attacker === owner ? 1.2 : 1;
    case 'hotPotato':
      // a hit passes the bomb
      if (abnPlay.bomb && attacker === abnPlay.bomb && target !== attacker && abnPlay.t < 300) {
        abnPlay.bomb = target;
        playTone({ frequency: 1200, duration: 0.08, type: 'square', volume: 0.05 });
      }
      return 1;
    case 'statsUp':
      if (attacker === opponent) return 1.5;
      if (target === opponent) return 0.67;
      return 1;
    default:
      return 1;
  }
}

function drawAbnPlayerRules() {
  if (!isAbnormalPlayer(player1)) return;
  const rules = getAbnormalRules();
  ctx.save();
  // the four slots
  rules.forEach((id, index) => {
    const x = 16 + index * 58;
    const y = canvas.height - 64;
    const ready = abnPlay.cooldowns[index] <= 0;
    const active = abnPlay.rule && abnPlay.rule.id === id;
    ctx.fillStyle = active ? 'rgba(144, 202, 249, 0.85)' : 'rgba(5, 10, 30, 0.8)';
    ctx.fillRect(x, y, 52, 48);
    ctx.strokeStyle = ready ? '#90caf9' : '#455a64';
    ctx.lineWidth = 2;
    ctx.strokeRect(x, y, 52, 48);
    if (!ready) {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
      ctx.fillRect(x, y, 52, 48 * (abnPlay.cooldowns[index] / abnPlayCooldown));
    }
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 16px Courier New, monospace';
    ctx.fillText(String(index + 1), x + 4, y + 16);
    drawAbnormalSuit(abnormalSuits[index], x + 34, y + 30, 9, abnormalSuitColors[abnormalSuits[index]]);
  });
  const rule = abnPlay.rule;
  if (rule) {
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(5, 10, 30, 0.8)';
    ctx.fillRect(canvas.width / 2 - 280, 112, 560, 40);
    ctx.strokeStyle = '#90caf9';
    ctx.strokeRect(canvas.width / 2 - 280, 112, 560, 40);
    ctx.fillStyle = '#90caf9';
    ctx.font = '900 11px Courier New, monospace';
    ctx.fillText('REGLA DE ABNORMAL', canvas.width / 2, 126);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 13px Courier New, monospace';
    ctx.fillText(rule.title, canvas.width / 2, 144);
    ctx.fillStyle = '#90caf9';
    ctx.fillRect(canvas.width / 2 - 280, 150, 560 * (1 - abnPlay.t / abnPlayRuleFrames), 2);
    drawAbnExtraRule(rule);
    if (rule.id === 'smallArena') {
      ctx.fillStyle = 'rgba(13, 22, 64, 0.85)';
      ctx.fillRect(0, 0, 205, ground);
      ctx.fillRect(canvas.width - 205, 0, 205, ground);
    }
    if (rule.id === 'hats') {
      [player1, player2].forEach((fighter, index) => {
        const cx = fighter.position.x + fighter.width / 2;
        const top = fighter.position.y + fighter.height - fighter.height * (fighter.giantScale || 1);
        ctx.fillStyle = index ? '#ff4081' : '#ffd54f';
        ctx.beginPath();
        ctx.moveTo(cx - 16, top + 2);
        ctx.lineTo(cx, top - 40);
        ctx.lineTo(cx + 16, top + 2);
        ctx.closePath();
        ctx.fill();
      });
    }
  }
  ctx.restore();
}

