function clearAbnormalCameo() {
  abnCameo.pending = null;
  abnCameo.active = false;
  abnCameo.watching = false;
  abnCameo.gone = false;
  abnCameo.hammer = null;
  abnCameo.launch = null;
  abnCameo.bubble = null;
  abnCameo.music = false;
  abnCameo.bravo = false;
  abnCameo.titanRuleDone = false;
  if (typeof resetDarkworldFight === 'function') resetDarkworldFight();
  abnCameo.resumeCutscene = false;
  document.body.classList.remove('titan-giant-fight');
  abnCameo.toss = null;
  abnCameo.pops = [];
  abnCameo.guest = null;
  abnCameo.noBucket = false;
  abnCameo.helpWin = false;
  abnCameo.gifts = null;
  setAbnCameoCinematic(false);
}

// his visits are real cinematics: no health bars over the dialog
function setAbnCameoCinematic(on) {
  if (on) document.body.classList.add('arcade-cutscene');
  else if (!arcadeCutscene.active) document.body.classList.remove('arcade-cutscene');
}

function rollAbnormalCameo() {
  if (!isAbnormalUnlocked() || !normalArcadeActive || arcadeRouteB) return null;
  const forced = window.abnCameoForce;
  const roll = (chance) => forced === true || (forced !== false && Math.random() < chance);
  if (arcadeChapter === 'normal' && selectedNormalArcadeLevel === 3) return roll(abnCameoChance) ? 'normalMeet' : null;
  if (arcadeChapter === 'fireMaster' && selectedNormalArcadeLevel === 3) return roll(abnCameoChance) ? 'popcornFire' : null;
  if (arcadeChapter === 'gambler' && selectedNormalArcadeLevel === 5) return roll(abnCameoChance) ? 'casino' : null;
  if (arcadeChapter === 'reflecter' && selectedNormalArcadeLevel === 7) return roll(abnCameoChance) ? 'hammer' : null;
  if (arcadeChapter === 'knight' && selectedNormalArcadeLevel >= 1 && selectedNormalArcadeLevel <= 7) {
    if (!roll(abnCameoKnightChance)) return null;
    return `knight${selectedNormalArcadeLevel}`;
  }
  return null;
}

function queueAbnormalCameo() {
  clearAbnormalCameo();
  const kind = rollAbnormalCameo();
  if (!kind) return;
  abnCameo.pending = kind;
  abnCameo.wait = 45;
  // (level 7: he waits until both of them have landed on the bridge)
  if (kind === 'knight7') abnCameo.wait = 90;
}

function startAbnormalCameo(kind) {
  abnCameo.pending = null;
  abnCameo.active = true;
  abnCameo.kind = kind;
  abnCameo.lines = abnCameoScenes[kind];
  abnCameo.index = -1;
  abnCameo.t = 0;
  abnCameo.actor = abnCameo.actor || makeChronoCameoAbnormal();
  abnCameo.music = true;
  abnCameo.gone = false;
  setAbnCameoCinematic(true);
  // he lands between the two fighters (on the hammer's way, of course)
  const middle = (getFighterCenterX(player1) + getFighterCenterX(player2)) / 2;
  abnCameo.x = Math.max(120, Math.min(canvas.width - 180, middle - abnCameo.actor.width / 2));
  if (Math.abs(getFighterCenterX(player1) - getFighterCenterX(player2)) < 160) abnCameo.x = getFighterCenterX(player1) < canvas.width / 2 ? canvas.width - 220 : 160;
  abnCameo.y = 420;
  abnCameoNextLine();
}

function abnCameoNextLine() {
  abnCameo.index += 1;
  abnCameo.typed = 0;
  abnCameo.lineT = 0;
  const line = abnCameo.lines[abnCameo.index];
  if (!line) {
    endAbnormalCameoScene();
    return;
  }
  if (line.descend) {
    abnCameo.y = 420;
    abnCameo.beam = 1;
    abnCameo.flash = 1;
    playNoise({ duration: 0.8, volume: 0.1, filterFrequency: 5000 });
    playTone({ frequency: 1200, duration: 1.2, type: 'sine', volume: 0.05, slideTo: 300 });
  }
  if (line.ascend) {
    abnCameo.launch = { kind: 'ascend', t: 0 };
    abnCameo.beam = 1;
    abnCameo.flash = 0.8;
    playNoise({ duration: 0.8, volume: 0.1, filterFrequency: 5000 });
    playTone({ frequency: 300, duration: 1.2, type: 'sine', volume: 0.05, slideTo: 1200 });
  }
  if (line.hammer) {
    // Omegarius doesn't even look: the hammer flies
    const owner = isOmegarius(player2) ? player2 : player1;
    const head = getOmegariusHammerHead(owner);
    abnCameo.hammer = { owner, x: head.x, y: head.y, t: 0, back: false, hit: false };
    playSound('judgeThrow');
  }
  if (line.gone) {
    abnCameo.gone = true;
    abnCameo.music = false;
  }
  if (line.toss) {
    abnCameo.toss = { target: line.toss === 'p1' ? player1 : player2, card: line.card || 'A', eat: Boolean(line.eat), t: 0, done: false };
    playTone({ frequency: 700, duration: 0.2, type: 'triangle', volume: 0.04, slideTo: 1100 });
  } else if (abnCameo.toss && abnCameo.toss.eat) {
    abnCameo.toss = null;
  }
  if (line.pop) {
    abnCameo.pops = [];
    abnCameo.popT = 0;
    playSound('fireball');
  }
  if (line.shock) playTone({ frequency: 980, duration: 0.18, type: 'square', volume: 0.04 });
  if (line.giantRule && typeof applyTitanGiantRule === 'function') applyTitanGiantRule();
}

function endAbnormalCameoScene() {
  abnCameo.active = false;
  if (abnCameo.kind === 'titanRuleLW' && typeof startTitanOmegaShowdown === 'function') startTitanOmegaShowdown();
  if (abnCameo.resumeCutscene) {
    abnCameo.resumeCutscene = false;
    arcadeCutscene.active = true;
  }
  setAbnCameoCinematic(false);
  abnCameo.hammer = null;
  abnCameo.launch = null;
  const line = abnCameo.lines[abnCameo.lines.length - 1];
  if (line.popcorn) {
    // he stays at the edge of the stage with his bucket (and his music)
    abnCameo.watching = true;
    abnCameo.music = true;
    abnCameo.x = getFighterCenterX(player1) < canvas.width / 2 ? canvas.width - 96 : 30;
    abnCameo.lastHealth = player1.health + player2.health;
    abnCameo.bubble = { text: '*crunch crunch*', t: 120 };
    return;
  }
  abnCameo.gone = true;
  abnCameo.music = false;
}

function advanceAbnormalCameo() {
  if (!abnCameo.active) return false;
  const line = abnCameo.lines[abnCameo.index];
  if (!line) return false;
  if (abnCameo.typed < line.text.length) {
    abnCameo.typed = line.text.length;
    return true;
  }
  // (the scene waits for the light, the hammer and the flight)
  if (line.descend && abnCameo.y > 0) return true;
  if (line.hammer && !(abnCameo.launch && abnCameo.launch.t > 50)) return true;
  if (line.ascend && !(abnCameo.launch && abnCameo.launch.t > 60)) return true;
  abnCameoNextLine();
  return true;
}

function handleAbnCameoKey(event) {
  if (!abnCameo.active) return false;
  if (event.key === 'Enter' || event.key === ' ') {
    if (!event.repeat) advanceAbnormalCameo();
    return true;
  }
  return false;
}

function abnCameoMusicKey() {
  return Boolean((normalArcadeActive || String(abnCameo.kind || '').startsWith('titanRule')) && gameStarted && !gameOver && abnCameo.music && (abnCameo.active || abnCameo.watching));
}

// the animate loop asks this before the fight runs: true = the fight is frozen
function updateAbnormalCameo() {
  if (!gameStarted || gameOver) return false;
  if (abnCameo.helpWin) {
    abnCameo.helpWin = false;
    player2.duoActive = false;
    player2.duoPartnerActor = null;
    player2.health = 0;
    player2.position = { x: canvas.width + 400, y: ground - player2.height };
    normalArcadeEnemiesRemaining = 0;
    updateHealthBars();
    return false;
  }
  if (abnCameo.pending) {
    abnCameo.wait -= 1;
    if (abnCameo.wait <= 0) startAbnormalCameo(abnCameo.pending);
  }
  if (!abnCameo.active) return false;
  abnCameo.t += 1;
  abnCameo.lineT += 1;
  const line = abnCameo.lines[abnCameo.index];
  if (!line) return false;
  if (!document.body.classList.contains('arcade-cutscene')) setAbnCameoCinematic(true);
  abnCameo.typed = Math.min(line.text.length, abnCameo.typed + 1.1);
  if (abnCameo.y > 0 && (line.descend || abnCameo.index > 0)) abnCameo.y = Math.max(0, abnCameo.y - 6);
  if (abnCameo.beam > 0 && !line.descend && !line.ascend) abnCameo.beam = Math.max(0, abnCameo.beam - 0.025);
  if (abnCameo.flash > 0) abnCameo.flash = Math.max(0, abnCameo.flash - 0.035);
  if (line.popcorn) abnCameo.munch += 1;
  updateAbnCameoHammer();
  if (abnCameo.launch) abnCameo.launch.t += 1;
  // (on a phone there is no Enter: the text moves on by itself)
  const ready = abnCameo.typed >= line.text.length;
  if (ready && abnCameo.lineT > line.text.length / 1.1 + 200) advanceAbnormalCameo();
  drawStage();
  player1.draw();
  player2.draw();
  drawAbnormalCameoActor();
  drawAbnCameoProps(line);
  drawAbnCameoDialog(line);
  return true;
}

function updateAbnCameoHammer() {
  const hammer = abnCameo.hammer;
  if (!hammer) return;
  hammer.t += 1;
  const targetX = abnCameo.x + abnCameo.actor.width / 2;
  const targetY = ground - abnCameo.actor.height * 0.7;
  if (!hammer.hit) {
    hammer.x += (targetX - hammer.x) * 0.22;
    hammer.y += (targetY - hammer.y) * 0.22;
    if (Math.hypot(targetX - hammer.x, targetY - hammer.y) < 26 || hammer.t > 24) {
      hammer.hit = true;
      abnCameo.flash = 0.9;
      abnCameo.music = false;
      abnCameo.launch = { kind: 'hammer', t: 0, dir: getFighterCenterX(hammer.owner) > targetX ? -1 : 1 };
      playSound('judgeHammerHit');
      playNoise({ duration: 0.4, volume: 0.14, filterFrequency: 900 });
      playTone({ frequency: 880, duration: 0.9, type: 'triangle', volume: 0.05, slideTo: 1600 });
    }
    return;
  }
  // back to its owner's hand
  const home = getOmegariusHammerHead(hammer.owner);
  hammer.x += (home.x - hammer.x) * 0.16;
  hammer.y += (home.y - hammer.y) * 0.16;
  if (Math.hypot(home.x - hammer.x, home.y - hammer.y) < 14) abnCameo.hammer = null;
}

function drawAbnCameoBeam(x, k) {
  if (k <= 0) return;
  const beam = ctx.createLinearGradient(x - 50, 0, x + 50, 0);
  beam.addColorStop(0, 'rgba(255, 255, 255, 0)');
  beam.addColorStop(0.5, `rgba(255, 255, 255, ${0.55 * k})`);
  beam.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = beam;
  ctx.fillRect(x - 50, 0, 100, ground);
}

function drawAbnormalCameoActor() {
  const actor = abnCameo.actor;
  if (!actor) return;
  const line = abnCameo.active ? abnCameo.lines[abnCameo.index] : null;
  const centerX = abnCameo.x + actor.width / 2;
  ctx.save();
  if (abnCameo.active) drawAbnCameoBeam(centerX, abnCameo.beam);
  if (!abnCameo.gone) {
    let x = abnCameo.x;
    let y = ground - actor.height - abnCameo.y;
    let spin = 0;
    const launch = abnCameo.launch;
    if (launch && launch.kind === 'hammer') {
      // off he goes, spinning, into the sky... and a little star
      x += launch.dir * launch.t * 11;
      y -= launch.t * 9 - launch.t * launch.t * 0.02;
      spin = launch.t * 0.35 * launch.dir;
    } else if (launch && launch.kind === 'ascend') {
      y -= Math.min(560, launch.t * launch.t * 0.14);
    } else if (line && line.windup) {
      x += Math.sin(abnCameo.t * 0.6) * 2;
    }
    actor.attacksToTheRight = getFighterCenterX(player1) > centerX;
    if (abnCameo.watching) actor.attacksToTheRight = abnCameo.x < canvas.width / 2;
    actor.isAttacking = false;
    ctx.save();
    ctx.translate(x + actor.width / 2, y + actor.height / 2);
    ctx.rotate(spin);
    actor.position = { x: -actor.width / 2, y: -actor.height / 2 };
    actor.draw();
    if ((line && (line.popcorn || line.bucket)) || (abnCameo.watching && !abnCameo.noBucket)) drawAbnPopcorn(actor, line && line.bucket && !(abnCameo.popT > 40));
    ctx.restore();
    if (launch && launch.kind === 'hammer' && launch.t > 34) {
      const star = Math.max(0, 1 - (launch.t - 34) / 40);
      const sx = abnCameo.x + launch.dir * 380;
      ctx.fillStyle = `rgba(255, 255, 255, ${star})`;
      ctx.beginPath();
      ctx.moveTo(sx, 40);
      ctx.lineTo(sx + 7, 54);
      ctx.lineTo(sx, 68);
      ctx.lineTo(sx - 7, 54);
      ctx.closePath();
      ctx.fill();
    }
  }
  // the hammer in flight
  const hammer = abnCameo.hammer;
  if (hammer) drawOmegariusHammer(hammer.x, hammer.y + 50, hammer.t * 0.6, 0.85, 1.4);
  if (abnCameo.flash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${abnCameo.flash})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  ctx.restore();
}

// his popcorn bucket (red and white, of course, it is a SHOW)
function drawAbnPopcorn(actor, raw = false) {
  const dir = actor.attacksToTheRight ? 1 : -1;
  const bx = actor.position.x + actor.width / 2 + dir * 22 - 14;
  const by = actor.position.y + actor.height * 0.5;
  ctx.save();
  ctx.fillStyle = raw ? '#ffca28' : '#fff8e1';
  for (let index = 0; index < 7; index += 1) {
    ctx.beginPath();
    ctx.arc(bx + 3 + index * 3.6, by - 2 + Math.sin(index * 2.3) * 3, 4, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.beginPath();
  ctx.moveTo(bx - 2, by);
  ctx.lineTo(bx + 30, by);
  ctx.lineTo(bx + 25, by + 30);
  ctx.lineTo(bx + 3, by + 30);
  ctx.closePath();
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.fillStyle = '#e53935';
  [0, 1, 2].forEach((stripe) => {
    ctx.beginPath();
    const sx = bx + 1 + stripe * 10;
    ctx.moveTo(sx, by);
    ctx.lineTo(sx + 5, by);
    ctx.lineTo(sx + 4, by + 30);
    ctx.lineTo(sx + 1, by + 30);
    ctx.closePath();
    ctx.fill();
  });
  // a kernel on its way to his visor
  const cycle = abnCameo.munch % 70;
  if (cycle < 22) {
    const k = cycle / 22;
    const headX = actor.position.x + actor.width / 2 + dir * 8;
    const headY = actor.position.y + 28;
    ctx.fillStyle = '#fff8e1';
    ctx.beginPath();
    ctx.arc(bx + 14 + (headX - bx - 14) * k, by - 4 + (headY - by + 4) * k - Math.sin(k * Math.PI) * 26, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawAbnCameoDialog(line) {
  const speaker = abnCameoSpeakers[line.speaker] || abnCameoSpeakers.abnormal;
  ctx.save();
  ctx.fillStyle = 'rgba(5, 10, 30, 0.93)';
  ctx.fillRect(56, 60, 912, 112);
  ctx.strokeStyle = speaker.color;
  ctx.lineWidth = 4;
  ctx.strokeRect(56, 60, 912, 112);
  // the suits in the corners: it is HIS scene
  ctx.fillStyle = 'rgba(144, 202, 249, 0.35)';
  ctx.font = '900 16px Arial';
  ctx.textAlign = 'right';
  ctx.fillText('♠ ♥ ♦ ♣', 958, 82);
  ctx.fillStyle = speaker.color;
  ctx.fillRect(76, 46, 200, 28);
  ctx.fillStyle = '#111';
  ctx.font = '900 18px Courier New, monospace';
  ctx.textAlign = 'center';
  ctx.fillText(speaker.name, 176, 66);
  ctx.fillStyle = '#ffffff';
  ctx.font = '700 20px Arial';
  ctx.textAlign = 'left';
  drawWrappedText(line.text.slice(0, Math.floor(abnCameo.typed)), 84, 104, 850, 26);
  if (abnCameo.typed >= line.text.length && Math.floor(performance.now() / 350) % 2 === 0) {
    ctx.fillStyle = speaker.color;
    ctx.font = '900 14px Courier New, monospace';
    ctx.textAlign = 'right';
    ctx.fillText('ENTER >', 952, 160);
  }
  ctx.restore();
}

// behind the fighters: the spectator with his popcorn
function drawAbnormalSpectator() {
  if (!abnCameo.watching || abnCameo.active || !gameStarted) return;
  const actor = abnCameo.actor;
  abnCameo.munch += 1;
  abnCameo.y = 0;
  drawAbnormalCameoActor();
  // he reacts to the big hits
  const health = player1.health + player2.health;
  if (abnCameo.bubbleCooldown > 0) abnCameo.bubbleCooldown -= 1;
  if (!gameOver && abnCameo.lastHealth - health >= 9 && abnCameo.bubbleCooldown <= 0) {
    const cheers = abnCameoCheers[abnCameo.kind] || abnCameoCheers.default;
    abnCameo.bubble = { text: cheers[Math.floor(Math.random() * cheers.length)], t: 110 };
    abnCameo.bubbleCooldown = 200;
  }
  if (gameOver && !abnCameo.bravo) {
    abnCameo.bravo = true;
    abnCameo.bubble = { text: '¡BRAVO! ¡BRAVISIMO!', t: 400 };
  }
  abnCameo.lastHealth = health;
  const bubble = abnCameo.bubble;
  if (!bubble || bubble.t <= 0) return;
  bubble.t -= 1;
  const cx = abnCameo.x + actor.width / 2;
  const top = ground - actor.height - 30;
  ctx.save();
  ctx.font = '900 13px Arial';
  const width = ctx.measureText(bubble.text).width + 20;
  const bx = Math.max(6, Math.min(canvas.width - width - 6, cx - width / 2));
  ctx.globalAlpha = Math.min(1, bubble.t / 15);
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = '#0d1640';
  ctx.lineWidth = 2;
  ctx.fillRect(bx, top - 24, width, 24);
  ctx.strokeRect(bx, top - 24, width, 24);
  ctx.fillStyle = '#0d1640';
  ctx.textAlign = 'center';
  ctx.fillText(bubble.text, bx + width / 2, top - 7);
  ctx.restore();
}

canvas.addEventListener('click', () => {
  if (abnCameo.active) advanceAbnormalCameo();
});

// ================= RANDOM MAP =================
function pickRandomMap() {
  const options = Array.from(document.querySelectorAll('.map-option')).filter((button) => {
    const map = button.dataset.map;
    return map && map !== 'random' && !button.disabled && !button.classList.contains('hidden') && !button.classList.contains('locked') && !button.classList.contains('abn-hall-option') && button.offsetParent !== null;
  });
  if (!options.length) return null;
  return options[Math.floor(Math.random() * options.length)].dataset.map;
}

// what he shouts from the stands, depending on who he is watching
const abnCameoCheers = {
  default: ['¡OOOOH!', '¡Eso dolio hasta aca!', '¡JO JO! ¡Elegante!', '¡Otra! ¡OTRA!', '¡Ay! *crunch*', '¡Ese golpe merece un aplauso!'],
  normalMeet: ['¡VAMOS, NORMAL!', '¡Eso fue NORMALMENTE increible!', '¡Mi opuesto favorito!', '¡Usa la carta! ...No, no hace nada. Era de recuerdo.', '¡Lo comun tambien pega fuerte!', '¡Normal! ¡Normal! ¡NORMAL!'],
  popcornFire: ['¡Mas fuego! ¡Se me enfrian!', '¡Que calentito! *crunch*', '¡Eso estuvo a punto caramelo!', '¡JO JO! ¡Arde el show!'],
  knight1: ['¡Cuidado con la pluma! ¡LA PLUMA!', '¡Podale las ramas, caballero!', '*crunch* ...¿Ese arbusto me esta mirando?', '¡Caballero! ¡Mi rey de corazones vengara!'],
  knight3: ['¡Cuidado con el cuchillo!', '¡Niños, sin morder!', '*crunch nervioso*', '¡Que alguien llame al panadero! ...ah, no.'],
  knight6: ['¡Mi faro gira mejor!', '¡Ilumina ESO, guardian!', '¡JO JO! ¡Gratis y en primera fila!', '*crunch* ¡Que pelea!'],
};

// the little things in his scenes: the "!!", the cards, the popcorn fire
function drawAbnCameoProps(line) {
  const actor = abnCameo.actor;
  if (!actor || !line) return;
  const ax = abnCameo.x + actor.width / 2;
  const ay = ground - actor.height - abnCameo.y;
  ctx.save();
  if (line.shock && !abnCameo.gone) {
    const shake = (Math.random() - 0.5) * 4;
    // (the "!!" goes over whoever is surprised)
    if (line.speaker !== 'abnormal') {
      const who = ['knight', 'normal', 'gambler', 'fireMaster', 'reflecter'].includes(line.speaker) ? player1 : player2;
      ctx.font = 'bold 34px Arial';
      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 4;
      ctx.textAlign = 'center';
      ctx.strokeText('!!', getFighterCenterX(who) + shake, who.position.y - 14);
      ctx.fillText('!!', getFighterCenterX(who) + shake, who.position.y - 14);
      ctx.restore();
      return;
    }
    ctx.font = 'bold 34px Arial';
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 4;
    ctx.textAlign = 'center';
    ctx.strokeText('!!', ax + shake, ay - 14);
    ctx.fillText('!!', ax + shake, ay - 14);
  }
  // a card on its way (and maybe into somebody's mouth)
  const toss = abnCameo.toss;
  if (toss) {
    toss.t += 1;
    const target = toss.target;
    const tx = getFighterCenterX(target);
    const ty = target.position.y + target.height * 0.45;
    const k = Math.min(1, toss.t / 30);
    if (k >= 1 && !toss.done) {
      toss.done = true;
      if (toss.eat) {
        playNoise({ duration: 0.25, volume: 0.08, filterFrequency: 1200 });
        playNoise({ duration: 0.2, volume: 0.08, filterFrequency: 900, delay: 0.25 });
      } else {
        playTone({ frequency: 1300, duration: 0.12, type: 'triangle', volume: 0.04 });
      }
    }
    if (!(toss.eat && toss.done)) {
      const x = ax + (tx - ax) * k;
      const y = ay + 50 + (ty - ay - 50) * k - Math.sin(k * Math.PI) * 70;
      drawAbnCameoCard(x, y, toss.card, toss.done ? 0.2 : toss.t * 0.5, 0.6);
    }
  }
  // the high card game
  if (line.reveal) {
    const flip = Math.min(1, abnCameo.lineT / 14);
    drawAbnCameoCard(ax, ay - 60, 'A', 0, flip);
    if (abnCameo.index > abnCameo.lines.findIndex((entry) => entry.reveal)) drawAbnCameoCard(getFighterCenterX(player1), player1.position.y - 60, 'JOKER', 0, 1);
  }
  // Fire Master pops the corn
  if (line.pop) {
    abnCameo.popT = (abnCameo.popT || 0) + 1;
    const fx = getFighterCenterX(player1);
    const fy = player1.position.y + 40;
    if (abnCameo.popT < 40) {
      const k = abnCameo.popT / 40;
      const flame = ctx.createRadialGradient(fx + (ax - fx) * k, fy + (ay + 60 - fy) * k, 2, fx + (ax - fx) * k, fy + (ay + 60 - fy) * k, 22);
      flame.addColorStop(0, '#fff59d');
      flame.addColorStop(0.5, '#ff9800');
      flame.addColorStop(1, 'rgba(255, 61, 0, 0)');
      ctx.fillStyle = flame;
      ctx.beginPath();
      ctx.arc(fx + (ax - fx) * k, fy + (ay + 60 - fy) * k, 22, 0, Math.PI * 2);
      ctx.fill();
    } else if (abnCameo.popT < 110) {
      if (abnCameo.popT % 4 === 0) {
        abnCameo.pops.push({ x: ax + (Math.random() - 0.5) * 30, y: ay + 58, vx: (Math.random() - 0.5) * 4, vy: -4 - Math.random() * 4 });
        if (abnCameo.popT % 8 === 0) playTone({ frequency: 1500 + Math.random() * 600, duration: 0.04, type: 'square', volume: 0.03 });
      }
    }
    ctx.fillStyle = '#fff8e1';
    abnCameo.pops.forEach((pop) => {
      pop.x += pop.vx;
      pop.y += pop.vy;
      pop.vy += 0.3;
      ctx.beginPath();
      ctx.arc(pop.x, pop.y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
    abnCameo.pops = abnCameo.pops.filter((pop) => pop.y < ground);
  }
  ctx.restore();
}

function drawAbnCameoCard(x, y, value, spin, scaleX) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(spin);
  ctx.scale(Math.max(0.05, scaleX), 1);
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = '#0d1640';
  ctx.lineWidth = 2;
  ctx.fillRect(-18, -25, 36, 50);
  ctx.strokeRect(-18, -25, 36, 50);
  const joker = value === 'JOKER';
  const red = value === 'K';
  ctx.fillStyle = joker ? '#8e24aa' : red ? '#d32f2f' : '#0d1640';
  ctx.textAlign = 'center';
  ctx.font = joker ? '900 8px Courier New, monospace' : '900 13px Courier New, monospace';
  ctx.fillText(value, joker ? 0 : -9, joker ? -12 : -11);
  ctx.font = '900 20px Arial';
  ctx.fillText(joker ? '\u2605' : red ? '\u2665' : '\u2660', 0, 10);
  ctx.restore();
}

