function injectAbnGuestLines(lines, spec) {
  const result = [];
  lines.forEach((line, index) => {
    if (spec.before && spec.before[index]) result.push(...spec.before[index]);
    result.push(line);
    if (spec.after && spec.after[index]) result.push(...spec.after[index]);
  });
  if (spec.end) result.push(...spec.end);
  return result;
}

// (the chapter 5 scenes get his lines while he is watching)
['startKnightLightScene', 'startKnightSetoIntro', 'startKnightKidsTeam', 'startKnightGuardFall'].forEach((name) => {
  const original = window[name];
  if (typeof original !== 'function') return;
  window[name] = function abnGuestScene(...args) {
    const result = original.apply(this, args);
    if (abnCameo.watching && normalArcadeActive && arcadeChapter === 'knight' && arcadeCutscene.active && abnGuestLines[arcadeCutscene.scene]) {
      let spec = abnGuestLines[arcadeCutscene.scene];
      const helps = window.abnHelpForce === true || (window.abnHelpForce !== false && Math.random() < abnHelpChance);
      if (arcadeCutscene.scene === 'knightKidsTeam' && helps) spec = { after: spec.after, end: abnHelpLines };
      arcadeCutscene.lines = injectAbnGuestLines(arcadeCutscene.lines, spec);
      abnCameo.guest = arcadeCutscene.scene;
    }
    return result;
  };
});

function drawAbnormalCutsceneGuest() {
  if (!abnCameo.watching || !abnCameo.guest || !arcadeCutscene.active || arcadeCutscene.scene !== abnCameo.guest) return;
  const line = arcadeCutscene.lines[arcadeCutscene.lineIndex];
  if (abnCameo.fxLine !== arcadeCutscene.lineIndex) {
    abnCameo.fxLine = arcadeCutscene.lineIndex;
    abnCameo.fxT = 0;
    if (line && line.abnCharge) playTone({ frequency: 200 + (line.abnCharge - 1) * 160, duration: 1.4, type: 'sawtooth', volume: 0.04, slideTo: 500 + line.abnCharge * 200 });
    if (line && line.abnFire) playNoise({ duration: 0.7, volume: 0.1, filterFrequency: 3000 });
  }
  abnCameo.fxT += 1;
  if (line && line.helpWin) abnCameo.helpWin = true;
  if (line && (line.abnCharge || line.abnFire || line.abnGifts)) drawAbnHelpFx(line);
  if (line && line.abnDrop) abnCameo.noBucket = true;
  abnCameo.munch += 1;
  abnCameo.y = 0;
  drawAbnormalCameoActor();
  const actor = abnCameo.actor;
  const cx = abnCameo.x + actor.width / 2;
  ctx.save();
  if (abnCameo.noBucket) {
    // the bucket on the floor, popcorn everywhere
    const dir = abnCameo.x < canvas.width / 2 ? 1 : -1;
    const bx = cx + dir * 46;
    ctx.save();
    ctx.translate(bx, ground - 10);
    ctx.rotate(dir * 1.3);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-12, -14, 24, 28);
    ctx.fillStyle = '#e53935';
    ctx.fillRect(-8, -14, 5, 28);
    ctx.fillRect(3, -14, 5, 28);
    ctx.restore();
    ctx.fillStyle = '#fff8e1';
    for (let index = 0; index < 9; index += 1) {
      ctx.beginPath();
      ctx.arc(bx + dir * (14 + index * 7), ground - 3 - (index % 3), 3.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  if (line && line.abnShock) {
    ctx.font = 'bold 34px Arial';
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 4;
    ctx.textAlign = 'center';
    ctx.strokeText('!!', cx, ground - actor.height - 14);
    ctx.fillText('!!', cx, ground - actor.height - 14);
  }
  ctx.restore();
}

