function drawAbnHelpFx(line) {
  const actor = abnCameo.actor;
  const cx = abnCameo.x + actor.width / 2;
  const cy = ground - actor.height / 2;
  const t = abnCameo.fxT;
  const time = performance.now() / 1000;
  const kidsX = [arcadeCutscene.scammerX + 30, arcadeCutscene.setoActor ? arcadeCutscene.setoActor.position.x + 30 : arcadeCutscene.scammerX + 110];
  ctx.save();
  // the charge: cards spinning around him, faster and bigger with every line
  if (line.abnCharge) {
    const power = line.abnCharge;
    const glow = ctx.createRadialGradient(cx, cy, 10, cx, cy, 70 + power * 30);
    glow.addColorStop(0, `rgba(144, 202, 249, ${0.25 + power * 0.12})`);
    glow.addColorStop(1, 'rgba(144, 202, 249, 0)');
    ctx.fillStyle = glow;
    ctx.fillRect(cx - 200, cy - 200, 400, 400);
    const count = 4 + power * 3;
    for (let index = 0; index < count; index += 1) {
      const angle = time * (1.5 + power) + (index / count) * Math.PI * 2;
      const radius = 50 + power * 18 + Math.sin(time * 3 + index) * 6;
      drawAbnCameoCard(cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius * 0.6, ['A', 'K', 'A', 'K'][index % 4], angle, 0.7);
    }
    if (power >= 3) {
      ctx.fillStyle = `rgba(255, 255, 255, ${0.08 + Math.sin(time * 20) * 0.05})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
  }
  // the attack: a fan of cards flying at the kids...
  if (line.abnFire) {
    for (let index = 0; index < 12; index += 1) {
      const k = Math.min(1, Math.max(0, (t - index * 2) / 30));
      if (k <= 0 || k >= 1) continue;
      const tx = kidsX[index % 2] + ((index * 37) % 60) - 30;
      drawAbnCameoCard(cx + (tx - cx) * k, cy - 20 + (ground - 160 - cy + 20) * k - Math.sin(k * Math.PI) * 90, index % 2 ? 'K' : 'A', t * 0.4, 0.7);
    }
    if (t > 40) {
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.max(0, 1 - (t - 40) / 30)})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
    if (t === 41) {
      [523, 659, 784, 1047].forEach((frequency, index) => playTone({ frequency, duration: 0.18, type: 'triangle', volume: 0.05, delay: index * 0.08 }));
    }
  }
  // ...that turn into presents (and confetti)
  if (line.abnGifts || (line.abnFire && t > 40)) {
    if (!abnCameo.gifts) {
      abnCameo.gifts = [];
      for (let index = 0; index < 10; index += 1) {
        abnCameo.gifts.push({ x: kidsX[index % 2] + ((index * 53) % 120) - 60, y: -40 - index * 30, color: ['#ef5350', '#42a5f5', '#66bb6a', '#ffca28', '#ab47bc'][index % 5], size: 18 + (index % 3) * 6 });
      }
    }
    abnCameo.gifts.forEach((gift) => {
      gift.y = Math.min(ground - gift.size, gift.y + 5);
      ctx.fillStyle = gift.color;
      ctx.fillRect(gift.x - gift.size / 2, gift.y, gift.size, gift.size);
      ctx.fillStyle = '#fff59d';
      ctx.fillRect(gift.x - 2, gift.y, 4, gift.size);
      ctx.fillRect(gift.x - gift.size / 2, gift.y + gift.size / 2 - 2, gift.size, 4);
      ctx.beginPath();
      ctx.arc(gift.x - 4, gift.y - 2, 4, 0, Math.PI * 2);
      ctx.arc(gift.x + 4, gift.y - 2, 4, 0, Math.PI * 2);
      ctx.fill();
    });
    for (let index = 0; index < 30; index += 1) {
      const fx = (index * 97 + time * 40 * (1 + (index % 3))) % canvas.width;
      const fy = (index * 53 + time * 90 * (1 + (index % 2))) % ground;
      ctx.fillStyle = ['#ef5350', '#42a5f5', '#66bb6a', '#ffca28', '#ab47bc'][index % 5];
      ctx.fillRect(fx, fy, 5, 8);
    }
  }
  ctx.restore();
}

