function getVersusMusicSetting() {
  try {
    const saved = localStorage.getItem(versusMusicKey);
    if (saved === 'random') return saved;
    return versusMusicTracks.some((track) => track.key === saved) ? saved : null;
  } catch (error) {
    return null;
  }
}

// (getReflecterBattleTrackKey asks this: only for versus fights, never in the arcade)
function getVersusMusicChoice() {
  if (normalArcadeActive || (typeof scamChallenge !== 'undefined' && scamChallenge.active)) return null;
  let key = getVersusMusicSetting();
  // "Aleatoria": a different song for every fight (the same one for the whole fight)
  if (key === 'random') {
    if (versusMusicUi.randomFor !== fightStartedAt || !versusMusicUi.randomKey) {
      const options = versusMusicTracks.filter((track) => reflecterBattleTrackSources[track.key]);
      versusMusicUi.randomKey = options[Math.floor(Math.random() * options.length)].key;
      versusMusicUi.randomFor = fightStartedAt;
    }
    key = versusMusicUi.randomKey;
  }
  return key && reflecterBattleTrackSources[key] ? key : null;
}

function versusMusicBadge(track, big = false) {
  return `<span class="vm-badge${big ? ' vm-badge-big' : ''}${track.rainbow ? ' vm-rainbow' : ''}" style="--vm-color: ${track.color}" aria-hidden="true">${track.symbol}</span>`;
}

// a little record: the badge is its label (it spins while it plays)
function versusMusicDisc(track) {
  return `<span class="vm-disc" style="--vm-color: ${track.color}" aria-hidden="true"><span class="vm-disc-label${track.rainbow ? ' vm-rainbow' : ''}">${track.symbol}</span></span>`;
}

const versusMusicAuto = { key: null, name: 'Automatica', from: 'La musica de siempre', symbol: '♫', color: '#cfd8dc', group: 'all' };
const versusMusicRandom = { key: 'random', name: 'Aleatoria', from: 'Una distinta en cada pelea', symbol: '?', color: '#ff80ab', group: 'all', rainbow: true };

function getVersusMusicTrack(key) {
  if (key === 'random') return versusMusicRandom;
  return versusMusicTracks.find((item) => item.key === key) || versusMusicAuto;
}

function renderVersusMusicButton() {
  const button = versusMusicUi.button;
  if (!button) return;
  const track = getVersusMusicTrack(getVersusMusicSetting());
  button.innerHTML = `${versusMusicBadge(track)}<span class="vm-label"><small>&#9835; MUSICA</small><b>${track.name}</b></span><span class="vm-caret">&#9662;</span>`;
  button.classList.toggle('hidden', normalArcadeActive);
}

function stopVersusMusicPreview(resumeMenu = true) {
  if (versusMusicUi.previewTimer) clearTimeout(versusMusicUi.previewTimer);
  if (versusMusicUi.frame) cancelAnimationFrame(versusMusicUi.frame);
  versusMusicUi.previewTimer = null;
  versusMusicUi.frame = null;
  if (versusMusicUi.preview) versusMusicUi.preview.pause();
  versusMusicUi.preview = null;
  versusMusicUi.previewKey = null;
  renderVersusMusicNowPlaying();
  document.querySelectorAll('.vm-card.previewing').forEach((card) => card.classList.remove('previewing'));
  if (resumeMenu && !gameStarted && document.body.classList.contains('menu-open')) startMenuMusic();
}

function previewVersusMusic(track) {
  stopVersusMusicPreview(false);
  if (typeof Audio === 'undefined' || !reflecterBattleTrackSources[track.key]) return;
  stopMenuMusic();
  try {
    const audio = new Audio(reflecterBattleTrackSources[track.key]);
    audio.volume = Math.min(1, (reflecterBattleTrackVolumes[track.key] || 0.5) * audioSettings.master * audioSettings.music);
    const played = audio.play();
    if (played && played.catch) played.catch(() => {});
    versusMusicUi.preview = audio;
    versusMusicUi.previewKey = track.key;
    versusMusicUi.previewStart = performance.now();
    versusMusicUi.previewTimer = setTimeout(() => stopVersusMusicPreview(), versusMusicPreviewSeconds * 1000);
  } catch (error) {
    // no preview: the choice still counts
  }
  document.querySelectorAll('.vm-card').forEach((card) => card.classList.toggle('previewing', card.dataset.key === track.key));
  renderVersusMusicNowPlaying();
  const tick = () => {
    const bar = versusMusicUi.panel && versusMusicUi.panel.querySelector('.vm-now-progress span');
    if (!bar || !versusMusicUi.preview) return;
    bar.style.width = `${Math.min(100, ((performance.now() - versusMusicUi.previewStart) / (versusMusicPreviewSeconds * 1000)) * 100)}%`;
    versusMusicUi.frame = requestAnimationFrame(tick);
  };
  versusMusicUi.frame = requestAnimationFrame(tick);
}

function chooseVersusMusic(key) {
  try {
    if (key) localStorage.setItem(versusMusicKey, key);
    else localStorage.removeItem(versusMusicKey);
  } catch (error) {
    // only for this session
  }
  playTone({ frequency: 880, duration: 0.08, type: 'triangle', volume: 0.04 });
  renderVersusMusicButton();
  renderVersusMusicPanel();
}

function renderVersusMusicNowPlaying() {
  const panel = versusMusicUi.panel;
  if (!panel) return;
  const now = panel.querySelector('.vm-now');
  const playing = versusMusicUi.previewKey ? getVersusMusicTrack(versusMusicUi.previewKey) : null;
  const chosen = getVersusMusicTrack(getVersusMusicSetting());
  const track = playing || chosen;
  now.classList.toggle('playing', Boolean(playing));
  now.style.setProperty('--vm-color', track.color);
  now.innerHTML = `
    ${versusMusicDisc(track)}
    <div class="vm-now-text">
      <small>${playing ? 'ESCUCHANDO' : 'ELEGIDA'}</small>
      <strong>${track.name}</strong>
      <span>${track.from}</span>
      <div class="vm-now-progress"><span></span></div>
    </div>
    <div class="vm-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>
    ${playing ? '<button type="button" class="vm-stop" title="Parar">&#9632;</button>' : ''}`;
  const stop = now.querySelector('.vm-stop');
  if (stop) stop.addEventListener('click', () => stopVersusMusicPreview());
}

function renderVersusMusicPanel() {
  const panel = versusMusicUi.panel;
  if (!panel) return;
  const current = getVersusMusicSetting();
  const chips = panel.querySelector('.vm-chips');
  chips.innerHTML = '';
  versusMusicGroups.forEach((group) => {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = `vm-chip${versusMusicUi.group === group.id ? ' active' : ''}`;
    const count = group.id === 'all' ? versusMusicTracks.length : versusMusicTracks.filter((track) => track.group === group.id).length;
    chip.innerHTML = `${group.label} <i>${count}</i>`;
    chip.addEventListener('click', () => {
      versusMusicUi.group = group.id;
      renderVersusMusicPanel();
    });
    chips.appendChild(chip);
  });
  const grid = panel.querySelector('.vm-grid');
  grid.innerHTML = '';
  const search = versusMusicUi.search.trim().toLowerCase();
  const tracks = (search ? [] : [versusMusicAuto, versusMusicRandom]).concat(versusMusicTracks.filter((track) => (versusMusicUi.group === 'all' || track.group === versusMusicUi.group) && (!search || `${track.name} ${track.from}`.toLowerCase().includes(search))));
  if (!tracks.length) grid.innerHTML = '<p class="vm-empty">Ninguna cancion con ese nombre. ¡Proba con otro!</p>';
  tracks.forEach((track) => {
    const card = document.createElement('div');
    const selected = track.key === current;
    card.className = `vm-card${selected ? ' selected' : ''}${track.key && track.key === versusMusicUi.previewKey ? ' previewing' : ''}`;
    card.dataset.key = track.key || '';
    card.style.setProperty('--vm-color', track.color);
    card.innerHTML = `
      <button type="button" class="vm-pick">
        ${versusMusicBadge(track)}
        <span class="vm-label">
          <strong>${track.name}</strong>
          <small>${track.from}${versusMusicGroupNames[track.group] ? ` &middot; ${versusMusicGroupNames[track.group]}` : ''}</small>
        </span>
        ${selected ? '<span class="vm-check" aria-hidden="true">&#10003;</span>' : ''}
      </button>
      ${track.key && track.key !== 'random' ? '<button type="button" class="vm-play" title="Escuchar un poco">&#9654;</button>' : ''}`;
    card.querySelector('.vm-pick').addEventListener('click', () => chooseVersusMusic(track.key));
    const play = card.querySelector('.vm-play');
    if (play) {
      play.addEventListener('click', () => {
        if (versusMusicUi.previewKey === track.key) stopVersusMusicPreview();
        else previewVersusMusic(track);
      });
    }
    grid.appendChild(card);
  });
  renderVersusMusicNowPlaying();
}

function openVersusMusicPanel() {
  if (versusMusicUi.panel) return;
  const panel = document.createElement('div');
  panel.className = 'vm-modal';
  panel.innerHTML = `
    <div class="vm-panel" role="dialog" aria-label="Musica de fondo">
      <header class="vm-head">
        <div>
          <h3>&#9835; MUSICA DE FONDO</h3>
          <p>Elegi la cancion para tus peleas normales. El arcade siempre usa la suya.</p>
        </div>
        <button type="button" class="vm-close" title="Cerrar">&#10005;</button>
      </header>
      <div class="vm-now"></div>
      <div class="vm-tools">
        <div class="vm-chips"></div>
        <label class="vm-search"><span aria-hidden="true">&#9906;</span><input type="search" placeholder="Buscar cancion o personaje..." /></label>
      </div>
      <div class="vm-grid"></div>
      <footer class="vm-foot">
        <button type="button" class="vm-done">Listo</button>
      </footer>
    </div>`;
  document.body.appendChild(panel);
  versusMusicUi.panel = panel;
  panel.addEventListener('click', (event) => {
    if (event.target === panel) closeVersusMusicPanel();
  });
  panel.querySelector('.vm-done').addEventListener('click', closeVersusMusicPanel);
  panel.querySelector('.vm-close').addEventListener('click', closeVersusMusicPanel);
  const search = panel.querySelector('.vm-search input');
  search.value = versusMusicUi.search;
  search.addEventListener('input', () => {
    versusMusicUi.search = search.value;
    renderVersusMusicPanel();
  });
  renderVersusMusicPanel();
}

function closeVersusMusicPanel() {
  if (!versusMusicUi.panel) return;
  stopVersusMusicPreview();
  versusMusicUi.panel.remove();
  versusMusicUi.panel = null;
}

(function buildVersusMusicButton() {
  const screen = document.getElementById('mapScreen');
  if (!screen) return;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'vm-button';
  button.id = 'versusMusicButton';
  button.addEventListener('click', openVersusMusicPanel);
  screen.appendChild(button);
  versusMusicUi.button = button;
  renderVersusMusicButton();
  // (the arcade picks its own music: the button hides there)
  new MutationObserver(() => {
    if (!screen.classList.contains('hidden')) renderVersusMusicButton();
    else closeVersusMusicPanel();
  }).observe(screen, { attributes: true, attributeFilter: ['class'] });
})();

window.addEventListener('keydown', (event) => {
  if (versusMusicUi.panel && event.key === 'Escape') closeVersusMusicPanel();
});

// ---------- the nine new rules ----------
function updateAbnExtraRule(rule, owner, opponent) {
  const t = abnPlay.t;
  if (rule.id === 'mirrorControls') {
    // every step he takes goes the other way
    const prev = typeof abnPlay.prevX === 'number' ? abnPlay.prevX : opponent.position.x;
    const moved = opponent.position.x - prev;
    opponent.position.x = Math.max(0, Math.min(canvas.width - opponent.width, prev - moved));
    abnPlay.prevX = opponent.position.x;
  } else if (rule.id === 'cardRain') {
    if (t % 9 === 0) abnPlay.cards.push({ x: getFighterCenterX(opponent) + (Math.random() - 0.5) * 220, y: -30, spin: Math.random() * 6, red: Math.random() < 0.5 });
    abnPlay.cards.forEach((card) => {
      card.y += 9;
      card.spin += 0.3;
      if (!card.hit && card.x > opponent.position.x - 10 && card.x < opponent.position.x + opponent.width + 10 && card.y > opponent.position.y && card.y < opponent.position.y + opponent.height) {
        card.hit = true;
        applyDamage(owner, opponent, 3, { isSpecial: true });
        playTone({ frequency: 1500, duration: 0.05, type: 'square', volume: 0.03 });
      }
    });
    abnPlay.cards = abnPlay.cards.filter((card) => !card.hit && card.y < ground + 20);
  } else if (rule.id === 'swapPlaces') {
    if (t % 90 === 45) {
      const ownerX = owner.position.x;
      owner.position.x = opponent.position.x;
      opponent.position.x = ownerX;
      owner.attacksToTheRight = !owner.attacksToTheRight;
      opponent.attacksToTheRight = !opponent.attacksToTheRight;
      abnPlay.flash = 0.6;
      playNoise({ duration: 0.18, volume: 0.06, filterFrequency: 5000 });
    }
  } else if (rule.id === 'ceiling') {
    opponent.velocity.y = Math.max(-7, opponent.velocity.y - gravity * 1.9);
    if (opponent.position.y < 70) {
      opponent.position.y = 70;
      opponent.velocity.y = 0;
    }
  } else if (rule.id === 'timeFreeze') {
    if (t < 120) {
      opponent.gamblerStunTimer = Math.max(opponent.gamblerStunTimer || 0, 2);
      opponent.velocity.x = 0;
      opponent.isAttacking = false;
      if (t === 1) playTone({ frequency: 2000, duration: 0.6, type: 'sine', volume: 0.05, slideTo: 600 });
    }
    if (t === 120) playNoise({ duration: 0.3, volume: 0.08, filterFrequency: 6000 });
  } else if (rule.id === 'hotPotato') {
    if (t % 30 === 0 && t < 300) playTone({ frequency: 700 + t * 2, duration: 0.05, type: 'square', volume: 0.04 });
    if (t === 300 && abnPlay.bomb) {
      // BOOM: whoever holds it pays
      const holder = abnPlay.bomb;
      const other = holder === owner ? opponent : owner;
      applyDamage(other, holder, 25, { isSpecial: true, ignoreInvincible: true });
      holder.velocity.y = -9;
      abnPlay.boom = { x: getFighterCenterX(holder), y: holder.position.y + 30, t: 30 };
      abnPlay.bomb = null;
      playNoise({ duration: 0.6, volume: 0.14, filterFrequency: 700 });
      updateHealthBars();
    }
  } else if (rule.id === 'disco') {
    if (t % 40 === 0 && opponent.position.y + opponent.height >= ground - 2) opponent.velocity.y = -11;
    if (t % 20 === 0) playTone({ frequency: [523, 659, 784, 659][(t / 20) % 4], duration: 0.08, type: 'square', volume: 0.025 });
  }
}

function drawAbnExtraRule(rule) {
  const opponent = getAbnPlayOpponent();
  const time = performance.now() / 1000;
  ctx.save();
  if (rule.id === 'cardRain') {
    abnPlay.cards.forEach((card) => drawAbnCameoCard(card.x, card.y, card.red ? 'K' : 'A', card.spin, 0.55));
  } else if (rule.id === 'mirrorControls') {
    ctx.font = '900 26px Arial';
    ctx.fillStyle = '#90caf9';
    ctx.textAlign = 'center';
    ctx.fillText('\u21C4', getFighterCenterX(opponent), opponent.position.y - 16);
  } else if (rule.id === 'ceiling') {
    ctx.strokeStyle = 'rgba(144, 202, 249, 0.6)';
    ctx.lineWidth = 2;
    for (let index = 0; index < 4; index += 1) {
      const x = opponent.position.x + 6 + index * (opponent.width / 3);
      const y = opponent.position.y + opponent.height + 10 + ((time * 80 + index * 15) % 40);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x, y - 14);
      ctx.stroke();
    }
  } else if (rule.id === 'timeFreeze' && abnPlay.t < 120) {
    ctx.fillStyle = 'rgba(179, 229, 252, 0.45)';
    ctx.strokeStyle = '#e1f5fe';
    ctx.lineWidth = 3;
    ctx.fillRect(opponent.position.x - 10, opponent.position.y - 10, opponent.width + 20, opponent.height + 14);
    ctx.strokeRect(opponent.position.x - 10, opponent.position.y - 10, opponent.width + 20, opponent.height + 14);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
    ctx.beginPath();
    ctx.moveTo(opponent.position.x, opponent.position.y + 10);
    ctx.lineTo(opponent.position.x + 20, opponent.position.y - 4);
    ctx.stroke();
  } else if (rule.id === 'hotPotato' && abnPlay.bomb) {
    const holder = abnPlay.bomb;
    const left = Math.max(0, Math.ceil((300 - abnPlay.t) / 60));
    const x = getFighterCenterX(holder);
    const y = holder.position.y - 40 + Math.sin(time * 10) * 3;
    drawAbnCameoCard(x, y, 'K', Math.sin(time * 12) * 0.2, 0.75);
    ctx.fillStyle = left <= 1 ? '#ff1744' : '#ffd54f';
    ctx.font = '900 18px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(String(left), x + 26, y - 14);
  } else if (rule.id === 'disco') {
    // the dance floor lights
    ['#ff4081', '#40c4ff', '#69f0ae', '#ffd54f'].forEach((color, index) => {
      const x = canvas.width * (0.2 + index * 0.2) + Math.sin(time * 2 + index) * 120;
      const beam = ctx.createLinearGradient(x, 0, x, ground);
      beam.addColorStop(0, `${color}55`);
      beam.addColorStop(1, `${color}00`);
      ctx.fillStyle = beam;
      ctx.beginPath();
      ctx.moveTo(x - 10, 0);
      ctx.lineTo(x + 10, 0);
      ctx.lineTo(x + 90, ground);
      ctx.lineTo(x - 90, ground);
      ctx.closePath();
      ctx.fill();
    });
    ctx.fillStyle = '#e0e0e0';
    ctx.beginPath();
    ctx.arc(canvas.width / 2, 170, 16, 0, Math.PI * 2);
    ctx.fill();
  }
  if (abnPlay.boom && abnPlay.boom.t > 0) {
    const boom = abnPlay.boom;
    boom.t -= 1;
    const k = 1 - boom.t / 30;
    ctx.fillStyle = `rgba(255, 152, 0, ${1 - k})`;
    ctx.beginPath();
    ctx.arc(boom.x, boom.y, 20 + k * 90, 0, Math.PI * 2);
    ctx.fill();
  }
  if (abnPlay.flash > 0) {
    ctx.fillStyle = `rgba(255, 255, 255, ${abnPlay.flash})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    abnPlay.flash = Math.max(0, abnPlay.flash - 0.05);
  }
  ctx.restore();
}

// ---------- the fight of titans: the clash, bigger ----------
function drawSmallDownedFighter(fighter, scale) {
  if (scale === 1) {
    drawDownedFighter(fighter);
    return;
  }
  const pivotX = fighter.position.x + fighter.width / 2;
  ctx.save();
  ctx.translate(pivotX, ground);
  ctx.scale(scale, scale);
  ctx.translate(-pivotX, -ground);
  drawDownedFighter(fighter);
  ctx.restore();
}

function drawTitanClashEpicBack(clash, point, from, mouth, time) {
  ctx.save();
  // the sky splits in two colors: gold on his side, violet on the titan's
  const sky = ctx.createLinearGradient(0, 0, canvas.width, 0);
  const split = point.x / canvas.width;
  sky.addColorStop(0, 'rgba(255, 213, 79, 0.22)');
  sky.addColorStop(Math.max(0.01, split - 0.05), 'rgba(255, 213, 79, 0.08)');
  sky.addColorStop(Math.min(0.99, split + 0.05), 'rgba(170, 0, 255, 0.1)');
  sky.addColorStop(1, 'rgba(170, 0, 255, 0.28)');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // the ground cracks open under the clash, glowing
  ctx.strokeStyle = `rgba(255, 245, 220, ${0.5 + Math.sin(time * 9) * 0.3})`;
  ctx.lineWidth = 3;
  for (let crack = 0; crack < 7; crack += 1) {
    ctx.beginPath();
    let cx = point.x;
    let cy = ground;
    ctx.moveTo(cx, cy);
    for (let step = 0; step < 6; step += 1) {
      cx += (crack - 3) * 18 + Math.sin(crack * 7 + step * 3) * 14;
      cy += 4 + Math.abs(Math.sin(crack + step)) * 6;
      ctx.lineTo(cx, cy);
    }
    ctx.stroke();
  }
  // rocks torn off the ground, floating up
  ctx.fillStyle = '#1a1020';
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.lineWidth = 1.5;
  (clash.rocks || []).forEach((rock) => {
    ctx.save();
    ctx.translate(rock.x, rock.y);
    ctx.rotate(rock.spin);
    ctx.fillRect(-rock.r, -rock.r * 0.7, rock.r * 2, rock.r * 1.4);
    ctx.strokeRect(-rock.r, -rock.r * 0.7, rock.r * 2, rock.r * 1.4);
    ctx.restore();
  });
  // the General's own beam: a column of gold feeding the World Cut
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(255, 213, 79, 0.55)';
  ctx.lineWidth = 70 + Math.sin(time * 30) * 6;
  ctx.beginPath();
  ctx.moveTo(from.x, from.y);
  ctx.lineTo(point.x, point.y);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
  ctx.lineWidth = 18;
  ctx.stroke();
  // dark rings spiralling down the titan's laser
  ctx.strokeStyle = 'rgba(234, 128, 252, 0.7)';
  ctx.lineWidth = 4;
  for (let ring = 0; ring < 6; ring += 1) {
    const k = ((time * 1.6 + ring / 6) % 1);
    const rx = mouth.x + (point.x - mouth.x) * k;
    const ry = mouth.y + (point.y - mouth.y) * k;
    ctx.beginPath();
    ctx.ellipse(rx, ry, 18, 62, Math.atan2(point.y - mouth.y, point.x - mouth.x), 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

function drawTitanClashEpicFront(clash, point, time) {
  ctx.save();
  // shockwave rings out of the meeting point
  for (let ring = 0; ring < 3; ring += 1) {
    const k = (time * 1.4 + ring / 3) % 1;
    ctx.strokeStyle = `rgba(255, 255, 255, ${0.6 * (1 - k)})`;
    ctx.lineWidth = 6 * (1 - k) + 1;
    ctx.beginPath();
    ctx.arc(point.x, point.y, 40 + k * 260, 0, Math.PI * 2);
    ctx.stroke();
  }
  // lightning out of the clash: up into the sky and down into the ground
  (clash.bolts || []).forEach((bolt) => {
    ctx.strokeStyle = `rgba(255, 255, 255, ${bolt.life / 10})`;
    ctx.shadowColor = bolt.seed % 2 > 1 ? '#ffd54f' : '#ea80fc';
    ctx.shadowBlur = 16;
    ctx.lineWidth = 3;
    ctx.beginPath();
    let bx = point.x;
    let by = point.y;
    const goUp = bolt.seed % 3 > 1.5;
    ctx.moveTo(bx, by);
    for (let step = 0; step < 8; step += 1) {
      bx += Math.sin(bolt.seed + step * 2.3) * 40;
      by += goUp ? -(point.y / 8) : (ground - point.y) / 8;
      ctx.lineTo(bx, by);
    }
    ctx.stroke();
  });
  ctx.shadowBlur = 0;
  // a white-hot core, flickering
  const core = 50 + Math.sin(time * 35) * 10;
  const glow = ctx.createRadialGradient(point.x, point.y, 2, point.x, point.y, core * 2.4);
  glow.addColorStop(0, 'rgba(255, 255, 255, 1)');
  glow.addColorStop(0.3, 'rgba(255, 255, 255, 0.7)');
  glow.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(point.x - core * 2.4, point.y - core * 2.4, core * 4.8, core * 4.8);
  // cinematic bars
  ctx.fillStyle = '#000000';
  ctx.fillRect(0, canvas.height - 26, canvas.width, 26);
  ctx.restore();
}

// ---------- the zoom of the scene (the General shrinking in a world that grows) ----------
const cutsceneZoom = { on: false };

function endCutsceneZoom() {
  if (!cutsceneZoom.on) return;
  ctx.restore();
  cutsceneZoom.on = false;
}

function beginCutsceneZoom(cutscene) {
  endCutsceneZoom();
  const zoom = cutscene && cutscene.active ? cutscene.mapZoom || 1 : 1;
  if (zoom <= 1.001) return;
  const ax = cutscene.zoomAnchorX || canvas.width / 2;
  ctx.save();
  ctx.translate(ax, ground);
  ctx.scale(zoom, zoom);
  ctx.translate(-ax, -ground);
  cutsceneZoom.on = true;
}

// ================= CODE "DARKWORLD": the dark world comes to the roster (after chapter 6) =================
const darkworldVariants = ['hydraBeast', 'blackKnightBoss', 'babyTitan', 'titanGiant'];
const darkworldButtonIds = { hydraBeast: 'darkworldHydraButton', blackKnightBoss: 'darkworldKnightButton', babyTitan: 'darkworldBabyButton', titanGiant: 'darkworldTitanButton' };
// (a fair fight outside the chapter: no thousands of health)
const darkworldVersusHealth = { hydraBeast: 220, blackKnightBoss: 240, babyTitan: 160, titanGiant: 500 };
const darkworldCooldowns = [150, 240, 360];
let darkworldCodeActive = false;
const darkworldFx = { items: [] };

function isDarkworldFighter(fighter) {
  return Boolean(fighter && darkworldVariants.includes(fighter.secretVariant));
}

function isDarkworldVariantActive(variant) {
  return darkworldCodeActive && darkworldVariants.includes(variant);
}

function isDarkworldVersus() {
  return !normalArcadeActive && !(typeof isChronoChapterFight === 'function' && isChronoChapterFight());
}

// the places of chapter 6, for any fight
const darkworldMaps = [
  ['darkWorld', 'Mundo Oscuro'], ['redForest', 'Bosque Carmesi'], ['violetForest', 'Bosque Violeta'],
  ['castleGate', 'Puertas del Castillo'], ['castleClocks', 'Sala de Relojes'], ['castleMirrors', 'Sala de Espejos'],
  ['castleDining', 'Comedor Real'], ['castleGallery', 'Galeria'], ['castleArmory', 'Armeria'],
  ['castleStairs', 'Escalera Oscura'], ['castleHall', 'Gran Salon'], ['castleThroneHall', 'Salon del Trono'],
  ['orderChamber', 'Camara de la Orden'], ['castleRoof', 'Techo del Castillo'], ['castleRuins', 'Ruinas del Castillo'],
  ['castleOutskirts', 'Afueras del Castillo'], ['kingThrone', 'Trono del Rey'], ['lightWorld', 'Mundo de la Luz'], ['tempusLobby', 'Vestibulo de Tempus'],
];
let darkworldMapPreviewsBuilt = false;

function buildDarkworldMapButtons() {
  const grid = document.querySelector('#mapScreen .map-grid');
  if (!grid || document.querySelector('.darkworld-map')) return;
  darkworldMaps.forEach(([map, name]) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'map-option darkworld-map hidden';
    button.dataset.map = map;
    button.innerHTML = `<span>${name}</span><span class="map-preview" aria-hidden="true"><span class="map-sky"></span><span class="map-platform"></span><span class="map-detail"></span></span>`;
    button.addEventListener('click', () => selectMap(map));
    grid.appendChild(button);
  });
}

// (their previews: the stage itself, drawn once)
function buildDarkworldMapPreviews() {
  if (darkworldMapPreviewsBuilt) return;
  darkworldMapPreviewsBuilt = true;
  const saved = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const savedMap = selectedMap;
  const thumb = document.createElement('canvas');
  const thumbCtx = thumb.getContext('2d');
  thumb.width = 360;
  thumb.height = 140;
  document.querySelectorAll('.darkworld-map').forEach((button) => {
    try {
      selectedMap = button.dataset.map;
      ctx.save();
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawStage();
      ctx.restore();
      const sourceHeight = canvas.width * (thumb.height / thumb.width);
      thumbCtx.clearRect(0, 0, thumb.width, thumb.height);
      thumbCtx.drawImage(canvas, 0, canvas.height - sourceHeight - 10, canvas.width, sourceHeight, 0, 0, thumb.width, thumb.height);
      const preview = button.querySelector('.map-preview');
      preview.style.backgroundImage = `url(${thumb.toDataURL()})`;
      preview.classList.add('rendered-preview');
    } catch (error) {
      // keep the simple preview
    }
  });
  selectedMap = savedMap;
  ctx.putImageData(saved, 0, 0);
}

function syncDarkworldButtons() {
  Object.values(darkworldButtonIds).forEach((id) => {
    const button = document.getElementById(id);
    if (button) button.classList.toggle('hidden', !darkworldCodeActive);
  });
  buildDarkworldMapButtons();
  document.querySelectorAll('.darkworld-map').forEach((button) => button.classList.toggle('hidden', !darkworldCodeActive));
  if (darkworldCodeActive) buildDarkworldMapPreviews();
}

function unlockDarkworldCode() {
  const done = typeof isArcadeChapterDone === 'function' && isArcadeChapterDone('chrono');
  if (!done) {
    showCustomToast('DARKWORLD', '...El mundo oscuro todavia no te conoce. Termina el capitulo 6 y volve a llamarlo.');
    playTone({ frequency: 70, duration: 1.2, type: 'sawtooth', volume: 0.05, slideTo: 45 });
    return;
  }
  darkworldCodeActive = true;
  unlockAchievement('codeBreaker');
  syncDarkworldButtons();
  showCustomToast('DARKWORLD ACTIVADO', 'La Bestia de Tres Cabezas, el Caballero Negro, el Bebe Titan y los lugares del mundo oscuro ya se pueden elegir. Y algo mas... algo enorme... te esta mirando desde el roster.');
  playTone({ frequency: 55, duration: 2, type: 'sawtooth', volume: 0.07, slideTo: 35 });
  setTimeout(() => playSound('titanRoar'), 500);
}

function lockDarkworldCode() {
  darkworldCodeActive = false;
  syncDarkworldButtons();
  if (!normalArcadeActive && darkworldMaps.some(([map]) => map === selectedMap)) selectedMap = 'foundry';
}

(function hookDarkworld() {
  Object.entries(darkworldButtonIds).forEach(([variant, id]) => {
    const button = document.getElementById(id);
    if (!button) return;
    button.addEventListener('click', () => {
      if (variant === 'titanGiant') {
        playSound('titanRoar');
        playTone({ frequency: 45, duration: 1.4, type: 'sawtooth', volume: 0.07, slideTo: 30 });
      }
      selectCharacter('normal', variant);
    });
  });
  // the titan's slot whispers when you get close
  const titanButton = document.getElementById(darkworldButtonIds.titanGiant);
  if (titanButton) {
    titanButton.addEventListener('pointerenter', () => {
      playTone({ frequency: 62, duration: 0.9, type: 'sine', volume: 0.06, slideTo: 48 });
      playNoise({ duration: 0.5, volume: 0.03, filterFrequency: 500 });
    });
  }
  // (CLEAR takes it away like every other code)
  const originalClear = window.clearActiveCodes;
  if (typeof originalClear === 'function') {
    window.clearActiveCodes = function clearActiveCodesWithDarkworld(...args) {
      lockDarkworldCode();
      return originalClear.apply(this, args);
    };
  }
  // their Q / F / R
  const originalKeys = window.handleOriginsCodeKey;
  if (typeof originalKeys === 'function') {
    window.handleOriginsCodeKey = function handleOriginsCodeKeyWithDarkworld(fighter, target, slot) {
      if (isDarkworldFighter(fighter) && isDarkworldVersus()) {
        castDarkworldAbility(fighter, target, slot);
        return true;
      }
      return originalKeys.call(this, fighter, target, slot);
    };
  }
  syncDarkworldButtons();
})();

// ---------- every fight: their versus stats, the giant rule, the bot's specials ----------
function resetDarkworldFight() {
  darkworldFx.items = [];
  darkworldFx.banner = null;
  darkworldFx.selfRuleIn = 0;
  [player1, player2].forEach((fighter) => {
    fighter.dwPrepared = false;
    fighter.dwCooldowns = [0, 0, 0];
    fighter.dwGuard = 0;
    if (fighter.dwGiantSaved) {
      // (the giant rule only lasts one fight)
      fighter.setMaxHealth(fighter.dwGiantSaved.maxHealth);
      fighter.damageMultiplier = fighter.dwGiantSaved.damageMultiplier;
      fighter.attackBox = fighter.dwGiantSaved.attackBox;
      fighter.dwGiantSaved = null;
    }
    if (fighter.giantScale && fighter.giantScale !== 1 && !(typeof isChronoChapterFight === 'function' && isChronoChapterFight())) fighter.giantScale = 1;
  });
}

function prepareDarkworldFighter(fighter) {
  fighter.dwPrepared = true;
  fighter.dwCooldowns = [0, 0, 0];
  if (!isDarkworldFighter(fighter)) return;
  fighter.setMaxHealth(darkworldVersusHealth[fighter.secretVariant] || 200);
  fighter.health = fighter.maxHealth;
  if (fighter.secretVariant === 'titanGiant') {
    fighter.damageMultiplier = 2;
    fighter.attackBox = { offset: { x: fighter.width, y: 120 }, width: 230, height: 150 };
  } else {
    fighter.damageMultiplier = Math.min(fighter.damageMultiplier || 1, 1.3);
  }
  updateHealthBars();
}

// Abnormal's rule: the titan's rival becomes a titan too
function applyTitanGiantRule() {
  const titan = player1.secretVariant === 'titanGiant' ? player1 : player2;
  const rival = titan === player1 ? player2 : player1;
  if (rival.secretVariant === 'titanGiant' || rival.dwGiantSaved) return;
  rival.dwGiantSaved = { maxHealth: rival.maxHealth, damageMultiplier: rival.damageMultiplier, attackBox: { ...rival.attackBox, offset: { ...rival.attackBox.offset } } };
  const ratio = rival.health / rival.maxHealth;
  rival.setMaxHealth(titan.maxHealth);
  rival.health = rival.maxHealth * ratio;
  rival.damageMultiplier = (rival.damageMultiplier || 1) * 2.2;
  rival.attackBox = { ...rival.attackBox, width: rival.attackBox.width * 2, height: rival.attackBox.height * 1.9 };
  rival.dwGrowT = 0;
  playTone({ frequency: 200, duration: 1.4, type: 'triangle', volume: 0.06, slideTo: 600 });
  updateHealthBars();
}

function updateDarkworldVersus() {
  if (!gameStarted || !isDarkworldVersus()) return;
  const titanFight = isTitanGiant(player1) || isTitanGiant(player2);
  document.body.classList.toggle('titan-giant-fight', Boolean(titanFight && !gameOver));
  if (gameOver) return;
  [player1, player2].forEach((fighter) => {
    if (!fighter.dwPrepared) prepareDarkworldFighter(fighter);
    fighter.dwCooldowns = (fighter.dwCooldowns || [0, 0, 0]).map((value) => Math.max(0, value - 1));
    if (fighter.dwGuard > 0) fighter.dwGuard -= 1;
    // (the titan is wider than its body: keep all of it on screen)
    if (fighter.secretVariant === 'titanGiant') fighter.position.x = Math.max(180 - fighter.width / 2, Math.min(canvas.width - 180 - fighter.width / 2, fighter.position.x));
    // the rival grows... slowly, then stays a titan
    if (fighter.dwGiantSaved) {
      fighter.dwGrowT = (fighter.dwGrowT || 0) + 1;
      fighter.giantScale = Math.min(chronoTitanGiantScale, 1 + fighter.dwGrowT * 0.012);
      const half = (fighter.width * fighter.giantScale) / 2;
      fighter.position.x = Math.max(half - fighter.width / 2, Math.min(canvas.width - half - fighter.width / 2, fighter.position.x));
    }
  });
  // a titan against anyone else: Abnormal has something to say
  if (titanFight && !(isTitanGiant(player1) && isTitanGiant(player2)) && !abnCameo.titanRuleDone && !abnCameo.active && !abnCameo.pending) {
    abnCameo.titanRuleDone = true;
    const rival = isTitanGiant(player1) ? player2 : player1;
    if (rival.secretVariant === 'abnormal') {
      darkworldFx.selfRuleIn = 40;
    } else if (rival.characterType === 'lightWarrior' && rival.secretVariant === 'omega') {
      // (Light Warrior has his own answer to a titan)
      abnCameo.pending = 'titanRuleLW';
      abnCameo.wait = 40;
    } else {
      abnCameo.pending = 'titanRule';
      abnCameo.wait = 40;
    }
  }
  if (darkworldFx.selfRuleIn > 0) {
    darkworldFx.selfRuleIn -= 1;
    if (darkworldFx.selfRuleIn === 0) {
      const abn = isTitanGiant(player1) ? player2 : player1;
      darkworldFx.banner = { title: 'EL GUARDIA SUPREMO TAMBIEN ES GIGANTE', t: 240 };
      showFlametombThought(abn, '¿Un titan? ¡JO JO! Dos pueden jugar a ser enormes.');
      [392, 523, 659, 784].forEach((frequency, index) => setTimeout(() => playTone({ frequency, duration: 0.16, type: 'square', volume: 0.05 }), index * 100));
      applyTitanGiantRule();
    }
  }
  // the bot uses their specials too
  if (botEnabled && isDarkworldFighter(player2)) {
    const distance = Math.abs(getFighterCenterX(player2) - getFighterCenterX(player1));
    if (Math.random() < 0.02 && canFighterAct(player2)) {
      const slot = distance < 180 ? (Math.random() < 0.5 ? 1 : 2) : Math.floor(Math.random() * 3);
      castDarkworldAbility(player2, player1, slot);
    }
  }
  updateDarkworldFx();
}

// (the Black Knight's guard)
function darkworldDamageScale(attacker, target) {
  if (!isDarkworldVersus()) return 1;
  return target && target.dwGuard > 0 ? 0.5 : 1;
}

// ---------- their abilities ----------
function castDarkworldAbility(fighter, target, slot) {
  if (!gameStarted || gameOver || !canFighterAct(fighter)) return;
  if (!fighter.dwCooldowns) fighter.dwCooldowns = [0, 0, 0];
  if (fighter.dwCooldowns[slot] > 0) return;
  fighter.dwCooldowns[slot] = darkworldCooldowns[slot];
  const dir = getFighterCenterX(target) >= getFighterCenterX(fighter) ? 1 : -1;
  fighter.attacksToTheRight = dir > 0;
  const cx = getFighterCenterX(fighter);
  const front = cx + dir * (fighter.width / 2);
  const add = (item) => darkworldFx.items.push({ owner: fighter, target, dir, t: 0, hit: false, ...item });
  const variant = fighter.secretVariant;
  if (variant === 'hydraBeast') {
    if (slot === 0) {
      // three heads, three fireballs
      [-1.6, 0, 1.6].forEach((vy) => add({ kind: 'fireball', x: front, y: fighter.position.y + 40, vx: dir * 9, vy, dmg: 6 }));
      playSound('fireball');
    } else if (slot === 1) {
      add({ kind: 'lunge', dmg: 15 });
      playTone({ frequency: 180, duration: 0.3, type: 'sawtooth', volume: 0.06, slideTo: 90 });
    } else {
      add({ kind: 'roar', x: cx, y: fighter.position.y + 40, dmg: 5 });
      playTone({ frequency: 90, duration: 1, type: 'sawtooth', volume: 0.08, slideTo: 60 });
    }
  } else if (variant === 'blackKnightBoss') {
    if (slot === 0) {
      add({ kind: 'darkWave', x: front, vx: dir * 10, dmg: 12 });
      playNoise({ duration: 0.4, volume: 0.08, filterFrequency: 1200 });
    } else if (slot === 1) {
      add({ kind: 'shadowStep', dmg: 10 });
      playNoise({ duration: 0.3, volume: 0.07, filterFrequency: 3000 });
    } else {
      fighter.dwGuard = 150;
      add({ kind: 'guard' });
      playTone({ frequency: 300, duration: 0.5, type: 'triangle', volume: 0.05, slideTo: 150 });
    }
  } else if (variant === 'babyTitan') {
    if (slot === 0) {
      add({ kind: 'stomp', x: cx, r: 0, dmg: 9 });
      playNoise({ duration: 0.5, volume: 0.1, filterFrequency: 300 });
    } else if (slot === 1) {
      add({ kind: 'miniLaser', dmg: 2 });
      playTone({ frequency: 600, duration: 0.8, type: 'sine', volume: 0.05, slideTo: 1200 });
    } else {
      fighter.velocity.y = -17;
      add({ kind: 'leap', dmg: 14 });
      playTone({ frequency: 300, duration: 0.4, type: 'triangle', volume: 0.05, slideTo: 700 });
    }
  } else if (variant === 'titanGiant') {
    if (slot === 0) {
      add({ kind: 'roarRing', x: cx, r: 0, dmg: 20 });
      playSound('titanRoar');
    } else if (slot === 1) {
      const tx = getFighterCenterX(target);
      add({ kind: 'spikes', spots: [tx, tx - 130, tx + 130].map((spot) => Math.max(30, Math.min(canvas.width - 30, spot))), dmg: 22 });
      playTone({ frequency: 70, duration: 0.8, type: 'sawtooth', volume: 0.06, slideTo: 45 });
    } else {
      add({ kind: 'eyeBeam', from: cx, dmg: 18 });
      playTone({ frequency: 400, duration: 0.8, type: 'sine', volume: 0.05, slideTo: 1200 });
    }
  }
}

function darkworldHit(item, damage, knock = 0) {
  if (item.hit || gameOver) return;
  item.hit = true;
  applyDamage(item.owner, item.target, damage, { isSpecial: true });
  if (knock) {
    item.target.velocity.y = -knock;
    item.target.velocity.x = item.dir * knock * 0.8;
  }
  updateHealthBars();
}

function darkworldTargetBox(target) {
  const scale = target.giantScale || 1;
  const w = target.width * scale;
  const h = target.height * scale;
  return { x: target.position.x + target.width / 2 - w / 2, w, top: target.position.y + target.height - h, bottom: target.position.y + target.height };
}

function updateDarkworldFx() {
  darkworldFx.items.forEach((item) => {
    item.t += 1;
    const owner = item.owner;
    const box = darkworldTargetBox(item.target);
    const grounded = box.bottom > ground - 30;
    const inside = (x, y, pad = 0) => x > box.x - pad && x < box.x + box.w + pad && y > box.top - pad && y < box.bottom + pad;
    if (item.kind === 'fireball') {
      item.x += item.vx;
      item.y += item.vy;
      if (inside(item.x, item.y, 10)) darkworldHit(item, item.dmg, 4);
      item.done = item.hit || item.x < -40 || item.x > canvas.width + 40;
    } else if (item.kind === 'lunge') {
      if (item.t < 14) {
        owner.position.x = Math.max(0, Math.min(canvas.width - owner.width, owner.position.x + item.dir * 14));
        if (inside(getFighterCenterX(owner) + item.dir * owner.width / 2, owner.position.y + owner.height / 2, 20)) darkworldHit(item, item.dmg, 8);
      }
      item.done = item.t > 16;
    } else if (item.kind === 'roar') {
      if (item.t === 10 && Math.abs(getFighterCenterX(item.target) - item.x) < 300) {
        darkworldHit(item, item.dmg);
        item.target.gamblerStunTimer = Math.max(item.target.gamblerStunTimer || 0, 70);
      }
      item.done = item.t > 50;
    } else if (item.kind === 'darkWave') {
      item.x += item.vx;
      if (grounded && Math.abs(item.x - (box.x + box.w / 2)) < box.w / 2 + 20) darkworldHit(item, item.dmg, 7);
      item.done = item.hit || item.x < -60 || item.x > canvas.width + 60;
    } else if (item.kind === 'shadowStep') {
      if (item.t === 8) {
        // he steps out of his shadow... behind you
        const behind = getFighterCenterX(item.target) + item.dir * 70;
        owner.position.x = Math.max(0, Math.min(canvas.width - owner.width, behind - owner.width / 2));
        owner.attacksToTheRight = item.dir < 0;
      }
      if (item.t === 18 && Math.abs(getFighterCenterX(owner) - getFighterCenterX(item.target)) < 140) darkworldHit(item, item.dmg, 6);
      item.done = item.t > 30;
    } else if (item.kind === 'guard') {
      item.done = owner.dwGuard <= 0;
    } else if (item.kind === 'stomp' || item.kind === 'roarRing') {
      const delay = item.kind === 'roarRing' ? 30 : 6;
      if (item.t > delay) {
        item.r += item.kind === 'roarRing' ? 13 : 9;
        const edges = [item.x - item.r, item.x + item.r];
        if (grounded && edges.some((edge) => edge > box.x - 15 && edge < box.x + box.w + 15)) darkworldHit(item, item.dmg, 6);
      }
      if (item.kind === 'roarRing' && item.t === delay + 1) chronoTitan.shake = 12;
      item.done = item.r > (item.kind === 'roarRing' ? canvas.width : 260);
    } else if (item.kind === 'miniLaser') {
      const eyeY = owner.position.y + 22;
      item.y = eyeY;
      if (item.t % 6 === 0 && item.t < 50) {
        const from = getFighterCenterX(owner);
        const reach = item.dir > 0 ? box.x > from : box.x + box.w < from;
        if (reach && eyeY > box.top && eyeY < box.bottom) {
          applyDamage(owner, item.target, item.dmg, { isSpecial: true });
          updateHealthBars();
        }
      }
      item.done = item.t > 50;
    } else if (item.kind === 'leap') {
      if (item.t < 30) owner.position.x += (getFighterCenterX(item.target) - getFighterCenterX(owner)) * 0.08;
      if (item.t > 12 && owner.position.y + owner.height >= ground - 2 && !item.landed) {
        item.landed = true;
        if (Math.abs(getFighterCenterX(owner) - getFighterCenterX(item.target)) < 130 && grounded) darkworldHit(item, item.dmg, 9);
        playNoise({ duration: 0.4, volume: 0.1, filterFrequency: 400 });
      }
      item.done = item.landed || item.t > 120;
    } else if (item.kind === 'spikes') {
      if (item.t === 45) playNoise({ duration: 0.5, volume: 0.12, filterFrequency: 900 });
      if (item.t > 45 && item.t < 70) item.spots.forEach((spot) => {
        if (spot > box.x - 30 && spot < box.x + box.w + 30 && box.bottom > ground - 150) darkworldHit(item, item.dmg, 9);
      });
      item.done = item.t > 85;
    } else if (item.kind === 'eyeBeam') {
      if (item.t > 30 && item.t <= 70) {
        item.sweep = item.from + item.dir * ((item.t - 30) / 40) * canvas.width;
        if (grounded && item.sweep > box.x && item.sweep < box.x + box.w) darkworldHit(item, item.dmg, 6);
      }
      item.done = item.t > 75;
    }
  });
  darkworldFx.items = darkworldFx.items.filter((item) => !item.done);
}

function drawDarkworldFx() {
  if (!gameStarted || !isDarkworldVersus()) return;
  const time = performance.now() / 1000;
  ctx.save();
  [player1, player2].forEach((fighter) => {
    if (fighter.dwGuard > 0) {
      ctx.strokeStyle = `rgba(179, 157, 219, ${0.5 + Math.sin(time * 10) * 0.3})`;
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.ellipse(getFighterCenterX(fighter), fighter.position.y + fighter.height / 2, fighter.width * 0.9, fighter.height * 0.65, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
  });
  // the card of Abnormal's rule (the one he plays on himself)
  if (darkworldFx.banner && darkworldFx.banner.t > 0) {
    const banner = darkworldFx.banner;
    banner.t -= 1;
    ctx.globalAlpha = Math.min(1, banner.t / 20);
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(5, 10, 30, 0.85)';
    ctx.fillRect(canvas.width / 2 - 280, 212, 560, 42);
    ctx.strokeStyle = '#90caf9';
    ctx.lineWidth = 2;
    ctx.strokeRect(canvas.width / 2 - 280, 212, 560, 42);
    ctx.fillStyle = '#90caf9';
    ctx.font = '900 11px Courier New, monospace';
    ctx.fillText('REGLA DE ABNORMAL', canvas.width / 2, 227);
    ctx.fillStyle = '#ffffff';
    ctx.font = '900 14px Courier New, monospace';
    ctx.fillText(banner.title, canvas.width / 2, 246);
    ctx.globalAlpha = 1;
    ctx.textAlign = 'left';
  }
  darkworldFx.items.forEach((item) => {
    const owner = item.owner;
    if (item.kind === 'fireball') {
      const glow = ctx.createRadialGradient(item.x, item.y, 2, item.x, item.y, 18);
      glow.addColorStop(0, '#fff59d');
      glow.addColorStop(0.5, '#ff5722');
      glow.addColorStop(1, 'rgba(183, 28, 28, 0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(item.x, item.y, 18, 0, Math.PI * 2);
      ctx.fill();
    } else if (item.kind === 'roar' || (item.kind === 'roarRing' && item.t <= 30)) {
      const k = item.kind === 'roar' ? item.t / 50 : item.t / 30;
      ctx.strokeStyle = `rgba(255, 255, 255, ${0.6 * (1 - k)})`;
      ctx.lineWidth = 4;
      for (let ring = 0; ring < 3; ring += 1) {
        ctx.beginPath();
        ctx.arc(getFighterCenterX(owner), owner.position.y + 50, 20 + k * 200 + ring * 20, 0, Math.PI * 2);
        ctx.stroke();
      }
    } else if (item.kind === 'darkWave') {
      ctx.fillStyle = '#1a0f2e';
      ctx.strokeStyle = '#b39ddb';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(item.x - item.dir * 30, ground);
      ctx.quadraticCurveTo(item.x + item.dir * 10, ground - 90, item.x + item.dir * 26, ground);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();
    } else if (item.kind === 'shadowStep' && item.t < 14) {
      ctx.fillStyle = `rgba(20, 0, 40, ${0.7 - item.t / 20})`;
      ctx.beginPath();
      ctx.ellipse(getFighterCenterX(owner), ground - 10, 60, 14, 0, 0, Math.PI * 2);
      ctx.fill();
    } else if ((item.kind === 'stomp' || item.kind === 'roarRing') && item.r > 0) {
      ctx.strokeStyle = item.kind === 'roarRing' ? 'rgba(255, 255, 255, 0.85)' : 'rgba(255, 255, 255, 0.6)';
      ctx.lineWidth = item.kind === 'roarRing' ? 6 : 4;
      [-1, 1].forEach((side) => {
        const ex = item.x + side * item.r;
        ctx.beginPath();
        ctx.moveTo(ex, ground);
        ctx.lineTo(ex - side * 20, ground - (item.kind === 'roarRing' ? 70 : 34));
        ctx.stroke();
      });
    } else if (item.kind === 'miniLaser' && item.t < 50) {
      const from = getFighterCenterX(owner);
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
      ctx.shadowColor = '#ffffff';
      ctx.shadowBlur = 12;
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(from, item.y);
      ctx.lineTo(item.dir > 0 ? canvas.width : 0, item.y);
      ctx.stroke();
      ctx.shadowBlur = 0;
    } else if (item.kind === 'spikes') {
      item.spots.forEach((spot) => {
        if (item.t <= 45) {
          ctx.fillStyle = `rgba(255, 255, 255, ${0.25 + Math.sin(time * 18) * 0.15})`;
          ctx.fillRect(spot - 30, ground - 6, 60, 6);
        } else {
          const rise = Math.min(1, (item.t - 45) / 8) * (item.t > 75 ? Math.max(0, 1 - (item.t - 75) / 10) : 1);
          ctx.fillStyle = '#000000';
          ctx.strokeStyle = '#ffffff';
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.moveTo(spot - 28, ground);
          ctx.lineTo(spot, ground - 150 * rise);
          ctx.lineTo(spot + 28, ground);
          ctx.closePath();
          ctx.fill();
          ctx.stroke();
        }
      });
    } else if (item.kind === 'eyeBeam') {
      const eye = { x: getFighterCenterX(owner) + item.dir * 12, y: owner.position.y + 18 };
      if (item.t <= 30) {
        ctx.fillStyle = `rgba(255, 255, 255, ${item.t / 30})`;
        ctx.beginPath();
        ctx.arc(eye.x, eye.y, 6 + item.t / 3, 0, Math.PI * 2);
        ctx.fill();
      } else if (item.sweep !== undefined) {
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.95)';
        ctx.shadowColor = '#ffffff';
        ctx.shadowBlur = 20;
        ctx.lineWidth = 10;
        ctx.beginPath();
        ctx.moveTo(eye.x, eye.y);
        ctx.lineTo(item.sweep, ground - 4);
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
    }
  });
  ctx.restore();
}

// Abnormal sees a titan about to squash someone... and makes a rule
abnCameoScenes.titanRule = [
  { speaker: 'abnormal', text: '¡¡ALTO, ALTO, ALTO!! ¿Un TITAN contra ESO? ¡Esto no es una pelea, es un aplastamiento!', descend: true, shock: true },
  { speaker: 'abnormal', text: 'Lo vi de cerca, eh. Tiene cicatriz, mal humor y cero modales. Pero como Guardia Supremo y EXPERTO en reglas...' },
  { speaker: 'abnormal', text: '¡DECLARO UNA REGLA NUEVA: EL RIVAL DEL TITAN TAMBIEN ES GIGANTE!', giantRule: true },
  { speaker: 'abnormal', text: '¡JO JO! ¡Ahora si! ¡Una verdadera PELEA DE TITANES! Distinguidamente justa. ¡Peleen!', ascend: true },
];

