// after the scene: Light Warrior becomes OMEGA... and the titan, the one from chapter 6
function startTitanOmegaShowdown() {
  const titan = isTitanGiant(player1) ? player1 : player2;
  const hero = titan === player1 ? player2 : player1;
  titan.setMaxHealth(5000);
  titan.health = 5000;
  updateHealthBars();
  if (typeof startLightWarriorOmegaTransformation === 'function') startLightWarriorOmegaTransformation(hero, hero === player1 ? 1 : 2);
  playSound('titanRoar');
}

