  blackKnightBoss: { divineGeneral: 'Otra vez de rodillas, desterrado. Como el dia que te expulsaron.', abnormal: 'Volve a tu portal, guardia. Y deja de jugar a los heroes.', chrono: 'Un reloj roto no detiene a la Orden.' },
  hydraBeast: { chrono: '(*las tres cabezas olfatean los engranajes... y gruñen satisfechas*)' },
