      Object.assign(debugSettings, {
        damageMultiplier: pick(0.5, 3, 0.25), healthMultiplier: pick(0.5, 3, 0.25), moveMultiplier: pick(0.5, 2.5, 0.25), cooldownMultiplier: pick(0, 2, 0.25),
        gravityMultiplier: pick(0.25, 2, 0.25), projectileMultiplier: pick(0.5, 3, 0.25), durationMultiplier: pick(0.5, 2, 0.25), knockbackMultiplier: pick(0.5, 3, 0.25),
      });
