function syncDebugTabs() {
  document.querySelectorAll('.dbg-tab').forEach((tab) => tab.classList.toggle('active', tab.dataset.dbgTab === debugConsole.tab));
  document.querySelectorAll('.dbg-panel').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.dbgPanel !== debugConsole.tab));
}

function getDebugCanvasFilter() {
  const parts = [];
  if (debugExtras.night) parts.push('brightness(0.5) contrast(1.25) saturate(0.8)');
  if (debugExtras.retro) parts.push('grayscale(1) contrast(1.35)');
  if (debugExtras.rainbow) parts.push(`hue-rotate(${(debugConsole.frame * 4) % 360}deg) saturate(1.4)`);
  return parts.join(' ');
}

function syncDebugCanvasLook() {
  canvas.style.transform = debugExtras.mirror ? 'scaleX(-1)' : '';
  canvas.style.filter = getDebugCanvasFilter();
}

// ---------- in the fight ----------
// (the game speed: frames are skipped or doubled)
(function hookDebugGameSpeed() {
  const originalAnimate = window.animate;
  if (typeof originalAnimate !== 'function') return;
  let tick = 0;
  window.animate = function animateWithDebugSpeed(...args) {
    const speed = debugExtras.gameSpeed;
    if (speed < 1 && gameStarted) {
      tick += 1;
      const every = Math.round(1 / speed);
      if (tick % every !== 0) {
        animationId = requestAnimationFrame(window.animate);
        return undefined;
      }
    }
    const result = originalAnimate.apply(this, args);
    if (speed > 1 && gameStarted && animationId && !gameOver) {
      const extra = Math.round(speed) - 1;
      for (let step = 0; step < extra && animationId; step += 1) {
        cancelAnimationFrame(animationId);
        originalAnimate.apply(this, args);
      }
    }
    return result;
  };
})();

function updateDebugExtras() {
  if (!gameStarted) return;
  const now = performance.now();
  if (debugConsole.lastTime) debugConsole.fps = debugConsole.fps * 0.9 + (1000 / Math.max(1, now - debugConsole.lastTime)) * 0.1;
  debugConsole.lastTime = now;
  debugConsole.frame += 1;
  if (gameOver) return;
  if (debugExtras.godP1) player1.health = player1.maxHealth;
  if (debugExtras.godP2) player2.health = player2.maxHealth;
  if (debugExtras.godP1 || debugExtras.godP2) updateHealthBars();
  if (debugExtras.p1Size !== 1) player1.giantScale = debugExtras.p1Size;
  if (debugExtras.p2Size !== 1) player2.giantScale = debugExtras.p2Size;
  if (debugExtras.freezeBot && botEnabled) {
    player2.velocity.x = 0;
    player2.isAttacking = false;
  }
  if (debugExtras.rainbow) canvas.style.filter = getDebugCanvasFilter();
}

// (KO of one hit: asked by applyDamage)
function debugExtraDamageScale(attacker, target) {
  if (debugExtras.godP1 && target === player1) return 0;
  if (debugExtras.godP2 && target === player2) return 0;
  return debugExtras.oneHitKo && target && target.health > 0 ? 9999 : 1;
}

function drawDebugExtras() {
  if (!gameStarted) return;
  ctx.save();
  if (debugExtras.hitboxes) {
    ctx.lineWidth = 2;
    [player1, player2].forEach((fighter) => {
      ctx.strokeStyle = 'rgba(0, 229, 255, 0.9)';
      ctx.strokeRect(fighter.position.x, fighter.position.y, fighter.width, fighter.height);
      ctx.fillStyle = 'rgba(0, 229, 255, 0.9)';
      ctx.fillRect(fighter.position.x + fighter.width / 2 - 2, fighter.position.y + fighter.height - 2, 4, 4);
      if (fighter.isAttacking) {
        const area = fighter.attackArea;
        ctx.fillStyle = 'rgba(255, 23, 68, 0.25)';
        ctx.fillRect(area.x, area.y, area.width, area.height);
        ctx.strokeStyle = 'rgba(255, 23, 68, 0.95)';
        ctx.strokeRect(area.x, area.y, area.width, area.height);
      }
    });
    ctx.strokeStyle = 'rgba(105, 240, 174, 0.6)';
    ctx.setLineDash([6, 6]);
    ctx.beginPath();
    ctx.moveTo(0, ground);
    ctx.lineTo(canvas.width, ground);
    ctx.stroke();
    ctx.setLineDash([]);
  }
  if (debugExtras.infoPanel) {
    const row = (fighter, label) => `${label} ${(fighter.secretVariant || fighter.characterType).slice(0, 12).padEnd(12)} x:${String(Math.round(fighter.position.x)).padStart(4)} y:${String(Math.round(fighter.position.y)).padStart(4)} vx:${fighter.velocity.x.toFixed(1).padStart(5)} vy:${fighter.velocity.y.toFixed(1).padStart(5)} hp:${Math.round(fighter.health)}/${Math.round(fighter.maxHealth)}${fighter.isAttacking ? ' ATK' : ''}`;
    const lines = [
      `FPS ${Math.round(debugConsole.fps)}  frame ${debugConsole.frame}  mapa ${selectedMap}  vel x${debugExtras.gameSpeed}`,
      row(player1, 'P1'),
      row(player2, 'P2'),
    ];
    ctx.font = '700 11px Courier New, monospace';
    const width = Math.max(...lines.map((line) => ctx.measureText(line).width)) + 20;
    const x = canvas.width / 2 - width / 2;
    ctx.fillStyle = 'rgba(0, 10, 4, 0.82)';
    ctx.fillRect(x, canvas.height - 64, width, 56);
    ctx.strokeStyle = '#00e676';
    ctx.lineWidth = 1;
    ctx.strokeRect(x, canvas.height - 64, width, 56);
    ctx.fillStyle = '#69f0ae';
    lines.forEach((line, index) => ctx.fillText(line, x + 10, canvas.height - 48 + index * 16));
  }
  ctx.restore();
}

// the shortcuts in a fight
window.addEventListener('keydown', (event) => {
  if (!debugExtras.shortcuts || !gameStarted || gameOver || !['F6', 'F7', 'F8', 'F9'].includes(event.key)) return;
  if (!(typeof isDebugModified === 'function' && (isDebugModified() || debugExtrasChanged().length)) && !debugConsole.used) return;
  event.preventDefault();
  if (event.key === 'F6') {
    player1.health = player1.maxHealth;
    player2.health = player2.maxHealth;
    updateHealthBars();
  } else if (event.key === 'F7') {
    player2.health = 1;
    updateHealthBars();
  } else if (event.key === 'F8') {
    debugExtras.hitboxes = !debugExtras.hitboxes;
  } else {
    const speeds = [1, 0.5, 0.25, 2];
    debugExtras.gameSpeed = speeds[(speeds.indexOf(debugExtras.gameSpeed) + 1) % speeds.length];
  }
  playTone({ frequency: 990, duration: 0.06, type: 'square', volume: 0.03 });
});

(function hookDebugConsole() {
  buildDebugConsole();
  const originalOpen = window.openDebug;
  if (typeof originalOpen === 'function') {
    window.openDebug = function openDebugConsole(...args) {
      const result = originalOpen.apply(this, args);
      debugConsole.used = true;
      syncDebugControls();
      refreshDebugConsole();
      return result;
    };
  }
})();

// ---------- the console, part 2: who is affected (with every secret one), save slots, the in-fight badge ----------
const debugAffectedVariants = {};
const debugTargetGroups = [
  { id: 'base', name: 'Personajes base', hint: 'El roster de siempre', color: '#69f0ae', base: true, list: characterTypes },
  { id: 'special', name: 'Especiales', hint: 'Desbloqueables y desafios', color: '#ffd54f', list: ['superFireMaster', 'scammer', 'neoScammer', 'knight', 'shaolinMaster', 'abnormal', 'frostFire', 'obsidian'] },
  { id: 'arcade', name: 'Jefes de arcade', hint: 'Codigo bossrush · los jefes finales', color: '#ff5252', list: ['arcadeBoss', 'iceMaster', 'shadowJester', 'titanUnit', 'omegarius'] },
  { id: 'mini', name: 'Mini jefes', hint: 'Codigo bossrush · a mitad de capitulo', color: '#ff8a65', list: ['icedThug', 'defectiveAssembler', 'chronoRival'] },
  { id: 'magic', name: 'Magic Town', hint: 'Codigo magictown', color: '#4fc3f7', list: magicTownVariants },
  { id: 'origins', name: 'La ciudad', hint: 'Codigos 911 y friend', color: '#b39ddb', list: ['policeOfficer', 'policeSergeant', 'policeChief', 'friendThing', 'bigFriend'] },
  { id: 'dark', name: 'Mundo oscuro', hint: 'Codigo darkworld', color: '#ea80fc', list: darkworldVariants },
];
// (some of them don't know their own name outside their chapter)
const debugVariantNames = { arcadeBoss: 'Jefe de la Banda', icedThug: 'Maton Helado', iceMaster: 'Ice Master', shadowJester: 'Shadow Jester', defectiveAssembler: 'Ensambladora Defectuosa', chronoRival: 'Chrono Potenciado', titanUnit: 'Proyecto Titan', omegarius: 'Omegarius', superFireMaster: 'Super Fire Master', obsidian: 'Obsidian', titanGiant: 'Titan', neoScammer: 'Neo Scammer' };
const debugUi = { search: '' };

function getDebugVariantName(variant) {
  if (debugVariantNames[variant]) return debugVariantNames[variant];
  let name = variant;
  try {
    const actor = new Fighter({ x: 0, y: 0, color: '#999999', attacksToTheRight: true });
    actor.setCharacterType(variant === 'superFireMaster' || variant === 'frostFire' || variant === 'obsidian' ? 'fireMaster' : 'normal', variant);
    name = getCharacterDisplayName(actor) || variant;
    if (variant === 'superFireMaster') name = 'Super Fire Master';
    if (variant === 'obsidian') name = 'Obsidian';
  } catch (error) {
    // (the id is better than nothing)
  }
  debugVariantNames[variant] = name;
  return name;
}

function isDebugVariantKnown(variant) {
  return debugTargetGroups.some((group) => !group.base && group.list.includes(variant));
}

// (asked by isDebugAffected: null = "decide as always")
function debugTargetFilter(fighter) {
  const side = debugExtras.affectSide || 'both';
  if (side === 'p1' && fighter === player2) return false;
  if (side === 'p2' && fighter === player1) return false;
  if (fighter.secretVariant && isDebugVariantKnown(fighter.secretVariant)) return debugAffectedVariants[fighter.secretVariant] !== false;
  return null;
}

function isDebugTargetOn(group, id) {
  return group.base ? debugAffectedCharacters[id] !== false : debugAffectedVariants[id] !== false;
}

function setDebugTarget(group, id, on) {
  if (group.base) debugAffectedCharacters[id] = on;
  else debugAffectedVariants[id] = on;
}

function debugExcludedCount() {
  return debugTargetGroups.reduce((sum, group) => sum + group.list.filter((id) => !isDebugTargetOn(group, id)).length, 0);
}

function renderDebugTargets() {
  const panel = document.querySelector('[data-dbg-panel="targets"] .dbg-targets');
  if (!panel) return;
  const side = debugExtras.affectSide || 'both';
  panel.querySelectorAll('.dbg-side button').forEach((button) => button.classList.toggle('active', button.dataset.side === side));
  const groupsBox = panel.querySelector('.dbg-groups');
  groupsBox.innerHTML = '';
  const search = debugUi.search.trim().toLowerCase();
  debugTargetGroups.forEach((group) => {
    const items = group.list.map((id) => ({ id, name: group.base ? characterDisplayNames[id] || id : getDebugVariantName(id) }))
      .filter((item) => !search || item.name.toLowerCase().includes(search) || item.id.toLowerCase().includes(search));
    if (!items.length) return;
    const on = group.list.filter((id) => isDebugTargetOn(group, id)).length;
    const box = document.createElement('div');
    box.className = 'dbg-group';
    box.style.setProperty('--grp', group.color);
    box.innerHTML = `
      <div class="dbg-group-head">
        <span class="dbg-group-dot"></span>
        <strong>${group.name}</strong>
        <small>${group.hint}</small>
        <span class="dbg-group-count">${on}/${group.list.length}</span>
        <button type="button" class="dbg-mini" data-all="1">Todos</button>
        <button type="button" class="dbg-mini" data-all="0">Ninguno</button>
      </div>
      <div class="dbg-chips"></div>`;
    box.querySelectorAll('.dbg-mini').forEach((button) => button.addEventListener('click', () => {
      group.list.forEach((id) => setDebugTarget(group, id, button.dataset.all === '1'));
      syncDebugControls();
      renderDebugTargets();
      refreshDebugConsole();
    }));
    const chips = box.querySelector('.dbg-chips');
    items.forEach((item) => {
      const chip = document.createElement('button');
      chip.type = 'button';
      const active = isDebugTargetOn(group, item.id);
      chip.className = `dbg-target${active ? ' on' : ''}`;
      chip.innerHTML = `<span class="dbg-target-mark">${active ? '✓' : '✕'}</span>${item.name}`;
      chip.addEventListener('click', () => {
        setDebugTarget(group, item.id, !isDebugTargetOn(group, item.id));
        syncDebugControls();
        renderDebugTargets();
        refreshDebugConsole();
        playTone({ frequency: active ? 330 : 660, duration: 0.05, type: 'square', volume: 0.03 });
      });
      chips.appendChild(chip);
    });
    groupsBox.appendChild(box);
  });
  if (!groupsBox.children.length) groupsBox.innerHTML = '<p class="dbg-empty">Nadie con ese nombre en el juego. ¿Seguro que existe?</p>';
}

function buildDebugTargets() {
  const panel = document.querySelector('[data-dbg-panel="targets"]');
  if (!panel || panel.querySelector('.dbg-targets')) return;
  const old = panel.querySelector('.debug-targets');
  if (old) old.classList.add('hidden');
  const box = document.createElement('div');
  box.className = 'dbg-targets';
  box.innerHTML = `
    <div class="dbg-targets-top">
      <div class="dbg-side" role="group" aria-label="A quien afecta">
        <span>Afecta a:</span>
        <button type="button" data-side="both">Ambos</button>
        <button type="button" data-side="p1">Solo P1</button>
        <button type="button" data-side="p2">Solo P2</button>
      </div>
      <label class="dbg-search"><span aria-hidden="true">&gt;</span><input type="search" placeholder="buscar personaje..." /></label>
    </div>
    <div class="dbg-groups"></div>`;
  box.querySelectorAll('.dbg-side button').forEach((button) => button.addEventListener('click', () => {
    debugExtras.affectSide = button.dataset.side;
    renderDebugTargets();
    refreshDebugConsole();
  }));
  const input = box.querySelector('.dbg-search input');
  input.addEventListener('input', () => {
    debugUi.search = input.value;
    renderDebugTargets();
  });
  panel.appendChild(box);
  renderDebugTargets();
}

// ---------- save slots ----------
const debugSlotsKey = 'moqueteDebugSlots';

function readDebugSlots() {
  try {
    const slots = JSON.parse(localStorage.getItem(debugSlotsKey) || '[]');
    return Array.isArray(slots) ? slots : [];
  } catch (error) {
    return [];
  }
}

function writeDebugSlots(slots) {
  try {
    localStorage.setItem(debugSlotsKey, JSON.stringify(slots));
  } catch (error) {
    // only for this session
  }
}

function renderDebugSlots() {
  const box = document.querySelector('.dbg-slots');
  if (!box) return;
  const slots = readDebugSlots();
  box.innerHTML = '';
  for (let index = 0; index < 3; index += 1) {
    const slot = slots[index];
    const card = makeDebugCard(`
      <span class="dbg-label">Ranura ${index + 1}</span>
      <small>${slot ? `${slot.summary || 'Sin cambios'}<br><em>${slot.date}</em>` : 'Vacia'}</small>
      <div class="dbg-slot-actions">
        <button type="button" class="dbg-mini" data-act="save">Guardar</button>
        <button type="button" class="dbg-mini" data-act="load"${slot ? '' : ' disabled'}>Cargar</button>
      </div>`, 'dbg-slot');
    card.querySelector('[data-act="save"]').addEventListener('click', () => {
      const all = readDebugSlots();
      const changed = debugSettingsChanged().concat(debugExtrasChanged()).map((key) => debugLabels[key] || key);
      all[index] = { settings: { ...debugSettings }, extras: { ...debugExtras }, characters: { ...debugAffectedCharacters }, variants: { ...debugAffectedVariants }, summary: changed.join(', '), date: new Date().toLocaleString() };
      writeDebugSlots(all);
      renderDebugSlots();
      showDebugConsoleToast(`Guardado en la ranura ${index + 1}`);
    });
    card.querySelector('[data-act="load"]').addEventListener('click', () => {
      const saved = readDebugSlots()[index];
      if (!saved) return;
      Object.assign(debugSettings, defaultDebugSettings, saved.settings || {});
      Object.assign(debugExtras, defaultDebugExtras, saved.extras || {});
      Object.assign(debugAffectedCharacters, saved.characters || {});
      Object.keys(debugAffectedVariants).forEach((key) => delete debugAffectedVariants[key]);
      Object.assign(debugAffectedVariants, saved.variants || {});
      applyDebugSettings();
      syncDebugCanvasLook();
      renderDebugTargets();
      refreshDebugConsole();
      showDebugConsoleToast(`Ranura ${index + 1} cargada`);
    });
    box.appendChild(card);
  }
}

function buildDebugSlots() {
  const panel = document.querySelector('[data-dbg-panel="presets"]');
  if (!panel || panel.querySelector('.dbg-slots')) return;
  const title = document.createElement('h4');
  title.className = 'dbg-subtitle';
  title.textContent = '> Tus configuraciones';
  const box = document.createElement('div');
  box.className = 'dbg-grid dbg-slots';
  panel.append(title, box);
  renderDebugSlots();
}

// ---------- the badge in the fight: so nobody forgets the console is on ----------
function drawDebugBadge() {
  if (!gameStarted || gameOver || !debugConsole.used) return;
  const changed = debugSettingsChanged().length + debugExtrasChanged().length + (debugExcludedCount() > 0 ? 1 : 0);
  if (!changed) return;
  ctx.save();
  ctx.font = '900 11px Courier New, monospace';
  ctx.textAlign = 'center';
  const text = `DEBUG · ${changed} cambio${changed > 1 ? 's' : ''}`;
  const width = ctx.measureText(text).width + 18;
  ctx.fillStyle = 'rgba(0, 20, 8, 0.8)';
  ctx.fillRect(canvas.width / 2 - width / 2, 6, width, 18);
  ctx.strokeStyle = '#00e676';
  ctx.strokeRect(canvas.width / 2 - width / 2, 6, width, 18);
  ctx.fillStyle = Math.floor(performance.now() / 600) % 2 ? '#69f0ae' : '#b9f6ca';
  ctx.fillText(text, canvas.width / 2, 19);
  ctx.restore();
}

(function hookDebugConsolePart2() {
  defaultDebugExtras.affectSide = 'both';
  if (!debugExtras.affectSide) debugExtras.affectSide = 'both';
  debugLabels.affectSide = 'Solo un jugador';
  buildDebugTargets();
  buildDebugSlots();
  const originalRefresh = window.refreshDebugConsole;
  window.refreshDebugConsole = function refreshDebugConsoleWithTargets(...args) {
    originalRefresh.apply(this, args);
    const status = document.querySelector('.dbg-status');
    const excluded = debugExcludedCount();
    if (status && excluded) {
      status.classList.add('dirty');
      status.insertAdjacentHTML('beforeend', ` <span class="dbg-chip dbg-chip-alt">${excluded} personaje${excluded > 1 ? 's' : ''} sin cambios</span>`);
    }
  };
  const originalDraw = window.drawDebugExtras;
  window.drawDebugExtras = function drawDebugExtrasWithBadge(...args) {
    originalDraw.apply(this, args);
    drawDebugBadge();
  };
  // (resetting everything frees every character too)
  const resetAll = document.getElementById('debugResetButton');
  if (resetAll) resetAll.addEventListener('click', () => {
    Object.keys(debugAffectedVariants).forEach((key) => delete debugAffectedVariants[key]);
    debugExtras.affectSide = 'both';
    setTimeout(() => {
      renderDebugTargets();
      refreshDebugConsole();
    }, 0);
  });
  refreshDebugConsole();
})();

