// each line stays on screen from its "show" until the next one comes up
(function timeLightfullLyrics() {
  lightfullLyrics.forEach((stanza) => {
    stanza.lines.forEach((line, index) => {
      const next = stanza.lines[index + 1];
      line.start = line.show;
      line.end = next ? next.show : stanza.to;
      line.singStart = line.sweep.length ? line.sweep[0][0] : line.show;
    });
  });
})();

// how much of the line is already sung at this second (straight from the video's green)
function getLightfullSung(line, time) {
  const sweep = line.sweep;
  if (!sweep.length || time < sweep[0][0]) return 0;
  if (time >= sweep[sweep.length - 1][0]) return 1;
  for (let index = 1; index < sweep.length; index += 1) {
    const [t1, f1] = sweep[index];
    if (time < t1) {
      const [t0, f0] = sweep[index - 1];
      return f0 + ((f1 - f0) * (time - t0)) / Math.max(0.01, t1 - t0);
    }
  }
  return 1;
}

function getLightfullTrack() {
  if (typeof reflecterBattleMusic === 'undefined' || reflecterBattleMusic.current !== 'lightFinal') return null;
  const track = reflecterBattleMusic.tracks && reflecterBattleMusic.tracks.lightFinal;
  return track && !track.paused ? track : null;
}

function findLightfullLine(time) {
  for (const stanza of lightfullLyrics) {
    if (time < stanza.from - 1.5 || time > stanza.to + 1.2) continue;
    const index = stanza.lines.findIndex((line) => time >= line.start && time < line.end);
    if (index >= 0) return { stanza, index, line: stanza.lines[index] };
    if (time < stanza.from) return { stanza, index: -1, line: null };
    return { stanza, index: stanza.lines.length - 1, line: stanza.lines[stanza.lines.length - 1], over: true };
  }
  return null;
}

function drawLightfullLyrics(forcedTime = null) {
  if (!gameStarted && forcedTime === null) return;
  const track = getLightfullTrack();
  if (!track && forcedTime === null) return;
  const time = forcedTime !== null ? forcedTime : track.currentTime;
  const found = findLightfullLine(time);
  if (!found) return;
  const { stanza, index, line } = found;
  const now = performance.now() / 1000;
  const baseY = canvas.height - 46;
  ctx.save();
  // a warm band of light behind the words
  const fadeIn = Math.min(1, (time - (stanza.from - 1.5)) / 1.5);
  const fadeOut = Math.min(1, (stanza.to + 1.2 - time) / 1.2);
  const alpha = Math.max(0, Math.min(fadeIn, fadeOut));
  ctx.globalAlpha = alpha;
  const band = ctx.createLinearGradient(0, baseY - 60, 0, canvas.height);
  band.addColorStop(0, 'rgba(62, 39, 35, 0)');
  band.addColorStop(0.45, 'rgba(62, 39, 35, 0.55)');
  band.addColorStop(1, 'rgba(30, 18, 8, 0.75)');
  ctx.fillStyle = band;
  ctx.fillRect(0, baseY - 60, canvas.width, canvas.height - baseY + 60);
  if (!line) {
    // (a little sun waiting for the first word)
    drawLyricsSun(canvas.width / 2, baseY - 8, 10 + Math.sin(now * 4) * 2, alpha);
    ctx.restore();
    return;
  }
  // the current line: word by word, like a karaoke
  const progress = getLightfullSung(line, time);
  const words = line.text.split(' ');
  // (a word lights up once the green has gone past most of it, like in the video)
  const lengths = words.map((word) => word.length + 1);
  const totalLength = lengths.reduce((sum, value) => sum + value, 0);
  let reached = 0;
  let sung = 0;
  lengths.forEach((value) => {
    if (reached + value * 0.6 <= progress * totalLength + 0.01) sung += 1;
    reached += value;
  });
  if (found.over) sung = words.length;
  const size = line.big ? 34 : 24;
  // (the big lines bounce on the song's own beat: 4 per bar)
  const bounce = line.big ? Math.abs(Math.sin((time / (lightfullBar / 4)) * Math.PI)) * 5 : 0;
  ctx.font = `900 ${size}px Courier New, monospace`;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  const full = ctx.measureText(line.text).width;
  let x = canvas.width / 2 - full / 2;
  const y = baseY - bounce;
  const lineIn = Math.min(1, (time - line.start) / 0.25);
  ctx.globalAlpha = alpha * lineIn;
  words.forEach((word, wordIndex) => {
    const text = wordIndex < words.length - 1 ? `${word} ` : word;
    const width = ctx.measureText(text).width;
    const lit = wordIndex < sung;
    ctx.lineWidth = 6;
    ctx.strokeStyle = '#3e2723';
    ctx.strokeText(text, x, y);
    ctx.shadowColor = lit ? '#fdd835' : 'transparent';
    ctx.shadowBlur = lit ? (line.big ? 22 : 12) : 0;
    ctx.fillStyle = lit ? (line.big ? '#fff59d' : '#ffe082') : 'rgba(255, 255, 255, 0.45)';
    ctx.fillText(text, x, y);
    ctx.shadowBlur = 0;
    x += width;
  });
  if (line.big) {
    drawLyricsSun(canvas.width / 2 - full / 2 - 34, y, 13, alpha);
    drawLyricsSun(canvas.width / 2 + full / 2 + 34, y, 13, alpha);
  }
  // the next line, small, so you can sing along
  const next = stanza.lines[index + 1];
  if (next && !found.over) {
    ctx.globalAlpha = alpha * 0.55;
    ctx.font = '700 14px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(next.text, canvas.width / 2, baseY + 28);
  }
  ctx.restore();
}

function drawLyricsSun(x, y, r, alpha) {
  const time = performance.now() / 1000;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(x, y);
  ctx.rotate(time);
  ctx.strokeStyle = '#fdd835';
  ctx.lineWidth = 2;
  for (let ray = 0; ray < 8; ray += 1) {
    const a = (ray / 8) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * r * 1.2, Math.sin(a) * r * 1.2);
    ctx.lineTo(Math.cos(a) * r * 1.8, Math.sin(a) * r * 1.8);
    ctx.stroke();
  }
  ctx.fillStyle = '#fff59d';
  ctx.shadowColor = '#fdd835';
  ctx.shadowBlur = 12;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// drawn on top of every part of the fight (the boxes, the climb, the kicks...)
(function hookLightfullLyrics() {
  const originalAnimate = window.animate;
  if (typeof originalAnimate !== 'function') return;
  window.animate = function animateWithLyrics(...args) {
    const result = originalAnimate.apply(this, args);
    try {
      drawLightfullLyrics();
    } catch (error) {
      // (never let a lyric break the fight)
    }
    return result;
  };
})();

// ================= chapter 5, level 7: OMEGA LIGHT WARRIOR's transformation, bigger =================
function updateOmegaTransformEpic(cutscene) {
  if (cutscene.phase !== 'transform') return;
  const frame = cutscene.frame;
  const epic = cutscene.omegaEpic || (cutscene.omegaEpic = { motes: [], sparks: [], bolts: [] });
  const lwX = cutscene.scammerX + player2.width / 2;
  const lwY = ground - player2.height / 2 - cutscene.scammerY;
  // light rising off the ground toward him
  if (frame < 235 && Math.random() < 0.6) epic.motes.push({ x: lwX + (Math.random() - 0.5) * 500, y: ground + 10, vy: -2 - Math.random() * 3, life: 90 });
  epic.motes.forEach((mote) => {
    mote.y += mote.vy;
    mote.x += (lwX - mote.x) * 0.012;
    mote.life -= 1;
  });
  epic.motes = epic.motes.filter((mote) => mote.life > 0);
  // the charge: the screen shakes harder and harder, a rising hum
  if (frame > 150 && frame < 235) {
    cutscene.shake = 2 + (frame - 150) / 10;
    if (frame % 12 === 0) playTone({ frequency: 200 + (frame - 150) * 9, duration: 0.25, type: 'sawtooth', volume: 0.035 });
    if (Math.random() < 0.18) epic.bolts.push({ angle: Math.random() * Math.PI * 2, life: 8, seed: Math.random() * 100 });
  }
  epic.bolts.forEach((bolt) => (bolt.life -= 1));
  epic.bolts = epic.bolts.filter((bolt) => bolt.life > 0);
  // the moment: a shockwave, a burst of sparks, the whole farol shaking
  if (frame === 235) {
    epic.wave = 0;
    for (let spark = 0; spark < 90; spark += 1) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 4 + Math.random() * 12;
      epic.sparks.push({ x: lwX, y: lwY, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, life: 60 + Math.random() * 40 });
    }
    playSound('omegaKickImpact');
    playNoise({ duration: 1.4, volume: 0.18, filterFrequency: 2500 });
  }
  if (frame >= 235 && frame < 265) cutscene.shake = 16 - (frame - 235) / 2;
  if (typeof epic.wave === 'number') epic.wave += 26;
  epic.sparks.forEach((spark) => {
    spark.x += spark.vx;
    spark.y += spark.vy;
    spark.vx *= 0.96;
    spark.vy = spark.vy * 0.96 + 0.05;
    spark.life -= 1;
  });
  epic.sparks = epic.sparks.filter((spark) => spark.life > 0);
  if (frame > 240 && Math.random() < 0.4) epic.sparks.push({ x: lwX + (Math.random() - 0.5) * 260, y: lwY + (Math.random() - 0.5) * 200, vx: 0, vy: -0.6, life: 70 });
}

function drawOmegaTransformEpic(cutscene) {
  if (cutscene.phase !== 'transform' || !cutscene.omegaEpic) return;
  const epic = cutscene.omegaEpic;
  const frame = cutscene.frame;
  const time = performance.now() / 1000;
  const lwX = cutscene.scammerX + player2.width / 2;
  const lwY = ground - player2.height / 2 - cutscene.scammerY;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  // a column of light coming down from the sky
  const pillar = frame < 60 ? frame / 60 : frame < 235 ? 1 : Math.max(0.35, 1 - (frame - 235) / 120);
  const pillarW = 40 + (frame < 235 ? frame / 3 : 120) + Math.sin(time * 9) * 6;
  const beam = ctx.createLinearGradient(lwX - pillarW, 0, lwX + pillarW, 0);
  beam.addColorStop(0, 'rgba(255, 241, 118, 0)');
  beam.addColorStop(0.5, `rgba(255, 249, 196, ${0.35 * pillar})`);
  beam.addColorStop(1, 'rgba(255, 241, 118, 0)');
  ctx.fillStyle = beam;
  ctx.fillRect(lwX - pillarW, 0, pillarW * 2, ground);
  // the floor of the farol glows under him
  const floor = ctx.createRadialGradient(lwX, ground, 4, lwX, ground, 260);
  floor.addColorStop(0, `rgba(255, 241, 118, ${0.45 * pillar})`);
  floor.addColorStop(1, 'rgba(255, 241, 118, 0)');
  ctx.fillStyle = floor;
  ctx.fillRect(lwX - 260, ground - 60, 520, 120);
  // motes of light rising
  ctx.fillStyle = 'rgba(255, 249, 196, 0.8)';
  epic.motes.forEach((mote) => ctx.fillRect(mote.x - 1.5, mote.y - 1.5, 3, 3));
  // the charge: rings of energy closing in on him, lightning around
  if (frame > 120 && frame < 235) {
    for (let ring = 0; ring < 4; ring += 1) {
      const k = 1 - (((frame + ring * 12) % 48) / 48);
      ctx.strokeStyle = `rgba(255, 241, 118, ${0.7 * (1 - k)})`;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.ellipse(lwX, lwY, 40 + k * 300, (40 + k * 300) * 0.55, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
  }
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
  ctx.lineWidth = 2.5;
  epic.bolts.forEach((bolt) => {
    ctx.beginPath();
    let x = lwX;
    let y = lwY;
    ctx.moveTo(x, y);
    for (let step = 1; step <= 6; step += 1) {
      x = lwX + Math.cos(bolt.angle) * step * 26 + Math.sin(bolt.seed + step * 3) * 14;
      y = lwY + Math.sin(bolt.angle) * step * 18 + Math.cos(bolt.seed + step * 2) * 12;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  });
  // after: wings of light beating behind him
  if (frame >= 235) {
    const open = Math.min(1, (frame - 235) / 40);
    const beat = Math.sin(time * 4) * 0.12;
    [-1, 1].forEach((side) => {
      ctx.save();
      ctx.translate(lwX, lwY - 10);
      ctx.scale(side, 1);
      ctx.rotate(-0.25 + beat);
      const wing = ctx.createLinearGradient(0, 0, 220 * open, 0);
      wing.addColorStop(0, 'rgba(255, 249, 196, 0.55)');
      wing.addColorStop(1, 'rgba(255, 213, 79, 0)');
      ctx.fillStyle = wing;
      ctx.beginPath();
      ctx.moveTo(10, 0);
      ctx.quadraticCurveTo(120 * open, -150 * open, 240 * open, -110 * open);
      ctx.quadraticCurveTo(170 * open, -40 * open, 210 * open, 10 * open);
      ctx.quadraticCurveTo(130 * open, 10 * open, 150 * open, 60 * open);
      ctx.quadraticCurveTo(80 * open, 40 * open, 10, 20);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });
  }
  // sparks
  epic.sparks.forEach((spark) => {
    ctx.fillStyle = `rgba(255, 249, 196, ${Math.min(1, spark.life / 40)})`;
    ctx.fillRect(spark.x - 2, spark.y - 2, 4, 4);
  });
  ctx.globalCompositeOperation = 'source-over';
  // the shockwave across the whole screen
  if (typeof epic.wave === 'number' && epic.wave < canvas.width * 1.4) {
    ctx.strokeStyle = `rgba(255, 255, 255, ${Math.max(0, 1 - epic.wave / (canvas.width * 1.4))})`;
    ctx.lineWidth = 14;
    ctx.beginPath();
    ctx.arc(lwX, lwY, epic.wave, 0, Math.PI * 2);
    ctx.stroke();
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(lwX, lwY, epic.wave * 0.75, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

(function hookOmegaTransformEpic() {
  const originalUpdate = window.updateKnightFarolTop;
  const originalDraw = window.drawKnightFarolTopFx;
  if (typeof originalUpdate === 'function') {
    window.updateKnightFarolTop = function updateKnightFarolTopEpic(cutscene) {
      originalUpdate.call(this, cutscene);
      updateOmegaTransformEpic(cutscene);
    };
  }
  if (typeof originalDraw === 'function') {
    window.drawKnightFarolTopFx = function drawKnightFarolTopFxEpic(cutscene) {
      drawOmegaTransformEpic(cutscene);
      originalDraw.call(this, cutscene);
    };
  }
})();

