// (the lowest score that earns each grade, same order)
const boxRushThresholds = [-Infinity, 15, 25, 35, 42, 48, 54, 60, 66, 71, 76, 81, 86, 90, 94, 99, 104, 110];
const boxRushBestKey = 'moqueteBoxRushBest';
const boxRushDoneKey = 'moqueteBoxRushDone';
const boxRushLastKey = 'moqueteBoxRushLast';
const boxRush = { track: null, active: false, stage: null, entry: null, queue: [], results: [], countdown: 0, endT: 0, playFrames: 0, startHealth: 0, panel: null, overlay: null };

