function readBoxRushJson(key) {
  try {
    return JSON.parse(localStorage.getItem(key) || '{}') || {};
  } catch (error) {
    return {};
  }
}

function writeBoxRushJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    // only for this session
  }
}

function isBoxRushUnlocked(entry) {
  if (window.boxRushUnlockAll || entry.tutorial) return true;
  if (entry.scam) return Boolean(readBoxRushJson(boxRushDoneKey).neoFinal || (typeof scammerShop !== 'undefined' && scammerShop.owned && scammerShop.owned.rareMachine));
  if (readBoxRushJson(boxRushDoneKey)[entry.theme]) return true;
  if (typeof coinWallet !== 'undefined' && coinWallet.arcadeLevels && coinWallet.arcadeLevels[`${entry.chapter}-${entry.level}`]) return true;
  if (entry.theme === 'jesterFinale') {
    try {
      return localStorage.getItem(knightSecretBeatenStorageKey) === '1';
    } catch (error) {
      return false;
    }
  }
  return false;
}

function getBoxRushGrade(score) {
  let index = 0;
  boxRushThresholds.forEach((threshold, at) => {
    if (score >= threshold) index = at;
  });
  return boxRushGrades[index];
}

function getBoxRushGradeColor(grade) {
  if (grade === 'P') return 'rainbow';
  if (grade.startsWith('S')) return '#ffd54f';
  if (grade.startsWith('A')) return '#69f0ae';
  if (grade.startsWith('B')) return '#40c4ff';
  if (grade.startsWith('C')) return '#b388ff';
  if (grade.startsWith('D')) return '#ff8a65';
  if (grade.startsWith('F')) return '#ef5350';
  return '#757575';
}

// the score: every hit costs, the health lost costs, parries and a clean run pay
function scoreBoxRush(stats) {
  // (long boxes with many phases forgive each hit a little more)
  const perHit = Math.max(1.5, 12 / Math.max(3, stats.phases));
  let bonus;
  if (stats.kind === 'charged') bonus = stats.parries * 2;
  else if (stats.kind === 'laser') bonus = stats.breaks * 0.6 + stats.faceShots * 0.2;
  else bonus = stats.perfectPhases * 2 + Math.floor(stats.streak / 10);
  let score = 100 - stats.hits * perHit - stats.lost * 15 + Math.min(12, bonus);
  if (stats.hits === 0) score += 10;
  return Math.round(score);
}

function readBoxRushScore(record) {
  if (typeof record === 'number') return record;
  return record && typeof record.score === 'number' ? record.score : null;
}

function boxRushRecordText(theme) {
  const best = readBoxRushScore(readBoxRushJson(boxRushBestKey)[theme]);
  const last = readBoxRushScore(readBoxRushJson(boxRushLastKey)[theme]);
  return { best, last, bestGrade: best === null ? null : getBoxRushGrade(best), lastGrade: last === null ? null : getBoxRushGrade(last) };
}

// (every hit, phase by phase, and the longest streak without one)
function noteBoxRushHit(phaseIndex) {
  const track = boxRush.track;
  if (!track) return;
  track.phaseHits[phaseIndex] = (track.phaseHits[phaseIndex] || 0) + 1;
  track.longest = Math.max(track.longest, boxRush.playFrames - track.lastHit);
  track.lastHit = boxRush.playFrames;
}

// ---------- the menu ----------
function openBoxRushPanel() {
  closeBoxRushPanel();
  const panel = document.createElement('div');
  panel.className = 'br-modal';
  const best = readBoxRushJson(boxRushBestKey);
  const unlocked = boxRushEntries.filter((entry) => isBoxRushUnlocked(entry) && !entry.tutorial);
  const groups = [];
  boxRushEntries.forEach((entry) => {
    if (!groups.includes(entry.group)) groups.push(entry.group);
  });
  panel.innerHTML = `
    <div class="br-panel" role="dialog" aria-label="Desafio de cajas">
      <header class="br-head">
        <div>
          <h3>DESAFIO DE CAJAS</h3>
          <p>Todos los BOX ATTACKS del arcade, uno por uno. Esquiva todo... y consigue la P.</p>
        </div>
        <button type="button" class="br-close" title="Cerrar">&#10005;</button>
      </header>
      <div class="br-top">
        <span class="br-count"><b>${unlocked.length}</b> / ${boxRushEntries.length - 1} desbloqueados</span>
        <button type="button" class="br-marathon"${unlocked.length ? '' : ' disabled'}>&#9654; Maraton: todos seguidos</button>
      </div>
      <div class="br-groups">${groups.map((group) => `
        <section class="br-group">
          <h4>${group}</h4>
          <div class="br-grid">${boxRushEntries.filter((entry) => entry.group === group).map((entry) => {
            const open = isBoxRushUnlocked(entry);
            const records = boxRushRecordText(entry.theme);
            const grade = records.bestGrade || '';
            const color = grade ? getBoxRushGradeColor(grade) : '';
            const recordLine = records.best === null ? 'Sin jugar' : `Mejor: ${records.bestGrade} (${records.best}) · Anterior: ${records.lastGrade} (${records.last})`;
            return `
            <button type="button" class="br-card${open ? '' : ' locked'}" data-theme="${entry.theme}" style="--br-color: ${entry.color}"${open ? '' : ' disabled'}>
              <span class="br-card-name">${open ? entry.name : '? ? ?'}</span>
              <span class="br-card-from">${open ? entry.from : `Completa ${entry.hint}`}</span>
              ${open && !entry.tutorial ? `<span class="br-card-record">${recordLine}</span>` : ''}
              <span class="br-card-grade${color === 'rainbow' ? ' br-rainbow' : ''}" style="${color && color !== 'rainbow' ? `color: ${color}` : ''}">${open ? (grade || '—') : '&#128274;'}</span>
            </button>`;
          }).join('')}</div>
        </section>`).join('')}
      </div>
      <p class="br-legend">Z &lt; F- &lt; F &lt; D- &lt; D &lt; C- &lt; C &lt; C+ &lt; B- &lt; B &lt; B+ &lt; A- &lt; A &lt; A+ &lt; S &lt; SS &lt; SSS &lt; <b>P</b></p>
    </div>`;
  document.body.appendChild(panel);
  boxRush.panel = panel;
  panel.addEventListener('click', (event) => {
    if (event.target === panel) closeBoxRushPanel();
  });
  panel.querySelector('.br-close').addEventListener('click', closeBoxRushPanel);
  panel.querySelector('.br-marathon').addEventListener('click', () => startBoxRush(unlocked));
  panel.querySelectorAll('.br-card:not(.locked)').forEach((card) => card.addEventListener('click', () => {
    startBoxRush([boxRushEntries.find((entry) => entry.theme === card.dataset.theme)]);
  }));
}

function closeBoxRushPanel() {
  if (boxRush.panel) boxRush.panel.remove();
  boxRush.panel = null;
}

// ---------- playing ----------
function startBoxRush(entries) {
  if (!entries.length) return;
  closeBoxRushPanel();
  closeBoxRushOverlay();
  Object.assign(boxRush, { active: true, queue: entries.slice(), results: [], marathon: entries.length > 1 });
  startNextBoxRush();
}

function startNextBoxRush() {
  const entry = boxRush.queue.shift();
  if (!entry) {
    showBoxRushResults();
    return;
  }
  boxRush.entry = entry;
  // a clean fight, outside the arcade
  normalArcadeActive = false;
  arcadeRouteB = false;
  botEnabled = true;
  if (dodgeRound.active) dodgeRound.active = false;
  entry.setup();
  if (entry.theme === 'titanBoxBreak' && dodgeRoundThemes.titanBoxBreak) {
    dodgeRoundThemes.titanBoxBreak.hammerMode = false;
    dodgeRoundThemes.titanBoxBreak.title = 'BOX ATTACK FINAL DEL TITAN!';
  }
  selectedMap = entry.map;
  if (titleScreen) titleScreen.classList.add('hidden');
  startGame();
  player1.health = player1.maxHealth;
  player1.position = { x: 220, y: ground - player1.height };
  player2.position = { x: 700, y: ground - player2.height };
  if (entry.titan && typeof chronoTitan !== 'undefined') Object.assign(chronoTitan, { visible: true, rise: 1, attacks: [], bar: null });
  boxRush.stage = 'countdown';
  boxRush.countdown = 210;
  boxRush.playFrames = 0;
  updateHealthBars();
}

function beginBoxRushRound() {
  const entry = boxRush.entry;
  boxRush.stage = 'playing';
  boxRush.startHealth = player1.health;
  boxRush.track = { phaseHits: {}, lastHit: 0, longest: 0 };
  if (entry.scam) {
    castScamFinalAct(player2, player1);
    return;
  }
  if (!startDodgeRound(entry.theme, player2, player1)) return;
  if (entry.titan && typeof titanBoxRect !== 'undefined') {
    const box = { ...titanBoxRect };
    dodgeRound.boxTarget = box;
    dodgeRound.soul.x = box.x + box.width / 2 - dodgeRound.soul.width / 2;
    dodgeRound.soul.y = box.y + box.height / 2 - dodgeRound.soul.height / 2;
    dodgeRound.titanHands = { mode: 'rest', k: 1 };
    if (entry.laser) dodgeRound.titanLasers = [];
    playSound('titanRoar');
  }
}

function finishBoxRushRound(round) {
  const entry = boxRush.entry;
  const track = boxRush.track || { phaseHits: {}, lastHit: 0, longest: 0 };
  track.longest = Math.max(track.longest, boxRush.playFrames - track.lastHit);
  const phaseList = entry.scam ? scamFinalPhases : (round.config && round.config.phases) || [];
  const phases = Math.max(1, phaseList.length);
  const perfectPhases = phaseList.filter((phase, index) => !track.phaseHits[index]).length;
  let worst = -1;
  Object.keys(track.phaseHits).forEach((index) => {
    if (worst < 0 || track.phaseHits[index] > track.phaseHits[worst]) worst = Number(index);
  });
  const worstPhase = worst >= 0 && phaseList[worst] ? String(phaseList[worst].caption || phaseList[worst].title || '').replace(/\[\[|\]\]/g, '') : null;
  const stats = {
    theme: entry.theme,
    name: entry.name,
    kind: entry.laser ? 'laser' : round.config && round.config.charged ? 'charged' : 'dodge',
    hits: round.hits || 0,
    parries: round.parries || 0,
    breaks: round.laserBreaks || 0,
    faceShots: round.laserFace || 0,
    phases,
    perfectPhases,
    streak: Math.round(track.longest / 6) / 10,
    worstPhase,
    lost: Math.max(0, (boxRush.startHealth - player1.health) / Math.max(1, player1.maxHealth)),
    seconds: Math.round(boxRush.playFrames / 6) / 10,
    tutorial: Boolean(entry.tutorial),
  };
  stats.score = scoreBoxRush(stats);
  stats.grade = getBoxRushGrade(stats.score);
  if (!entry.tutorial) {
    const best = readBoxRushJson(boxRushBestKey);
    const last = readBoxRushJson(boxRushLastKey);
    stats.previous = readBoxRushScore(last[entry.theme]);
    stats.previousBest = readBoxRushScore(best[entry.theme]);
    stats.newBest = stats.previousBest === null || stats.score > stats.previousBest;
    if (stats.newBest) best[entry.theme] = stats.score;
    last[entry.theme] = stats.score;
    writeBoxRushJson(boxRushBestKey, best);
    writeBoxRushJson(boxRushLastKey, last);
  }
  boxRush.results.push(stats);
  boxRush.stage = 'ending';
  boxRush.endT = 0;
}

function boxRushStatsRows(item) {
  const rows = [
    ['Golpes recibidos', item.hits],
    ['Vida perdida', `${Math.round(item.lost * 100)}%`],
    ['Fases perfectas', `${item.perfectPhases} / ${item.phases}`],
    ['Racha mas larga sin golpes', `${item.streak} s`],
  ];
  if (item.kind === 'charged') rows.push(['Parrys', item.parries]);
  if (item.kind === 'laser') {
    rows.push(['Ataques rotos con el laser', item.breaks]);
    rows.push(['Disparos a la cara del titan', item.faceShots]);
  }
  if (item.worstPhase) rows.push(['Fase mas dificil', item.worstPhase]);
  rows.push(['Tiempo', `${item.seconds} s`]);
  rows.push(['Puntos', item.score]);
  return rows.map(([label, value]) => `<span>${label}</span><b>${value}</b>`).join('');
}

function showBoxRushResults() {
  boxRush.stage = 'results';
  if (animationId) {
    cancelAnimationFrame(animationId);
    animationId = null;
  }
  const results = boxRush.results;
  const overall = Math.round(results.reduce((sum, item) => sum + item.score, 0) / Math.max(1, results.length));
  const single = results.length === 1;
  const main = single ? results[0] : { grade: getBoxRushGrade(overall), score: overall };
  const color = getBoxRushGradeColor(main.grade);
  const overlay = document.createElement('div');
  overlay.className = 'br-results';
  overlay.innerHTML = `
    <div class="br-results-panel">
      <p class="br-results-title">${single ? results[0].name : `MARATON: ${results.length} CAJAS`}</p>
      <div class="br-big-grade${color === 'rainbow' ? ' br-rainbow' : ''}" style="${color !== 'rainbow' ? `color: ${color}; text-shadow: 0 0 30px ${color}` : ''}">${main.grade}</div>
      ${single ? `
      <div class="br-stats">${boxRushStatsRows(results[0])}</div>
      ${results[0].tutorial ? '<p class="br-new-best">¡TUTORIAL COMPLETADO! Ya sabes todo lo necesario.</p>' : `
      <div class="br-records">
        <span>Anterior: <b>${results[0].previous === null ? '—' : `${getBoxRushGrade(results[0].previous)} (${results[0].previous})`}</b></span>
        <span>Mejor: <b>${results[0].newBest ? `${results[0].grade} (${results[0].score})` : `${getBoxRushGrade(results[0].previousBest)} (${results[0].previousBest})`}</b></span>
      </div>
      ${results[0].newBest ? '<p class="br-new-best">¡NUEVO RECORD!</p>' : ''}`}` : `
      <div class="br-list">${results.map((item) => {
        const itemColor = getBoxRushGradeColor(item.grade);
        return `<span>${item.name}</span><b class="${itemColor === 'rainbow' ? 'br-rainbow' : ''}" style="${itemColor !== 'rainbow' ? `color: ${itemColor}` : ''}">${item.grade}</b>`;
      }).join('')}</div>
      <p class="br-overall">Promedio: ${overall} puntos · Golpes totales: ${results.reduce((sum, item) => sum + item.hits, 0)}</p>`}
      <div class="br-actions">
        <button type="button" class="br-again">Reintentar</button>
        <button type="button" class="br-pick">Elegir otra</button>
        <button type="button" class="br-exit">Salir</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  boxRush.overlay = overlay;
  const replay = boxRushEntries.filter((entry) => results.some((item) => item.theme === entry.theme));
  playSound(main.grade === 'P' || main.grade.startsWith('S') ? 'achievement' : 'judgeFinalStart');
  overlay.querySelector('.br-again').addEventListener('click', () => startBoxRush(replay));
  overlay.querySelector('.br-pick').addEventListener('click', () => {
    endBoxRush();
    openBoxRushPanel();
  });
  overlay.querySelector('.br-exit').addEventListener('click', endBoxRush);
}

function closeBoxRushOverlay() {
  if (boxRush.overlay) boxRush.overlay.remove();
  boxRush.overlay = null;
}

function endBoxRush() {
  closeBoxRushOverlay();
  boxRush.active = false;
  boxRush.stage = null;
  if (dodgeRound.active) dodgeRound.active = false;
  if (scamFinal.active) scamFinal.active = false;
  if (typeof returnToMenu === 'function') returnToMenu();
}

// the countdown, the pause at the end... drawn by the game loop
function drawBoxRushCountdown() {
  const left = boxRush.countdown;
  drawStage();
  player1.draw();
  player2.draw();
  ctx.save();
  ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.textAlign = 'center';
  ctx.fillStyle = boxRush.entry.color;
  ctx.font = '900 18px Courier New, monospace';
  ctx.fillText(boxRush.marathon ? `CAJA ${boxRush.results.length + 1}` : 'DESAFIO DE CAJAS', canvas.width / 2, 170);
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 34px Courier New, monospace';
  ctx.fillText(boxRush.entry.name.toUpperCase(), canvas.width / 2, 215);
  ctx.font = '700 15px Courier New, monospace';
  ctx.fillStyle = '#b0bec5';
  ctx.fillText(`de ${boxRush.entry.from}`, canvas.width / 2, 242);
  const records = boxRushRecordText(boxRush.entry.theme);
  if (records.best !== null && !boxRush.entry.tutorial) {
    ctx.fillStyle = '#ffd54f';
    ctx.font = '900 14px Courier New, monospace';
    ctx.fillText(`MEJOR: ${records.bestGrade} (${records.best})   ·   ANTERIOR: ${records.lastGrade} (${records.last})`, canvas.width / 2, 268);
  }
  const number = left > 150 ? 'PREPARATE' : left > 30 ? String(Math.ceil((left - 30) / 40)) : '¡YA!';
  const pulse = 1 + ((left - 30) % 40) / 160;
  ctx.font = `900 ${Math.round((number.length > 2 ? 46 : 96) * (left > 30 && left <= 150 ? pulse : 1))}px Courier New, monospace`;
  ctx.fillStyle = left <= 30 ? '#69f0ae' : '#ffd54f';
  ctx.shadowColor = ctx.fillStyle;
  ctx.shadowBlur = 20;
  ctx.fillText(number, canvas.width / 2, 340);
  ctx.restore();
  if (left === 150 || left === 110 || left === 70) playTone({ frequency: 660, duration: 0.12, type: 'square', volume: 0.05 });
  if (left === 30) playTone({ frequency: 990, duration: 0.25, type: 'square', volume: 0.06 });
}

function drawBoxRushEnding() {
  drawStage();
  player1.draw();
  player2.draw();
  const result = boxRush.results[boxRush.results.length - 1];
  ctx.save();
  ctx.fillStyle = `rgba(0, 0, 0, ${Math.min(0.6, boxRush.endT / 40)})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.textAlign = 'center';
  ctx.font = '900 40px Courier New, monospace';
  ctx.fillStyle = '#ffffff';
  ctx.fillText(result.hits === 0 ? '¡SIN UN RASGUÑO!' : '¡CAJA SUPERADA!', canvas.width / 2, 250);
  if (boxRush.marathon && boxRush.endT > 40) {
    const color = getBoxRushGradeColor(result.grade);
    ctx.font = '900 64px Courier New, monospace';
    ctx.fillStyle = color === 'rainbow' ? `hsl(${(boxRush.endT * 8) % 360}, 90%, 65%)` : color;
    ctx.fillText(result.grade, canvas.width / 2, 340);
  }
  ctx.restore();
}

(function hookBoxRush() {
  const wrap = (name, make) => {
    const original = window[name];
    if (typeof original === 'function') window[name] = make(original);
  };
  wrap('animate', (original) => function animateWithBoxRush(...args) {
    if (boxRush.active && (boxRush.stage === 'countdown' || boxRush.stage === 'ending')) {
      animationId = requestAnimationFrame(window.animate);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (boxRush.stage === 'countdown') {
        drawBoxRushCountdown();
        boxRush.countdown -= 1;
        if (boxRush.countdown <= 0) beginBoxRushRound();
      } else {
        drawBoxRushEnding();
        boxRush.endT += 1;
        if (boxRush.endT >= (boxRush.marathon ? 130 : 90)) {
          if (boxRush.queue.length) startNextBoxRush();
          else showBoxRushResults();
        }
      }
      return undefined;
    }
    if (boxRush.active && boxRush.stage === 'results') return undefined;
    if (boxRush.active && boxRush.stage === 'playing') boxRush.playFrames += 1;
    return original.apply(this, args);
  });
  // the end of a round: the grade (and none of the chapter's story after it)
  wrap('finishDodgeRound', (original) => function finishDodgeRoundWithRush(...args) {
    const round = dodgeRound;
    if (boxRush.active && boxRush.stage === 'playing') {
      finishBoxRushRound(round);
      return original.apply(this, args);
    }
    // (beaten in the arcade: unlocked in the box rush)
    if (normalArcadeActive && round.theme) {
      const done = readBoxRushJson(boxRushDoneKey);
      if (!done[round.theme]) {
        done[round.theme] = true;
        writeBoxRushJson(boxRushDoneKey, done);
      }
    }
    return original.apply(this, args);
  });
  wrap('hurtDodgeTarget', (original) => function hurtDodgeTargetTracked(...args) {
    const before = dodgeRound.hits;
    const result = original.apply(this, args);
    if (boxRush.active && boxRush.stage === 'playing' && dodgeRound.hits > before) noteBoxRushHit(dodgeRound.phaseIndex);
    return result;
  });
  wrap('hurtScamFinalTarget', (original) => function hurtScamFinalTargetTracked(...args) {
    const before = scamFinal.hits;
    const result = original.apply(this, args);
    if (boxRush.active && boxRush.stage === 'playing' && scamFinal.hits > before) noteBoxRushHit(scamFinal.phaseIndex);
    return result;
  });
  wrap('finishScamFinalAct', (original) => function finishScamFinalActWithRush(...args) {
    if (boxRush.active && boxRush.stage === 'playing') {
      finishBoxRushRound(scamFinal);
      scamFinal.active = false;
      return undefined;
    }
    if (scamChallenge && scamChallenge.active) {
      const done = readBoxRushJson(boxRushDoneKey);
      done.neoFinal = true;
      writeBoxRushJson(boxRushDoneKey, done);
    }
    return original.apply(this, args);
  });
  ['startRiftClash', 'friendBoxEnd', 'startChronoTitanBabyCall', 'startFarolClimb'].forEach((name) => {
    wrap(name, (original) => function skippedInBoxRush(...args) {
      if (boxRush.active) return undefined;
      return original.apply(this, args);
    });
  });
  // (leaving the fight leaves the mode)
  wrap('returnToMenu', (original) => function returnToMenuEndsBoxRush(...args) {
    if (boxRush.active && boxRush.stage !== 'results') {
      boxRush.active = false;
      boxRush.stage = null;
      if (dodgeRound.active) dodgeRound.active = false;
      if (scamFinal.active) scamFinal.active = false;
    }
    const result = original.apply(this, args);
    return result;
  });
  // the button in the game modes screen
  const screen = document.getElementById('gameModesScreen');
  const list = screen && screen.querySelector('.character-guide');
  if (list && !document.getElementById('boxRushModeButton')) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'arcade-mode-option box-rush-option';
    button.id = 'boxRushModeButton';
    button.innerHTML = '<strong>Desafio de cajas</strong><span>Rejuga cada BOX ATTACK que superaste en el arcade, uno por uno o todos seguidos, y consegui la mejor nota: de Z a P.</span>';
    button.addEventListener('click', openBoxRushPanel);
    list.appendChild(button);
  }
})();

window.addEventListener('keydown', (event) => {
  if (event.key !== 'Escape') return;
  if (boxRush.panel) closeBoxRushPanel();
  else if (boxRush.active && boxRush.stage !== 'results') endBoxRush();
});

// ================= the tutorial, better: tips, keys on screen, Light Warrior reacting, an objective =================
const boxTutorial = { tip: null, bubble: null, firstHit: false, firstParry: false, phase: -1, phaseParries: 0, loops: 0 };
const boxTutorialTips = [
  { title: 'MOVERSE', text: 'W A S D mueven tu alma. Los disparos amarillos se esquivan: no te quedes quieto.' },
  { title: 'PARRY', text: 'Los ataques AZULES se devuelven: mantene Q, apunta con W A S D y solta Q encima del azul. Objetivo: 3 parrys.' },
  { title: 'AVISOS', text: 'Antes de cada columna aparece una franja: es el aviso. Salite de ahi antes de que se encienda.' },
  { title: 'HUECOS', text: 'Los anillos tienen un hueco. Buscalo y quedate adentro hasta que pase.' },
];
const boxTutorialPhaseLines = [
  '¡Primero lo basico! Movete y que no te toquen.',
  '¡Ahora los azules! Cargá con Q y tirate encima. ¡Hace 3!',
  'Mira el piso de la caja: la luz avisa antes de bajar.',
  '¡Ultima! Los anillos se cierran... busca el hueco.',
];

function isBoxTutorialRound() {
  return Boolean(dodgeRound.active && dodgeRound.theme === 'tutorialBox');
}

function boxTutorialSay(text, life = 150) {
  boxTutorial.bubble = { text, life };
}

function updateBoxTutorial() {
  const round = dodgeRound;
  if (round.stage === 'phase' && round.phaseIndex !== boxTutorial.phase) {
    boxTutorial.phase = round.phaseIndex;
    boxTutorial.phaseParries = round.parries || 0;
    boxTutorial.loops = 0;
    boxTutorialSay(boxTutorialPhaseLines[round.phaseIndex] || '¡Vamos!', 200);
  }
  if (!boxTutorial.firstParry && (round.parries || 0) > 0) {
    boxTutorial.firstParry = true;
    boxTutorialSay('¡ESO! ¡Asi se devuelve un azul! Jeje.', 140);
  }
  if (round.stage === 'outro' && boxTutorial.phase !== 'done') {
    boxTutorial.phase = 'done';
    boxTutorialSay(round.hits === 0 ? '¡SIN UN RASGUÑO! ¡Sos un natural! Ya estas listo para el desafio.' : '¡Lo lograste! Con practica, ninguna caja te va a poder.', 220);
  }
  if (boxTutorial.bubble) boxTutorial.bubble.life -= 1;
}

function drawBoxTutorialHud() {
  const round = dodgeRound;
  ctx.save();
  // the keys, lit while pressed
  const keyBox = (label, x, y, on, w = 34) => {
    ctx.fillStyle = on ? '#fff59d' : 'rgba(0, 0, 0, 0.6)';
    ctx.strokeStyle = on ? '#fdd835' : '#9e9e9e';
    ctx.lineWidth = 2;
    ctx.fillRect(x, y, w, 30);
    ctx.strokeRect(x, y, w, 30);
    ctx.fillStyle = on ? '#3e2723' : '#ffffff';
    ctx.font = '900 15px Courier New, monospace';
    ctx.textAlign = 'center';
    ctx.fillText(label, x + w / 2, y + 20);
  };
  const baseX = 26;
  const baseY = canvas.height - 118;
  keyBox('W', baseX + 38, baseY, keys.w);
  keyBox('A', baseX, baseY + 34, keys.a);
  keyBox('S', baseX + 38, baseY + 34, keys.s);
  keyBox('D', baseX + 76, baseY + 34, keys.d);
  keyBox('Q', baseX + 126, baseY + 34, keys.q, 44);
  ctx.fillStyle = '#fff59d';
  ctx.font = '700 11px Courier New, monospace';
  ctx.textAlign = 'left';
  ctx.fillText('mover', baseX + 32, baseY + 80);
  ctx.fillText('dash', baseX + 132, baseY + 80);
  // the tip of this phase
  const tip = boxTutorialTips[round.phaseIndex];
  if (round.stage === 'phase' && tip) {
    const x = canvas.width - 292;
    const y = 212;
    ctx.fillStyle = 'rgba(20, 16, 4, 0.85)';
    ctx.fillRect(x, y, 276, 112);
    ctx.strokeStyle = '#fdd835';
    ctx.strokeRect(x, y, 276, 112);
    ctx.fillStyle = '#fdd835';
    ctx.font = '900 13px Courier New, monospace';
    ctx.fillText(`CONSEJO ${round.phaseIndex + 1}/4: ${tip.title}`, x + 10, y + 18);
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 12px Arial';
    drawWrappedText(tip.text, x + 10, y + 38, 256, 16);
    if (round.phaseIndex === 1) {
      const done = Math.min(3, (round.parries || 0) - boxTutorial.phaseParries);
      ctx.fillStyle = done >= 3 ? '#69f0ae' : '#4fc3f7';
      ctx.font = '900 13px Courier New, monospace';
      ctx.fillText(`PARRYS: ${done} / 3${done >= 3 ? '  ¡LISTO!' : ''}`, x + 10, y + 102);
    }
  }
  // Light Warrior talks to you
  const bubble = boxTutorial.bubble;
  if (bubble && bubble.life > 0) {
    ctx.globalAlpha = Math.min(1, bubble.life / 20);
    ctx.font = '900 13px Arial';
    const width = Math.min(300, ctx.measureText(bubble.text).width + 24);
    const bx = Math.min(canvas.width - width - 10, 790 - width / 2);
    const by = 338;
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#fdd835';
    ctx.lineWidth = 3;
    ctx.fillRect(bx, by, width, 44);
    ctx.strokeRect(bx, by, width, 44);
    ctx.fillStyle = '#3e2723';
    ctx.textAlign = 'left';
    drawWrappedText(bubble.text, bx + 12, by + 18, width - 24, 15);
  }
  ctx.restore();
}

// ================= BOX MODIFIERS (from the debug console) =================
const defaultBoxMods = { speed: 1, damage: 1, soulSize: 1, soulSpeed: 1, mirror: false, gravity: false, freeDash: false, shield: false, party: false, bonus: 0, hotkey: true };
const boxMods = { ...defaultBoxMods, shieldLeft: 3, paused: false, overlay: null, confetti: [] };
const boxModLabels = { speed: 'Velocidad de ataques', damage: 'Daño recibido', soulSize: 'Tamaño del alma', soulSpeed: 'Velocidad del alma', mirror: 'Controles al reves', gravity: 'Gravedad', freeDash: 'Dash infinito', shield: 'Escudo de 3 golpes', party: 'Modo fiesta', bonus: 'Bonus de puntos' };

function boxModsActive() {
  return Object.keys(boxModLabels).filter((key) => boxMods[key] !== defaultBoxMods[key]);
}

// harder rules pay more points, easier ones cost points
function getBoxModsBonus() {
  let bonus = 0;
  bonus += (boxMods.speed - 1) * 20;
  bonus += boxMods.damage === 0 ? -25 : (boxMods.damage - 1) * 8;
  bonus += (boxMods.soulSize - 1) * 15;
  bonus += (1 - boxMods.soulSpeed) * 10;
  if (boxMods.mirror) bonus += 8;
  if (boxMods.gravity) bonus += 8;
  if (boxMods.freeDash) bonus -= 6;
  if (boxMods.shield) bonus -= 8;
  bonus += boxMods.bonus;
  return Math.round(bonus);
}

function makeBoxModsControls(onChange) {
  const box = document.createElement('div');
  box.className = 'dbg-grid bm-grid';
  const range = (key, label, desc, min, max, step, format) => {
    const card = makeDebugCard(`<span class="dbg-label">${label}</span><small>${desc}</small><input type="range" min="${min}" max="${max}" step="${step}" value="${boxMods[key]}" /><strong class="dbg-value"></strong>`);
    const input = card.querySelector('input');
    const out = card.querySelector('.dbg-value');
    const show = () => {
      out.textContent = format(boxMods[key]);
      card.classList.toggle('dbg-changed', boxMods[key] !== defaultBoxMods[key]);
    };
    input.addEventListener('input', () => {
      boxMods[key] = Number(input.value);
      show();
      onChange();
    });
    show();
    return card;
  };
  const toggle = (key, label, desc, icon) => {
    const card = makeDebugCard(`<label class="dbg-switch"><span class="dbg-icon">${icon}</span><span class="dbg-text"><span class="dbg-label">${label}</span><small>${desc}</small></span><input type="checkbox"${boxMods[key] ? ' checked' : ''} /><i class="dbg-knob" aria-hidden="true"></i></label>`, 'dbg-toggle-card');
    const input = card.querySelector('input');
    input.addEventListener('change', () => {
      boxMods[key] = input.checked;
      card.classList.toggle('dbg-changed', boxMods[key] !== defaultBoxMods[key]);
      onChange();
    });
    card.classList.toggle('dbg-changed', boxMods[key] !== defaultBoxMods[key]);
    return card;
  };
  const times = (value) => `x${Number(value).toFixed(2).replace(/\.?0+$/, '')}`;
  box.append(
    range('speed', 'Velocidad de ataques', 'Mas rapido = mas dificil (y mas puntos).', 0.5, 2, 0.25, times),
    range('damage', 'Daño recibido', '0 = inmortal (resta puntos).', 0, 3, 0.5, (value) => (value === 0 ? 'inmortal' : times(value))),
    range('soulSize', 'Tamaño del alma', 'Mas chica = mas facil de esquivar.', 0.5, 1.75, 0.25, times),
    range('soulSpeed', 'Velocidad del alma', 'Tu alma se mueve mas rapido o mas lento.', 0.5, 2, 0.25, times),
    toggle('mirror', 'Controles al reves', 'Izquierda es derecha. Arriba es abajo. (+8 pts)', '⇄'),
    toggle('gravity', 'Gravedad', 'Tu alma cae: hay que sostenerla con W. (+8 pts)', '↓'),
    toggle('freeDash', 'Dash infinito', 'El dash cargado no tiene cooldown. (-6 pts)', '⚡'),
    toggle('shield', 'Escudo de 3 golpes', 'Los primeros 3 golpes no hacen nada. (-8 pts)', '◈'),
    toggle('party', 'Modo fiesta', 'Confeti, colores y un alma arcoiris. Solo por diversion.', '❀'),
    range('bonus', 'Bonus de puntos', 'Puntos extra al final del desafio de cajas.', 0, 30, 5, (value) => `+${value}`),
    toggle('hotkey', 'F10 en una caja', 'Abre este menu en medio de un box attack (y lo pausa).', '⌨'),
  );
  return box;
}

function boxModsSummary() {
  const bonus = getBoxModsBonus();
  const active = boxModsActive();
  return active.length ? `${active.length} modificador${active.length > 1 ? 'es' : ''} · ${bonus >= 0 ? '+' : ''}${bonus} pts` : 'Sin modificadores';
}

// the tab in the debug console
function buildBoxModsTab() {
  const tabs = document.querySelector('#debugScreen .dbg-tabs');
  if (!tabs || tabs.querySelector('[data-dbg-tab="boxes"]')) return;
  const tab = document.createElement('button');
  tab.type = 'button';
  tab.className = 'dbg-tab';
  tab.dataset.dbgTab = 'boxes';
  tab.textContent = '▣ Cajas';
  tabs.appendChild(tab);
  const panel = document.createElement('div');
  panel.className = 'dbg-panel hidden';
  panel.dataset.dbgPanel = 'boxes';
  const head = document.createElement('div');
  head.className = 'dbg-status bm-status';
  const refresh = () => {
    head.innerHTML = `<b>BOX ATTACKS</b> — ${boxModsSummary()} <span class="bm-hint">(se aplican a todas las cajas; en el Desafio de cajas ajustan el puntaje)</span>`;
  };
  panel.append(head, makeBoxModsControls(refresh));
  const reset = document.createElement('button');
  reset.type = 'button';
  reset.className = 'dbg-mini bm-reset';
  reset.textContent = '↺ Restaurar cajas';
  reset.addEventListener('click', () => {
    Object.assign(boxMods, defaultBoxMods);
    panel.querySelector('.bm-grid').replaceWith(makeBoxModsControls(refresh));
    refresh();
  });
  panel.appendChild(reset);
  refresh();
  const last = Array.from(document.querySelectorAll('#debugScreen .dbg-panel')).pop();
  last.after(panel);
  tab.addEventListener('click', () => {
    debugConsole.tab = 'boxes';
    syncDebugTabs();
  });
}

// F10 inside a box: the same menu, paused
function openBoxModsOverlay() {
  if (boxMods.overlay) return;
  boxMods.paused = true;
  const overlay = document.createElement('div');
  overlay.className = 'bm-overlay';
  overlay.innerHTML = '<div class="bm-overlay-panel"><header><h3>MODIFICADORES DE CAJA</h3><span class="bm-sum"></span><button type="button" class="bm-resume">▶ Seguir (F10)</button></header><div class="bm-body"></div></div>';
  const sum = overlay.querySelector('.bm-sum');
  const refresh = () => {
    sum.textContent = boxModsSummary();
  };
  overlay.querySelector('.bm-body').appendChild(makeBoxModsControls(refresh));
  refresh();
  overlay.querySelector('.bm-resume').addEventListener('click', closeBoxModsOverlay);
  document.body.appendChild(overlay);
  boxMods.overlay = overlay;
}

function closeBoxModsOverlay() {
  if (boxMods.overlay) boxMods.overlay.remove();
  boxMods.overlay = null;
  boxMods.paused = false;
  resetKeys();
}

window.addEventListener('keydown', (event) => {
  if (event.key !== 'F10') return;
  if (boxMods.overlay) {
    event.preventDefault();
    closeBoxModsOverlay();
    return;
  }
  if (!boxMods.hotkey || !(dodgeRound.active || scamFinal.active)) return;
  // like F6-F9: only once the debug console was opened
  if (!(debugConsole.used || boxModsActive().length || boxRush.active)) return;
  event.preventDefault();
  openBoxModsOverlay();
});

function drawBoxModsParty() {
  if (!boxMods.party) return;
  const time = performance.now() / 1000;
  if (Math.random() < 0.6) boxMods.confetti.push({ x: Math.random() * canvas.width, y: -10, vy: 2 + Math.random() * 3, vx: (Math.random() - 0.5) * 2, hue: Math.random() * 360, life: 300 });
  ctx.save();
  boxMods.confetti.forEach((bit) => {
    bit.x += bit.vx;
    bit.y += bit.vy;
    bit.life -= 1;
    ctx.fillStyle = `hsl(${bit.hue}, 90%, 60%)`;
    ctx.fillRect(bit.x, bit.y, 6, 9);
  });
  boxMods.confetti = boxMods.confetti.filter((bit) => bit.life > 0 && bit.y < canvas.height);
  if (dodgeRound.active) {
    const soul = getDodgeSoulCenter();
    ctx.strokeStyle = `hsl(${(time * 300) % 360}, 90%, 60%)`;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(soul.x, soul.y, 26, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.restore();
}

(function hookBoxModsAndTutorial() {
  const wrap = (name, make) => {
    const original = window[name];
    if (typeof original === 'function') window[name] = make(original);
  };
  // speed of the attacks
  wrap('getTitanBoxTimeScale', (original) => function getTimeScaleWithMods(round) {
    return original.call(this, round) * boxMods.speed;
  });
  // the damage, the shield, the gentle tutorial
  const scaleHit = (target, before) => {
    const lost = before - target.health;
    if (lost <= 0) return;
    let factor = boxMods.damage;
    if (isBoxTutorialRound()) factor *= 0.5;
    if (boxMods.shield && boxMods.shieldLeft > 0) {
      boxMods.shieldLeft -= 1;
      factor = 0;
    }
    target.health = Math.max(1, before - lost * factor);
    updateHealthBars();
  };
  wrap('hurtDodgeTarget', (original) => function hurtDodgeTargetWithMods(...args) {
    const target = dodgeRound.target;
    const before = target.health;
    const hits = dodgeRound.hits;
    const result = original.apply(this, args);
    if (dodgeRound.hits > hits) {
      scaleHit(target, before);
      if (isBoxTutorialRound() && !boxTutorial.firstHit) {
        boxTutorial.firstHit = true;
        boxTutorialSay('¡Auch! Tranqui, en el tutorial duele la mitad. ¡Segui moviendote!', 160);
      }
    }
    return result;
  });
  wrap('hurtScamFinalTarget', (original) => function hurtScamFinalTargetWithMods(...args) {
    const target = scamFinal.target;
    const before = target.health;
    const hits = scamFinal.hits;
    const result = original.apply(this, args);
    if (scamFinal.hits > hits) scaleHit(target, before);
    return result;
  });
  // the soul: size (at the start), speed, mirror, gravity, free dash
  wrap('startDodgeRound', (original) => function startDodgeRoundWithMods(...args) {
    const result = original.apply(this, args);
    if (result) {
      boxMods.shieldLeft = 3;
      if (boxMods.soulSize !== 1) {
        const soul = dodgeRound.soul;
        const cx = soul.x + soul.width / 2;
        const cy = soul.y + soul.height / 2;
        soul.width = Math.max(6, Math.round(soul.width * boxMods.soulSize));
        soul.height = Math.max(8, Math.round(soul.height * boxMods.soulSize));
        soul.x = cx - soul.width / 2;
        soul.y = cy - soul.height / 2;
      }
      if (dodgeRound.theme === 'tutorialBox') Object.assign(boxTutorial, { tip: null, bubble: null, firstHit: false, firstParry: false, phase: -1, phaseParries: 0, loops: 0 });
    }
    return result;
  });
  wrap('castScamFinalAct', (original) => function castScamFinalActWithMods(...args) {
    const result = original.apply(this, args);
    if (result) boxMods.shieldLeft = 3;
    return result;
  });
  wrap('moveDodgeSoul', (original) => function moveDodgeSoulWithMods(...args) {
    const round = dodgeRound;
    const soul = round.soul;
    let swapped = null;
    if (boxMods.mirror) {
      swapped = { a: keys.a, d: keys.d, w: keys.w, s: keys.s };
      Object.assign(keys, { a: swapped.d, d: swapped.a, w: swapped.s, s: swapped.w });
    }
    if (boxMods.freeDash && round.dash) round.dash.cooldown = 0;
    const before = { x: soul.x, y: soul.y };
    const result = original.apply(this, args);
    if (swapped) Object.assign(keys, swapped);
    if (round.stage === 'phase') {
      if (boxMods.soulSpeed !== 1) {
        soul.x += (soul.x - before.x) * (boxMods.soulSpeed - 1);
        soul.y += (soul.y - before.y) * (boxMods.soulSpeed - 1);
      }
      if (boxMods.gravity && !keys.w) soul.y += 2.2;
      const box = round.box;
      soul.x = Math.max(box.x, Math.min(box.x + box.width - soul.width, soul.x));
      soul.y = Math.max(box.y, Math.min(box.y + box.height - soul.height, soul.y));
    }
    return result;
  });
  // the tutorial's objective: the blue phase waits for 3 parries (up to three extra loops)
  wrap('advanceDodgePhase', (original) => function advanceDodgePhaseWithTutorial(round, config, ...rest) {
    if (round.theme === 'tutorialBox' && round.phaseIndex === 1 && boxTutorial.loops < 3) {
      const frames = config.phases[1].frames || config.phaseFrames || 600;
      if (round.phaseFrame >= frames - 45 && (round.parries || 0) - boxTutorial.phaseParries < 3) {
        round.phaseFrame = 60;
        boxTutorial.loops += 1;
        boxTutorialSay(`¡Te faltan ${3 - ((round.parries || 0) - boxTutorial.phaseParries)} parrys! Otra ronda de azules...`, 170);
      }
    }
    return original.call(this, round, config, ...rest);
  });
  // the score of the box rush
  wrap('scoreBoxRush', (original) => function scoreBoxRushWithMods(stats) {
    const bonus = getBoxModsBonus();
    stats.modBonus = bonus;
    stats.mods = boxModsActive().map((key) => boxModLabels[key]);
    return original.call(this, stats) + bonus;
  });
  wrap('boxRushStatsRows', (original) => function boxRushStatsRowsWithMods(item) {
    let html = original.call(this, item);
    if (item.mods && item.mods.length) html += `<span>Modificadores</span><b>${item.modBonus >= 0 ? '+' : ''}${item.modBonus}</b>`;
    return html;
  });
  // pause, tutorial HUD, party
  wrap('animate', (original) => function animateWithBoxMods(...args) {
    if (boxMods.paused && (dodgeRound.active || scamFinal.active)) {
      animationId = requestAnimationFrame(window.animate);
      return undefined;
    }
    const result = original.apply(this, args);
    if (isBoxTutorialRound()) {
      updateBoxTutorial();
      drawBoxTutorialHud();
    }
    if (dodgeRound.active || scamFinal.active) drawBoxModsParty();
    return result;
  });
  buildBoxModsTab();
})();

// ================= the modifiers inside the box rush panel; a game modes screen you can leave =================
(function hookBoxRushPanelMods() {
  const originalOpen = window.openBoxRushPanel;
  if (typeof originalOpen !== 'function') return;
  window.openBoxRushPanel = function openBoxRushPanelWithMods(...args) {
    const result = originalOpen.apply(this, args);
    const panel = boxRush.panel;
    const top = panel && panel.querySelector('.br-top');
    if (!top) return result;
    const section = document.createElement('details');
    section.className = 'br-mods';
    if (boxModsActive().length) section.open = true;
    section.innerHTML = '<summary><span class="br-mods-title">\u2699 MODIFICADORES</span><span class="br-mods-sum"></span></summary><p class="br-mods-help">Hace las cajas mas faciles, mas dificiles o mas raras. Lo dificil suma puntos a la nota, lo facil resta. Tambien podes abrirlos con F10 en medio de una caja.</p>';
    const sum = section.querySelector('.br-mods-sum');
    const refresh = () => {
      const active = boxModsActive().length;
      sum.textContent = boxModsSummary();
      sum.classList.toggle('on', active > 0);
    };
    const reset = document.createElement('button');
    reset.type = 'button';
    reset.className = 'br-mods-reset';
    reset.textContent = '\u21BA Sin modificadores';
    reset.addEventListener('click', () => {
      Object.assign(boxMods, defaultBoxMods);
      section.querySelector('.bm-grid').replaceWith(makeBoxModsControls(refresh));
      refresh();
    });
    section.append(makeBoxModsControls(refresh), reset);
    refresh();
    top.after(section);
    return result;
  };
})();

window.addEventListener('keydown', (event) => {
  if (event.key !== 'Escape' || gameStarted) return;
  if (boxRush.panel) {
    event.preventDefault();
    closeBoxRushPanel();
  } else if (!gameModesScreen.classList.contains('hidden')) {
    event.preventDefault();
    closeGameModes();
  }
});

