// the guide keeps a secret: Omegarius is only there if you saw him there
(function hideOmegariusUntilSeen() {
  const original = storyBooks.darkGuide2.pages;
  storyBooks.darkGuide2.pages = () => {
    const pages = original();
    if (isOmegaGuestSeen()) return pages;
    pages.forEach((page) => {
      page.text = page.text.map((text) => text.replace(' Y... alguien mas. Un viejo conocido. No es relevante para esta guia.', ''));
      if (page.margin) page.margin = page.margin.filter((note) => !/OMEGARIUS/i.test(note.text));
      if (page.margin && !page.margin.length) delete page.margin;
    });
    return pages;
  };
})();

