// ================= MUSICSM's music: his own theme in his box, and a stuttering hum at 3:00 PM =================
const musicsmSong = {
  bass: [110, 87.31, 130.81, 98],
  chords: [[220, 261.63, 329.63], [174.61, 220, 261.63], [261.63, 329.63, 392], [196, 246.94, 293.66]],
  lead: [
    [659.25, 0, 659.25, 880, 0, 783.99, 659.25, 0, 587.33, 0, 659.25, 0, 523.25, 0, 440, 0],
    [523.25, 0, 523.25, 698.46, 0, 659.25, 523.25, 0, 440, 0, 523.25, 0, 587.33, 0, 659.25, 0],
    [783.99, 0, 783.99, 1046.5, 0, 987.77, 783.99, 0, 659.25, 0, 783.99, 0, 880, 0, 783.99, 0],
    [587.33, 0, 587.33, 783.99, 0, 739.99, 587.33, 0, 493.88, 0, 587.33, 659.25, 739.99, 783.99, 880, 987.77],
  ],
};
const musicsmBox = { frame: 0 };

function playMusicsmStep(step, intensity) {
  if (typeof musicGain === 'undefined' || !musicGain) return;
  const bar = Math.floor(step / 16) % 4;
  const beat = step % 16;
  const bass = musicsmSong.bass[bar];
  // the bass pumps in eighths (octave jumps), the drums keep the robot's tempo
  if (beat % 2 === 0) playTone({ frequency: beat % 4 === 0 ? bass : bass * 2, duration: 0.14, type: 'sawtooth', volume: 0.045, destination: musicGain });
  if (beat === 0 || beat === 8 || (intensity >= 2 && beat === 12)) playKick({ volume: 0.06, destination: musicGain });
  if (beat === 4 || beat === 12) playSnare({ volume: 0.04, destination: musicGain });
  if (beat % 2 === 1 || intensity >= 2) playHat({ volume: 0.016, destination: musicGain });
  if (beat === 0) playChord(musicsmSong.chords[bar], { duration: 0.5, type: 'triangle', volume: 0.016, destination: musicGain });
  const note = musicsmSong.lead[bar][beat];
  if (intensity >= 1 && note) playTone({ frequency: intensity >= 2 ? note * 2 : note, duration: 0.1, type: 'square', volume: 0.026, destination: musicGain });
  // FORTISSIMO: a bright arpeggio on top
  if (intensity >= 2 && beat % 2 === 0) {
    const chord = musicsmSong.chords[bar];
    playTone({ frequency: chord[(beat / 2) % 3] * 4, duration: 0.06, type: 'triangle', volume: 0.012, destination: musicGain });
  }
}

function updateMusicsmBoxMusic() {
  const playing = boxRush.active && boxRush.entry && boxRush.entry.theme === 'rushRhythm' && (boxRush.stage === 'countdown' || boxRush.stage === 'playing') && !boxMods.paused;
  if (!playing) {
    musicsmBox.frame = 0;
    return;
  }
  // a sixteenth every 10 frames: one beat = 40 frames, the same beat as his notes
  if (musicsmBox.frame % 10 === 0) {
    const step = Math.floor(musicsmBox.frame / 10);
    const intensity = boxRush.stage === 'countdown' ? 0 : dodgeRound.active ? Math.max(0, dodgeRound.phaseIndex) : 0;
    playMusicsmStep(step, intensity);
  }
  musicsmBox.frame += 1;
}

// 3:00 PM to 3:10 PM: MUSICSM hums somewhere in the Planta 7... and it stutters
const musicsmHum = { timer: null, step: 0, toastShown: null };

function isMusicsmHour() {
  if (window.musicsmHourForce) return true;
  const now = new Date();
  return now.getHours() === 15 && now.getMinutes() < 10;
}

function playMusicsmHumStep() {
  if (typeof musicGain === 'undefined' || !musicGain) return;
  const step = musicsmHum.step;
  musicsmHum.step += 1;
  const bar = Math.floor(step / 16) % 4;
  const beat = step % 16;
  // (sometimes the record skips: it goes back a few steps)
  if (Math.random() < 0.06) musicsmHum.step = Math.max(0, musicsmHum.step - 3);
  if (beat % 4 === 0) playTone({ frequency: musicsmSong.bass[bar], duration: 0.16, type: 'triangle', volume: 0.04, destination: musicGain });
  if (beat === 4 || beat === 12) playHat({ volume: 0.014, destination: musicGain });
  const note = musicsmSong.lead[bar][beat];
  if (!note) return;
  const roll = Math.random();
  if (roll < 0.3) {
    // t-t-t-ta: the same note, stuttered
    const repeats = 2 + Math.floor(Math.random() * 3);
    for (let index = 0; index < repeats; index += 1) playTone({ frequency: note, duration: 0.035, type: 'square', volume: 0.024, delay: index * 0.045, destination: musicGain });
  } else if (roll < 0.4) {
    // the voice glitches and slides
    playTone({ frequency: note, duration: 0.14, type: 'square', volume: 0.022, slideTo: note * (Math.random() < 0.5 ? 0.5 : 1.5), destination: musicGain });
  } else if (roll < 0.47) {
    // ...silence. (he forgot the note)
  } else {
    playTone({ frequency: note, duration: 0.1, type: 'square', volume: 0.026, destination: musicGain });
  }
}

function startMusicsmHum() {
  if (musicsmHum.timer || typeof ensureAudio !== 'function' || !ensureAudio()) return;
  musicsmHum.step = 0;
  musicsmHum.timer = setInterval(playMusicsmHumStep, 165);
  const today = new Date().toDateString();
  if (musicsmHum.toastShown !== today && typeof showCustomToast === 'function') {
    musicsmHum.toastShown = today;
    showCustomToast('♪ M-M-MUSICSM ♪', 'Son las 3:00 PM. En algun pasillo de la Planta 7, MUSICSM tararea su cancion... y se le traba. Hasta las 3:10.');
  }
}

function stopMusicsmHum() {
  if (musicsmHum.timer) clearInterval(musicsmHum.timer);
  musicsmHum.timer = null;
}

(function hookMusicsmMusic() {
  // the hum replaces the menu music during those ten minutes
  const originalStart = window.startMenuMusic;
  const originalStop = window.stopMenuMusic;
  if (typeof originalStart === 'function' && typeof originalStop === 'function') {
    window.startMenuMusic = function startMenuMusicOrHum(...args) {
      if (isMusicsmHour()) {
        startMusicsmHum();
        return undefined;
      }
      return originalStart.apply(this, args);
    };
    window.stopMenuMusic = function stopMenuMusicAndHum(...args) {
      stopMusicsmHum();
      return originalStop.apply(this, args);
    };
    // (checked every few seconds: 3:00 starts it, 3:10 ends it)
    setInterval(() => {
      if (musicsmHum.timer && !isMusicsmHour()) {
        stopMusicsmHum();
        window.startMenuMusic();
      } else if (!musicsmHum.timer && isMusicsmHour() && typeof menuMusicPlaying !== 'undefined' && menuMusicPlaying) {
        originalStop();
        window.startMenuMusic();
      }
    }, 3000);
  }
  // his box has his own song (and no other music on top)
  const originalTrack = window.getReflecterBattleTrackKey;
  if (typeof originalTrack === 'function') {
    window.getReflecterBattleTrackKey = function getTrackKeyWithMusicsm(...args) {
      if (boxRush.active && boxRush.entry && boxRush.entry.theme === 'rushRhythm') return null;
      return originalTrack.apply(this, args);
    };
  }
  const originalAnimate = window.animate;
  window.animate = function animateWithMusicsm(...args) {
    const result = originalAnimate.apply(this, args);
    updateMusicsmBoxMusic();
    // (remember that Omegarius came to help in level 9)
    if (typeof omegaGuest !== 'undefined' && omegaGuest.joined && !isOmegaGuestSeen()) {
      try {
        localStorage.setItem(omegaGuestSeenKey, '1');
      } catch (error) {
        // (nothing to remember with)
      }
    }
    return result;
  };
})();

