const arcadePortraitPalette = {
  knight: ['#5d4037', '#b0bec5'], darkKnight: ['#212121', '#b71c1c'], darkKnightBoss: ['#212121', '#ffd54f'],
  mossBeast: ['#2e7d32', '#a5d6a7'], celesteGirl: ['#4fc3f7', '#ffffff'], setoBoy: ['#ef6c00', '#fff3e0'],
  mochiMouse: ['#9e9e9e', '#c2185b'], chefBoss: ['#eceff1', '#d32f2f'], lanternGuard: ['#1a237e', '#fbc02d'],
  shaolinMaster: ['#b71c1c', '#ffd54f'], angryCustomer: ['#8d6e63', '#ffccbc'], policeOfficer: ['#0d47a1', '#ffd54f'],
  policeSergeant: ['#283593', '#ffd54f'], policeChief: ['#1a237e', '#ffffff'], friendThing: ['#424242', '#e0e0e0'],
  bigFriend: ['#000000', '#e0e0e0'], arcaneMinion: ['#6a1b9a', '#ea80fc'], abnormal: ['#263238', '#90caf9'],
  leafWisp: ['#e53935', '#ffcc80'], barkBeast: ['#5d4037', '#a1887f'], thornHound: ['#33691e', '#e53935'],
  crimsonMoth: ['#880e4f', '#f48fb1'], hydraBeast: ['#1b1b2f', '#7e57c2'], blackKnightBoss: ['#111111', '#ffd54f'],
  babyTitan: ['#eceff1', '#212121'], titanBody: ['#fafafa', '#111111'], titanGiant: ['#fafafa', '#111111'],
  chronoRival: ['#37474f', '#26c6da'], omega: ['#ffd54f', '#fff8e1'],
};
// (these already have their own look, or ARE the brutes)
const arcadePortraitKeep = ['arcadeBoss', 'icedThug', 'iceBrute'];

function getArcadePortraitColors(fighter) {
  const variant = fighter.secretVariant;
  if (arcadePortraitPalette[variant]) return arcadePortraitPalette[variant];
  // anyone else: their own color if they have one, or a color made from their name
  if (fighter.color && !/^#42a5f5$/i.test(fighter.color)) return [fighter.color, '#f5f5f5'];
  let hash = 0;
  for (let index = 0; index < variant.length; index += 1) hash = (hash * 31 + variant.charCodeAt(index)) % 360;
  return [`hsl(${hash}, 45%, 34%)`, '#f5f5f5'];
}

function applyArcadePortrait(portrait, fighter) {
  if (!portrait || !fighter) return;
  portrait.style.removeProperty('--portrait-main');
  portrait.style.removeProperty('--portrait-accent');
  if (fighter.characterType !== 'normal' || !fighter.secretVariant || fighter.rushSkin || arcadePortraitKeep.includes(fighter.secretVariant)) return;
  const [main, accent] = getArcadePortraitColors(fighter);
  portrait.style.setProperty('--portrait-main', main);
  portrait.style.setProperty('--portrait-accent', accent);
}

(function hookArcadePortraits() {
  const original = window.updateCombatHudIdentity;
  if (typeof original !== 'function') return;
  window.updateCombatHudIdentity = function updateCombatHudIdentityWithPortraits(...args) {
    const result = original.apply(this, args);
    applyArcadePortrait(p1Portrait, player1);
    applyArcadePortrait(p2Portrait, player2);
    return result;
  };
})();

