function isTrophyChapterDone(key) {
  if (key === 'fireMasterB') return typeof readFlametombFlag === 'function' && typeof routeB2DoneKey !== 'undefined' && readFlametombFlag(routeB2DoneKey);
  return typeof isArcadeChapterDone === 'function' && isArcadeChapterDone(key);
}

function getChapterTrophyTier(entry) {
  const records = (typeof loadHardcoreRecords === 'function' ? loadHardcoreRecords() : {})[entry.key] || {};
  if (records.harder) return entry.routeB ? 'void' : 'diamond';
  if (records.hard) return entry.routeB ? 'frostfire' : 'gold';
  if (isTrophyChapterDone(entry.key)) return entry.routeB ? 'obsidian' : 'bronze';
  return null;
}

// the statues: something that stands for each chapter
function chapterTrophyStatue(kind, fill, dark, width = 1.2) {
  const s = `fill="${fill}" stroke="${dark}" stroke-width="${width}"`;
  switch (kind) {
    case 'coin': return `<circle cx="30" cy="32" r="16" ${s}/><circle cx="30" cy="32" r="12" fill="none" stroke="${dark}" stroke-width="0.8"/><text x="30" y="39" text-anchor="middle" font-family="Georgia, serif" font-size="17" font-weight="900" fill="${dark}">$</text><path d="M15 19 h11 v6 h-11z M34 19 h11 v6 h-11z M26 21 h8" ${s}/>`;
    case 'fist': return `<rect x="17" y="14" width="26" height="25" rx="7" ${s}/><path d="M24 15 v10 M30 14 v11 M36 15 v10" stroke="${dark}" stroke-width="1"/><path d="M17 29 q-7 -2 -4 -11 q7 0 9 6" ${s}/><rect x="21" y="39" width="18" height="14" rx="2" ${s}/>`;
    case 'flame': return `<path d="M30 4 C43 18 49 30 43 43 C39 53 21 53 17 43 C12 31 22 25 25 14 C27 22 31 24 30 4Z" ${s}/><path d="M30 25 C37 33 39 40 35 46 C33 50 27 50 25 46 C22 40 28 35 30 25Z" fill="${dark}" opacity="0.3"/>`;
    case 'die': return `<g transform="rotate(12 30 30)"><rect x="15" y="15" width="30" height="30" rx="5" ${s}/><circle cx="23" cy="23" r="2.6" fill="${dark}"/><circle cx="30" cy="30" r="2.6" fill="${dark}"/><circle cx="37" cy="37" r="2.6" fill="${dark}"/></g><rect x="25" y="46" width="10" height="7" ${s}/>`;
    case 'mirror': return `<path d="M30 6 L46 16 L46 36 L30 46 L14 36 L14 16 Z" ${s}/><rect x="20" y="22" width="20" height="6" rx="2" fill="${dark}" opacity="0.6"/><rect x="26" y="46" width="8" height="7" ${s}/>`;
    case 'sword': return `<path d="M30 3 L34 9 L34 34 L26 34 L26 9 Z" ${s}/><rect x="19" y="34" width="22" height="4" rx="1" ${s}/><path d="M18 30 h24 v9 q0 9 -12 14 q-12 -5 -12 -14 Z" ${s}/>`;
    case 'clock': return `<circle cx="30" cy="27" r="17" ${s}/><circle cx="30" cy="27" r="12.5" fill="none" stroke="${dark}" stroke-width="0.8"/><path d="M30 27 V18 M30 27 L36 30" stroke="${dark}" stroke-width="2.2" stroke-linecap="round"/><path d="M24 44 h12 l-3 9 h-6 Z" ${s}/>`;
    // route B: bizarre, crooked, broken
    case 'frostFlame': return `<g transform="rotate(-10 30 30)"><path d="M30 4 C43 18 49 30 43 43 C39 53 21 53 17 43 C12 31 22 25 25 14 C27 22 31 24 30 4Z" ${s}/><path d="M30 4 L30 52" stroke="${dark}" stroke-width="1.4" stroke-dasharray="3 2"/><path d="M36 18 l6 -6 M38 28 l8 0 M36 38 l6 6" stroke="#e0ffff" stroke-width="1.5"/></g><path d="M21 51 q2 4 0 7 M39 51 q-1 4 1 6" stroke="${fill}" stroke-width="3" stroke-linecap="round"/>`;
    case 'stitched': return `<g transform="rotate(9 30 30)"><path d="M14 28 Q12 8 30 8 Q50 8 46 30 Q44 48 30 48 Q14 48 14 28Z" ${s}/><circle cx="23" cy="26" r="4.5" fill="${dark}"/><circle cx="23" cy="26" r="1.5" fill="${fill}"/><path d="M33 23 l7 7 M40 23 l-7 7" stroke="${dark}" stroke-width="2"/><path d="M18 38 L42 38 M22 35 v6 M28 35 v6 M34 35 v6 M40 35 v6" stroke="${dark}" stroke-width="1.2"/></g>`;
    case 'brokenGear': return `<g transform="rotate(-14 30 28)"><path d="M30 8 l4 0 l1 5 l5 2 l4 -3 l3 3 l-3 4 l2 5 l5 1 l0 4 l-5 1 l-2 5 l3 4 l-3 3 l-4 -3 l-5 2 l-1 5 l-4 0 l-1 -5 l-5 -2 L18 28 Z" ${s}/><circle cx="31" cy="28" r="5" fill="${dark}"/><circle cx="31" cy="28" r="2" fill="#ff1744"/></g><path d="M13 40 l4 4 l-3 3 Z M45 46 l3 -2 l1 4 Z" ${s}/>`;
    default: return '';
  }
}

function chapterTrophySvg(entry, tier, suffix = '') {
  const id = `ct-${entry.key}${suffix}`;
  const material = chapterTrophyMaterials[tier || (entry.routeB ? 'obsidian' : 'bronze')];
  const [deep, mid, shine, edge] = material.stops;
  const fill = tier ? `url(#${id}-m)` : 'rgba(255,255,255,0.07)';
  const dark = tier ? deep : 'rgba(255,255,255,0.22)';
  const podium = entry.routeB
    // a warped, cracked podium with a glowing crack
    ? `<path d="M7 72 L53 68 L56 84 L4 84 Z" fill="url(#${id}-pb)" stroke="#4a148c" stroke-width="0.8"/>
       <path d="M11 60 L50 57 L52 70 L9 72 Z" fill="url(#${id}-pb)" stroke="#4a148c" stroke-width="0.8"/>
       <path d="M14 55 L48 53 L49 58 L13 60 Z" fill="#3a2d4a"/>
       <path d="M31 58 l-4 6 l5 4 l-3 6 l3 6" fill="none" stroke="${tier ? '#e040fb' : '#555'}" stroke-width="1.1"/>`
    : `<rect x="4" y="74" width="52" height="10" rx="1" fill="url(#${id}-pb)" stroke="#78909c" stroke-width="0.6"/>
       <rect x="10" y="59" width="40" height="15" fill="url(#${id}-pb)" stroke="#78909c" stroke-width="0.6"/>
       <rect x="7" y="54" width="46" height="5" rx="1" fill="url(#${id}-pb)" stroke="#78909c" stroke-width="0.6"/>
       <path d="M10 59 H50 M4 74 H56" stroke="${tier ? mid : '#90a4ae'}" stroke-width="1.4"/>`;
  return `
    <svg class="ct-svg" viewBox="0 0 60 84" aria-hidden="true">
      <defs>
        <linearGradient id="${id}-m" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stop-color="${deep}"/><stop offset="0.35" stop-color="${mid}"/><stop offset="0.52" stop-color="${shine}"/><stop offset="0.7" stop-color="${mid}"/><stop offset="1" stop-color="${edge}"/>
        </linearGradient>
        <radialGradient id="${id}-s" cx="0.32" cy="0.25" r="0.55">
          <stop offset="0" stop-color="#ffffff" stop-opacity="0.85"/><stop offset="1" stop-color="#ffffff" stop-opacity="0"/>
        </radialGradient>
        <radialGradient id="${id}-g" cx="0.5" cy="0.5" r="0.5">
          <stop offset="0" stop-color="${tier ? material.glow : 'rgba(0,0,0,0)'}"/><stop offset="1" stop-color="rgba(0,0,0,0)"/>
        </radialGradient>
        <linearGradient id="${id}-pb" x1="0" y1="0" x2="0" y2="1">
          ${entry.routeB ? '<stop offset="0" stop-color="#2b2238"/><stop offset="1" stop-color="#0c0814"/>' : '<stop offset="0" stop-color="#fafafa"/><stop offset="1" stop-color="#b0bec5"/>'}
        </linearGradient>
      </defs>
      <ellipse cx="30" cy="30" rx="27" ry="27" fill="url(#${id}-g)"/>
      ${podium}
      <rect x="21" y="62" width="18" height="9" rx="1.5" fill="${entry.routeB ? '#0d0b12' : '#263238'}" stroke="${tier ? mid : '#546e7a'}" stroke-width="0.8"/>
      <text x="30" y="69" text-anchor="middle" font-family="Courier New, monospace" font-size="7" font-weight="900" fill="${tier ? shine : '#78909c'}">${entry.num}</text>
      <g class="ct-statue">
        ${chapterTrophyStatue(entry.statue, fill, dark)}
        ${tier ? `<g opacity="0.75">${chapterTrophyStatue(entry.statue, `url(#${id}-s)`, 'none', 0)}</g>` : ''}
      </g>
    </svg>`;
}

function readSeenTrophies() {
  try {
    return JSON.parse(localStorage.getItem(chapterTrophySeenKey) || '{}') || {};
  } catch (error) {
    return {};
  }
}

// the ceremony: a trophy you just earned (or improved) shows up big, and changes material in front of you
function showNextTrophyCeremony() {
  const next = chapterTrophyCeremony.queue.shift();
  if (!next) {
    if (chapterTrophyCeremony.element) chapterTrophyCeremony.element.remove();
    chapterTrophyCeremony.element = null;
    return;
  }
  let overlay = chapterTrophyCeremony.element;
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.className = 'ct-ceremony';
    overlay.addEventListener('click', () => {
      clearTimeout(chapterTrophyCeremony.timer);
      showNextTrophyCeremony();
    });
    document.body.appendChild(overlay);
    chapterTrophyCeremony.element = overlay;
  }
  const { entry, from, to } = next;
  const toName = chapterTrophyMaterials[to].name;
  overlay.innerHTML = `
    <div class="ct-ceremony-box ct-route-${entry.routeB ? 'b' : 'a'}">
      <span class="ct-ceremony-kicker">${from ? 'TROFEO MEJORADO' : 'NUEVO TROFEO'}</span>
      <div class="ct-ceremony-stage">
        ${from ? `<span class="ct-big ct-big-from">${chapterTrophySvg(entry, from, '-cf')}</span>` : ''}
        <span class="ct-big ct-big-to${from ? ' ct-delayed' : ''}">${chapterTrophySvg(entry, to, '-ct')}</span>
        <span class="ct-flash${from ? ' ct-delayed' : ''}"></span>
      </div>
      <strong>${entry.name}</strong>
      <span class="ct-ceremony-material">${from ? `${chapterTrophyMaterials[from].name} &rarr; ` : ''}<b>${toName}</b></span>
      <small>(toca para seguir)</small>
    </div>`;
  playSound('achievement');
  if (from) setTimeout(() => playTone({ frequency: 1318, duration: 0.25, type: 'triangle', volume: 0.05 }), 1100);
  chapterTrophyCeremony.timer = setTimeout(showNextTrophyCeremony, from ? 4200 : 3200);
}

function syncChapterTrophies() {
  const title = document.getElementById('titleScreen');
  if (!title) return;
  // (the old side cabinets, if a previous version made them)
  document.querySelectorAll('.ct-cabinet').forEach((cabinet) => cabinet.remove());
  let left = title.querySelector('.ct-shelf-a');
  let right = title.querySelector('.ct-shelf-b');
  if (!left) {
    left = document.createElement('div');
    left.className = 'ct-shelves ct-shelf-a';
    right = document.createElement('div');
    right.className = 'ct-shelves ct-shelf-b';
    title.append(left, right);
  }
  const seen = readSeenTrophies();
  const ceremonies = [];
  const render = (entries) => entries.map((entry) => {
    const tier = getChapterTrophyTier(entry);
    // a new trophy, or a better one than last time: the next "level"
    if (tier && (chapterTrophyRank[tier] || 0) > (chapterTrophyRank[seen[entry.key]] || 0)) {
      ceremonies.push({ entry, from: seen[entry.key] || null, to: tier });
      seen[entry.key] = tier;
    }
    const label = tier ? `${entry.name}: trofeo de ${chapterTrophyMaterials[tier].name}` : `${entry.name}: sin trofeo todavia`;
    return `<span class="ct-trophy ct-${tier || 'empty'}" title="${label}" aria-label="${label}">${chapterTrophySvg(entry, tier)}</span>`;
  }).join('');
  const routeA = chapterTrophyList.filter((entry) => !entry.routeB && (entry.key !== 'origins' || isTrophyChapterDone('origins') || (typeof isOriginsUnlocked === 'function' && isOriginsUnlocked())));
  const routeBOpen = typeof isRouteBUnlocked === 'function' && isRouteBUnlocked();
  const anyWon = chapterTrophyList.some((entry) => getChapterTrophyTier(entry));
  left.innerHTML = anyWon ? render(routeA) : '';
  right.innerHTML = anyWon && routeBOpen ? render(chapterTrophyList.filter((entry) => entry.routeB)) : '';
  left.classList.toggle('hidden', !anyWon);
  right.classList.toggle('hidden', !anyWon || !routeBOpen);
  try {
    localStorage.setItem(chapterTrophySeenKey, JSON.stringify(seen));
  } catch (error) {
    // (no memory: the ceremony comes again)
  }
  // (the first time the trophies exist, the ones you already had arrive quietly)
  const firstVisit = Boolean(window.chapterTrophiesFirstSync);
  if (ceremonies.length && !title.classList.contains('hidden') && !firstVisit) {
    chapterTrophyCeremony.queue.push(...ceremonies);
    if (!chapterTrophyCeremony.element) setTimeout(showNextTrophyCeremony, 500);
  }
}

(function hookChapterTrophies() {
  // the very first sync after this update: the trophies you already earned just appear (no ceremony)
  let hadMemory = false;
  try {
    hadMemory = localStorage.getItem(chapterTrophySeenKey) !== null;
  } catch (error) {
    hadMemory = false;
  }
  window.chapterTrophiesFirstSync = !hadMemory;
  syncChapterTrophies();
  window.chapterTrophiesFirstSync = false;
  // every time the title menu comes back, the trophies are checked again
  const title = document.getElementById('titleScreen');
  if (title && typeof MutationObserver === 'function') {
    let wasHidden = title.classList.contains('hidden');
    new MutationObserver(() => {
      const hidden = title.classList.contains('hidden');
      if (wasHidden && !hidden) syncChapterTrophies();
      wasHidden = hidden;
    }).observe(title, { attributes: true, attributeFilter: ['class'] });
  }
})();

