function syncBlackDoor() {
  const title = document.getElementById('titleScreen');
  if (!title) return;
  let door = title.querySelector('.black-door');
  if (!door) {
    door = document.createElement('button');
    door.type = 'button';
    door.className = 'black-door';
    door.setAttribute('aria-label', 'Una puerta negra');
    door.innerHTML = '<span class="black-door-scratch" aria-hidden="true"></span><span class="black-door-knob" aria-hidden="true"></span><span class="black-door-hole" aria-hidden="true"></span><span class="black-door-eye" aria-hidden="true"></span><span class="black-door-light" aria-hidden="true"></span><span class="black-door-fog" aria-hidden="true"></span>';
    door.addEventListener('click', knockBlackDoor);
    title.appendChild(door);
  }
  door.classList.toggle('has-key', hasCleanKey());
  door.classList.toggle('visited', readSpookyFlag(blackDoorKey));
}

function knockBlackDoor() {
  const door = document.querySelector('.black-door');
  if (!scammerShop.owned.rustyKey) {
    showCustomToast('LA PUERTA NEGRA', 'Esta cerrada. Muy cerrada. Del otro lado no se escucha nada... y eso es peor. Necesitas una llave.');
    [90, 70].forEach((frequency, index) => setTimeout(() => playNoise({ duration: 0.12, volume: 0.09, filterFrequency: 300 }), index * 160));
    if (door) {
      door.classList.remove('rattle');
      void door.offsetWidth;
      door.classList.add('rattle');
    }
    return;
  }
  if (!hasCleanKey()) {
    showCustomToast('LA PUERTA NEGRA', 'La llave oxidada entra... pero no gira. Cruje. Esta demasiado oxidada. Si tan solo pudieras volverla atras en el tiempo...');
    playTone({ frequency: 140, duration: 0.5, type: 'sawtooth', volume: 0.04, slideTo: 110 });
    if (door) {
      door.classList.remove('rattle');
      void door.offsetWidth;
      door.classList.add('rattle');
    }
    return;
  }
  openBlackDoorPlace();
}

