// the carved symbols of the doors
function blackDoorSymbol(kind) {
  if (kind === 'eye') return '<svg viewBox="0 0 40 24" aria-hidden="true"><path d="M2 12 Q20 -6 38 12 Q20 30 2 12Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="20" cy="12" r="5" fill="currentColor"/></svg>';
  if (kind === 'moon') return '<svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="18" cy="20" r="14" fill="currentColor"/><circle cx="26" cy="15" r="12" fill="#2a0c3a"/></svg>';
  if (kind === 'hand') return '<svg viewBox="0 0 40 44" aria-hidden="true"><path d="M12 42 L10 22 L8 10 Q9 7 12 10 L14 20 L15 6 Q17 3 19 6 L20 19 L22 4 Q24 1 26 4 L26 19 L29 8 Q31 5 33 8 L31 24 Q30 36 24 42Z" fill="none" stroke="currentColor" stroke-width="2"/></svg>';
  return '<svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="3" fill="currentColor"/></svg>';
}

function startBlackDoorAmbience() {
  stopBlackDoorAmbience();
  // a low drone that never quite resolves, and whispers that come and go
  const drone = () => {
    playTone({ frequency: 55, duration: 3.6, type: 'sine', volume: 0.05, slideTo: 52 });
    playTone({ frequency: 58.3, duration: 3.6, type: 'sine', volume: 0.03 });
  };
  drone();
  blackDoorAmbience.timer = setInterval(() => {
    drone();
    const scene = document.querySelector('.black-door-place .bd-scene');
    if (!scene || Math.random() < 0.35) return;
    const whisper = document.createElement('span');
    whisper.className = 'bd-whisper';
    whisper.textContent = blackDoorWhispers[Math.floor(Math.random() * blackDoorWhispers.length)];
    whisper.style.left = `${8 + Math.random() * 70}%`;
    whisper.style.top = `${6 + Math.random() * 40}%`;
    scene.appendChild(whisper);
    setTimeout(() => whisper.remove(), 4200);
    playNoise({ duration: 0.9, volume: 0.015, filterFrequency: 1400 });
  }, 3500);
}

function stopBlackDoorAmbience() {
  if (blackDoorAmbience.timer) clearInterval(blackDoorAmbience.timer);
  blackDoorAmbience.timer = null;
}

function openBlackDoorPlace() {
  // the door opens: a long creak
  playTone({ frequency: 180, duration: 1.4, type: 'sawtooth', volume: 0.035, slideTo: 80 });
  playNoise({ duration: 0.9, volume: 0.04, filterFrequency: 500 });
  let overlay = document.querySelector('.black-door-place');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.className = 'black-door-place';
    overlay.addEventListener('click', (event) => {
      const go = event.target.closest('[data-door-go]');
      if (!go) return;
      playNoise({ duration: 0.15, volume: 0.05, filterFrequency: 900 });
      renderBlackDoorPlace(go.dataset.doorGo);
    });
    // the eyes of the portraits follow the pointer
    overlay.addEventListener('pointermove', (event) => {
      const scene = overlay.querySelector('.bd-scene');
      if (!scene) return;
      const box = scene.getBoundingClientRect();
      scene.style.setProperty('--ex', `${Math.max(-1, Math.min(1, ((event.clientX - box.left) / box.width - 0.5) * 2)) * 2.5}px`);
      scene.style.setProperty('--ey', `${Math.max(-1, Math.min(1, ((event.clientY - box.top) / box.height - 0.4) * 2)) * 2}px`);
    });
    document.body.appendChild(overlay);
  }
  overlay.classList.remove('hidden');
  startBlackDoorAmbience();
  // crossing the black door opens something in the Arcade
  if (!readSpookyFlag(forestUnlockKey)) {
    writeSpookyFlag(forestUnlockKey);
    if (typeof syncForestChapterCard === 'function') syncForestChapterCard();
    setTimeout(() => showCustomToast('...', 'Algo se abrio en el Arcade. Huele a tierra mojada y a hojas podridas.'), 1800);
  }
  renderBlackDoorPlace('hall');
}

