    return `<div class="bd-gallery">${portraits.map(([color, name]) => `<span class="bd-portrait${name === 'Ghost' ? ' bd-holes' : ''}" style="--pc:${color}" title="${name}"><i></i><i></i></span>`).join('')}<span class="bd-portrait bd-forest-painting" title="PROXIMAMENTE"><b></b></span></div>`;
