function pickSkinShopReaction(who) {
  if (!scammerShop.owned || !scammerShop.owned.wardrobe) return null;
  const skinId = readFighterSkins()[who];
  const lines = skinShopReactions[who] && skinShopReactions[who][skinId];
  if (!lines) return null;
  let seen = {};
  try {
    seen = JSON.parse(localStorage.getItem('moqueteSkinReactions') || '{}') || {};
  } catch (error) {
    seen = {};
  }
  const first = seen[who] !== skinId;
  if (!first && Math.random() > 0.35) return null;
  seen[who] = skinId;
  try {
    localStorage.setItem('moqueteSkinReactions', JSON.stringify(seen));
  } catch (error) {
    // (he will just say it again)
  }
  return first ? lines.first : lines.again[Math.floor(Math.random() * lines.again.length)];
}

(function skinShopReactionHooks() {
  const baseOpenShop = openScammerShop;
  openScammerShop = function openScammerShopNoticingSkin(vendorLine) {
    baseOpenShop(vendorLine);
    if (scammerShop.grudge) return;
    const reaction = pickSkinShopReaction('scammer');
    if (reaction) scammerShopSay(reaction[0], reaction[1]);
  };
  // (the market's button already opens it: this listener runs right after and changes his greeting)
  if (typeof tempusWatchButton !== 'undefined' && tempusWatchButton) {
    tempusWatchButton.addEventListener('click', () => {
      if (typeof isTempusSwitcherShift === 'function' && isTempusSwitcherShift()) return;
      if (!tempusScreen || tempusScreen.classList.contains('hidden')) return;
      const reaction = pickSkinShopReaction('chrono');
      if (reaction) tempusSay(reaction);
    });
  }
})();

