function getArcadeVhsNotes() {
  const done = (check) => {
    try {
      return Boolean(check());
    } catch (error) {
      return false;
    }
  };
  return [
    {
      id: 'scammer',
      side: 'left',
      unlocked: done(() => scammerShop.owned.rareMachine),
      label: 'NOTA DE SCAMMER',
      text: 'KID! ESCUCHA: LO QUE SE VE DEL OTRO LADO DE ESA PANTALLA [[NO]] ES NUESTRO MUNDO. TIERRA NARANJA, PUESTITOS, GENTE CUADRADA QUE NO VI NUNCA... YO ESTUVE EN MUCHOS LUGARES RAROS (Y VENDI EN TODOS), PERO ESTE NO LO CONOZCO. Y LA MAQUINA LA VENDI YO. [[SIN DEVOLUCIONES]].',
      sign: '- S. (vendedor certificado)',
    },
    {
      id: 'jester',
      side: 'left',
      unlocked: done(() => isArcadeChapterDone('chrono')),
      label: 'NOTA DE SHADOW JESTER',
      text: 'Que hallazgo tan encantador. Ese mundo detras del vidrio me intriga... sobre todo la figura del aura extraña, la que tuerce la musica cuando aparece. Pienso ir a verlo con mis propios ojos. No me esperes despierto.',
      sign: '- S.J.',
    },
    {
      id: 'lightWarrior',
      side: 'right',
      unlocked: done(() => isLightWarriorUnlocked()),
      label: 'NOTA DE LIGHT WARRIOR',
      text: 'Estuve mirando la pantalla. Ese mundo es raro: no es el que suelo ver, y no se parece a ninguno que conozca. Hay algo ahi que no me termina de gustar... Si tengo que elegir, prefiero mantenerme lejos antes que causar problemas.',
      sign: '- L.W.',
    },
    {
      id: 'abnormal',
      side: 'right',
      unlocked: done(() => isChronoSecretBeaten()),
      label: 'NOTA DE ABNORMAL',
      text: abnormalVhsNoteLines[Math.floor(Math.random() * abnormalVhsNoteLines.length)],
      sign: '- A. (elegantemente)',
    },
  ];
}

function addArcadeVhsNotes(overlay) {
  const notes = getArcadeVhsNotes().filter((note) => note.unlocked);
  if (!notes.length) return;
  overlay.classList.add('has-notes');
  const tv = overlay.querySelector('.vhs-tv');
  const columns = {};
  ['left', 'right'].forEach((side) => {
    const column = document.createElement('div');
    column.className = `vhs-notes ${side}`;
    columns[side] = column;
  });
  overlay.insertBefore(columns.left, tv);
  tv.after(columns.right);
  notes.forEach((note, index) => {
    const card = document.createElement('div');
    card.className = `vhs-note note-${note.id}`;
    card.style.setProperty('--tilt', `${(index % 2 ? 1 : -1) * (1.5 + Math.random() * 2)}deg`);
    card.style.animationDelay = `${0.25 + index * 0.18}s`;
    card.innerHTML = `<span class="vhs-note-pin"></span><b>${note.label}</b><p></p><i>${note.sign}</i>`;
    card.querySelector('p').textContent = note.text;
    columns[note.side].appendChild(card);
    // Abnormal can't stay on one subject: his note rewrites itself now and then
    if (note.id === 'abnormal') {
      const line = card.querySelector('p');
      let last = note.text;
      const timer = setInterval(() => {
        if (!card.isConnected) {
          clearInterval(timer);
          return;
        }
        let next = last;
        while (next === last) next = abnormalVhsNoteLines[Math.floor(Math.random() * abnormalVhsNoteLines.length)];
        last = next;
        card.classList.add('rewrite');
        setTimeout(() => {
          line.textContent = next;
          card.style.setProperty('--tilt', `${(Math.random() - 0.5) * 9}deg`);
        }, 260);
        setTimeout(() => card.classList.remove('rewrite'), 560);
      }, 7000);
    }
  });
  // (an empty column keeps the screen centered; on a phone it disappears)
  ['left', 'right'].forEach((side) => {
    if (!columns[side].children.length) columns[side].classList.add('empty');
  });
}

// ================= Ajustes: the "Lightfull Man" lyrics can be turned off (Light Warrior has something to say) =================
const lightfullLyricsStorageKey = 'moqueteLightfullLyrics';
const lightfullLyricsToggle = document.getElementById('lightfullLyricsToggle');
let lightfullLyricsOn = true;
try {
  lightfullLyricsOn = localStorage.getItem(lightfullLyricsStorageKey) !== '0';
} catch (error) {
  lightfullLyricsOn = true;
}
const lightfullLyricsOffLines = [
  'Sacaste la letra? ...Bueno. Igual la voy a cantar por dentro.',
  'Esta bien, esta bien. Era un poco vergonzoso que todos la leyeran.',
  'Sin letra... Asi nadie se entera de que desafino. Gracias, creo.',
];
const lightfullLyricsOnLines = [
  'La letra volvio! ...No es que la haya escrito yo. Bueno, un poco.',
  'LIGHTFULL MAN! LIGHTFULL MAN! ...Perdon, me emocione.',
  'Bien! Ahora todos pueden cantar conmigo. Todos. Hasta Knight.',
];

(function hookLightfullLyricsSetting() {
  const baseDrawLyrics = drawLightfullLyrics;
  drawLightfullLyrics = function drawLightfullLyricsIfWanted(forcedTime = null) {
    if (!lightfullLyricsOn && forcedTime === null) return;
    return baseDrawLyrics(forcedTime);
  };
  if (!lightfullLyricsToggle) return;
  lightfullLyricsToggle.checked = lightfullLyricsOn;
  lightfullLyricsToggle.addEventListener('change', () => {
    lightfullLyricsOn = lightfullLyricsToggle.checked;
    try {
      localStorage.setItem(lightfullLyricsStorageKey, lightfullLyricsOn ? '1' : '0');
    } catch (error) {
      // the setting still works for this session
    }
    // Light Warrior hears about it
    const lines = lightfullLyricsOn ? lightfullLyricsOnLines : lightfullLyricsOffLines;
    showCustomToast('LIGHT WARRIOR', `"${lines[Math.floor(Math.random() * lines.length)]}"`);
    const label = document.querySelector('[data-i18n="achievementToastLabel"]');
    if (label) {
      const original = label.textContent;
      label.textContent = lightfullLyricsOn ? 'Letra activada' : 'Letra desactivada';
      setTimeout(() => {
        label.textContent = original;
      }, 4000);
    }
    playSound('menuSelect');
  });
})();
